INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('00266997-5748-5572-8d3d-09e19acab6d8', 'Rhue Lighthouse, near Ullapool', 'https://www.walkhighlands.co.uk/ullapool/rhue.shtml', 1.2, 32, 0.3333333333333333, 'A short and easy walk to Rhue lighthouse with good views down Loch Broom and out to sea including to the Summer Isles. Can be combined with a walk up the road and track to the mast on Meall Mòr to make a longer walk.', 57.9239, -5.2155),
('003880e2-3466-50c9-a4ce-4486e875b68b', 'Boreraig and Suisnish: the Cleared Coast', 'https://www.walkhighlands.co.uk/skye/boreraigsuisnish.shtml', 16.5, 350, 6.0, 'The ruined coastal villages of Suisnish and Boreraig are a reminder of the Clearances; the walk to visit them gives an easy though long circuit with fine views.', 57.2147, -5.948),
('006395bc-af81-51d2-9287-75885fdc579b', 'Aden Country Park, near Mintlaw', 'https://www.walkhighlands.co.uk/aberdeenshire/aden-country-park.shtml', 4.0, 25, 1.0, 'Aden Country Park is a 230 acre parkland set just west of Mintlaw, 15km west of Peterhead. The park features an aboretum, ruined mansion, lake, burn and woodland. The walking route described here makes a circuit around the park.', 57.5215, -2.0323),
('0073679c-2e80-5caa-bcff-993398b73486', 'Ben Chonzie via Glen Lednock', 'https://www.walkhighlands.co.uk/perthshire/ben-chonzie.shtml', 12.5, 712, 5.0, 'An easier ascent by Munro standards, Ben Chonzie can be climbed in a long half day and is the highest summit in a large area of heather moorland.', 56.4209, -4.0394),
('00afea79-d35a-5bc5-af95-08f627477d22', 'Treshnish Coast and the Whisky Cave', 'https://www.walkhighlands.co.uk/mull/treshnish.shtml', 11.0, 343, 4.5, 'This superb circular walk takes in an interesting section of coastline on the Treshnish peninsula. It includes cliff scenery, a chance to see wildlife, evocative abandoned villages and the legendary whisky cave - where the finest moonshine on Mull was produced.', 56.5542, -6.2961),
('0131be59-fcb5-56af-a9e8-cf8f1bc6543e', 'Barpa Langass and the Stone Circle', 'https://www.walkhighlands.co.uk/outer-hebrides/barpa-langass.shtml', 3.25, 90, 1.0, 'This short circular walk visits two prehistoric sites - the spectacular chambered cairn of Barpa Langass together with the only stone circle on North Uist. The views are excellent but the walk is wet underfoot in places.', 57.5712, -7.2959),
('0157cf50-af1b-578a-9b70-c2b54a1a9bc3', 'North Sutor, Nigg', 'https://www.walkhighlands.co.uk/ullapool/nigg.shtml', 5.5, 226, 2.0, 'This bracing walk climbs from Nigg Ferry over the impressive cliffs of the North Sutor, forming one half of the gateway to the Cromarty Firth. There are great views, and the chance to spot dolphins in the sea below.', 57.6927, -4.0207),
('017eefda-8257-51cd-9010-06e653d5f6ee', 'Haddington and the River Tyne', 'https://www.walkhighlands.co.uk/lothian/haddington.shtml', 3.5, 5, 1.0, 'Haddington was once one of the most important towns in Scotland, but it suffered from attacks by the English army and was badly damaged by floods in 1358. Today it has a population of only 9,000 but it remains the administrative capital of East Lothian. This short and easy walk combines the town''s finest buildings with an attractive stroll along the banks of the River Tyne.', 55.9555, -2.77785),
('01cb6c9a-c6f5-587e-8825-e7a2b762430d', 'Harlaw and Threipmuir Reservoirs', 'https://www.walkhighlands.co.uk/lothian/harlaw-threipmuir.shtml', 4.25, 35, 1.0, 'The short circular walk through the woods surrounding the Harlaw Reservoir is a very popular Pentlands stroll. The walk described here extends this to follow the bank of Threipmuir reservoir to Black Springs.', 55.8755, -3.3101),
('02101868-e28a-5b45-8186-96eaf9ae94c0', 'Coire Làir & Easan Dorcha circuit, Achnashellach', 'https://www.walkhighlands.co.uk/torridon/Easandorcha.shtml', 15.0, 560, 7.0, 'A varied circuit on clear and well made paths with good mountain views. Beautiful scots pine wood and waterfalls along Easan Dorcha make this a perfect lunch spot. The final section of the walk has fine views down Lochcarron and across the sea.', 57.4817, -5.32931),
('023e3fd0-2792-54d4-b993-c922d61b95a5', 'Meall na h-Eilde and Geal Charn, Loch Arkaig', 'https://www.walkhighlands.co.uk/fortwilliam/meall-na-h-eilde.shtml', 17.0, 1017, 7.0, 'This pair of Corbetts lying to the north of the foot of Loch Arkaig have a mostly rounded, heathery character. They occupy a great position, however, giving stunning views over Loch Arkaig and Loch Quoich in good conditions towards the rugged peaks of the wild west.', 56.9576, -5.03209),
('0267425c-b97c-5124-a463-52d169ecea15', 'Leathad an Taobhain and Càrn Dearg Mòr', 'https://www.walkhighlands.co.uk/cairngorms/leathad-an-taobhain.shtml', 33.5, 989, 10.0, 'These two Corbetts can be combined into this long walk from Glen Feshie. Leathad an Tobhair is a rounded dome of heather surrounded by miles and miles of empty moors - one of the remotest places in Britain but scarred by a landrover track makes for an easy approach. Càrn Dearg Mòr has excellent views, especially on the descent, of beautiful Glen Feshie and Badenoch beyond.', 57.0631, -3.897),
('02b41eaf-4f55-5ee5-ba9c-a507203d769f', 'Ben Hogh, from Clabhach', 'https://www.walkhighlands.co.uk/islands/ben-hogh.shtml', 1.5, 72, 1.0, 'Ben Hogh - though only 106m high - is the highest hill on Coll and is an excellent viewpoint, well repaying the short ascent. Near the summit is the Clach na Ban-righ or Queen''s Stone.', 56.6351, -6.5991),
('02b85174-260d-5221-8e10-2f423b61797c', 'MacGregor''s Cave, near Kinloch Rannoch', 'https://www.walkhighlands.co.uk/perthshire/macgregors-cave.shtml', 5.0, 154, 2.0, 'This idyllic short walk passes the shores of Dunalasdair Water and through some fine oakwoods to reach MacGregor''s Cave - reputedly once a hideout for members of the outlawed clan. In Victorian times the cave was ''improved'' to become a picturesque spot for a walk and picnic.', 56.6935, -4.1219),
('02d136c2-d4e7-55e2-8130-69c474802f77', 'Glas Maol Munros circuit, Cairnwell Pass', 'https://www.walkhighlands.co.uk/cairngorms/glas-maol.shtml', 19.25, 891, 7.5, 'Glas Maol is the highest of the four Munros on the east side of the Cairnwell Pass. With a high-level start and little descent between the summits, which are arranged on a plateau, this is a straightforward round in good conditions for four Munros.', 56.9033, -3.4008),
('031e0fa7-dd8e-5c0f-a265-a7f882e32b82', 'Loch Innes, Kinlochbervie', 'https://www.walkhighlands.co.uk/sutherland/kinlochbervie.shtml', 4.0, 92, 1.0, 'This short leg stretcher offers an opportunity to work off a big lunch. It runs around Loch Innis na Ba Buidhe, to give it its full name, on the fringes of the fishing port of Kinlochbervie.', 58.4581, -5.0368),
('032f7f7a-d4a7-5476-86c5-2133868875e4', 'Achaderry and River Spean circuit, Roybridge', 'https://www.walkhighlands.co.uk/fortwilliam/roybridge.shtml', 6.0, 86, 2.0, 'This circular walk explores the environs of the village of Roybridge. It passes through a great deal of fine native woodland and visits an attractive lochan before reaching the River Spean.', 56.8911, -4.8416),
('03adcb46-526a-5fa0-aedf-df88092905e7', 'Conachair and Village Bay, St Kilda', 'https://www.walkhighlands.co.uk/outer-hebrides/village-bay-conachair.shtml', 5.5, 459, 3.5, 'St Kilda is Scotland''s most remote group of islands, situated 66km west of Benbecula. Britain''s only double World Heritage Site for both its natural and cultural significance, a visit is an unforgettable experience; long day trips are available from Harris, Lewis and Skye. This walk climbs up to the summit of Conachair - the highest point on the archipelago and the rim of the UK''s highest sea cliffs, site of spectacular bird colonies. It then returns to Village Bay to visit the remains of the remarkable community which survived here until 1930, when the last residents were evacuated at their own request.', 57.8109, -8.5661),
('04295cad-fc5b-56c2-b060-a2c7eb7a23bc', 'Coldingham Bay circuit, Coldingham', 'https://www.walkhighlands.co.uk/borders/coldingham.shtml', 5.5, 112, 1.5, 'This excellent walk starts from Coldingham Priory before taking the ancient Creel Path to the sea at St Abbs. A coastal path leads to a sandy beach at Coldingham Bay before a path heads inland to complete the circuit.', 55.8868, -2.15666),
('047d0d31-da98-5e42-932e-63ac03c3a3ab', 'Thurso Bay and Castle, Thurso', 'https://www.walkhighlands.co.uk/sutherland/thurso-bay.shtml', 7.0, 60, 2.0, 'An exploration of the coastline that makes up the eastern side of Thurso Bay, this walk passes the ruinous Thurso Castle and has good views across to Scrabster, Dunnet Head and Hoy. Thurso is renowned for its surf and you may see surfers braving the waves.', 58.5947, -3.5159),
('0485cf84-3377-54fe-87d1-a5874cde5aa0', 'Poulouriscaig, from Armadale', 'https://www.walkhighlands.co.uk/sutherland/poulouriscaig.shtml', 6.0, 192, 2.5, 'Climb over the bleak moors to visit the deserted village of Poulouriscaig. This is a fine example of the places where Highlanders forced to leave the fertile straths during the Clearances were made to settle. It is easy to imagine how hard life must have been.', 58.5532, -4.0877),
('049785f7-9b93-56a1-8f88-f354b4f87d9f', 'A'' Mharconaich and Geal Chàrn, Drumochter', 'https://www.walkhighlands.co.uk/cairngorms/a-mharconaich.shtml', 11.5, 731, 6.0, 'These are the northerly two summits of the four Munros on the west side of the Drumochter Pass. Geal Chàrn is a featureless lump with superb views towards Ben Alder, whilst A'' Mharconaich is the shapliest of the range, with a steep prow prominent from the A9.', 56.8835, -4.2536),
('04a4e533-9e11-5033-8d53-c2b44926526f', 'Newark Bay and Point of Ayre, Deerness, Mainland', 'https://www.walkhighlands.co.uk/orkney/newark-bay.shtml', 5.25, 3, 2.0, 'A pleasant out-and-return coastal walk with a sandy beach, rocky foreshore and great views over the island of Copinsay.', 58.9219, -2.7532),
('04f7a6c2-19fc-5e47-869b-3bc349d02bae', 'Docharn Woods circuit, Carrbridge', 'https://www.walkhighlands.co.uk/cairngorms/carrbridge.shtml', 7.5, 125, 2.0, 'There are many possible circular walks through the beautiful pinewoods that almost surround Carrbridge. This route takes in some of the quieter, informal paths in Docharn Woods, revealing some great views towards the Cairngorms.', 57.2825, -3.8136),
('05047726-0eb9-525d-b51f-4adad468e77e', 'Stonefield Castle and Barmore Island', 'https://www.walkhighlands.co.uk/argyll/stonefield-castle.shtml', 2.75, 60, 1.0, 'Stonefield Castle dates back to 1837 and is now a hotel. The walk descends through the gardens to make an idyllic round of Barmore Island.', 55.8908, -5.41758),
('05240851-8da0-5bed-bb71-3cfcc3f19a2e', 'Dunskey Castle from Portpatrick', 'https://www.walkhighlands.co.uk/galloway/dunskey-castle.shtml', 2.0, 55, 1.0, 'A short circular walk along the cliffs to the south of Portpatrick to the ruins of Dunskey Castle and returning on a disused railway line. Good coastal scenery.', 54.839, -5.1163),
('05bb06ef-74c7-510f-b9d3-07bd1f9ddfe3', 'Dùn Ringill, Kilmarie', 'https://www.walkhighlands.co.uk/skye/dunringill.shtml', 3.0, 27, 1.5, 'A short, attractive walk to the remains of a medieval castle, visiting a Chambered Cairn on the way back.', 57.1812, -6.0516),
('05d9df75-3fce-5080-a93b-510010d50d52', 'Hough Bay and Beinn', 'https://www.walkhighlands.co.uk/islands/hough-bay.shtml', 6.0, 149, 2.5, 'Stride out across the Machair towards Tiree''s most westerly point, overlooking one of its very finest beaches. The walk then continues along the stonier Hough Bay before a rougher climb up to the two summits of Beinn Hough - the island''s second highest hill.', 56.4994, -6.9633),
('061fbb24-d98f-5956-84ec-54e2516ec216', 'Sgùrr Cos na Breachd-laoidh, Loch Arkaig', 'https://www.walkhighlands.co.uk/fortwilliam/sgurr-cos-na-breachd-laoidh.shtml', 13.0, 861, 7.0, 'This excellent walk around a rocky ridge horseshoe is straightforward by the standards of the Rough Bounds of Knoydart - but gives characteristically excellent views of this mountainous corner.', 56.9715, -5.3122),
('0636738c-2732-5f9f-935a-f9135e48c77c', 'Fethaland from Isbister', 'https://www.walkhighlands.co.uk/shetland/fethaland.shtml', 10.0, 345, 4.0, 'Head out to the northermost point of Mainland Shetland on this classic walk. A rough coastal stretch leads to the haunting remains of an old fishing station and some dramatic cliff scenery.', 60.5997, -1.3239),
('06389441-b5b7-5776-aea1-1c8918912815', 'West Avonside and Knock Earth House, Strath Avon', 'https://www.walkhighlands.co.uk/cairngorms/west-avonside.shtml', 7.0, 84, 2.5, 'Explore the quiet rolling countryside of Strath Avon and the mysterious Earth House before following the river and returning on a minor road.', 57.3214, -3.4053),
('064659c5-2923-538b-bd7e-aa43b34b768f', 'Beinn na h-Uamha', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-na-h-uamha.shtml', 16.0, 835, 8.0, 'This rather neglected hill lies in very heart of Ardgour. Beinn na h-Uamha may only just scrape Corbett status, but it exhibits the great ruggedness characteristic of the area, with steep rocky slopes and grand views across Loch Linnhe and of nearby Sgùrr Dhònuill and Garbh Bheinn.', 56.7145, -5.3045),
('067f56ce-6ab8-5954-9567-fb0266c89f26', 'Kildonan Castle', 'https://www.walkhighlands.co.uk/arran/kildonan-castle.shtml', 0.8, 25, 0.5, 'This very short circular walk crosses a beautiful sandy beach before ascending to view the ruins of Kildonan Castle. Despite its brevity, the section along the shore is rough going over rocks and seaweed, and the path up to the castle becomes overgrown in summer.', 55.442, -5.1101),
('06958673-9507-5abe-b69c-243fed1a97f5', 'Carbisdale Castle circuit', 'https://www.walkhighlands.co.uk/sutherland/carbisdale-castle.shtml', 6.25, 206, 2.5, 'This walk explores the woodland paths above Carbisdale Castle overlooking the Kyle of Sutherland. It gives excellent views, passing the castle and a very attractive forest loch as well as the site of the Battle of Carbisdale.', 57.925, -4.401),
('06c53726-671f-553d-957f-fc6e4d726328', 'Craigmonie and the Divach Falls, Drumnadrochit', 'https://www.walkhighlands.co.uk/lochness/Craigmonie.shtml', 10.0, 278, 4.0, 'This route enjoys great views towards Loch Ness from the hilltop fort site of Craigmonie and then continues to visit the spectacular Divach Falls.', 57.3353, -4.48),
('06db2341-82d9-54cd-bacd-88e116d00881', 'Knockfarrel and Cnoc Mòr, Strathpeffer', 'https://www.walkhighlands.co.uk/lochness/Knockfarrel.shtml', 7.0, 255, 2.0, 'This superb walk follows paths across the flanks of the hill overlooking Strathpeffer before climbing up to the ridge to visit the site of a vitrified fort with wonderful views. It then continues along the ridge to a minor summit before a final, rougher descent.', 57.5801, -4.5455),
('0721c02e-d535-5ab3-acf0-8701a5be99c8', 'Drumlanrig Castle & Burnmouth Bridge circuit', 'https://www.walkhighlands.co.uk/galloway/drumlanrig-castle.shtml', 15.75, 162, 4.5, 'Follow the River Nith upstream along tree-lined banks from Drumlanrig Castle before heading back along a quiet, minor road with good views of the hills and surrounding countryside.', 55.2748, -3.8096),
('076c834b-1f48-55da-879c-ff1a900f33cd', 'Gardenstown and Crovie', 'https://www.walkhighlands.co.uk/aberdeenshire/gardenstown-crovie.shtml', 4.5, 138, 1.5, 'The oldest part of Gardenstown - Seatown - is a tightly packed huddle of houses hemmed in by the cliffs. This walk links this old fishing village by the old shore route to picturesque but tiny Crovie before returning along a new clifftop path.', 57.6743, -2.3332),
('076d107c-5866-5840-aba5-649a15b0c543', 'Dùn Deardail fort, Glen Nevis', 'https://www.walkhighlands.co.uk/fortwilliam/dun-deardail.shtml', 10.0, 314, 3.5, 'Dùn Deardail is an iron-age fort whose outline can still be seen as grassy embankments. The fort has a spectacular hilltop location with stunning views and makes a worthy objective on this waymarked walk from Glen Nevis.', 56.816, -5.0792),
('0808c005-8672-5acd-b383-422a599d64e2', 'Ladder Hills: Càrn Mòr from Chapeltown', 'https://www.walkhighlands.co.uk/cairngorms/ladder-hills.shtml', 14.5, 519, 5.0, 'Càrn Mòr is the highest of the Ladder Hills; it could be ascended from the Lecht summit but this circular route from Chapeltown in Glenlivet makes a much more enjoyable outing.', 57.273, -3.2578),
('081e45d1-0443-589b-a14b-a2ce26b7d932', 'Dùn Totaig from Letterfearn', 'https://www.walkhighlands.co.uk/kintail/duntotaig.shtml', 6.75, 282, 2.5, 'A lovely walk along the shore of Loch Duich, with good views of Eilean Donan Castle, to the slipway and cottage at Totaig and then through woodland to visit the impressive remains of an iron age broch. There are superb views across the loch.', 57.2562, -5.51021),
('0831a552-4961-54bc-a4b7-dea05a0a134f', 'Eilean Fhianain, Dalelia', 'https://www.walkhighlands.co.uk/fortwilliam/eilean-fhianain.shtml', 4.5, 15, 1.5, 'This delightful walk follows a farm track from Dalelia, passing a memorial as it leads near the shores of Loch Shiel to the pier overlooking Eilean Fhianian - an old island burial ground in Loch Shiel.', 56.7585, -5.7089),
('085b53ef-01ca-550e-bd64-407947a09e97', 'An Aird, Braes', 'https://www.walkhighlands.co.uk/skye/anaird.shtml', 3.0, 115, 2.0, 'The An Aird peninsula is beautifully situated and has excellent coastal scenery itself, making a delightful short walk.', 57.3379, -6.1141),
('0889a555-62e8-5bb9-8dda-1d04614fb0b1', 'Macleod''s Stone and Tràigh Iar', 'https://www.walkhighlands.co.uk/outer-hebrides/macleods-stone.shtml', 2.5, 69, 1.0, 'This short walk crosses the stunningly beautiful sands of Tràigh Iar before climbing up to visit a massive standing stone. The route then passes over a low hill to reach the equally fine beach of Tràigh Niosaboit before returning beside the road; great views throughout.', 57.8597, -6.9936),
('091d8d8a-8207-5f0d-8a25-f64a03ee40fa', 'Red Point Beaches', 'https://www.walkhighlands.co.uk/torridon/Redpoint.shtml', 5.0, 85, 2.5, 'There are two spectacular sandy beaches at Red Point; this walk combines both to make a short but rough circuit with great views out to the islands on a fine day.', 57.6508, -5.80334),
('09206cb7-e19b-50e9-8ba3-d03ad5f45f44', 'Ailsa Craig - the ascent', 'https://www.walkhighlands.co.uk/glasgow/ailsa-craig.shtml', 3.0, 342, 2.5, 'The dramatic granite outpost of Ailsa Craig is an icon amongst Scotland''s smaller islands. The island can be visited on a boat trip from Girvan; the ascent to its highest point as described here is extremely steep and rough: it gives a real hillwalking challenge but an unforgettable one.', 55.2536, -5.1095),
('0925edee-faa8-5c89-acf4-546aeb224d4c', 'Papa Westray - the island circuit', 'https://www.walkhighlands.co.uk/orkney/papa-westray.shtml', 19.5, 150, 8.0, 'Papa Westray is one of the smaller and more remote islands of Orkney, but it is packed with interest. This full coastal circuit of the island takes in northern Europe''s oldest standing house, one of northern Scotland''s most ancient churches, sandy beaches, rocky cliffs and spectacular colonies of seabirds. The walk be can shortened by cutting across the island at several points. In the summer months there are several ferries a day to Moclett Pier from Gill Pier near Pierowall on Westray, enabling the walk to be done in a day visit from the larger nearby island. Out of season there are fewer ferries and a day visit may be reliant on using a flight between the two islands - the shortest in the world.', 59.3273, -2.89),
('096793d0-7e69-58d1-90b6-22534dbcfbb6', 'Carradale Bay and Point', 'https://www.walkhighlands.co.uk/argyll/carradale.shtml', 8.0, 105, 2.5, 'This delightful walk explores the surroundings of Carradale, including the ancient fort at Carradale Point with superb sea views. The return takes in the stunning long sandy breach of Carradale Bay.', 55.5923, -5.4636),
('098b0bf4-33a9-5f52-a27a-5d19c47ecc39', 'Kyles of Bute', 'https://www.walkhighlands.co.uk/argyll/kyles-of-bute.shtml', 9.0, 150, 3.5, 'The Kyles of Bute is one of the most stunning areas of coastal scenery in Argyll. This linear walk, part of the Cowal Way, runs along a beautiful coastal track before reaching an adventurous but exciting section of path that threads a route between boulders, over walkways and rough ground. If arranging return transport is difficult, it may be possibleto catch a bus from the A8003 at the far end of the walk to get back to Tighnabruaich - or you could double the length and time given by returning the same way.', 55.9063, -5.2336),
('09986446-0f31-54ac-a67c-12cee5252ec2', 'Beinn Maol Chaluim, from Glen Etive', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-maol-chaluim.shtml', 8.0, 844, 6.0, 'Beinn Maol Chaluim lies behind its great neighbour Bidean nam Bian and is thus hidden from Glencoe except for a glimpse from the village. The steep slopes of Bidean deter any walk linking the two mountains - instead Beinn Maol Chaluim is almost invariably climbed from Glen Etive. It gives a fairly short hillwalk, with rugged going lower down but crowned by the final ridge traverse with excellent views.', 56.6008, -5.0167),
('09c5c0c1-9f5a-570a-83a7-7b2ff96d427e', 'Rosemarkie beach and Hillockhead circuit', 'https://www.walkhighlands.co.uk/lochness/rosemarkie.shtml', 9.25, 217, 3.5, 'This circular walk has great variety. Starting with a sandy beach, it continues along a rough and rocky coastline. A steep climb gives fine views before the walk continues with country lanes and then a final descent through a lovely wooded glen, complete with waterfalls.', 57.5918, -4.1146),
('09c9260e-adfd-5315-8457-76c32999bb1a', 'Inversnaid RSPB nature trail', 'https://www.walkhighlands.co.uk/lochlomond/inversnaid.shtml', 2.5, 145, 1.0, 'This short but steep little nature trail explores the stunningly beautiful oakwoods on the east side of Loch Lomond. Inversnaid was celebrated in poetry by Gerard Manley Hopkins.', 56.243, -4.6855),
('09e49cac-c08c-51c1-9c08-9e2d32d6063d', 'Stranburgh Ness, Fetlar', 'https://www.walkhighlands.co.uk/shetland/stranburgh-ness.shtml', 9.5, 296, 3.5, 'This wonderful walk takes in some of Fetlar''s most stunning coastal clifftop scenery, becoming wilder in the second half before returning via the old fishing station at Funzie and through croftland on minor roads.', 60.5982, -0.7947),
('09e6e4ba-ffdb-5231-96ae-512b692060c9', 'Mount Keen from Glen Esk', 'https://www.walkhighlands.co.uk/angus/mount-keen.shtml', 17.5, 681, 6.0, 'Mount Keen is the most easterly of the Munros, taking the form of a dome rising above vast swathes of empty, bleak moorland, with extensive views on a good day. The ascent from Glen Esk via Glen Mark is the shortest route and gives good going underfoot.', 56.9115, -2.91052),
('0a202bf0-3187-5641-a97b-0c3b8be82c7b', 'Cademuir Hill forest, near Peebles', 'https://www.walkhighlands.co.uk/borders/cademuir-hill.shtml', 5.0, 219, 2.0, 'This waymarked figure-of-eight forestry walk ascends to the summit of Cademuir Hill, a Sub 2000 or Marilyn. It offers superb views, but young trees will obscure them in time.', 55.6327, -3.1966),
('0a22b407-ad42-5be7-b2db-612a8a3e99ab', 'Calgary Bay and the Art in Nature trail', 'https://www.walkhighlands.co.uk/mull/calgary-beach.shtml', 3.0, 60, 2.0, 'Calgary Bay is Mull''s best known and perhaps finest sandy beach. Adjacent to it is Calgary Wood, home to the ''Art in Nature'' project; dotted amongst the trees are some beautiful sculptures and other artworks. There is also an excellent tea room.', 56.5829, -6.2716),
('0ae08a1c-d5ef-51f6-a3bf-4119f7dc181b', 'Creach Bheinn, from Druimavuic', 'https://www.walkhighlands.co.uk/argyll/creach-bheinn.shtml', 14.25, 899, 6.0, 'Creach Bheinn is a rather sprawling summit, but its position above the western seaboard gives it superlative views out to the islands of Lismore and Mull as well as towards the Glencoe peaks.', 56.5556, -5.2412),
('0aecae24-e5c1-5e56-b093-17d063c795bc', 'Nethy Bridge riverside and Dell woods', 'https://www.walkhighlands.co.uk/cairngorms/nethybridge.shtml', 3.0, 30, 1.0, 'This is a walk of two halves, the first alongside the burbling River Nethy and then through beautiful Dell Woods (a National Nature Reserve) to return to Nethy Bridge. An easy short walk on good, waymarked paths, with plenty of variety and the option to extend the walk.', 57.2644, -3.6568),
('0b0e57db-09cf-5a8f-afeb-778644a682a7', 'Beinn Odhar, Beinn Chaorach and Cam Chreag', 'https://www.walkhighlands.co.uk/argyll/beinn-odhar-cam-chreag.shtml', 21.0, 1367, 8.0, 'These three grassy Corbetts make an enjoyable round from Tyndrum. Beinn Odhar is a graceful cone with fine views; there is then a very steep descent and climb to reach the very rounded Beinn Chaorach, well-named as the hill of the sheep. The final summit, Cam Chreag, is a little more rocky before a lengthy descent and return to Tyndrum via the West Highland Way.', 56.4363, -4.7114),
('0b543fc0-a89b-5292-a60e-7327e644dd9b', 'The Port of Leith, Edinburgh', 'https://www.walkhighlands.co.uk/lothian/port-of-leith.shtml', 3.0, 1, 1.0, 'Starting from Ocean Terminal in Leith, the shopping mall where the Royal Yacht Britannia is berthed and can be visited, this short route explores the old docks, and the newly regenerated quayside buildings of Edinburgh''s old port. As the route heads along a short section of the Water of Leith many restaurants and bars are passed.', 55.9816, -3.17568),
('0b5b22d2-2023-5472-9cc9-8e9b9cd806df', 'Roineabhal, from Rodel', 'https://www.walkhighlands.co.uk/outer-hebrides/roineabhal.shtml', 7.5, 453, 4.0, 'Roineabhal is the highest summit of the bare, rocky, lunar-like landscape of southeastern Harris. The ascent is rough and pathless, but is rewarded with superb views over the sea and surrounding islands.', 57.7411, -6.9623),
('0b7fd718-92d0-544e-88bc-80f9edd59b64', 'Bidean nam Bian', 'https://www.walkhighlands.co.uk/fortwilliam/bideannambian.shtml', 11.0, 1316, 9.0, 'The highest mountain in the old county of Argyll, Bidean nam Bian is the whole majestic range of mountains on the south side of Glen Coe. It''s dramatic northern ridges are known as the Three Sisters, whilst the highest summits of the group are hidden away behind.', 56.6677, -4.9865),
('0c02b9da-05a3-52b1-a05f-1254c3a8cd0d', 'Beaver Trail, Rothiemurchus', 'https://www.walkhighlands.co.uk/cairngorms/beaver-trail-rothiemurchus.shtml', 7.0, 75, 2.0, 'Visit Lochan Mor in Rothiemurchus Forest, to which beavers were reintroduced to the Cairngorms National Park in 2023. The route continues along forest paths and a minor road to reach Loch an Eilein, with its famed ruined castle. The route returns on tracks and roads through farmland and forestry.', 57.1768, -3.8198),
('0c22aadc-4f31-5c94-95ba-566ca303d71e', 'River Spey circuit, Aviemore', 'https://www.walkhighlands.co.uk/cairngorms/river-spey.shtml', 10.5, 75, 3.0, 'This circular walk follows the banks of the beautiful River Spey downstream from Aviemore, before returning on the Speyside Way. There are great views to the distant Cairngorms.', 57.2029, -3.8184),
('0c9ec28f-fbaf-50a8-9e1b-1989632e7ce2', 'Port na Murrach, near Arisaig', 'https://www.walkhighlands.co.uk/fortwilliam/port-na-murrach.shtml', 4.5, 85, 2.0, 'This popular walk heads out from the end of the Rhu road to visit a secluded and sheltered sandy beach, with great views to the Small Isles along the way.', 56.8967, -5.89776),
('0ca451e7-4906-5fd8-9746-8f93577d4b2b', 'Craig Rossie, near Auchterarder', 'https://www.walkhighlands.co.uk/perthshire/craig-rossie.shtml', 6.5, 357, 3.0, 'One of the more northerly of the Ochils, Craig Rossie presents a bold profile and challenge to travellers along the nearby A9. The ascent is steep and sustained but grassy, and makes for an enjoyable circular walk with extensive views. The route is not marked and paths are faint at times.', 56.301, -3.6525),
('0cb4e6b0-19cb-5c59-9b28-5a2d1156c385', 'Water of Minnoch circuit, Glen Trool', 'https://www.walkhighlands.co.uk/galloway/water-of-minnoch.shtml', 11.25, 113, 3.5, 'Follow part of the Southern Upland Way then woodland paths and forestry tracks on this pretty circuit which takes in lovely riverside sections, mixed woodland as well as open areas with mountain views.', 55.0748, -4.552),
('0cbf2f0b-a69d-541b-a963-3854372f856a', 'Balnakailly circuit, Rhubodach', 'https://www.walkhighlands.co.uk/argyll/rhubodach.shtml', 6.25, 143, 2.0, 'This waymarked circuit from the Rhubodach ferry explores the northernmost part of Bute. The walk climbs up through beautiful deciduous woodland to visit a deserted farm. It then continues up to reach a fine viewpoint overlooking the Kyles. The return is on forestry tracks and then on the road by the shore.', 55.9204, -5.1586),
('0cce1a57-81c5-55e1-934a-290913b9a5e4', 'Athelstaneford and the Garleton Hills, Athelstaneford', 'https://www.walkhighlands.co.uk/lothian/garleton-hills.shtml', 6.25, 131, 2.0, 'Although the Garelton Hills are very modest, rising above rolling farmland, they still provide a panoramic walk along their spine with excellent views over much of East Lothian.', 55.9866, -2.74684),
('0cea64a4-3b3a-5404-9d86-ab330ee7062b', 'Roslin Glen and Rosslyn Chapel, Roslin', 'https://www.walkhighlands.co.uk/lothian/roslin-glen.shtml', 4.25, 120, 2.0, 'Explore the countryside and dramatic wooden gorge of Rosslyn Glen to pass the semi-ruined Rosslyn Castle. A good walk to combine with a visit to Rosslyn Chapel.', 55.8558, -3.1612),
('0d0eac0f-d3fc-5721-bdf8-d819669ca9c2', 'Ben Nevis by the Càrn Mòr Dearg Arête', 'https://www.walkhighlands.co.uk/fortwilliam/carnmordeargarete.shtml', 17.5, 1506, 11.0, 'For experienced, fit mountain walkers who do not mind easy scrambling but are not climbers, this is the finest way to climb Ben Nevis. This is a truly spectacular route incorporating two Munros. It will live long in the memory and does true justice to the mountain.', 56.8419, -5.0432),
('0d21e35d-2c65-5ae0-adeb-32dde0330fae', 'Sgor Gaoithe, Cromdale Hills', 'https://www.walkhighlands.co.uk/cairngorms/gaoithe-cromdale.shtml', 3.5, 251, 2.0, 'The westernmost of the Cromdale Hills may be only a minor summit, but it has by far the best views in the range, with a truly magnficient outlook towards the Cairngorms and over Strathspey. An excellent introduction to hillwalking on a fine day.', 57.2808, -3.55855),
('0dbe693c-f8e1-5619-aaed-3b2e97cc5eea', 'Graemsay island circuit', 'https://www.walkhighlands.co.uk/orkney/graemsay.shtml', 9.75, 150, 4.0, 'Explore ''Orkney''s Green Isle'' - as Graemsay is known locally - passing the two lighthouses, a sandy beach, WWII gun emplacements. You''ll probably have this coastal circuit to yourself, the seabirds and seals.', 58.9312, -3.2677),
('0dd26540-1768-5c4b-aa4f-e38a31ce5d34', 'Mount Hill and the Hopetoun Monument, Cupar', 'https://www.walkhighlands.co.uk/fife-stirling/mount-hill.shtml', 12.5, 209, 4.0, 'Thanks to the slender cylindrical tower of the Hopetoun Monument, Mount Hill is a real landmark in the Howe of Fife. There''s a public path to the summit - but one thing prevents it becoming a popular walk, and that''s a lack of parking. We describe the route here with an approach along quiet country roads from Cupar which has proper parking; if you have a bike for the approach, that would be ideal. If you wish to shorten the route, it''s possible for one car to park very carefully on the grass verge near a tree mentioned in the text.', 56.3222, -3.02881),
('0e2c612b-9c3d-5239-8d2d-c4248b22b648', 'Loch Lomond Shores walk, Balloch', 'https://www.walkhighlands.co.uk/lochlomond/lomond-shores.shtml', 1.0, 10, 0.5, 'This short stroll from the Loch Lomond Shores shopping complex makes a good leg stretch or family walk and is suitable for baby buggies and some wheelchairs.', 56.0046, -4.5937),
('0f005551-33a3-5500-9ec5-9a925b530c17', 'Coille Iòsal, Braes', 'https://www.walkhighlands.co.uk/skye/braes.shtml', 2.0, 111, 0.75, 'This short walk is set in the heart of the lovely Braes area south of Portree. It climbs up through native woodland to visit a waterfall before a more open return giving great views across the Sound to Raasay and Ben Tianavaig.', 57.3523, -6.1329),
('0f2232c0-e2ea-5071-bce4-d4772bb318dc', 'Knock Hill from Swilebog', 'https://www.walkhighlands.co.uk/aberdeenshire/knock-hill.shtml', 2.25, 236, 2.0, 'A short but steep climb to the summit of Knock Hill which has expansive views and a moorland feel, return is by the same route.', 57.5854, -2.7584),
('0f349a43-e2e3-5679-bc43-b3f922cff602', 'Camas Tuath, near Bunessan', 'https://www.walkhighlands.co.uk/mull/camas-tuath.shtml', 3.75, 54, 1.0, 'A short pleasant walk to the beautiful bay at Camas Tuath opposite an old pink granite quarry - optional extension to the sandy beach at Market Bay. A good family walk.', 56.3249, -6.3068),
('0f7c345a-b74d-5a24-9157-d9f2d2912ba8', 'Dunan - the Camel''s Hump, Ardnadam', 'https://www.walkhighlands.co.uk/argyll/ardnadam.shtml', 4.5, 192, 1.5, 'Climb through the Atlantic Oakwoods past an archaeological site to reach the hilltop of Dunan - locally known as the Camel''s Hump - for its superb views over Dunoon, the Clyde and the Holy Loch.', 55.9743, -4.948),
('0fa4555b-dba4-5e22-9525-2f7d39749ddf', 'Falls of Falloch', 'https://www.walkhighlands.co.uk/lochlomond/falls-of-falloch.shtml', 0.6, 10, 0.3333333333333333, 'A very short leg-stretcher to this popular waterfall and picnic spot, where the River Falloch falls in a single 10m leap, particularly impressive when in spate.', 56.3497, -4.69746),
('0fd248fc-2431-5e04-92d1-afbb5ee55bb4', 'Meallach Mhòr and Croidh-la, Glen Tromie', 'https://www.walkhighlands.co.uk/cairngorms/meallach-mhor.shtml', 25.0, 734, 8.0, 'Though a rather rounded and undistinguished hill in itself, Meallach Mhòr occupies a fine position and is a good viewpoint. The quickest approach is along Glen Tromie (easy MTB cycle), with wonderful regenerating native woodlands. The route described here makes a fuller day by returning along the heathery ridge that ends at Croidh-la - offering really superb views over the Strath.', 57.0733, -4.0227),
('0fe19e90-6cf5-589e-bfec-5bc03f80995b', 'Loch an Nostarie circuit, Mallaig', 'https://www.walkhighlands.co.uk/fortwilliam/lochnostarie.shtml', 6.0, 225, 3.0, 'This circular walk combines sea views with a visit to an attractive hill loch; the downside is that the terrain on the middle part of the walk is often very wet underfoot. For a very short and easy visit to Loch an Nostarie - with dry feet - try walking just the first section of theLoch Eiregoraidhroute as far as the picnic table.', 57.0045, -5.82371),
('0fec0f54-f26b-5b08-8338-102be7f5288f', 'Lunna Ness circuit, from Outrabister', 'https://www.walkhighlands.co.uk/shetland/lunna-ness.shtml', 11.0, 224, 4.0, 'A moorland exploration of the peninsula of Lunna Ness taking in the dramatic Stanes of Stofast before reaching the headland and returning along the coast, home to otters and numerous seals.', 60.4326, -1.0874),
('10400dfa-8a4f-5630-b2cb-f1d7428f928d', 'Inverbervie to Johnshaven', 'https://www.walkhighlands.co.uk/aberdeenshire/inverbervie-johnshaven.shtml', 7.5, 31, 2.0, 'This easy-going linear coastal walk traces the coastline south from Innerbervie, passing Gourdon harbour and continuing on to Johnshaven. The return can be made by bus.', 56.8456, -2.278),
('104a8468-51c2-5f3f-b271-b0989c41bc30', 'Beinn Trilleachan, Glen Etive', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-trilleachan.shtml', 8.75, 1000, 7.0, 'Beinn Trilleachan is famed for the rock-climbs on the Trilleachan Slabs high above Loch Etive. For hillwalkers, the mountain provides an enjoyable outing with stunning views.', 56.5688, -5.0812),
('10a4ca1a-0313-5611-8b2f-ac62ec6ee8e6', 'Rubha Ardnish, Broadford', 'https://www.walkhighlands.co.uk/skye/rubhaardnish.shtml', 6.5, 17, 2.0, 'A pleasant though pathless walk on a little-visited part of Skye''s coast. Excellent for bird- and wildlife watching, as well as for the views in fine weather.', 57.238, -5.8847),
('11670bf4-c549-55fb-b0e8-2004ffe6b197', 'Glenashdale Falls & Giant''s Graves, Whiting Bay', 'https://www.walkhighlands.co.uk/arran/glenashdale-falls.shtml', 4.75, 152, 2.0, 'This superb circular walk climbs up through a wooded glen to reach a viewing platform for the Glenashdale Falls - a double cascade which is the finest on Arran. The route then continues to visit the Giant''s Graves - two chambered cairns - with a fantastic outlook over Whiting Bay and Holy Island.', 55.4827, -5.0926),
('11914024-d93c-5c88-8eb8-b28e36b4bb33', 'Castle Semple Loch, Lochwinnoch', 'https://www.walkhighlands.co.uk/glasgow/castle-semple.shtml', 6.25, 92, 2.0, 'This lovely waymarked walk begins along the shores of beautiful Castle Semple Loch. It then heads into the woods before climbing to a viewpoint with views over several lochs, before heading through the trees to reach the beautifully situated ruins of a collegiate church.', 55.7969, -4.6207),
('11a3f171-9e0e-5eaa-99a8-0d6304b79370', 'Port Appin circuit', 'https://www.walkhighlands.co.uk/argyll/portappin.shtml', 2.5, 71, 1.5, 'An easy-going coastal walk taking in the headland beyond Port Appin with fine views over Lismore and out towards Mull.', 56.5533, -5.41377),
('11a707c5-425b-51b8-8f52-68c1a5cdd4bd', 'Chno Dearg and Stob Coire Sgriodain', 'https://www.walkhighlands.co.uk/fortwilliam/chnodearg.shtml', 13.5, 915, 7.0, 'Chno Dearg is an undistinguished rounded mountain which would be little visited if it were not a Munro; it''s neighbour Stob Coire Sgriodain is much rockier with some real character - it is also a stunning viewpoint.', 56.8655, -4.7085),
('120bae5c-ce71-505c-ac74-21187fa87bd7', 'Millfore from Black Loch', 'https://www.walkhighlands.co.uk/galloway/millfore.shtml', 11.0, 553, 5.0, 'Millfore exceeds two thousand feet but is one of the less visited of the Galloway hills. Its ascent is fairly short but rough, and is rewarded with a superb outlook over its neighbours and Loch Dee.', 55.029, -4.3497),
('1221f38b-74b4-52ad-9422-38a7b255cb48', 'Noup Head, Westray', 'https://www.walkhighlands.co.uk/orkney/noup-head.shtml', 7.0, 195, 2.5, 'This fine circuit visits the spectacular coastal cliffs and seabird colonies of Noup Head - an RSPB reserve, replete with stacks, arches and caves. After reaching the lighthouse the return is along a good track.', 59.3161, -3.0348),
('127e880d-3955-56fc-b852-21b43a145757', 'St Cyrus beach and cliff, St Cyrus', 'https://www.walkhighlands.co.uk/aberdeenshire/st-cyrus.shtml', 5.0, 93, 1.5, 'Head out along the fine sand of St Cyrus beach before climbing the cliffs for spectacular views and then return below the cliffs passing old salmon bothies in the nature reserve renowned for its grasslands, rare flowers and butterflies and moths. The walk can also be started from St Cyrus village.', 56.7614, -2.4243),
('12812168-838b-55e3-aa05-6bdaade38986', 'Tarbet Isle Walk, near Tarbet', 'https://www.walkhighlands.co.uk/lochlomond/tarbet-isle.shtml', 2.0, 55, 0.75, 'An easy circuit which climbs gently through pine woods and then oak woodland with good views over Loch Lomond and Tarbet Isle below.', 56.2115, -4.7),
('12a0d955-b0c5-5c04-9f49-64dfde99d04f', 'White Coomb by the Grey Mare''s Tail', 'https://www.walkhighlands.co.uk/galloway/white-coomb.shtml', 11.5, 751, 6.0, 'White Coomb is the highest of the Moffat hills. This circular hillwak is the classic approach, heading up past the spectacular Grey Mare''s Tail to beautiful Loch Skeen. It then encounters some tough going before reaching the tops at Lochcraig Head. From here broad ridges are followed arouFnd to the summit of White Coomb.', 55.4176, -3.2874),
('12d698d5-390b-5076-b326-5b3d07c884db', 'Cauldshiels Loch and the River Tweed, Melrose', 'https://www.walkhighlands.co.uk/borders/cauldshiels-loch.shtml', 14.25, 234, 4.0, 'A varied walk starting from Melrose and climbing through newly planted woodland and farmland to tranquil Cauldshiels Loch before descending to the River Tweed which is followed back to Melrose. The route passes Abbotsford, the home of Sir Walter Scott, which could be visited as a detour.', 55.5987, -2.7194),
('12e6cb19-eba7-54f5-82b1-8ef42d40550a', 'Loch Rannoch Forest walk', 'https://www.walkhighlands.co.uk/perthshire/loch-rannoch.shtml', 8.2, 180, 2.0, 'This excellent waymarked walk combines easy walking on forest paths and tracks with beautiful mixed woodland, including remnants of the ancient Caledonia Forest. There are good views over Loch Rannoch towards the end..', 56.6849, -4.2589),
('13624f0b-bfff-5593-80af-36e6eeeca1cd', 'An Sìdhean from Loch Monar, Glen Strathfarrar', 'https://www.walkhighlands.co.uk/lochness/an-sidhean.shtml', 17.0, 892, 7.0, 'This rather flat-topped Corbett lies in the heart of a wild and remote part of the Highlands, but access via the road up Glen Strathfarrar and good stalkers paths on the approach make it a relatively straightforward walk in beautiful surroundings. The difficulty is reduced to Grade 3 if the outward route is retraced for the return.', 57.4097, -4.9917),
('13ccd1e9-39e7-5dfc-ac63-99af39c2e7f0', 'Fife Coastal Path 8: Crail to Kingsbarns', 'https://www.walkhighlands.co.uk/fife-stirling/crail-kingsbarns.shtml', 9.5, 65, 3.5, 'This is the remotest part of the Fife Coast Path, heading from picturesque Crail and around the headland of Fife Ness. Some sections are impassable at high tide. This is a one-way walk; return is possible by bus. Keen walkers can double the length of the walk by continuing from Kingsbarns to St Andrews.', 56.2587, -2.6285),
('142f4642-bdc8-5d99-9a57-eec962e683bf', 'Beinn Sgritheall', 'https://www.walkhighlands.co.uk/kintail/Beinnsgritheall.shtml', 10.0, 1095, 6.0, 'Beinn Sgritheall gives a steep and punishing ascent; the effort is well worthwhile however as this is one of the finest viewpoints in the Highlands, with a fantastic outlook over dramatic Loch Hourn to Knoydart and the Cuillin of Skye.', 57.1344, -5.5679),
('14444c7b-62f5-52d9-9f83-8fed9dccb028', 'Old Coffin Road, near Abriachan', 'https://www.walkhighlands.co.uk/lochness/coffin-road.shtml', 4.0, 224, 1.5, 'Follow an old coffin road as it climbs high through native birchwoods on the north side of Loch Ness, with superb views.', 57.3652, -4.3922),
('1461c320-fc69-5d61-928a-deed8cc5fbff', 'Glen Rosa and the Blue Pool', 'https://www.walkhighlands.co.uk/arran/glen-rosa.shtml', 9.0, 158, 3.0, 'Glen Rosa is a fine glen leading into the heart of Arran''s dramatic granite mountains. This circular route visits the glen and some of the beautiful pools in its river - including the small pool dubbed by Instagrammers as the ''Blue Pool''.', 55.5913, -5.1556),
('146d687e-b93f-50f5-985d-719f570c3cc0', 'Peniel Heugh and the Waterloo Monument, Harestanes', 'https://www.walkhighlands.co.uk/borders/peniel-heugh.shtml', 7.25, 172, 3.0, 'The massive Waterloo Monument on the grassy hill of Peniel Heugh is a landmark in many a Borders view. The straightforward ascent to visit it makes for an enjoyable round from Harestanes Visitor Centre.', 55.5124, -2.56936),
('14a6a680-a0f2-5158-8b97-d760401cef49', 'Isleburgh chambered cairn from Mavis Grind', 'https://www.walkhighlands.co.uk/shetland/mavis-grind.shtml', 2.25, 94, 1.0, 'Mainland Shetland is almost divided in two at Mavis Grind, with only a narrow neck of land joining the northermost part of the island - Northmavine - to the rest of Shetland. This short walk starts from the neck and visits a fine example of a heel-shaped chambered cairn.', 60.3974, -1.384),
('14a9236a-4579-5eab-8c87-785a287f5055', 'Mount Keen by Glen Tanar', 'https://www.walkhighlands.co.uk/cairngorms/mount-keen.shtml', 29.0, 896, 9.0, 'Mount Keen is the most easterly of the Munros, taking the form of a dome-shaped swelling above the general level of the vast Mounth plateaux. The shortest route to it is from Glen Esk in the south, but the finest is this longer approach through the magnificent pinewoods of Glen Tanar.', 57.0573, -2.8587),
('14df7fc6-0894-54c3-b91d-c5e5ff12ad34', 'Greenock Cut, Inverclyde', 'https://www.walkhighlands.co.uk/glasgow/greenock-cut.shtml', 11.5, 180, 3.0, 'This classic circuit climbs over moorland, dotted with reservoirs, before heading along the Greenock Cut - a historic aqueduct which once kept the industries of Greenock supplied with water. The route gives stunning views over the Clyde estuary towards the Highlands.', 55.9103, -4.8062),
('1585bb4e-4c5c-5a13-8678-09658c8fdda0', 'Preaching Cave and Kilpatrick Dun, Kilpatrick', 'https://www.walkhighlands.co.uk/arran/preaching-cave.shtml', 3.0, 90, 1.5, 'This route combines two short walks from the same car park. First it heads down to the coast to visit a large cave once used for religious services, then climbs over boggy farmland to visit the remains of Kilpatrick Dun, a homestead and iron age fort dating back 4,000 years and a good viewpoint.', 55.4903, -5.32107),
('158934c9-0cc2-539c-aec4-f95dfd822daa', 'Brora to Golspie coastal walk, Brora', 'https://www.walkhighlands.co.uk/sutherland/brora-golspie.shtml', 11.0, 42, 3.5, 'This excellent walk follows the coastline between Brora and Golspie; make use of the train for the return leg of the journey. The route has lots of interest including tiny harbours, sandy beaches, a well-preserved iron-age broch and Dunrobin Castle, the grandest house in the Highlands.', 58.0127, -3.8528),
('15a925e1-45d6-5e5b-bbce-dac267d6270e', 'Soldier''s Rock and Kintra circuit', 'https://www.walkhighlands.co.uk/islay-jura/soldiers-rock.shtml', 7.75, 175, 4.0, 'This rugged walk explores the moorland and deserted villages west of Kintra en route to a dramatic corner of the coastline with a fine sea-stack. The return keeps high above the sea before a very soggy descent through scrub.', 55.6545, -6.26112),
('16207205-2eae-5e4e-bfd1-0b1a7c86cc43', 'Lecht Mine from the Well of Lecht', 'https://www.walkhighlands.co.uk/cairngorms/lechd-mine.shtml', 1.5, 32, 0.5, 'This pleasant, very short and easy walk visits the isolated site of the former Lecht Mine.', 57.222, -3.2689),
('162692cc-cdab-5756-ba6e-11ae74e71e77', 'Tolsta Head and Tràigh Mhòr', 'https://www.walkhighlands.co.uk/outer-hebrides/tolsta-head.shtml', 10.25, 311, 3.5, 'Tolsta Head - Rubha Tholastaidh in Gaelic - is a cliff-girt headland projecting from the east coast of Lewis. This walk gives some fine coastal cliff scenery as well as bird and sea-mammal watching opportunities. A short but very steep descent then leads down to Tràigh Mhor, one of Lewis'' finest beaches.', 58.3404, -6.1978),
('16353437-3ab2-57ef-8f41-bd992df4c242', 'Oak Wood and Quarrelwood, Elgin', 'https://www.walkhighlands.co.uk/moray/quarrelwood.shtml', 3.5, 73, 1.5, 'This circular forest trail follows stone markers carved with a human footprint. It leads through the trees to visit the circular ditches and banks that form the remains of a henge 4,000 years old, which may have been used for ceremonies by our ancient ancestors. Look out for forest wildlife including roe deer and red squirrels.', 57.6537, -3.3462),
('163ac3dc-902a-51d5-9881-5390e918b5d4', 'Knock Hill circular, Largs', 'https://www.walkhighlands.co.uk/glasgow/knock-hill.shtml', 13.0, 268, 4.0, 'This longer walk combines the lower and higher variants of the Ayrshire Coastal Path to make a visit to the site of an old hillfort with spectacular views over Largs and the Firth of Clyde.', 55.7964, -4.8702),
('165c2a1b-e4da-587b-8039-3985a3d3df99', 'The Duchess''s Drive, Bowhill', 'https://www.walkhighlands.co.uk/borders/duchess-drive.shtml', 11.25, 339, 4.0, 'This walk follows the route of a Victorian Carriage drive and provides some of the feeling of space, openness and views of hillwalking whilst having an easy track underfoot. The route lies on the Bowhill Estate and there is a charge for admission at certain times of the year.', 55.5409, -2.9129),
('166a82bd-a629-5526-b7d7-7420c6c538f7', 'The Lochalsh Dirty 30 Challenge', 'https://www.walkhighlands.co.uk/kintail/dirty-30.shtml', 47.0, 1263, 60.0, 'The Dirty 30 circuit can be completed as a tough long day or 2 day circuit over varied ground with great views. An annual challenge is held in June - click on the banner for details.', 57.214, -5.6206),
('1670f9ad-3f87-5372-bd60-dba9a66e31dc', 'Glen Strathfarrar Munros circuit', 'https://www.walkhighlands.co.uk/lochness/strathfarrar-munros.shtml', 25.0, 1567, 10.0, 'A long walk with excellent views and increasing interest from the mountains and ridges further along the route. The walk back along the road, although picturesque, can be tiring at the end of the day, a bike could be used to shorten this section.', 57.4056, -4.8591),
('16ecd605-c03f-5bd0-8e06-8e585b2297b2', 'Lochmaddy and the Hut of the Shadows', 'https://www.walkhighlands.co.uk/outer-hebrides/lochmaddy.shtml', 7.25, 67, 2.5, 'A enjoyable exploration of the coastline of Lochmaddy, visiting a hidden camera obscura before heading through crofting land typical of North Uist.', 57.5976, -7.1587),
('16f8f3b8-c083-5e4b-806e-65e33eae8a1c', 'Breabag and the Caves of Assynt', 'https://www.walkhighlands.co.uk/ullapool/breabag.shtml', 20.0, 778, 9.0, 'Breabag may lack the dramatic outline of the other peaks in Assynt and Coigach, but it certainly provides plenty of interest. This route climbs up past the Bone Caves to make a fairly rapid ascent, but then heads north along a very rough ridge of quartzite before descending past more limestone caves to Inchnadamph. Returning to the Bone Caves car park is a 4km road walk.', 58.1156, -4.9666),
('170aef43-cf76-507b-9751-33e4538ba23c', 'Corrieshalloch Gorge, Braemore Junction', 'https://www.walkhighlands.co.uk/ullapool/corrieshalloch.shtml', 3.5, 87, 0.75, 'Test your head for heights on the dramatic bridge and viewing platform suspended over this dramatic gorge, while the water surges many metres below your feet. The surrounding walk has spectacular views of waterfalls and the open countryside towards Loch Broom.', 57.7524, -5.01255),
('175078e7-25ae-523f-8a82-1e5568712f4d', 'Change House Walk, Erchite Wood, Inverfarigaig', 'https://www.walkhighlands.co.uk/lochness/change-house.shtml', 3.0, 56, 1.0, 'Follow the shores of Loch Ness for a short but beautiful stretch to visit the site of an old inn. You could head back the same way, or cross the line of General Wade''s military road to climb through forestry to further glimpses over Loch Ness and Urquhart Castle, with a final stretch along the tarmac road.', 57.3238, -4.4082),
('176356df-4abe-5964-89be-0180e4b55485', 'Stob Ban (Grey Corries)', 'https://www.walkhighlands.co.uk/fortwilliam/stob-ban-grey-corries.shtml', 18.0, 852, 7.0, 'Stob Ban is rather hidden away behind the much higher peaks of the Grey Corries. However it is a steep and shapely peak in its own right, and well repays the approach walk. The tiny Lairig Leacach bothy sits at its foot.', 56.8683, -4.8637),
('178f74ee-70b4-567a-80f3-36453679263a', 'Beinn Chuirn, Dalrigh', 'https://www.walkhighlands.co.uk/argyll/beinn-chuirn.shtml', 16.0, 706, 6.0, 'Though rather overshadowed by its great neighbour Ben Lui, Beinn Chuirn still offers an enjoyable hillwalk with some good views.', 56.4251, -4.6869),
('17b2e209-6a10-56ee-aee8-fd3e2e7d399d', 'Bannockburn, near Stirling', 'https://www.walkhighlands.co.uk/fife-stirling/bannockburn.shtml', 5.25, 51, 1.5, 'Bannockburn, scene of Robert the Bruce''s famed victory over the English in 1314, has a fine statue of the Bruce and a visitor centre. The route described heads through fields, along the Bannock Burn itself, and through some modern housing areas and provides a good leg-stretcher following a visit to this historic site.', 56.0925, -3.935),
('17de8df3-a096-5f6b-a6a4-f7c07cd9061d', 'Loch Fleet and Balblair Wood', 'https://www.walkhighlands.co.uk/sutherland/loch-fleet.shtml', 7.5, 35, 2.0, 'A beautiful exploration of Loch Fleet National Nature Reserve, a haven for birds, deer and pine martens. This circular walk takes in the shoreline as well as beautiful Scots pine and birch woodland.', 57.9525, -4.0042),
('17e8ca89-c3c6-524e-ab97-2b5f5d2ae53d', 'Duncansby Head and John o''Groats', 'https://www.walkhighlands.co.uk/sutherland/duncansby-head.shtml', 8.5, 110, 3.0, 'John o''Groats is famed as the northeastern corner of the British Mainland and the small village receives a huge number of visitors. The true northeasterly point is nearby Duncansby Head, which has two truly spectacular sea-stacks just to the south. An excellent coastal walk.', 58.6434, -3.0687),
('1846d2a5-8c1e-5185-bab0-743038afc82a', 'Meikle Bin, Carron Valley', 'https://www.walkhighlands.co.uk/glasgow/meikle-bin.shtml', 10.0, 397, 3.0, 'The steep but easy climb to the summit of Meikle Bin rewards with excellent views over the reservoir and surrounding fields. Popular with families, it is a good challenge for little legs.', 56.0474, -4.1328),
('186daadb-4685-5a20-a92b-23884d043911', 'Ousdale Broch, near Berriedale', 'https://www.walkhighlands.co.uk/sutherland/ousdale-broch.shtml', 2.0, 110, 0.75, 'Following the completion of excavation work in 2020, Ousdale Broch now ranks as perhaps the finest example of these distinctive iron-age defensive structures in Caithness. The short walk to it across the moorland passes the Borg, the scant ruins of a nineteenth century settlement which was a victim of the Highland Clearances.', 58.1495, -3.5926),
('188e75b5-f845-50a5-b4af-e24c3b1899cc', 'The Falls of Bruar, near Blair Atholl', 'https://www.walkhighlands.co.uk/perthshire/falls-of-bruar.shtml', 2.5, 150, 1.5, 'A beautiful short but surprisingly strenuous walk with good views of the gorge and falls from two stone bridges and a picnic area.', 56.7704, -3.9305),
('18e02e99-374c-590c-96a9-e6d9795f84ba', 'Millstone Hill, near Bennachie', 'https://www.walkhighlands.co.uk/aberdeenshire/millstone-hill.shtml', 4.75, 320, 3.0, 'This fine circular walk ascends Millstone Hill, a southern neighbour of Bennachie. It offers a gradual transition from conifer plantations, through birchwoods, to heather hill-top and gives excellent views.', 57.2607, -2.5449),
('190a9fab-9e43-5d3f-965e-c2df66b1b280', 'Forest of Ae walks', 'https://www.walkhighlands.co.uk/galloway/forest-of-ae.shtml', 9.0, 116, 2.5, 'The Forest of Ae is one of the largest areas of plantation forestry in the country. It is well known as one of the 7 Stanes mountain biking trail centres, but it does have waymarked walks too. This loop takes in part of the forest as well as the riverside and a couple of viewpoints.', 55.1892, -3.5966),
('191ce807-5ede-5d7e-a276-7dabaedab1f9', 'Coall Head and Fladdabister Loch, Fladdabister', 'https://www.walkhighlands.co.uk/shetland/coull-head.shtml', 4.5, 128, 2.5, 'This varied walk starts with a rough moorland section visiting a freshwater loch and then descends to the coast via a whole series of ruined mills. It climbs up to the fine viewpoint Coall Head atop the cliffs before following the rugged coastline to Fladdabister.', 60.0783, -1.2251),
('19696ae6-415d-59d2-8ec3-68aefe1aa60f', 'River Garry, Invergarry', 'https://www.walkhighlands.co.uk/fortwilliam/invergarry.shtml', 5.75, 70, 2.0, 'This delightful circuit explores the banks of the River Garry, which are beautifully wooded, from Invergarry. The walk can easily be extended to adding on the Ciste Dubh walk.', 57.0684, -4.80415),
('196d4513-4894-5103-adb2-1ec53ebc7bea', 'Bishop Hill circular from Scotlandwell', 'https://www.walkhighlands.co.uk/fife-stirling/bishop-hill-scotlandwell.shtml', 6.75, 414, 3.5, 'This short but steep hillwalk climbs up the more interesting side of Bishop Hill, giving superb views over Loch Leven.', 56.2034, -3.3186),
('19e75e91-f5b6-55c9-8abf-ecba66c629b3', 'Loch Eireagoraidh, near Mallaig', 'https://www.walkhighlands.co.uk/fortwilliam/locheireagoraidh.shtml', 9.0, 265, 3.5, 'This out-and-back walk visits a lonely loch hidden in the rough moorland southeast of Mallaig. Those looking for a short (and dry!) stroll can simply amble as far as Loch an Nostarie - the route becomes very wet underfoot beyond.', 56.993, -5.82839),
('19f13e73-8e65-5a78-ae6f-b288635d751e', 'Belwade Farm, Bell Wood and the Dee, Aboyne', 'https://www.walkhighlands.co.uk/aberdeenshire/aboyne.shtml', 10.0, 130, 3.0, 'This figure-of-eight walk explores the varied countryside around Aboyne, including Bell Wood, a section of the Old Deeside road (now a path), and a stretch along the banks of the River Dee. The walk passes the Belwade Farm horse centre, which has a cafe, at around half-way.', 57.0761, -2.7797),
('1a139c92-42ed-5bbc-b0bc-c1a13f413891', 'Elgol peninsula circuit', 'https://www.walkhighlands.co.uk/skye/elgolpeninsula.shtml', 18.0, 645, 8.0, 'This long circular walk gives wonderful views of the Cuillin and the islands of Rum, Eigg and Canna. It also visits the beautiful bay of Camasunary.', 57.1798, -6.0637),
('1a2a6e8b-38b5-595f-8f83-a410cf540c98', 'Water of Ruchill and Cultybraggan, Comrie', 'https://www.walkhighlands.co.uk/perthshire/water-of-ruchill.shtml', 6.75, 30, 2.0, 'This circular walk heads upriver beside the attractive Water of Ruchil from Comrie village. The return is a mix of minor roads and paths, and gives a chance to visit Cultybraggan Camp - now owned by the community but once a POW camp.', 56.3732, -3.9874),
('1a466cd9-d6d4-5bf9-b2bd-090969386a68', 'Druim an Aird, near Laggan', 'https://www.walkhighlands.co.uk/cairngorms/pattack.shtml', 4.5, 97, 1.5, 'This walk begins by passing above the lower Pattack gorge and its waterfalls. It then follows forest tracks to reach the lonely ruins of the deserted village of Druim an Aird. It was once possible to make a circuit using the Right of Way from Dalwhinnie, but this path has been lost following forest works so the return is back the same way.', 56.982, -4.3593),
('1a8e833c-b345-5064-9009-0eac631c98ce', 'Huntly Castle and the River Deveron', 'https://www.walkhighlands.co.uk/aberdeenshire/huntly-castle.shtml', 4.5, 12, 1.0, 'Explore the surroundings of Huntly, passing the ancient castle, and walking along the riverbank before returning to the attractive town centre.', 57.444, -2.7916),
('1aaad25d-0c01-5145-835a-49f5bafe1a4e', 'Insh Marshes - Invertromie Trail', 'https://www.walkhighlands.co.uk/cairngorms/inshmarshes.shtml', 4.5, 89, 2.0, 'A lovely walk exploring the edge of the Insh Marshes RSPB nature reserve with good views and varied countryside. Bring binoculars for the three bird hides.', 57.0733, -4.023),
('1aad1cd6-e60e-56e2-ba11-8d23cb19cef5', 'Geal-charn Mòr , from Lynwilg', 'https://www.walkhighlands.co.uk/cairngorms/geal-charn-mor.shtml', 12.5, 608, 4.5, 'Geal-chàrn Mòr is the southeasternmost summit of the vast Monadh Liath plateau. It gives a fairly straightforward hillwalk and offers superb views of the Cairngorms across Strathspey.', 57.1735, -3.8507),
('1ab80141-ee70-532b-aeca-1432f9062036', 'Port nan Crullach, Croggan', 'https://www.walkhighlands.co.uk/mull/croggan.shtml', 4.75, 16, 1.0, 'Croggan is one of the furthest-flung corners of Mull, reached along a truly tiny road along the southern shores of Loch Spelve. This short walk follows a track past the mouth of the loch to the lovely, secluded beach of Port nan Crullach.', 56.3823, -5.7167),
('1aba5da1-02c1-5d42-8bd0-ed5e2a2b827f', 'Loch Gruinart RSPB reserve trail', 'https://www.walkhighlands.co.uk/islay-jura/gruinart-rspb.shtml', 2.5, 11, 1.0, 'A short, easy walk through woodland to a viewing platform overlooking Loch Gruinart, a bird watchers'' paradise, and visit two bird hides.', 55.8241, -6.3498),
('1b2dab41-be6b-521d-bf44-0f674e75f0e8', 'Rubha Réidh and Camas Mòr, near Melvaig', 'https://www.walkhighlands.co.uk/torridon/rubha-reidh.shtml', 7.0, 298, 3.5, 'The walk begins near to Rubha Reidh lighthouse, with stunning views across to Skye. The walk around the coast on narrow cliff paths is rough going but gives views of amazing natural arches and the stunning beach at Camus Mòr. The route then climbs over heather moorland and bog to the mast at Maol Breac before returning to the coast road.', 57.8552, -5.80993),
('1b4571fd-2f19-5000-8111-c33ac19d6c6a', 'River Earn walk - Crieff to Muthill', 'https://www.walkhighlands.co.uk/perthshire/muthill.shtml', 9.75, 75, 3.0, 'A lovely linear walk along the banks of the River Earn and through beautiful woodland. The walk gives the chance to explore the town of Crieff and the pretty village of Muthill from where a bus can be caught back to Crieff.', 56.3732, -3.8412),
('1b734969-f386-5dcc-9f67-90e306258090', 'Quinish Point, from Dervaig', 'https://www.walkhighlands.co.uk/mull/quinish-point.shtml', 12.75, 189, 4.5, 'This excellent walk heads out onto the Quinish peninsula from Dervaig, through woods and pastures and passing a magnificent standing stone. The destination of this out-and-back excursion is Quinish Point - a headland offering superb seascapes on a clear day, taking in Coll, Rum, Skye and even the Outer Hebrides.', 56.5893, -6.18633),
('1b7b0c32-3722-50ad-bbd4-2d74ab9dfa27', 'Lundie Craigs circuit, Sidlaws', 'https://www.walkhighlands.co.uk/angus/lundie-craigs.shtml', 8.0, 135, 3.0, 'Lundie Craig is a prominent summit in the Sidlaw Hills, with a steep escarpment and a transmitter mast that make it easily identifiable when seen from afar. It is a great viewpoint and the ascent is very straightforward; the rougher descent given here could be omitted.', 56.5102, -3.1982),
('1bb86f97-e698-5169-9143-90835eb4d575', 'Scoraig from Badrallach', 'https://www.walkhighlands.co.uk/ullapool/scoraig.shtml', 16.5, 100, 5.0, 'A delightful, easy-going coastal walk visiting the Scoraig peninsula, home to an off-grid community. Although this is an out-and-back route, the excellent views all along the way make it thoroughly enjoyable. When the loch is too rough for boats, the path is Scoraig''s only link with the outside world.', 57.874, -5.2806),
('1c115dc9-7def-5f3b-acc4-40d9f31bbf32', 'Creag Mhòr and Beinn Heasgarnich', 'https://www.walkhighlands.co.uk/perthshire/beinn-heasgarnich.shtml', 25.75, 1470, 11.0, 'These two Munros give one of the more challenging outings for baggers in this part of the Highlands, requiring experience as it crosses some potentially difficult pathless terrain. Creag Mhòr is steep and craggy on the ascent with much character; Beinn Heasgarnich is a fine viewpoint but has a tricky descent with vast areas of peat bog.', 56.4991, -4.4759),
('1c70bff3-5f5c-56d7-bf21-a5ac52074c7b', 'Aros Castle, Glenaros', 'https://www.walkhighlands.co.uk/mull/aros-castle.shtml', 2.0, 46, 0.75, 'This short walk visits the remains of the 13th century Aros Castle - one of several castles that once guarded the shores of the Sound of Mull.', 56.5311, -5.9747),
('1c966c73-ae40-598d-be53-fbf0a19902cb', 'Sgùrr nan Gillean', 'https://www.walkhighlands.co.uk/skye/sgurrnangillean.shtml', 12.0, 985, 7.0, 'Sgùrr nan Gillean is perhaps the most famous of the Cuillin peaks - a popular route with a difficult scramble to the summit and fantastic views at all times.', 57.2894, -6.176),
('1cf16e49-ffa1-5de0-9320-b1e514c73a2f', 'Banff Town Heritage Trail', 'https://www.walkhighlands.co.uk/aberdeenshire/banff-heritage.shtml', 3.2, 40, 1.0, 'Explore the fine buildings and heritage of Banff with this partially waymarked trail. This route can be joined to the Bridge of Alvah walk from Duff House by taking the signed road from the car park.', 57.6628, -2.5223),
('1d170777-7c3a-5af9-94b7-d5ff03d0d2c8', 'Garmony Point and Fishnish', 'https://www.walkhighlands.co.uk/mull/garmony-point.shtml', 7.0, 60, 3.0, 'This pleasant - though sometimes muddy - walk follows the flat coastline north from Garmony Point, giving a chance to watch out for otters. The walk loops through the forest near Fishnish, overlooking the ferry to Morvern, before returning the same way.', 56.4959, -5.7751),
('1d294c30-4172-5027-a22a-04b0ef5fc884', 'Singing Sands, Cleadale', 'https://www.walkhighlands.co.uk/islands/singing-sands.shtml', 3.7, 106, 1.5, 'This short walk to the lovely singing sands of Eigg with great views over to Rum, starts from Cleadale in the north of the island. To reach here from the pier you can either walk along the road (following the directions for Laig Bay) or hire bikes at the pier and cycle.', 56.92, -6.1467),
('1de55758-75ec-513e-8647-46deea4756b7', 'Culag Woods, Lochinver', 'https://www.walkhighlands.co.uk/ullapool/culag-woods.shtml', 3.0, 120, 1.0, 'Culag Woods on the edge of Lochinver are owned and managed by a local community trust and have been made into an excellent facility for short family walks. There are some lovely views.', 58.1477, -5.2431),
('1de824da-7bd0-5d88-a8dc-760763aab664', '4 Lochs and 3 Distilleries from Ballygrant', 'https://www.walkhighlands.co.uk/islay-jura/ballygrant.shtml', 25.5, 286, 7.0, 'This long but easy going circular visits the lochs and woodland on the Dunlossit Estate before heading north on a minor roads with coastal views. Short detours lead to Caol Ila, Ardnahoe and Bunnahabhain distilleries, all of which are open for tours at various times during the day. The route then follows winding forestry tracks, moorland and farmland, with an opportunity to visit Finlaggan - once the home of the Lords of the Isles. The walk can be shortened by omitting the detours to Finlaggan or Caol Ila.', 55.819, -6.1595),
('1e2efe48-270c-5da8-bf68-79df574fbbbe', 'Loch Ardlaraich circular, Ardfern', 'https://www.walkhighlands.co.uk/argyll/ardfern.shtml', 3.5, 84, 1.5, 'This circular walk explores the undulating hinterland behind the beautifully-situated village of Ardfern, passing an attractive freshwater loch along the way.', 56.1816, -5.5354),
('1e398315-fbd8-5c3a-9270-19b1d322ac64', 'Glasgow Necropolis', 'https://www.walkhighlands.co.uk/glasgow/necropolis.shtml', 4.0, 46, 2.0, 'The Glasgow Necropolis is one of Europe''s most important cemeteries, and a wonderful memorial to the Victorian era itself as well as the final resting place of 50,000 people. The cemetery is a fascinating place to visit and also offers great views.', 55.8622, -4.2522),
('1e5fe802-6fb3-5d8c-9f86-4d5342079adf', 'Blairadam Forest walks, near Kelty', 'https://www.walkhighlands.co.uk/fife-stirling/blairadam.shtml', 6.2, 86, 2.0, 'This circuitous route combines several waymarked walks at this large Forestry and Land Scotland plantation. Red squirrels inhabit the forest, and remnants of the area''s industrial past can be spotted along the way.', 56.1363, -3.4025),
('1e7cd447-48e0-5472-a3db-6e3066080678', 'Gleann Beag brochs, Suardalan and Glenelg circuit', 'https://www.walkhighlands.co.uk/kintail/Gleannbeag.shtml', 22.25, 227, 8.0, 'A fairly low level circular walk allowing exploration of the fantastic remains of iron-age brochs, the open moorland above Gleann Beag, and the pretty coastal village of Glenelg.', 57.2122, -5.62208),
('1e9e1870-89ca-50bc-8bb8-5c80399ab0bd', 'Crombie Country Park, near Carnoustie', 'https://www.walkhighlands.co.uk/angus/crombie-country-park.shtml', 4.25, 23, 1.5, 'Crombie Country Park was opened in 1983, a mix of broadleaf and conifer woodland around Crombie Loch, a reservoir which once supplied water to Dundee. This easy walk encircles the reservoir and visits a couple of wildlife hides along the way.', 56.5511, -2.7679),
('1eaf693f-054b-5460-8ead-14080a63474b', 'Killantringan Lighthouse circuit, Portpatrick', 'https://www.walkhighlands.co.uk/galloway/killantringan-lighthouse.shtml', 10.0, 236, 4.5, 'Follow the rugged coastline from Portpatrick to the sturdy lighthouse at Killantringan before heading inland to take minor roads and a short woodland path to return. It is also possible to avoid the road walking by returning along the coast path.', 54.8427, -5.1198),
('1eb4d8cc-0518-5e1f-97ee-e167b74dfbff', 'Bochel circuit, near Tomnavoulin', 'https://www.walkhighlands.co.uk/cairngorms/bochel.shtml', 10.5, 200, 3.0, 'This circular waymarked walk makes a fine route through very varied countryside, including farmland, moorland and woodland sections.', 57.3157, -3.2993),
('1ebd7079-1a8c-51f3-92a4-592e45b23a3a', 'Saline Hill and Easter Cairn, Saline', 'https://www.walkhighlands.co.uk/fife-stirling/saline-hill.shtml', 9.5, 318, 4.0, 'Saline Hill rises above the village of the same name in a quiet corner of Fife. Be aware that 
INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('25167256-4724-584c-a332-7aa3447cf8e0', 'Hermitage of Braid and Blackford Hill', 'https://www.walkhighlands.co.uk/lothian/blackford-hill.shtml', 4.25, 137, 1.5, 'This delightful walk combines the wooded nature reserve of the Hermitage of Braid with an ascent of Blackford Hill, giving superb views over Edinburgh.', 55.9194, -3.2103),
('25d4a846-593c-5221-a2ca-d00793cf55d1', 'Papa Stour: the coastal circuit', 'https://www.walkhighlands.co.uk/shetland/papa-stour.shtml', 17.0, 304, 6.5, 'Explore this special island on this long coastal circuit taking in the best beaches and an array of sea stacks, high cliffs, and natural arches as well as visiting Papa Stour''s highest point. The island is served by only an infrequent ferry service and the complete walk is only possible as a day trip from Shetland Mainland on a number of days each week.', 60.3316, -1.6716),
('26024d34-aea9-5e7b-a27d-fde786dc9645', 'Baleromindubh and Cable Bay', 'https://www.walkhighlands.co.uk/islay-jura/cable-bay.shtml', 7.75, 127, 3.0, 'This walk explores a section of Colonsay''s southeastern coastline, linking some fine sandy bays. The section linking the bays is rough underfoot and pathless.', 56.0574, -6.206),
('26082db7-a003-5d91-8d6e-25081fb22b7b', 'Cammo Estate and River Almond walk, Cramond Brig', 'https://www.walkhighlands.co.uk/lothian/cammo-almond.shtml', 8.5, 104, 2.5, 'This figure-of-eight route on the fringe of Edinburgh runs through the interesting Cammo Estate - now a country park. It then follows the River Almond out towards the aiport before returning to Cramond Brig.', 55.9657, -3.318),
('26115461-384c-517d-ba96-652e880ee98f', 'Sailean nan Cuileag, Sunart Oakwoods', 'https://www.walkhighlands.co.uk/fortwilliam/saileannancuileag.shtml', 0.75, 25, 0.5, 'This very short walk heads down through some beautiful remnants of the Atlantic oakwoods to a bay that was once an important harbour.', 56.7143, -5.75693),
('263f5cfe-b189-5239-8597-44c5e9a63164', 'Burn Mill circuit, Lauder', 'https://www.walkhighlands.co.uk/borders/burn-mill.shtml', 3.0, 84, 1.0, 'This circular route follows the Lauder Burn upstream before climbing to a small ridge. It then joins the route of the Southern Upland Way, giving great views over Lauder and the surrounding countryside as it descends back to the site of an old granary mill.', 55.7162, -2.7491),
('26508c3f-a4ad-5b6c-8937-ffe9a40c9bb9', 'Craig Varr, Kinloch Rannoch', 'https://www.walkhighlands.co.uk/perthshire/craig-varr.shtml', 4.5, 340, 2.5, 'Craig Varr is a craggy bluff projecting from the high hillsides north of Kinloch Rannoch and is very prominent when seen from the village. Its ascent gives a short hillwalk and the views from the top are sensational.', 56.7009, -4.1876),
('26a1bcc7-64a4-53d3-84b0-71202d9bb118', 'Braeriach, circuit from Whitewell', 'https://www.walkhighlands.co.uk/cairngorms/braeriach.shtml', 26.0, 1217, 10.0, 'Braeriach is the third highest mountain in Britain, and its remote position ensures it is a tougher proposition and far less visited than its higher rivals. In good conditions this is a magnificent circuit taking in scenery from Caledonian pinewoods to a storm-swept plateau high above dramatic corries.', 57.1561, -3.7943),
('26e3d6b1-fec5-53dd-b580-3c42ca729f6e', 'Ben Ledi', 'https://www.walkhighlands.co.uk/lochlomond/ben-ledi.shtml', 10.0, 760, 6.0, 'Ben Ledi is a familiar landmark from Callander and the highest mountain in the main part of the Trossachs. It is a very popular hillwalk and its position on the edge of the Highlands makes it an excellent viewpoint.', 56.2534, -4.2822),
('26ec4797-59c3-5037-9e72-8b14b0e7bafb', 'Binn Hill from Kingston, near Garmouth', 'https://www.walkhighlands.co.uk/moray/binn-hill.shtml', 8.25, 92, 2.0, 'This figure-of-eight route visits some of Moray''s coastal defences from World War Two, before climbing steeply through the woods to enjoy the fine sea views from Binn Hill.', 57.6759, -3.11677),
('27118b99-39c0-5241-a1a5-39729fb07e50', 'Creagan a'' Chaise, Cromdale Hills', 'https://www.walkhighlands.co.uk/cairngorms/creagan-a-chaise.shtml', 16.0, 595, 5.0, 'The Cromdale Hills are a rather unfrequented ridge, boggy in places, rising between Speyside and Strath Avon. This walk from Cromdale village visits a ruined castle, a battle site and two massive hilltop cairns with extensive views.', 57.3389, -3.5379),
('2730196f-3cb3-5d06-850c-43fa04cc2556', 'Isle of Luing and the Slate Quarries', 'https://www.walkhighlands.co.uk/argyll/isle-of-luing.shtml', 5.5, 125, 2.5, 'The Isle of Luing was once the centre of a slate quarrying industry. This wonderful but challenging circular walk explores the remains of the industry on a now quiet coastline, passing through the delightful village of Cullipool. There''s one very rough tidal section scrambling over awkward boulders where the original route was destroyed by rockfall and erosion - it requires some care and agility and is completely impassable at high tide. Careful route finding is needed on the return over the hill.', 56.2663, -5.6335),
('2774bc2d-49be-522b-b328-bfbb0a84fd0e', 'Lyness Wartime Trail and Wee Fea hill, Hoy', 'https://www.walkhighlands.co.uk/orkney/lyness.shtml', 6.0, 88, 2.5, '12,000 troops were stationed at the Lyness base, HMS Prosperine, during WWII. This walk explores the legacy of that time, visiting the museum, war cemetery, air raid shelter, and climbing Wee Fea hill for good views over Scapa Flow.', 58.8337, -3.1924),
('27785b99-0bce-5390-bf30-17627495f479', 'Silver Walk to Castle Tioram, near Kinlochmoidart', 'https://www.walkhighlands.co.uk/fortwilliam/silver-walk.shtml', 12.5, 513, 4.5, 'Follow this fantastic ancient path as it weaves along the rugged shoreline of Loch Moidart, climbing steeply in places, to reach Castle Tioram, spectacularly sited on a small rocky island. The times and distances given for this linear route are for both directions but you could also get picked up at Diorlin.', 56.778, -5.7407),
('27d80215-2881-5042-8a39-1be24274c395', 'Loch Lundie, Invergarry', 'https://www.walkhighlands.co.uk/fortwilliam/loch-lundie.shtml', 5.0, 108, 1.5, 'Attractive and peaceful Loch Lundie, approached through fine mixed woodland, makes an excellent destination for a short walk from Invergarry.', 57.0698, -4.8118),
('27e6d24a-e031-50d3-91c3-d57384415645', 'Braid Hills, Edinburgh', 'https://www.walkhighlands.co.uk/lothian/braid-hills.shtml', 4.5, 132, 1.5, 'Southernmost of the Seven Hills on which Edinburgh is traditionally said to be built, the Braid Hills are largely occupied by golf courses. This circular walk enjoys superb views throughout.', 55.9154, -3.2045),
('27e75607-bdf4-5a8c-b4fa-00fee69ae204', 'Geal Chàrn, Monadhliath', 'https://www.walkhighlands.co.uk/cairngorms/geal-charn.shtml', 12.5, 625, 6.0, 'Geal Chàrn is the westernmost of the Monadh Liath and so far from the other three Munros that it is usually ascended on its own. Its eastern corrie is attractive but it is otherwise lacking in features; however it does have a feeling of remoteness.', 57.0199, -4.4359),
('2844ba6d-b5b9-50d5-b187-74603fabfdfb', 'Kerrowmore Woods and Falls, Glen Lyon', 'https://www.walkhighlands.co.uk/perthshire/kerrowmore.shtml', 4.75, 210, 2.0, 'This circular walk on the south side of Glen Lyon follows winding paths through woods and moorland, visiting small waterfalls, lochans and fine viewpoints. Although the trails are waymarked, it is quite rough and steep at times.', 56.5784, -4.3283),
('28491e6d-5f0f-5bc0-be3e-06278ee5436c', 'Reelig Glen, Moniack', 'https://www.walkhighlands.co.uk/lochness/Reeligglen.shtml', 3.5, 55, 1.5, 'The short but very popular circular walk - also known as the Tall Trees trail - heads up the Reelig Glen through beautful mixed woodland, boasting some of Britain''s tallest trees. Our description also includes a second walk - the Upper Reelig Trail - a waymarked loop through the woods above the glen.', 57.4555, -4.404),
('285db7dc-691d-5ab0-a02a-f59ccaabd58f', 'Footdee and Aberdeen harbour', 'https://www.walkhighlands.co.uk/aberdeenshire/footdee.shtml', 4.75, 19, 1.5, 'Footdee (pronounced Fittie) is a small fishing village at the mouth of the Dee and Aberdeen harbour, long since swallowed up by the expansion of the city. The village dates back to medieval times but the fascinating present day cluster of cottages was laid out by influential Aberdeen architect John Brown to rehouse the cities fishermen in 1809. The walk to it passes the fringe of the busy modern harbour and returns via the city beach.', 57.1475, -2.0952),
('28628c88-c755-5a86-bb1e-e34feb1b5244', 'Halterburn circuit & the Schil, nr Kirk Yetholm', 'https://www.walkhighlands.co.uk/borders/schil.shtml', 14.0, 662, 6.0, 'Combine the two alternatives for the final stretch of the Pennine Way on this fine hill round above and through the Halterburn valley. The ascent of the Schil itself can be omitted, but it''s rocky outcrops make it the most distinctive in the Cheviots.', 55.5423, -2.25517),
('2885bbeb-6878-56fc-af01-2a7160a7a640', 'Isle of Eriska circuit, near Benderloch', 'https://www.walkhighlands.co.uk/argyll/eriska.shtml', 8.5, 121, 4.0, 'Eriska is a magical and secluded small island, the setting for a luxury hotel. This walk starts on the mainland and accesses the island via a bridge before making a rough but memorable circular walk around the island.', 56.5203, -5.4125),
('289547a7-c27a-597b-8af9-5c831466d8d9', 'Castle Coeffin and Tirefour Broch from Point', 'https://www.walkhighlands.co.uk/argyll/castle-coeffin.shtml', 15.0, 294, 4.5, 'This enjoyable outing explores the northern half of lovely Lismore, including a visit to the 13th century ruins of Castle Coeffin, and the iron age broch of Tirefour Castle. The going is quite rough but there is the opportunity to visit a cafe and heritage centre at half way!', 56.5599, -5.4281),
('28ba657f-3db4-5bd7-bab9-f3c1aa7c9b11', 'Oronsay and the Strand', 'https://www.walkhighlands.co.uk/islay-jura/oronsay.shtml', 10.0, 50, 4.0, 'Cross The Strand at low tide to reach the island of Oronsay where the walk visits the ancient Priory before heading round the coast renowned for its grey seal colony. If you''re lucky you may also spot Corncrakes and Choughs. Locally the island is often known as Oransay. Only accessible at low tide - check times at the Hotel or Post Office.', 56.04, -6.2209),
('28c35160-8c04-51c0-8fe5-c5a6e728c237', 'Smoo Cave and Bhlar Duibhe', 'https://www.walkhighlands.co.uk/sutherland/smoo-cave.shtml', 6.75, 125, 2.0, 'Explore Smoo Cave, a massive sea cave, and then head inland on a moorland track for a pleasant, fairly flat circuit, with a short section along a minor road with pavement.', 58.5636, -4.7211),
('2918993a-0ad2-5da9-b928-7c781813a911', 'Torr Point and Red Haven, Auchencairn', 'https://www.walkhighlands.co.uk/galloway/torr-point.shtml', 7.0, 78, 3.0, 'Head around the back of Auchencairn Bay to visit a bird hide and then explore a quiet peninsula with sandy beach, beautiful headland and wildlife-rich woods.', 54.8443, -3.87),
('29618bce-47a9-54eb-aebc-5589970fffd2', 'Stob Coire Creagach (Binnein an Fhidhleir)', 'https://www.walkhighlands.co.uk/lochlomond/stob-coire-creagach.shtml', 7.0, 845, 5.0, 'Stob Coire Creagach is the highest summit of Binnein an Fhidhleir - the latter being the original name of the whole mountain, although walkers often use it to refer to the lower western summit. The mountain impressively walls in the north side of Glen Kinglas. It gives a short hillwalk but with a truly gruelling and unremittingly steep ascent. The views from the ridge are simply superb.', 56.2457, -4.8509),
('2965851c-44a5-5259-8619-bc25debfc800', 'Beinn Udlamain and Sgàirneach Mhòr', 'https://www.walkhighlands.co.uk/cairngorms/beinn-udlamain.shtml', 15.75, 783, 7.0, 'This southern pair of the four Munros on the west side of the Drumochter Pass are heathery hills rather than true mountains; the views, however, are good on a clear day.', 56.8515, -4.2444),
('29659eac-2e5f-5e89-add2-6249b6a11ef6', 'River Lundie walk, Leanachan Forest', 'https://www.walkhighlands.co.uk/fortwilliam/leanachan-forest.shtml', 3.5, 45, 1.0, 'A pleasant leg stretcher through forestry, with a short section of riverside. This walk only has glimpses of the nearby mountain scenery as it is mainly in the trees.', 56.8511, -5.0025),
('298ae81a-e181-5c0f-bd89-be342d40fe6b', 'Bracklinn Falls, Callander', 'https://www.walkhighlands.co.uk/lochlomond/bracklinn-falls.shtml', 5.25, 157, 1.5, 'A circular walk taking in the idyllic Bracklinn Falls, a very popular local beauty spot. Once over the bridge the route climbs through forestry before descending to the quiet upper glen, with a return by minor road.', 56.2478, -4.2012),
('29b89bf5-4644-558d-8fc2-e037a0b9190c', 'Stob Ghabhar and Stob a''Choire Odhair', 'https://www.walkhighlands.co.uk/argyll/stob-ghabhar.shtml', 16.0, 1239, 9.0, 'Stob Ghabhar is the finest of the Black Mount summits, its narrow rocky ridges and steep sides standing out amongst the hills of the southern Highlands. Stob a''Choire Odhair is an easier ascent with a magnificent view over Rannoch Moor. Combining both peaks, this route is a fine expedition for experienced hillwalkers.', 56.5372, -4.81407),
('29c74025-dd3c-588d-b6f9-07a743af3c87', 'Craig Phadrig, Inverness', 'https://www.walkhighlands.co.uk/lochness/craig-phadrig.shtml', 2.0, 75, 1.0, 'A visit to the site of the ancient fort atop Craig Phadrig, the wooded hill that rises on the west side of Inverness. The short ascent reveals glorious views over the Beauly Firth.', 57.4744, -4.2679),
('29f7bf95-07bc-5e3f-b469-4be719e3c867', 'Cat Law and Corwharn, Glen Isla', 'https://www.walkhighlands.co.uk/angus/cat-law.shtml', 18.5, 741, 7.0, 'The position of Cat Law, rising at the foot of the Angus Glens, makes it a fine viewpoint dividing Highlands and Lowlands. When combined with the neighbouring summit of Corwharn it makes for an enjoyable moorland circuit.', 56.7141, -3.1519),
('29f8fb4b-f9b1-5330-8429-26815dbfb1a7', 'Gunns Wood, Lairg', 'https://www.walkhighlands.co.uk/sutherland/gunns-wood.shtml', 2.25, 73, 0.6666666666666666, 'A short walk through attractive natural woodland and plantation, with some limited views over Loch Shin. Can easily be accessed from the centre of Lairg.', 58.023, -4.3901),
('2a0d58a6-5ce0-5fc1-9325-cec49ae585aa', 'Linn of Tummel circuit, Garry Bridge', 'https://www.walkhighlands.co.uk/perthshire/linn-of-tummel.shtml', 10.75, 175, 3.5, 'This circuit visits the falls at the Linn of Tummel as the first stage of a loop around the wooded banks of Loch Faskally. The route can easily be extended by starting from Pitlochry or Killiecrankie.', 56.728, -3.7778),
('2a60d677-4c77-53b3-b368-60498271b9f2', 'Fassfern Forest walks', 'https://www.walkhighlands.co.uk/fortwilliam/fassfern.shtml', 4.0, 138, 2.0, 'There are three waymarked forest walks from Fassfern; this route combines two of them to make an enjoyable, straightforward circuit.', 56.86, -5.24817),
('2a798cd1-0b5a-532d-816c-eec155c2a12b', 'Loch Earn viewpoint walk, St Fillans', 'https://www.walkhighlands.co.uk/perthshire/st-fillans.shtml', 6.75, 300, 2.5, 'Climb up the hillside via zig-zagging tracks to gain wonderful views looking along the length of Loch Earn, before descending back through the attractive village of St Fillans.', 56.3943, -4.1226),
('2af3859a-de64-5f79-b880-9d20efde3810', 'The Magnificent 11, Glasgow Southside', 'https://www.walkhighlands.co.uk/glasgow/magnificent-11.shtml', 17.0, 380, 4.5, 'This very varied circular route explores and links up the green spaces on the southern fringes of Glasgow; it includes the best views over the city from the Cathkin Braes. The route was devised and waymarked by Glasgow Ramblers and Glasgow Countryside Rangers.', 55.8022, -4.27043),
('2b4282b9-51e7-5a42-9b60-ff6e81439d9e', 'Salen Oakwoods', 'https://www.walkhighlands.co.uk/fortwilliam/salen.shtml', 1.5, 100, 1.0, 'This delightful short walk passes through beautiful ancient oak woodlands close to the shores of Loch Sunart. Although no longer waymarked, the path is still clear and hopefully passage of enough feet will help keep it open.', 56.7153, -5.7743),
('2b4772e4-c4ef-5dc3-8b7c-01f8533b7864', 'East Lomond from Glenrothes', 'https://www.walkhighlands.co.uk/fife-stirling/east-lomond-glenrothes.shtml', 10.5, 315, 3.5, 'The southern slopes of East Lomond perhaps lack the picturesque appeal of the steeper northern side above Falkland. The gradients are, however, gentler and the views superb on this approach from the outskirts of Glenrothes. The alternative return route suggested has a rough, pathless section.', 56.2183, -3.1845),
('2b66b690-7025-547b-99fe-3d4f51a0db1b', 'Burns walk circular, Dumfries', 'https://www.walkhighlands.co.uk/galloway/burns-dumfries.shtml', 7.5, 48, 2.5, 'Follow in the footsteps of Robbie Burns as you trace the banks of the River Nith from the heart of Dumfries. The route returns to the town centre using a cyclepath.', 55.0669, -3.6125),
('2be62387-e0a6-5f6a-b2be-9d298a07d2ec', 'Burra Ness and the broch, Yell', 'https://www.walkhighlands.co.uk/shetland/burra-ness.shtml', 7.0, 58, 2.5, 'Head out round a low-lying headland to visit the remains of the best-preserved broch on Yell. The walk leads through prime otter habitat and much of the footage in the award-winning documentary "On the track of the Wild Otter" by Hugh Miles was filmed here.', 60.6441, -1.0274),
('2c1a55f6-b33f-5ab2-a753-2627281d8b8e', 'Forsinard Flows and Tower, Forsinard', 'https://www.walkhighlands.co.uk/sutherland/forsinard.shtml', 1.5, 6, 0.75, 'This short but truly unique walk gives a fascinating introduction to the Forsinard Flows National Nature Reserve. The trail crosses the blanket bog on a wooden walkway to visit a spectacular modern tower overlooking this remarkable landscape and habitat. The walk then continues along an older trail of placed flagstones to visit more of the Dubh Lochan pools, rich with bird, plant and insect life.', 58.357, -3.8975),
('2c2d1cb7-efd5-56e8-9493-039b1bdad2f4', 'Fishnish Forest Circular, Fishnish', 'https://www.walkhighlands.co.uk/mull/fishnish.shtml', 5.5, 65, 1.5, 'A level circular walk mainly through forestry with some open sections and views over the water in places. Whilst not one of Mull''s more interesting walks, it could serve as a good leg stretcher before or after the ferry to Lochaline.', 56.51, -5.8025),
('2c56aa97-e047-520a-986c-a71c9ad973dd', 'Loch Kernsary round, Poolewe', 'https://www.walkhighlands.co.uk/torridon/lochkernsary.shtml', 10.0, 195, 3.0, 'A pleasant circular walk from the centre of Poolewe village, with good views of the distant mountains and part of Loch Maree.', 57.7658, -5.60289),
('2c6ee6f8-b98f-5279-a7f5-546de2bd7dd9', 'Blackness Castle, from near Bo''ness', 'https://www.walkhighlands.co.uk/fife-stirling/blackness-castle.shtml', 8.5, 19, 2.5, 'This coastal route to formidable Blackness Castle offers impressive views across the Forth and is now part of the John Muir Way; the return is made by retracing your steps.', 56.0146, -3.57277),
('2cc83963-3d07-5d36-8041-5c82b286b0bc', 'Perth City walk', 'https://www.walkhighlands.co.uk/perthshire/perth-city.shtml', 6.6, 50, 2.5, 'An exploration of the old streets of central Perth, combined with the vast green space of the North Inch and alongside the River Tay.', 56.3916, -3.4267),
('2cffef1c-534f-5b0e-ab95-563ef74bb066', 'Rumbling Bridge Gorge and Crook of Devon', 'https://www.walkhighlands.co.uk/fife-stirling/rumbling-bridge-gorge.shtml', 5.75, 65, 2.0, 'Rumbling Bridge gorge is a dramatic box canyon in seemingly otherwise gentle countryside. This circular walk follows the south side of the river to the village of Crook of Devon before following paths through woods and fields to return on the north side - before visiting viewing platforms above the gorge.', 56.1777, -3.5854),
('2d031a67-6d44-5d7d-bb71-ad046015aaa5', 'Orval, return via Harris', 'https://www.walkhighlands.co.uk/islands/orval-harris.shtml', 27.0, 961, 8.5, 'Orval is the highest of the hills in the northern half of Rum, a superb viewpoint for both the Rum and Skye Cuillin and surrounding islands, with a dramatic craggy escarpment of its own. The descent leads to Harris on Rum''s western coastline, the site of the Bullough''s mausoleum and a beautiful location in its own right, before a long return on tracks to Kinloch.', 57.0101, -6.2661),
('2d12c839-88d3-5e29-aacf-acfc390bbd2e', 'Fairy Lochs, near Badachro', 'https://www.walkhighlands.co.uk/torridon/Fairylochs.shtml', 6.0, 230, 2.5, 'A short circular hillwalk into an area of small rocky hills with many small lochs, collectively known as the Fairy Lochs locally as they lie below Sithean Mor (the fairy hill). Excellent views to both the coastline and mountains, the route visits a memorial marking the site of a fatal air-crash from World War 2.', 57.6877, -5.6801),
('2d2c7822-cd1c-5f97-ae11-e6cb32b4ea0a', 'Kelvin Walkway: Glasgow to Milngavie', 'https://www.walkhighlands.co.uk/glasgow/kelvin-walkway.shtml', 16.5, 144, 5.5, 'The Kelvin Walkway links the banks of the Clyde in Glasgow to Milngavie, providing a link between the Clyde Walkway and city with the start of the West Highland Way. The route follows the Kelvin on good cyclepaths and tracks through the city, before detouring away from the river through Summerston and then returning to first the Kelvin and then the banks of the Allandar for the much rougher and more rural final stretch to Milngavie.', 55.8657, -4.3058),
('2d410e3e-9767-5e74-b502-b5891467ecb4', 'The Brough of Birsay and Earl''s Palace, Mainland', 'https://www.walkhighlands.co.uk/orkney/brough-of-birsay.shtml', 6.0, 67, 2.5, 'This exploration of the far north-west tip of Orkney Mainland features rugged cliffs, a tidal causeway and centuries of history. Note: access the the Bough of Birsay is only possible within two hours either side of low tide. Tide times are availableonline- note these are GMT and so must be adjusted during the summer. There is a charge to visit the island in the summer months', 59.1354, -3.3248),
('2d90f943-dc02-5c32-9e0a-a1d60c7df928', 'Loch Druidibeag and the Machir circuit', 'https://www.walkhighlands.co.uk/outer-hebrides/loch-druidibeag.shtml', 10.5, 28, 4.0, 'An circular walk taking in the contrasting landscapes, wildlife and flowers of the watery interior moorland and the dune habitat of the coastal machair. A good walk to spot birds, listen for corncrakes, and watch the free-roaming ponies.', 57.3213, -7.3351),
('2d953db3-c8c0-501f-9f62-a17ddf769843', 'Carnoustie Links, Carnoustie', 'https://www.walkhighlands.co.uk/angus/carnoustie.shtml', 6.5, 8, 1.5, 'Follow the coast from Carnoustie and then skirt round the famous golf course to visit a wildlife pond and return on the shared cycleway passing golf clubs and the large Oxford Hotel on this almost level circuit. Care is needed to look out for golfers and not to disturb their play.', 56.4998, -2.7082),
('2dc2bc33-47fb-5059-967e-21787f33b96f', 'Loch Katrine', 'https://www.walkhighlands.co.uk/lochlomond/loch-katrine.shtml', 21.0, 180, 5.5, 'This linear walk along picturesque Loch Katrine can be combined with the steamer sailing from Trossachs Pier. It can also be walked in the other direction, catching the afternoon sailing from Stronachlachar. The route also makes a good, and popular, cycle, although bikes must be booked on the boat in advance.', 56.2576, -4.5779),
('2dce9600-e9ca-5011-925f-0ff7a00b6bef', 'Waughton Hill and the White Horse, from Strichen', 'https://www.walkhighlands.co.uk/aberdeenshire/waughton-hill.shtml', 7.75, 194, 3.0, 'The highest hill in the northeastern corner is usually referred to as Mormond Hill, whilst its highest point, visited here, is called Waughton Hill. The flanks of the hill include a White Horse - visited here - and a stag, which was restored in 2023 but is better seen from the countryside to the south.', 57.5869, -2.09081),
('2de897ea-fd4d-5faf-a8e6-84fa104a34e2', 'Lochore Meadows circuit, near Lochgelly', 'https://www.walkhighlands.co.uk/fife-stirling/lochore.shtml', 5.25, 10, 1.5, 'This straightforward walk through a Country Park loops all the way around Lochore, with good opportunities for birdwatching. It climbs a little over the Clune, a small area of grassland and heath. Cafe and toilets at the start.', 56.1508, -3.337),
('2defb1e2-28fb-5f4a-b417-fa07aa99930f', 'Ardmore Shore Walk, near Tobermory', 'https://www.walkhighlands.co.uk/mull/ardmore.shtml', 7.25, 198, 2.0, 'This enjoyable walk visits the sites of two old settlements en route to and from a beautiful section of shoreline at Ardmore Bay where there is a hide for watching otters and other wildlife.', 56.6266, -6.1017),
('2e20325f-5110-5030-a403-9b6111006539', 'Forvie Sands, Collieston', 'https://www.walkhighlands.co.uk/aberdeenshire/forvie-sands.shtml', 8.5, 118, 3.0, 'This excellent walk explores part of the Forvie Sands National Nature Reserve, a vast area of dunes and coastal heathland. Along the way there is some fine coastal scenery, a beautiful sandy bay and the site of a village destroyed by the drifting sands.', 57.3509, -1.9451),
('2e920bce-9171-5e59-8436-622f1d409043', 'Woolhope circuit, Newcastleton', 'https://www.walkhighlands.co.uk/borders/woolhope.shtml', 7.25, 104, 3.0, 'This short circular walk explores the tracks and hillfarms on the western slopes of Liddesdale, above Newcastleton.', 55.1798, -2.81288),
('2ed6662d-c553-52c0-b6ae-078aa02d3bef', 'Gorebridge and Temple circuit', 'https://www.walkhighlands.co.uk/lothian/gorebridge-temple.shtml', 13.75, 304, 4.0, 'This enjoyable and varied circuit explores the hidden wooded ravines of the Gore Water and the South Esk. It visits the ruins of Temple Church - once an important site of the Knights Templar - and the mansion of Arniston House.', 55.8462, -3.04955),
('2f0f225e-ab84-583a-b2ab-88d4bdfe36f5', 'Corrachree circuit and Knockargerty, Tarland', 'https://www.walkhighlands.co.uk/aberdeenshire/corrachree.shtml', 6.5, 138, 2.5, 'This circular walk heads around the edge of the Drummy Muir just outside Tarland. A spur ascends Knockargety Hill, site of an iron age fort and a good viewpoint.', 57.1264, -2.8658),
('2f430ca2-8345-501a-ba81-dbeb124f04d3', 'Toll an Lochain', 'https://www.walkhighlands.co.uk/ullapool/tollanlochain.shtml', 10.0, 490, 5.0, 'Toll an Lochain is one of the most magnificent corries in Scotland, its loch encircled by the serrated pinnacles of An Teallach and Corrag Buidhe. It comes as a reward for the approach walk which gives heavy going.', 57.8219, -5.1813),
('2f441f15-3f46-5113-ab29-439213521f20', 'Lochanan nan Tunag, Kildary', 'https://www.walkhighlands.co.uk/ullapool/kildary.shtml', 3.25, 18, 1.0, 'A visit to the site of some old gravel quarries behind doesn''t sound very promising; nature has now taken over the old ground however, and the loch itself is very beautiful, particularly in the autumn months.', 57.748, -4.0722),
('2f5899c7-498a-5822-9e9c-d784671d15e5', 'Knitchen Hill and Trumland Reserve, Rousay', 'https://www.walkhighlands.co.uk/orkney/blotchnie-fiold.shtml', 7.5, 273, 3.0, 'Climb to the highest point on Rousay, an excellent viewpoint, passing an impressive chambered cairn on the way. The circuit passes through the Trumland RSPB Reserve and is a good place to spot raptors and short eared owls.', 59.1306, -2.9866),
('2f634f40-738f-5b8c-889c-e437c15889ba', 'Creise and Meall a''Bhùiridh from the Ski centre', 'https://www.walkhighlands.co.uk/fortwilliam/creise.shtml', 10.5, 1093, 7.0, 'These two Munros form the northeastern part the Black Mount range, rising above the head of Glen Etive opposite the better known Buachaille Etive Mòr . This route ascends via the White Corries ski slopes. Meall a''Bhùiridh appears rather undistinguished seen from Rannoch Moor but its elegant west ridge is revealed from Creise, itself the high point of a dramatic ridge running from Sròn  na Creise in the north through Clach Leathad to Sròn  nam Forsair.', 56.6324, -4.8279),
('2f7c2474-a62a-50f0-9ade-1252cc94dc59', 'Applecross House and Walled Garden circuit', 'https://www.walkhighlands.co.uk/torridon/Applecrosshouse.shtml', 4.1, 60, 1.5, 'This straightforward walk combines woodland, riverside, and seafront as it passes through the grounds of Applecross House. The walk begins and ends at the beautiful Walled Garden which has a cafe / restaurant. Many variations are possible as there is a wide range of signed paths across the estate.', 57.4429, -5.8013),
('2f8899ec-ed55-5af8-957d-dec1ee3e91d0', 'Càrn Gorm, Meall Garbh, Càrn Mairg & Creag Mhòr', 'https://www.walkhighlands.co.uk/perthshire/carn-mairg.shtml', 19.5, 1330, 8.0, 'These four Munros on the north side of Glen Lyon lie on a mostly very broad and undulating ridge. With excellent views over the glen to the Lawers range, and over Loch Rannoch, the group give a very satisfying round on a clear day.', 56.6029, -4.192),
('2feb820c-ef85-5362-9332-bbd4663861fa', 'Allt Muick butterfly reserve, Loch Arkaig', 'https://www.walkhighlands.co.uk/fortwilliam/allt-muick.shtml', 1.75, 85, 1.0, 'This short waymarked walk climbs through the sparse birch woodland on the north side of Loch Arkaig. From mid-May to late June this walk offers a great chance to spot Chequered Skipper butterflies, whose caterpillars hibernate here through the winter.', 56.9731, -5.094),
('2ff2f438-77d0-5aaf-bddc-dbb6ea2c39e1', 'Mealaisbhal from Breanais, Uig', 'https://www.walkhighlands.co.uk/outer-hebrides/mealaisbhal.shtml', 7.0, 540, 4.5, 'Mealaisbhal is the highest of the Uig hills and the highest summit on Lewis. Its position on the western edge of the island - overlooking Uig Sands, the rocky neighbouring hills and a vast sweep of ocean - make it an unforgettable viewpoint. The ascent is pathless and boggy, most easily accomplished from the west as described here; the route can be extended to a rugged mountain day by continuing over the neighbouring hills.', 58.1252, -7.11),
('302d03b2-26fb-5cc5-ac87-6ef40da47d32', 'Rubha Aird a'' Mhuile, nr Bornais', 'https://www.walkhighlands.co.uk/outer-hebrides/rubha-aird-a-mhuile.shtml', 5.25, 5, 1.5, 'This excellent walk heads out to the westernmost point of South Uist, a grassy peninsula with a loch at its heart and vast beaches stretching off both north and south. The walk visits some interesting archaeological remains and is alive with sea and coastal birds.', 57.2414, -7.4181),
('3039b8e0-02d0-54ab-8425-5f3b5598359d', 'Beinn a'' Bha''ach Àrd', 'https://www.walkhighlands.co.uk/lochness/beinn-a-bha-ach-ard.shtml', 16.0, 928, 7.0, 'A long and fairly strenuous horseshoe taking in the summit of Beinn Bha''ach Àrd (862m) a Corbett with good views over the Beauly and Moray Firths and into the Affric, Strathfarrar and Strathconon glens and their surrounding mountains. The walk can be shortened by returning from the summit the same way. NOTE: There are sometimes stags in the field crossed on the return route - take care in the Autumn or return by outward route.', 57.4273, -4.6764),
('3040abec-fc8a-5436-9452-02b50acc0767', 'Kildoon Hill, Maybole', 'https://www.walkhighlands.co.uk/glasgow/kildoon-hill.shtml', 9.8, 138, 3.0, 'This straightforward circular route from Maybole follows local lines before making the ascent to Kildoon Hill and its monument - a local landmark and an excellent viewpoint. The return route can be overgrown - this can be avoided if necessary by returning the same way.', 55.3548, -4.68485),
('30896ba8-26ac-5f24-b7c4-6d231f893d27', 'Lael Forest Garden and forest walk', 'https://www.walkhighlands.co.uk/ullapool/lael.shtml', 1.75, 60, 1.0, 'An easy and pleasant walk taking in the Lael Forest Garden with its 200 different tree species together with a longer plantation section with waterfalls.', 57.7827, -5.0366),
('3091d46e-2d13-503c-a7c3-9810f1b2f15b', 'Loch Kinellan and Strathpeffer circuit', 'https://www.walkhighlands.co.uk/lochness/loch-kinellan.shtml', 6.0, 130, 2.5, 'Explore the woods and hills to the north of Strathpeffer on this enjoyable circuit that returns via Loch Kinellan and its crannog.', 57.588, -4.5384),
('30b0466d-67b6-58fe-963b-581c5bfd8647', 'The Horns of Hagmark, Unst', 'https://www.walkhighlands.co.uk/shetland/horns-of-hagmark.shtml', 9.0, 260, 3.5, 'This superb circuit climbs to the summit of the Hill of Clibberswick, which has some of Unst''s finest coastal cliff scenery, including the dramatically named Horns of Hagmark. The route descends to give views over the beautiful Norwick beach before returning to the start point, the former RAF base at the Saxa Vord resort.', 60.7972, -0.821),
('311f646a-1e01-5542-ab43-a0f170b2b246', 'Beinn Enaiglair, Braemore Junction', 'https://www.walkhighlands.co.uk/ullapool/beinn-enaiglair.shtml', 15.5, 754, 6.0, 'An outlier of the Beinn Dearg group, Beinn Enaiglair is prominent in the view from Ullapool harbour. The hill is completely encircled by stalkers'' paths; this route makes best use of these to head round to the more dramatic northern side for the ascent.', 57.7529, -5.0104),
('313ca185-7464-5d27-b194-b644032a7fcd', 'Canna Coastal circuit', 'https://www.walkhighlands.co.uk/islands/canna-coast.shtml', 19.5, 581, 9.0, 'This magnificent walk makes a complete coastal circuit of the Isle of Canna. It takes in the wild and rugged clifftops of the northern and western coastline, with magnificent views of sea and mountain throughout.', 57.0564, -6.4912),
('317bea3c-8542-5c39-a444-005884e4ab6d', 'Ardwell Pond walk', 'https://www.walkhighlands.co.uk/galloway/ardwell-pond.shtml', 2.5, 30, 1.0, 'This circular walk explores the Ardwell Estate on mostly woodland paths from the coast, passing the attractive Ardwell Pond. Chance to visit the walled gardens in summer (charge).', 54.7673, -4.9399),
('323e73dc-4362-5f27-8c79-68755b257a7c', 'Little Conval and Meikle Conval, Dufftown', 'https://www.walkhighlands.co.uk/moray/convals.shtml', 12.5, 580, 4.5, 'The Convals - two adjacent conical hills - make for a short but satisfying hillwalk from Dufftown with good views over the surrounding countryside and Ben Rinnes.', 57.4449, -3.1287),
('325961d1-63a4-5b07-866e-a06c117299e3', 'Inveraray Forest circuit', 'https://www.walkhighlands.co.uk/argyll/inveraray-forest.shtml', 10.0, 220, 3.0, 'Inveraray has a magnificent position on the shores of Loch Fyne. This walk explores the area around the town, taking in Inveraray Castle and its fine estate as a prelude to a long forest walk through the forest plantations above the loch.', 56.2307, -5.07278),
('326d9c68-796f-59ee-9686-e1f820bf8b23', 'Tay Bridge & Balmerino, from Wormit', 'https://www.walkhighlands.co.uk/fife-stirling/tay-bridge.shtml', 8.5, 124, 2.5, 'This circular walk along the Tay Estuary has excellent views of the Tay rail bridge and Dundee. It visits Balmerino, with its ruined abbey, before returning at a higher level.', 56.4222, -2.9876),
('32ae8faf-4880-5b8e-b44a-7d6bcba2e3bf', 'Caisteal Maol and Kyleakin', 'https://www.walkhighlands.co.uk/skye/caistealmaol.shtml', 3.5, 40, 1.5, 'This short but interesting walk explores the village of Kyleakin and its environs - including the Skye Bridge and a ruined castle.', 57.2729, -5.7295),
('32be2bc9-84b9-55ab-b6bb-6e03c441b8a8', 'Whitemill Bay circuit, Sanday', 'https://www.walkhighlands.co.uk/orkney/whitemill-bay.shtml', 4.5, 5, 1.0, 'Cross the white sands of Whitemill Bay before continuing along the coast, popular with birds and flowering plants, before heading inland past old farm buildings to return along the minor road.', 59.3042, -2.5512),
('32c07e07-253a-5a03-9242-39030320051c', 'Castle Loch circuit, Lochmaben', 'https://www.walkhighlands.co.uk/galloway/castle-loch.shtml', 6.25, 15, 2.5, 'This circuit of Castle Loch to the south of Lochmaben takes in a wooded sculpture trail on the west side of the loch, which would be popular with children, before exploring Lochmaben Castle. The return is along a new section of path close by the A709.', 55.1301, -3.4432),
('32f28e54-cb96-5d6b-b332-5327d88aaaf0', 'Monamenach, Glen Isla', 'https://www.walkhighlands.co.uk/angus/monamenach.shtml', 5.25, 444, 3.0, 'Monamenach is a rounded, heathery hill on the watershed between Glen Isla and Glen Shee. Approached from the former a high level start at the head of the glen makes this one of the shortest walks up a Corbett, though the ascent is fairly steep.', 56.8115, -3.324),
('32ff994d-09ae-5e5c-b631-c0b215211d13', 'Tain Hill and Pulpit Rock', 'https://www.walkhighlands.co.uk/ullapool/tain-hill.shtml', 2.0, 78, 0.6666666666666666, 'A short and easy walk to the top of Tain Hill which has good views over the Cromarty and Dornoch Firths.', 57.8037, -4.1004),
('3310cd02-dda9-5149-8f35-c572b4328aaa', 'Riverside Walk, Kincraig', 'https://www.walkhighlands.co.uk/cairngorms/kincraig.shtml', 2.7, 20, 1.0, 'A beautiful out-and-back walk along a high bank above the River Spey with good views of the Cairngorms and passing through lovely woodland.', 57.1272, -3.9282),
('3314b9b1-c6d7-5bc6-8959-d3d3b987a94a', 'Brown Cow Hill circuit, Cock Bridge', 'https://www.walkhighlands.co.uk/cairngorms/brown-cow-hill.shtml', 18.0, 575, 6.5, 'Brown Cow Hill is the highest summit of a sprawling area of rounded heather moorland. This route forms a horseshoe of the higher summits, with boggy ground and peat hags breaking up sections of easier going across short-cropped heather. Though unspectacular, the route gives good views and a chance to experience solitude.', 57.1653, -3.2347),
('332803b2-d172-5e8d-9bc3-fb2bef427349', 'Dùn Ban and Halaman Bay, Tangasdale', 'https://www.walkhighlands.co.uk/outer-hebrides/halaman-bay.shtml', 4.75, 60, 3.0, 'This superb walk passes the shores of Loch Tangasdale before heading across a bare, rocky landscape to reach the spectacularly situated iron-age fort of Dùn Ban. The return takes in Halaman beach, one of the finest and most popular on Barra.', 56.9704, -7.5167),
('33284736-8550-5205-9eaf-d34d212413e3', 'Ganavan Sands and Dunstaffnage Castle', 'https://www.walkhighlands.co.uk/argyll/dunstaffnage.shtml', 7.0, 177, 2.5, 'This superb circular starts with a rugged but beautiful moorland walk above the coastline, with truly stunning views. The route then visits the dramatic Dunstaffnage Castle before returning by following the cyclepath.', 56.4379, -5.46932),
('3353aadf-c871-5604-bce8-863bcc4e7d68', 'Cademuir Hill Forts and the Tweed, Peebles', 'https://www.walkhighlands.co.uk/borders/cademuir-forts.shtml', 12.5, 243, 4.5, 'This wonderfully varied circular walk uses old paths to climb high across the flanks of Cademuir Hill, visiting its spectacular hillforts and their fine views. The return to Peebles is then made along the beautiful banks of the Tweed.', 55.6496, -3.19039),
('335a59cc-b7c9-5c68-9755-5c3baf2a0dd2', 'Cow Hill circuit, Fort William', 'https://www.walkhighlands.co.uk/fortwilliam/cowhill.shtml', 11.0, 455, 4.0, 'Cow Hill is the summit that blocks the view of Ben Nevis from Fort William. It gives an enjoyable circuit with fine views, both over the town and down Glen Nevis and Loch Linnhe.', 56.8198, -5.1079),
('337cd32a-e647-5ddd-a92e-22305a65ea57', 'Mossdale Red Kite circuit, Mossdale', 'https://www.walkhighlands.co.uk/galloway/mossdale.shtml', 4.0, 55, 1.0, 'This attractive short walk leads over mixed terrain much favoured by red kites. It takes in woodland, farmland and the shores of Mossdale Loch.', 55.0112, -4.0954),
('3399bc56-189c-5003-ab66-590db10a60b5', 'Glamaig - avoiding the scree', 'https://www.walkhighlands.co.uk/skye/glamaig.shtml', 6.5, 827, 5.0, 'Glamaig is one of the finest 360 degree views in Scotland, but its steep slopes on all sides deter many an ascent. This unfrequented route avoids the worst of the terrain, ascending via the NE ridge over An Coileach.', 57.3089, -6.0943),
('34279dd7-aa45-54d5-80bf-c787ce247fcc', 'Stob Coir''an Albannaich and Meall nan Eun', 'https://www.walkhighlands.co.uk/fortwilliam/stobcoiranalbannaich.shtml', 18.0, 1327, 9.0, 'Stob Coir''an Albannaich is a little visited mountain with fine northern corries. This route combines it with neighbouring Meall nan Eun to give an escape from the crowds in Glencoe to the north.', 56.5762, -5.03566),
('3427ff22-6cdc-563a-a6a9-5c89ead4e416', 'Càrn a'' Ghille Charr, Cromdale Hills', 'https://www.walkhighlands.co.uk/cairngorms/carn-a-ghille-charr.shtml', 10.5, 490, 4.5, 'Càrn a'' Ghille Charr the more northeasterly of the two Fionas in the Cromdale Hills. Though a simple rounded hill it has fewer visitors than its neighbour, and the old paths that lead up onto the ridge from the Cromdale side have become overgrown which means parts of the route involve harder going through deep heather.', 57.3501, -3.4787),
('342b4595-f5d0-5b45-8f1f-d173113d7bea', 'Hill of Fare: southern circuit', 'https://www.walkhighlands.co.uk/aberdeenshire/hill-of-fare.shtml', 18.25, 433, 5.0, 'The Hill of Fare is an area of rough moorland rising above forest plantations a few kilometres north of Banchory. The hill is criss-crossed by landrover tracks and this circuit through the Raemoir Estate on its southern slopes makes for an enjoyable walk with extensive views.', 57.0836, -2.51777),
('342cb92e-5315-52d3-9801-6cb2cd5749e6', 'Sgòrr nan Lochan Uaine and Sgùrr Dubh', 'https://www.walkhighlands.co.uk/torridon/sgorr-nan-lochan-uaine.shtml', 14.25, 985, 9.0, 'These two Corbetts on the south side of Glen Torridon attract little attention, even though Sgùrr Dubh towers impressively above the road. Whilst they don''t quite match up to their magnificent neighbours across the glen, they still offer a superb and very rugged mountain walk. The higher Sgòrr nan Lochan Uaine has a sharp peak though often hidden from view, whilst Sgùrr Dubh must rank amongst the rockiest mountains in Scotland. Both are stunning viewpoints.', 57.5547, -5.4156),
('3445f8da-96ad-5b6c-a3b9-f1cc126e30f5', 'Laide Wood, near Aultbea', 'https://www.walkhighlands.co.uk/torridon/laide-wood.shtml', 2.5, 25, 0.75, 'This short and easy walk leads through a former commercial plantation, now run as a community woodland with broadleaf species being planted. It visits two forest lochs and a cascading burn, and is very popular with local dog-walkers.', 57.8565, -5.5512),
('3467e4b3-94f5-542c-abe8-e19dc0e2a40f', 'Ellan Wood and the river, Carrbridge', 'https://www.walkhighlands.co.uk/cairngorms/ellan-woods.shtml', 4.5, 53, 1.5, 'Ellan Wood is a fine pine wood on the fringes of the village of Carrbridge. Partly owned by the Woodland Trust, it offers several short waymarked trails, which can be combined to give the walk described here. The route finishes with a riverside section to the much-photographed packhorse bridge.', 57.2823, -3.8197),
('34acaeab-13ed-50ee-99d1-8f2dfd37eabd', 'Sgòr na h-Ulaidh and Meall Lighiche', 'https://www.walkhighlands.co.uk/fortwilliam/sgornaulaidh.shtml', 16.0, 1292, 9.0, 'Sgòr na h-Ulaidh is the forgotten Munro amongst the Glencoe peaks, being out of sight for most of the road through the glen. Combined with the Corbett Meall na Lighiche, it gives a day with superb views - but with a very steep ascent.', 56.6611, -5.06878),
('34c1d97a-89df-5def-9ed8-66c98cd05118', 'Vatersay beaches circuit', 'https://www.walkhighlands.co.uk/outer-hebrides/vatersay.shtml', 6.75, 83, 3.0, 'A beautiful circuit of the southern half of Vatersay, taking in lovely beaches, colourful machair, iron-age fort and standing stone, and the remains of a land raiders village. Starts at Vatersay Hall which has a cafe and toilet.', 56.9271, -7.5363),
('34dba329-9a49-5c5b-ac43-2843d48faff0', 'Creag Chòinnich, Braemar', 'https://www.walkhighlands.co.uk/cairngorms/creag-choinnich.shtml', 2.7, 200, 2.0, 'Creag Chòinnich is the diminutive but beautiful little hill just east of Braemar, clothed in pinewoods. Its ascent makes a short but very steep walk, which can easily be combined with the Lion''s Face walk.', 57.0056, -3.39824),
('355cb8b3-9013-5a8b-9a09-e6e8d1d7313d', 'Kenmore Explorer', 'https://www.walkhighlands.co.uk/perthshire/kenmore-explorer.shtml', 5.75, 153, 2.0, 'This varied walk takes in pretty Kenmore and the banks of Loch Tay. It then follows a good path along the River Tay, a popular salmon fishing river, passing a couple of interesting estate monuments and follies. The return is through Drummond Hill woods.', 56.5845, -3.9974),
('358145f6-94e1-58d8-ac73-e01bf5b5e6fe', 'Killinallan Point circuit, Loch Gruinart', 'https://www.walkhighlands.co.uk/islay-jura/killinallan-point.shtml', 10.25, 48, 3.0, 'This is a great walk for wildife watching and beachcombing - follow the sands out to Killinallan Point at the mouth of Loch Gruinart and after more beach return on an inland track.', 55.8542, -6.3129),
('3585f15f-579d-5997-bab1-332f9ed13062', 'Ythan Estuary and Forvie Sands, near Newburgh', 'https://www.walkhighlands.co.uk/aberdeenshire/ythan-estuary.shtml', 6.0, 40, 2.0, 'This fine circular heads out along the bird-rich Ythan Estuary and through the dunes of the Forvie National Nature Reserve. It has a long beach section and also visits the ruins of Forvie Church - all that remains of a village destroyed by the sands. Dogs must be kept on leads and ensure you do not get too close or disturb any seals or ground-nesting birds - obey any signs.', 57.3333, -1.9956),
('359be37f-0729-5531-830f-45ecb3dec3b3', 'Millbuies Country Park, near Elgin', 'https://www.walkhighlands.co.uk/moray/millbuies.shtml', 2.7, 34, 0.75, 'A short exploration of this pretty loch surrounded by a variety of trees - a longer walk is also possible further from the water. There is a picnic area and toilets at the start. The walk is open from 8.30 am to last light all year round.', 57.5934, -3.2748),
('35b04cdb-9c2f-5c4b-9022-eb678c3bdd56', 'East Coast walk, South Ronaldsay', 'https://www.walkhighlands.co.uk/orkney/south-ronaldsay-coast.shtml', 14.5, 290, 5.5, 'This excellent linear coastal walk runs along much of the east coast of South Ronaldsay, from the southernmost point up to the graveyard at Kirkhouse, 3km from St Margaret''s Hope. Along the way is some fine coastal cliff scenery as well as archaeological remains. Transport would need to be arranged to walk the whole route, though there are several opportunities to join and leave the path.', 58.742, -2.9658),
('35be0807-61fa-5adc-b1c4-5240f6621a3c', 'Tyndall Bruce Monument and Falkland Estate', 'https://www.walkhighlands.co.uk/fife-stirling/tyndall-bruce-monument.shtml', 6.0, 138, 2.0, 'The Falkland Estate was once a hunting ground for the Stuart Kings and Queens; today the area is criss-crossed by good footpaths and provides a great place for a wander. This route climbs up to the Tyndall Bruce Monument before returning through the woods past the Witches'' Cave.', 56.2538, -3.2168),
('35d867c6-f14c-5834-b921-98829f229494', 'Auchindoun Castle, near Dufftown', 'https://www.walkhighlands.co.uk/moray/auchindoun-castle.shtml', 2.0, 74, 0.5, 'A short walk along a track and over fields to the ruins of this impressive castle with a bloody past. Surrounded by fields and moorland the castle has a great setting and is a good destination for children.', 57.4256, -3.1003),
('36045b63-55ab-5700-9e63-6e1bfe94a25d', 'Sallochy to Rowardennan', 'https://www.walkhighlands.co.uk/lochlomond/rowardennan.shtml', 4.5, 130, 1.5, 'This linear walk follows a popular section of the West Highland Way long distance path. Starting in Sallochy the route winds up through lovely oak woodland to reach various viewpoints at the shore of Loch Lomond. The walk finishes at Rowardennan where there is a hotel, car park and toilets. Unless transport has been arranged, the outward route can be retraced provided different views down the Loch.', 56.1275, -4.6085),
('36129dc6-06c7-52bd-baa4-37144bdc851c', 'Broad Law, Cramalt Craig and Dollar Law', 'https://www.walkhighlands.co.uk/borders/broad-law.shtml', 21.5, 778, 6.5, 'Broad Law is the second highest hill in Southern Scotland, and the highest in the Borders. Its rounded slopes culminate in a broad, domed summit that is unfortunately marred by an air traffic beacon and a nearby radio tower. After a sharp descent and climb to Cramalt Craig, a fine grassy ridge continues to Dollar Law. The return heads down to the reservoir and along the road.', 55.4691, -3.3451),
('36277736-fe89-5d71-a7ee-82332cd55364', 'South Berneray circuit', 'https://www.walkhighlands.co.uk/outer-hebrides/south-berneray.shtml', 4.5, 21, 1.5, 'A lovely coastal walk crossing the machair to reach Loch Bhuirgh and passing a monument to a modern day giant before reaching the vast beach on Berneray''s west coast. Can be combined with the north Berneray circuit to make a much longer day walk.', 57.707, -7.2142),
('36622005-af03-579a-ab95-802854befb12', 'Cruden Bay to the Bullers of Buchan', 'https://www.walkhighlands.co.uk/aberdeenshire/bullers-of-buchan.shtml', 4.5, 70, 2.0, 'This dramatic coastal walk passes the impressive ruins of Slains Castle, the inspiration for Dracula, and reaching the Bullers of Buchan, where there is a massive blow hole with several natural arches. A bus can be caught from the main road to return to Cruden Bay; alternatively those looking for a much longer walk could continue on the coast path to Boddam, or walk back the same way.', 57.4163, -1.8474),
('366f16d3-d257-5925-b27a-c6e7ba7b5b17', 'Iona: the south end', 'https://www.walkhighlands.co.uk/mull/iona-south.shtml', 8.5, 120, 3.0, 'Iona is perhaps the most celebrated of Scotland''s smaller islands, its famous Abbey drawing thousands of visitors. This walk explores the less frequented southern end of the island, passing fine beaches en route to the bay where St Columba first landed on the island.', 56.3303, -6.3922),
('36767787-9230-5eeb-bac8-121ab120f61d', 'Cuaig Beach', 'https://www.walkhighlands.co.uk/torridon/Cuaig.shtml', 2.0, 40, 1.0, 'This short walk to a little visited but beautiful sandy beach. The walk is best done around low tide as the sands are covered when the sea comes in.', 57.5523, -5.83717),
('36856531-5b20-5d31-ba30-fd6bf6f88828', 'Borgie Forest walk', 'https://www.walkhighlands.co.uk/sutherland/borgie-forest.shtml', 1.75, 34, 0.6666666666666666, 'This short forestry walk briefly follows the River Borgie - renowned for its salmon. It offers some welcome shelter on a windy day.', 58.4944, -4.2922),
('36864566-7364-5f14-9fb6-ce403971bcb1', 'Waternish Head Circuit', 'https://www.walkhighlands.co.uk/skye/waternishloop.shtml', 21.5, 490, 8.0, 'The Waternish Head circuit is a tough and challenging coast walk with excellent sea views. Note that the walk crosses croft land and the crofter has requested that dogs should be kept on a lead.', 57.5561, -6.6418),
('36cb3887-406f-5c58-a2e2-4335228b16c4', 'Acheninver Hostel and Badenscallie', 'https://www.walkhighlands.co.uk/ullapool/achininver.shtml', 3.25, 72, 1.0, 'This short ramble near Achiltibuie leads past remote Acheninver Hostel down to a beautiful stretch of shoreline. There are both pebble and sandy beaches and great views across Horse Sound.', 58.0, -5.31),
('37099907-7751-5ec8-9593-2e20c781514a', 'River Esk circuit, Cortachy', 'https://www.walkhighlands.co.uk/angus/cortachy.shtml', 3.75, 77, 1.0, 'A lovely wooded glen with specimen trees leads to the path alongside the beautiful River South Esk. Woodland and open countryside lead to the small settlement of Dykehead from where the road is followed back.', 56.7249, -2.9932),
('371196c4-f7e8-561d-a584-aa669050c406', 'Ceum an Fhraoich (Heather path), Dundreggan', 'https://www.walkhighlands.co.uk/lochness/ceum-an-fhraoich.shtml', 4.25, 206, 2.0, 'The Dundreggan Rewilding Centre - run by Trees for Life - has four waymarked routes through the beautiful native woodlands that surround it. This is the longest of the trails, climbing through the beautiful regenerating woodland to the moors above for fine views Glen Moriston.', 57.1922, -4.76302),
('373b76dd-526a-5f57-b150-50da76588390', 'Loch Scalpaidh, near Kyle of Lochalsh', 'https://www.walkhighlands.co.uk/kintail/Scalpaidh.shtml', 2.75, 125, 1.5, 'A short walk to a little visited and extremely peaceful freshwater loch, a quiet haven just a stone''s throw from the busy A87 road.', 57.2834, -5.69055),
('375db1eb-39bb-5f98-9ced-8ef70c8d6e3c', 'River Tay: Perth to Luncarty', 'https://www.walkhighlands.co.uk/perthshire/river-tay.shtml', 10.0, 20, 3.0, 'This fine linear walk follows the banks of the mighty River Tay from Perth city centre out to Luncarty to the north. The return to Perth can be made by bus.', 56.397, -3.4257),
('37614359-146d-51eb-877f-48b7b8989be3', 'Allt Robuic Waterfalls, Glenbranter', 'https://www.walkhighlands.co.uk/argyll/lauder-walk.shtml', 3.5, 125, 2.0, 'This excellent forestry walk visits the impressive Allt Robuic gorge and its waterfalls. The walk is often known as the Lauder walk after Sir Harry Lauder, a famous music hall star from the first half of the twentieth century and a former owner of the Glenbranter estate.', 56.1351, -5.0416),
('3774f2f9-2636-5aad-a8d5-e5b3211c0ab7', 'Findlater Castle from Cullen', 'https://www.walkhighlands.co.uk/moray/findlater-castle.shtml', 9.5, 95, 3.5, 'Explore the pretty fishing town of Cullen and then follow the dramatic coast to a sandy beach and then to the clifftop ruins of Findlater Castle.', 57.6915, -2.8191),
('37a8106d-0e45-5c1e-8f56-bda58dd6bc16', 'Collieston and Old Slains Castle', 'https://www.walkhighlands.co.uk/aberdeenshire/collieston.shtml', 4.5, 102, 2.0, 'This short but enjoyable circuit follows the rough coastal path north from Collieston atop some fine low coastal cliffs to reach the scant remains of Old Slains Castle, not to be confused with its more impressive (also ruined) replacement near Cruden Bay.', 57.3486, -1.9314),
('37c1d6a4-c0ba-5357-8a9d-1a9f8d259aa3', 'West Sands, St Andrews', 'https://www.walkhighlands.co.uk/fife-stirling/west-sands.shtml', 7.25, 17, 2.5, 'Stretch your legs on the spectacular and vast sandy beach made famous in the film, ''Chariots of Fire''. The route then passes through Eden Estuary nature reserve before a track leads between the famous golf courses with good views over fine buildings of St Andrews.', 56.3415, -2.8076),
('37e31120-1457-521d-9dfd-e6c4c1630eaf', 'Northern Bute circuit, Port Bannatyne', 'https://www.walkhighlands.co.uk/argyll/port-bannatyne.shtml', 20.5, 454, 6.0, 'The final stage of theWest Island Wayheads inland to climb over farm and moorland before looping through forestry high above the ferry terminal at Rhubodach. The route then heads south, eventually leaving the trees to climb over wild moorland with great views before descending to the road near Port Bannatyne.', 55.8608, -5.0872),
('380989b4-2dc3-550c-b263-92fd4c70a3bd', 'Ben Hiant, Ardnamurchan', 'https://www.walkhighlands.co.uk/fortwilliam/ben-hiant.shtml', 4.5, 347, 3.0, 'Ben Hiant may be only 528m high, but its position as the highest point out on the Ardnamurchan peninsula makes it a superlative viewpoint, taking in miles of coastline and countless islands. It''s also a shapely little peak in its own right - a perfect short hillwalk.', 56.7044, -6.0023),
('38546da1-12bc-50a4-8d65-6406ea26d6d0', 'Troup Head, near Pennan', 'https://www.walkhighlands.co.uk/aberdeenshire/troup-head.shtml', 2.5, 105, 1.0, 'The cliffs at Troup Head house mainland Scotland''s only gannetry, with 1,500 pairs of these majestic birds. There are also puffins, guillemots and razorbills. This short but very dramatic walk visits the clifftops overlooking the gannets'' nests.', 57.6873, -2.2992),
('38d6af0e-a5e2-58eb-b435-a5b9394a839e', 'Càrn na Caim and A''Bhuidheanach Bheag, Drumochter', 'https://www.walkhighlands.co.uk/cairngorms/carn-na-caim.shtml', 19.0, 824, 6.0, 'The east side of Drumochter pass is bounded by a steeply rising moor, riven by gullies. Suprisingly given its unimpressive appearance, there are two Munros on the plateau above. The hills themselves lack interest but this walk gives a real feeling of space. The tops are the haunt of dotterel and ptarmigan.', 56.9089, -4.2366),
('38f32415-80e0-512c-8922-318f969507a6', 'Wig Sands, near Kirkcolm', 'https://www.walkhighlands.co.uk/galloway/wig-sands.shtml', 3.25, 7, 1.0, 'This short coastal circular heads along the shore by Wig Sands, giving excellent birdwatching opportunities as well as views across Loch Ryan and up the coast to Ailsa Craig.', 54.9648, -5.0749),
('390c3041-6b40-53df-8fcb-59354296eb25', 'Creag Mhòr and Loch Avon, from Glenmore', 'https://www.walkhighlands.co.uk/cairngorms/creag-mhor.shtml', 32.0, 868, 10.0, 'Creag Mhòr is a Corbett which is dwarfed by the giant neighbouring mountains, though its summit is distinguished by a granite tor. Its position - that awkward to reach - makes it an excellent opportunity for a fine circuit, visiting the lower end of spectacular Loch Avon.', 57.1591, -3.6816),
('391ba851-81a7-5eb1-8d02-a6aac6bd88dc', 'Stiomrabhaigh, Orasaigh, South Lochs', 'https://www.walkhighlands.co.uk/outer-hebrides/stiomrabhaigh.shtml', 5.0, 86, 2.0, 'The rugged, hilly estate of Pairc, South Lochs, was once home to many people before being systematically cleared to become a vast sheep farm (and later deer estate). This walk visits Stiomrabhaigh, the site of one of many abandoned villages. It is a beautiful and remote spot, but the walk to reach is very steep in places.', 58.0188, -6.4647),
('39301fa4-eee0-5c18-90d4-57db5d363f68', 'Contin Forest & View Rock circuit, near Contin', 'https://www.walkhighlands.co.uk/lochness/Continforest.shtml', 4.5, 141, 1.5, 'This circular route heads through attractive birch, pine and spruce woodland visiting View Rock. Keep your eyes peeled for the elusive wildcat which lives in the vast Torrachilty forest.', 57.5767, -4.5903),
('3943fbae-3bfe-58b9-91b5-b8e212745910', 'Balblair Forest, near Bonar Bridge', 'https://www.walkhighlands.co.uk/sutherland/balblair.shtml', 8.0, 230, 2.5, 'Balblair Forest is on the hill slopes to the east of the Kyle of Sutherland; this forestry circuit offers some mixed woodland and climbs to a mast for views across the Kyle to Carbisdale Castle and down the Dornoch Firth.', 57.9035, -4.3571),
('3949130f-bc07-5967-ae81-b5f3d130a025', 'Aldie Burn, near Tain', 'https://www.walkhighlands.co.uk/ullapool/aldie-burn.shtml', 3.0, 45, 1.0, 'This easy forestry walk is popular with local dog-walkers. The surface has been improved to make it suitable for many prams and wheelchairs.', 57.7849, -4.0924),
('3971c65f-cdc2-5a7e-851f-bb5ef58d6d76', 'Dunnet Forest', 'https://www.walkhighlands.co.uk/sutherland/dunnet-forest.shtml', 4.0, 45, 5.0, 'Explore this experimental forest on a waymarked circular that includes sculptures, a log cabin and a giant wooden xylophone. The forest has recently planted native species and is a good place to spot birdlife.', 58.6095, -3.3431),
('39be50cd-556a-500d-a479-5f6af097fc78', 'Dunvegan Two Churches Walk, Dunvegan', 'https://www.walkhighlands.co.uk/skye/twochurches.shtml', 3.0, 88, 1.0, 'An easy walk through woodland and open moor with good views on the later sections.', 57.4384, -6.5832),
('3a2b1076-625a-547a-8e6b-db7764ce89b4', 'Cromarty coastal circuit and McFarquhar''s Bed', 'https://www.walkhighlands.co.uk/lochness/Sutors.shtml', 8.0, 245, 3.5, 'A lovely walk with plenty of good coastal views and varied interest. The route is very muddy underfoot in places and can get very overgrown in summer, there are two steep eroded sections on the way down to the Bed and care is needed with children because of the steep cliffs nearby.', 57.6816, -4.0322),
('3ae27f17-1b34-5d18-9718-65b41ddcf7cb', 'Drummuir Castle Estate and Lochpark', 'https://www.walkhighlands.co.uk/moray/drummuir.shtml', 7.75, 139, 2.5, 'This walk through the estate surrounding Drummuir Castle follows trails and tracks waymarked by a local group. It passes through a mix of farmland, pleasant woods and forest tracks above attractive man-made Loch Park.', 57.483, -3.0426),
('3b123640-9574-5120-9e9f-bbd2ce6ecc24', 'Weem Forest Trail, Weem by Aberfeldy', 'https://www.walkhighlands.co.uk/perthshire/weem-wood.shtml', 1.7, 74, 1.0, 'This short circular waymarked trail climbs through Weem Wood to St David''s Well which has a good view over Aberfeldy and Strathtay and then descends past crags and through native woods.', 56.6248, -3.89254),
('3b1901ed-f956-50f3-a2a9-4b1c36b3cf1b', 'Tentsmuir Forest & dunes, near Leuchars', 'https://www.walkhighlands.co.uk/fife-stirling/tentsmuir.shtml', 5.5, 5, 2.0, 'Explore the dunes of Tentsmuir Point nature reserve, a great place to watch waders and wildfowl and a favourite spot for both grey and common seals. The return is via a 19th century ice-house and through forest inhabited by red squirrels.', 56.4078, -2.8137),
('3b3767b9-9baa-519c-9cd5-81a363289e27', 'Tarbert Castle circular', 'https://www.walkhighlands.co.uk/argyll/tarbert-castle.shtml', 5.0, 260, 3.0, 'This excellent and well waymarked walk climbs high to the south of the attractive fishing village of Tarbert. It visits the crumbling remains of a medieval castle and enjoys excellent views.', 55.8643, -5.4118),
('3b3d4691-80c5-5ead-8c1c-2789d2e3e8a7', 'Skipness Castle', 'https://www.walkhighlands.co.uk/argyll/skipness-castle.shtml', 4.0, 44, 1.5, 'This short but beautiful walk visits the impressive 13th century Skipness Castle and chapel before heading out to the stunning beach at Skipness Point. The return heads up a wooded dell beside a burn - this can be muddy but could be omitted if preferred.', 55.7691, -5.344),
('3b42b29a-e270-54a1-953a-1a67474b1458', 'Aoineadh Mòr Cleared Village, Morvern', 'https://www.walkhighlands.co.uk/fortwilliam/inniemore.shtml', 3.25, 108, 1.5, 'This waymarked forest walk visits the sad remains of the cleared village of Aoineadh Mòr . The return variant climbs steeply but briefly and gives a great view over Loch Doire nam Mart.', 56.5996, -5.8005),
('3b6efbbb-7f79-5b32-972b-5c294c2165fa', 'Loch Leven Heritage Trail, Kinross', 'https://www.walkhighlands.co.uk/perthshire/loch-leven.shtml', 19.25, 15, 6.0, 'This level circuit follows a cycle path right around the Loch Leven National Nature Reserve. The route takes you to many beautiful spots on the lochside and through varied woods and marshland, and is particularly renowned for its birdlife. There are several opportunities for cafe stops along the way. Loch Leven is a highly-designated and internationally-important nature reserve; dogs are asked to be kept on leads or under close control at all times to prevent bird disturbance.', 56.2, -3.4173),
('3b766931-302d-59fa-8134-24973602d476', 'Prince Charlie''s Cave, Elgol', 'https://www.walkhighlands.co.uk/skye/prince-charlies-cave.shtml', 4.0, 170, 3.0, 'This short but rough walk visits the cave where Bonnie Prince Charlie spent his last night on Skye before escaping by boat once more. Excellent coastal scenery and stunning views throughout.', 57.1455, -6.1078),
('3ba3d4af-68b4-52e8-a7c3-e401644ee3f7', 'River Tyne: Haddington to East Linton', 'https://www.walkhighlands.co.uk/lothian/haddington-east-linton.shtml', 10.25, 5, 3.5, 'This attractive linear walk follows the banks of the River Tyne downstream from Haddington - the traditional capital of East Lothian - to historic East Linton. The walk has plenty of interest - including views of Hailes Castle on the opposite bank - and there is a good bus service available for the return journey.', 55.9556, -2.7791),
('3bb1ec66-7c5e-57fa-9246-cb258df7425d', 'Meall Buidhe', 'https://www.walkhighlands.co.uk/perthshire/meall-buidhe.shtml', 8.5, 551, 3.5, 'This straightforward Munro makes a pleasant walk with good views over Loch an Dàimh, the Trossachs, Rannoch Moor and the mountains further north on a clear day. The route can be boggy in parts and is often combined with Stuchd an Lochain on the other side of the dam to make a full day.', 56.5858, -4.42486),
('3bd2e7c0-a741-556e-8a79-26a14e1b53f1', 'Beinn Chabhair, from Inverarnan', 'https://www.walkhighlands.co.uk/lochlomond/beinn-chabhair.shtml', 13.0, 948, 6.5, 'Whilst it may rank amongst the smaller Munros, Beinn Chabhair is a suprisingly rugged peak with great character. The summit ridge is a lumpy collection of knolls and rocky humps which make a fine walk. The start via Beinglas Falls is very steep and eroded, and there is fair amount of boggy ground on the middle, moorland section.', 56.3285, -4.7218),
('3be82a1b-00ad-5c8c-890d-e27f242fb568', 'Drumpellier Country Park, Coatbridge', 'https://www.walkhighlands.co.uk/glasgow/drumpellier.shtml', 4.25, 31, 1.5, 'Set on the edge of Coatbridge, Drumpellier Country Park is centred on two fine natural lochs - Woodend and Lochend. This popular walk encircles Lochend Loch and explores the woodland to its south.', 55.8735, -4.0709),
('3c0bb27a-4538-5099-a3d2-26e92c022ed4', 'Rhuvaal Lighthouse, Bunnahabhain', 'https://www.walkhighlands.co.uk/islay-jura/rubh-a-mhail.shtml', 13.5, 184, 5.0, 'A coastal there and back walk to reach the lighthouse at Rubh''a''Mhail, the most northerly point on Islay, good views to Jura and chance to spot otters and seals at the jetty.', 55.8839, -6.12963),
('3c0cc826-6bc2-58e9-9e7c-c9f5b4098e65', 'Moncreiffe Hill near Perth', 'https://www.walkhighlands.co.uk/perthshire/moncrieffe-hill.shtml', 8.3, 330, 3.0, 'This excellent circular walk explores Moncreiffe Hill, a beautiful woodland managed by the  Woodland Trust, as well as visiting the summit with its grand views over Perth, the Ochils and Fife.', 56.3576, -3.3717),
('3c12eef6-18af-5ce2-b367-86de6d895056', 'Sands of Breckon and Gloup Ness, Yell', 'https://www.walkhighlands.co.uk/shetland/sands-of-breckon.shtml', 9.0, 211, 4.5, 'Sheltered except to the northwest, the magnificent Sands of Breckon is the finest beach on Yell. This walk heads along the northernmost headland of the island - the Ness of Houlland - before visiting the beach. It then continues above the remote coastline to reach the old coastguard lookout on Gloup Ness - with fine views taking in the whole west coast of Unst and Muckle Flugga beyond.', 60.7234, -1.0363),
('3c8e075c-257c-5b85-b6cb-5d032e2241a9', 'Beinn Luibhean', 'https://www.walkhighlands.co.uk/lochlomond/beinn-luibhean.shtml', 4.5, 674, 4.0, 'Very much in the shadow of its higher neighbour Beinn Ìme, Beinn Luibhean is something of a Cinderella amongst the Arrochar Alps. Its ascent provides a short, mostly pathless but steep and grassy hillwalk from part way up the Rest and Be Thankful Pass.', 56.2141, -4.8351),
('3d4ecb0c-e4da-51b5-b315-4f963485e6b9', 'Beinn an Sguirr, Gillen', 'https://www.walkhighlands.co.uk/skye/gillen.shtml', 5.5, 182, 2.5, 'This moorland and clifftop circuit visits the impressive escarpments above the eastern coastline of the Waternish peninsula, with superb views.', 57.5417, -6.5667),
('3d587978-f776-52ec-95d7-7ad5d0ac98e6', 'Cairn William, Pitfitchie Forest, near Alford', 'https://www.walkhighlands.co.uk/aberdeenshire/cairn-william.shtml', 16.0, 421, 4.0, 'This pleasant circuit follows tracks and mountain biking paths through the forests and over the heathery, granite ridge of Cairn William. There are good views over the Aberdeenshire countryside.', 57.2082, -2.57328),
('3d8d28a9-e028-542e-aad6-3c1acd6f0a87', 'Doggartland walk, Dalry', 'https://www.walkhighlands.co.uk/glasgow/doggartland-dalry.shtml', 4.25, 60, 1.5, 'This circular walk on the outskirts of Dalry provides a quiet leg-stretcher through woods, farmland and quiet country lanes.', 55.7087, -4.72026),
('3d9d9219-6cd8-50b1-8767-585814aa80b3', 'Beinn na h-Eaglaise and Beinn nan Caorach', 'https://www.walkhighlands.co.uk/kintail/beinn-na-h-eaglaise.shtml', 11.5, 1020, 8.0, 'This short but very steep hillwalk takes in both of the Corbetts on the Glenelg peninsula. The pathless going is rewarded by truly stunning views in what must be one of the most beautiful corners of the Highlands.', 57.1251, -5.55389),
('3e271112-aa4b-5c2a-a2cb-2abf119df5b9', 'Sanna beaches and Point circuit from Portuairk', 'https://www.walkhighlands.co.uk/fortwilliam/sanna.shtml', 7.0, 179, 3.5, 'This idyllic walk explores some of the fabulous beaches on the northern coast of the Ardnamurchan Peninsula. In good weather, there are great views out to the Small Isles of Muck, Eigg and Rum.', 56.7318, -6.18701),
('3e3fa540-6ab2-5820-b54a-17e57a78abd9', 'Glasgow Murals Trail', 'https://www.walkhighlands.co.uk/glasgow/glasgow-murals.shtml', 9.75, 55, 4.0, 'Glasgow has a fantastic array of street murals. These impressive creations decorate blank end walls and vacant buildings and help to transform otherwise less attractive corners of the city into striking public art works. This walk visits many of the most impressive creations within the city centre; the artworks give great focus to an exploration of the city on foot. These works are ephemeral by nature; they are created, recreated and lost as buildings move into and out of use; some of the murals may change or be removed in the future. This is the third version on Walkhighlands!', 55.8638, -4.2529),
('3e63ce06-57e6-50e4-ab97-3ca7c9c1d477', 'Handa Island, near Tarbet', 'https://www.walkhighlands.co.uk/sutherland/handa-island.shtml', 6.5, 120, 3.5, 'Handa Island is a magical place for a walk. This unmissable and very popular excursion runs from the fine sandy beaches at its southern end to the mighty cliffs and Great Stack at the northern. The island has a fascinating history and is now a nature reserve run by the Scottish Wildlife Trust, protecting its important seabird colonies.', 58.3778, -5.17),
('3e6cffb6-8857-52f4-ae52-e6a1a1329443', 'Stuis of Graveland, Yell', 'https://www.walkhighlands.co.uk/shetland/stuis-of-graveland.shtml', 11.5, 330, 5.0, 'The Stuis of Graveland is a wild peninsula on the west side of Yell, striking out northwards between Whale Firth and Yell Sound. Its dramatic clifftop coastal scenery is revealed only to those prepared to undertake a rough moorland yomp to reach it.', 60.6149, -1.1571),
('3e82ebfe-5b36-5794-8e3a-33e74437200a', 'Cave of Gold, Kilmuir', 'https://www.walkhighlands.co.uk/skye/caveofgold.shtml', 2.25, 68, 1.0, 'The Uamh Òir or Cave of Gold is a secret place, Skye''s answer to Fingal''s cave on Staffa but in miniature. It gives a delightful short walk and is a great place for a picnic; however the final pathless coastal slope down to the cave is very steep and dangerous, requiring great care.', 57.6588, -6.3968),
('3ea0e8b8-a091-561d-8c34-2c55645310f9', 'Old Herring Path (Meal Path), Corran', 'https://www.walkhighlands.co.uk/kintail/Corrancoast.shtml', 7.5, 140, 4.0, 'This fabulous but rough coastal walk follows the route of an enchanting but almost forgotten old herring path through some of Scotland''s finest scenery.', 57.1252, -5.555),
('3eefa5b1-a5a2-5b26-96bb-c84afbbd4adc', 'Buckie and Portgordon: Gollachy circuit', 'https://www.walkhighlands.co.uk/moray/buckie.shtml', 8.75, 87, 3.0, 'This route, waymarked as the Gollachy Circular, heads along the seafront between the old fishing town of Buckie and its neighbour Portgordon; the return route is slightly inland. Though the route is close to the A990 for most of the way it does avoid the road.', 57.6764, -2.9644),
('3ef6575e-1259-566a-8535-b82bf15dd106', 'Tinto from Wiston Lodge', 'https://www.walkhighlands.co.uk/glasgow/tinto-wiston.shtml', 6.0, 454, 3.5, 'Tinto, with its easy access from Glasgow and the central belt, is one of the most popular hills in Scotland when climbed via its main path from the north. This alternative may appeal to experienced hillwalkers looking for a quieter day as it ascends the much steeper and rougher southern slopes.', 55.5723, -3.6565),
('3f14dc0a-8201-5477-9cae-2d1c92eccaf5', 'Moffat riverside', 'https://www.walkhighlands.co.uk/galloway/moffat-riverside.shtml', 4.5, 22, 1.5, 'This straightforward walk from Moffat follows the wooded banks of the River Annan before returning back to the town along a quiet road.', 55.3293, -3.4458),
('3f21ff93-2ddf-51a7-b8ef-18c37e229267', 'Three lochs circuit, south Loch Ness', 'https://www.walkhighlands.co.uk/lochness/Threelochs.shtml', 12.5, 193, 3.5, 'Delightful walk through varied and quiet countryside, taking in three lochs, each with a distinct character, on the south of Loch Ness.', 57.3591, -4.2501),
('3f66391f-a1c1-5ad0-84e2-46105d002862', 'Beinn Mhanach', 'https://www.walkhighlands.co.uk/argyll/beinn-mhanach.shtml', 23.5, 920, 7.5, 'Beinn Mhanach is a dome-shaped and unspectacular Munro. One of the remoter peaks of the Southern Highlands, it does have a feeling of seclusion and the approach up the glen from Auch is very enjoyable.', 56.4607, -4.71466),
('3fd37575-c31a-5ef6-83e6-0e3a506f7f13', 'The Mell circuit, Glen Finglas', 'https://www.walkhighlands.co.uk/lochlomond/glen-finglas.shtml', 27.0, 560, 7.0, 'This long and hilly circuit takes in Glen Finglas Reservoir before heading up wild Glen Meann and climbing to a high pass to circle Meall Cala known as The Mell. Beautiful woods and rushing streams are found in the glens, while the summit of the trail at 600 metres has a bleak mountain feel.', 56.229, -4.3467),
('3fe35448-6929-5e2c-b330-cd4565c733f7', 'Ben Newe, Strathdon', 'https://www.walkhighlands.co.uk/cairngorms/ben-newe.shtml', 4.0, 211, 2.0, 'This enjoyable route climbs up through the Ben Newe forestry plantations before visiting the characterful rocky summit. It''s a really outstanding 360 degree viewpoint over Strathdon and Glenbuchat, and to the Cairngorms.', 57.2098, -3.0385),
('3fe80da3-ffc2-5255-81c4-0104da776b5d', 'Rosemarkie to Cromarty', 'https://www.walkhighlands.co.uk/lochness/Cromartycoast.shtml', 15.0, 400, 5.5, 'A one-way coastal route from Rosemarkie to Cromarty - the return can be made by public transport (check the times). The first half of the walk is a rough walk along the shoreline with much interest; the second half is mostly on very quiet roads with good views.', 57.5928, -4.1176),
('40024127-815a-5421-89a2-5c665ee3574c', 'Hartaval and Baca Ruadh', 'https://www.walkhighlands.co.uk/skye/hartaval.shtml', 19.0, 1230, 8.0, 'An exploration of the Trotternish Ridge north of the Storr. This is a spectacular section of ridge and you can continue as far as you wish, however the return has to be made the same way.', 57.4977, -6.1594),
('40197464-d0d9-5820-8ed0-131fa1d8cc67', 'Mousa - the broch and RSPB reserve', 'https://www.walkhighlands.co.uk/shetland/mousa.shtml', 3.5, 44, 2.0, 'The island of Mousa - off the east coast of Shetland''s mainland is famed for its spectacular iron age broch - the most complete and best preserved of all such structures. The whole experience of taking the boat over and exploring the island - an RSPB reserve - on foot is a magical one; one of Shetland''s finest excursions.', 60.0022, -1.1847),
('40769ea3-2a17-56de-b63a-cf5ac393b21b', 'Beinn Loinne, from Cluanie', 'https://www.walkhighlands.co.uk/kintail/beinn-loinne.shtml', 18.0, 630, 6.0, 'The ascent of Beinn Loinne is a fairly straightforward trudge of a hillwalk from Cluanie; the reward is in the fine views, particularly of the Glen Shiel mountains.', 57.1557, -5.1779),
('4080e0d3-816d-5256-907b-6915b65d517a', 'Balmashanner Hill, Forfar', 'https://www.walkhighlands.co.uk/angus/balmashanner-hill.shtml', 4.0, 115, 1.5, 'Balmashanner Hill - locally known as Bummie - rises from the southern edges of Forfar and from its memorial there are fine views over the town. This short walk climbs up through Reid Park to make an enjoyable round.', 56.6448, -2.8908),
('408cad86-0f9c-5467-86b3-75cd22f020e0', 'Clauchlands Point and Dun Fionn', 'https://www.walkhighlands.co.uk/arran/dun-fionn.shtml', 5.0, 172, 2.0, 'This fine shorter circular route features coastal walking and a steep climb to an Iron Age fort with good views. The route finishes with a pleasant return through farm and woodland.', 55.5487, -5.09455),
('40c42bd5-41ff-52be-a782-3dd34b1ba882', 'The Ring of Brodgar and Stones of Stenness', 'https://www.walkhighlands.co.uk/orkney/ring-of-brodgar.shtml', 4.5, 11, 1.5, 'Although always near or on a road, this route along the Brodgar Peninsular links together some of the most archaeologically-significant sites in Britain. The Ring of Brodgar forms the heart of a huge prehistoric ceremonial complex positioned in a key location known as the Ness of Brodgar. Occupying the land between the Ring of Brodgar and the nearby Stones of Stenness this 2.5 hectare site has been excavated over recent years to reveal housing, decorated stone slabs, a massive stone wall with foundations, and a large building described variously as a Neolithic palace, cathedral or temple. The significance of the discoveries here has led archaeologists to declare the Ness of Brodgar a site of international importance, and shifted focus away from Stonehenge in the south of England to the far north.', 59.0048, -3.2317),
('40df0466-ab15-58e7-8b9b-e7e782422165', 'Daviot Wood circuit, Daviot', 'https://www.walkhighlands.co.uk/lochness/daviot.shtml', 3.75, 98, 1.0, 'A short leg stretcher in forestry with good views on the ascent and a chance to see red squirrels and roe deer. The noise of the A9 is ever present for the first half of the route.', 57.4248, -4.1305),
('40f65232-36c4-5cac-ad03-b5d76f1a5afc', 'Lochcarron Coffin Road circuit', 'https://www.walkhighlands.co.uk/torridon/lochcarron-coffin-road.shtml', 5.0, 116, 1.5, 'This circuit follows the line of the old coffin and drove road from Kirkton, before descending to Lochcarron and returning along the shore road.', 57.4139, -5.47346),
('40ff61b2-149b-5bef-905f-75d14b4aef41', 'Winding Walks, near Fochabers', 'https://www.walkhighlands.co.uk/moray/winding-walks.shtml', 5.75, 181, 2.5, 'This circular walk combines several of the waymarked walking trails at Winding Woods near Fochabers, It begins up the side of the Small Burn, passes Longhowe Loch and climbs up to the monument atop Whiteash Hill. On the descent the route takes in Peep''s Viewpoint overlooking Fochabers.', 57.6121, -3.0755),
('411bf5ce-3f64-5993-a767-d258d3e4ed66', 'Caisteal Abhail, via North Glen Sannox', 'https://www.walkhighlands.co.uk/arran/caisteal-abhail.shtml', 10.5, 838, 6.5, 'Caisteal Abhail is the most northerly of the Arran Corbetts, often known as the Sleeping Warrior due to its outline when seen from the Ayrshire coastline. This rocky mountain is a truly stunning viewpoint and has several granite tors on its summit, and a jagged cleft known as the Witches'' Step cuts deeply into its east ridge. The easiest ascent is via the northwest ridge, as described here.', 55.673, -5.19294),
('413a3cc1-2769-5d96-b300-345e170278e4', 'Gleann Lichd', 'https://www.walkhighlands.co.uk/kintail/Glenlichd.shtml', 13.0, 245, 4.0, 'Gleann Lichd is a quintessential wild Highland glen. There are few easy walks in the Kintail area, but this glen has a simple track; the walk up the glen can be made as short as you like.', 57.2349, -5.38087),
('4154ebfb-0f09-5a05-9892-a3daa92fd3ce', 'Three Lochs Circuit, Barabhas', 'https://www.walkhighlands.co.uk/outer-hebrides/three-lochs.shtml', 7.5, 89, 2.0, 'Starting at the stunning coastal Loch Mòr Bharabhais this route heads inland over wet ground to visit two more lochs and return via the small setttlement of Bru. Good bird watching opportunities.', 58.3639, -6.5482),
('415acac6-121e-5fae-ab47-30e10ec50127', 'Dùn Carloway Broch and moorland circuit', 'https://www.walkhighlands.co.uk/outer-hebrides/dun-carloway.shtml', 5.25, 98, 2.5, 'After exploring the stunning remains of Dùn Carloway broch, follow the remains of an ancient path past two peaceful moorland lochs and peat cuttings to reach the Doune Braes Hotel from where the return is on the road.', 58.2687, -6.7909),
('415fa081-bea9-59aa-ace5-69e69505bb79', 'Fas na Cloiche and the Fairy Bridge, Glen Creran', 'https://www.walkhighlands.co.uk/argyll/fas-na-cloiche.shtml', 4.0, 130, 1.5, 'The walk takes in the lovely mixed woodland of Coille Mheadonach and has good views up Glen Creran. A muddy section then leads to a pretty bridge and waterfall and then a chance to view the tree growing from the rock before returning along the minor road up the glen.', 56.5903, -5.20035),
('4187c222-8528-57d3-b7a6-bcf476c9a769', 'Kildonan Shore walk', 'https://www.walkhighlands.co.uk/arran/kildonan-shore.shtml', 4.25, 14, 2.0, 'This linear walk leads along a rugged shoreline below impressive cliffs with the opportunity to see a variety of wildlife at close quarters.  The return is made the same way.', 55.4427, -5.1296),
('41890d00-48a3-559e-9b1a-e92b467b9297', 'Sandend and Findlater Castle, Sandend', 'https://www.walkhighlands.co.uk/aberdeenshire/sandend-findlater.shtml', 5.0, 84, 2.0, 'Visit Findlater Castle and the fascinating medieval dovecot on this excellent short coastal circuit from the picturesque fishing village of Sandend.', 57.6829, -2.7486),
('41f16e4a-10fc-5782-9fb0-687411dc3949', 'Eoligarry Explorer', 'https://www.walkhighlands.co.uk/outer-hebrides/eoligarry.shtml', 8.75, 131, 3.5, 'The Eoligarry peninsula is the northernmost part of Barra; this varied walk ascends its low hill for great views, visits a historic church and dun, and heads along some superb beaches. There is a cafe at the airport on the route.', 57.0416, -7.4216),
('41f891f5-0254-5c9a-b03c-cd263e1e8c9e', 'Polglass broch and Rubha Dunan', 'https://www.walkhighlands.co.uk/ullapool/polglass-broch.shtml', 4.0, 67, 1.0, 'This short walk visits the bay at Polglass to pass a ruined broch and houses and then follow a grassy path out to the headland of Rubha Dunan. A wonderful spot to watch for otters and other sea life or enjoy the sunsets and view of Horse and Goat islands. The continuation has a rocky stretch and some boggy ground. The walk crosses working croft land and dogs are requested to be kept on a lead.', 58.0147, -5.3386),
('421fd5b4-5eef-5fb5-a95d-c0c48f939799', 'Sluie Walk, near Forres', 'https://www.walkhighlands.co.uk/moray/sluie-walk.shtml', 3.5, 58, 1.0, 'This short but dramatic woodland walk runs high above the swirling waters of the River Findhorn and its gorge, giving views of the rapids and pools far below. The views of the river are obscured somewhat by leaves in the summer months. Care should be taken especially with children.', 57.5521, -3.6509),
('425601e9-1c0c-50ca-9f50-bfe1d5201a69', 'Beinn Sgulaird', 'https://www.walkhighlands.co.uk/argyll/beinn-sgulaird.shtml', 13.0, 1240, 8.0, 'Beinn Sgulaird is a solitary Munro, rising steeply above upper Loch Creran. The upper slopes are rocky but the summit is best known as a fantastic viewpoint. On a clear day the 360 degree panorama of mountains, lochs, sea and islands is one of the finest in Scotland.', 56.5556, -5.2413),
('4271387f-44db-5bfe-876f-a4b64aa33865', 'Falls of Truim and Truim woods', 'https://www.walkhighlands.co.uk/cairngorms/falls-of-truim.shtml', 9.0, 340, 3.0, 'This varied walk visits the picturesque Falls of Truim before following an old Right of Way through an area of sheep grazings, with good views of the Cairngorms mountains. It then leads through pleasant forestry for a circuit of Glen Truim Woods - including a climb to a high crag which is an excellent viewpoint.', 57.0021, -4.1728),
('428ca778-396c-5e37-b919-1dcbe07b6fd1', 'Hardens Hill circular, Duns', 'https://www.walkhighlands.co.uk/borders/hardens-hill.shtml', 31.0, 677, 8.0, 'Starting and finishing from the market town of Duns this long circular route starts and finishes in the parkland around the castle but takes you on forest paths and into the surrounding rolling hills for a close encounter with wind turbines. There are good views of the Cheviots and the Eildons and plenty of opportunity to spot wildlife, from the array of birds and maybe a squirrel in the reserve to pheasant, grouse, rabbits and hares on hills and maybe a deer in the forest. This is a long walk which can be easily be shortened if desired.', 55.7785, -2.3454),
('432e80df-e1f9-518c-8bda-c042979ad8a0', 'War Ness and Ward Hill, Eday', 'https://www.walkhighlands.co.uk/orkney/war-ness.shtml', 6.5, 110, 3.0, 'Explore the Point of War Ness where seals often haul out, coastal cliffs teeming with seabirds, and then climb through farmland and heather moorland to Ward Hill which has great views.', 59.1445, -2.773),
('434c96f2-8a57-51c5-85b0-60dfeabe0293', 'Ben Avon via Gleann an-Slugain', 'https://www.walkhighlands.co.uk/cairngorms/ben-avon.shtml', 33.5, 1004, 10.0, 'Ben Avon is the easternmost of the High Cairngorms and its vast high level plateau sprawls over an area large enough for an entire hill range in the West Highlands. Its outstanding feature is the array of remarkable granite tors all over the plateau.  This walk gives the shortest ascent, using the old right of way up Gleann an t-Slugain.', 57.0057, -3.3381),
('435039fa-0b75-5a65-818f-1c1176e4de8d', 'Ayre to Cantick Head coastal circuit, South Walls', 'https://www.walkhighlands.co.uk/orkney/south-walls.shtml', 13.0, 249, 4.5, 'The stunning coastline of South Walls has dramatic stacks, arches, and gloups on the way to Cantick Head lighthouse. The return is on a pleasant minor road which cuts across South Walls - or the outward coastal route could be retraced for a slightly longer walk.', 58.7852, -3.2258)
INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('4376e452-1c73-5aae-a4d1-80c522f59f35', 'Dunnet Bay', 'https://www.walkhighlands.co.uk/sutherland/dunnet-bay.shtml', 5.0, 5, 2.0, 'Dunnet Bay is a fantastic sweeping arc of sand backed by dunes. A birdlife haven, the beach is also popular with surfers, beach combers and walkers.', 58.6156, -3.3457),
('437bb467-ccda-53ce-b791-e489337cb17d', 'Caisteal Dubh, near Grandtully', 'https://www.walkhighlands.co.uk/perthshire/caisteal-dubh.shtml', 5.8, 244, 1.5, 'This waymarked forest walk climbs to the hilltop site of an ancient fort - anglicised to Castle Dow on maps - where a line of cairns enjoy splendid views over this part of Perthshire.', 56.6509, -3.7427),
('43999f01-e1d4-556a-8ff7-b82384cfc05d', 'Inchcailloch island', 'https://www.walkhighlands.co.uk/lochlomond/inchcailloch.shtml', 3.0, 94, 1.5, 'Inchcailloch may not be the largest, but it is the most accessible and probably the most beautiful, of Loch Lomond''s islands. Part of a National Nature Reserve, the island has wonderful woodlands and offers fabulous views out across the loch.', 56.0824, -4.5511),
('43a60dfd-86fd-507a-80b5-dd4fafe9af49', 'Cairnsmore of Fleet, near Newton Stewart', 'https://www.walkhighlands.co.uk/galloway/cairnsmore-of-fleet.shtml', 12.25, 691, 5.0, 'The Cairnsmore of Fleet is the most southerly two thousand foot hill in Scotland and a magnificent viewpoint for the Cree Estuary and the Solway. It makes for a popular and fairly straightforward hillwalk.', 54.9399, -4.3997),
('43a93f2b-2cbb-5973-8b3d-136e01391006', 'Kylerhea hills circuit', 'https://www.walkhighlands.co.uk/skye/kylerheahills.shtml', 14.0, 1225, 10.0, 'A challenging circuit with a mountainous feel, rewarded by great views all round. A tough day walk but without the scrambling required in the Cuillin and in a very quiet part of the island.', 57.2278, -5.6687),
('43b2b356-917e-51f0-a5e7-8c3cee5cf7d9', 'Falls of Kirkaig, Inverkirkaig', 'https://www.walkhighlands.co.uk/ullapool/falls-of-kirkaig.shtml', 7.0, 165, 3.0, 'A walk up a beautiful wooded glen to the moorland above for a visit to the impressive Falls of Kirkaig.', 58.1215, -5.252),
('43dfd2b7-dba7-59cc-bdc0-53a2505cd077', 'The Isle of May', 'https://www.walkhighlands.co.uk/fife-stirling/isle-of-may.shtml', 4.0, 135, 2.0, 'The Isle of May is a stunning place to visit. A National Nature Reserve and home to a huge puffin colony, grey seals, razorbills, shags, eider ducks and other seabirds, the island also has fabulous cliff scenery and a fascinating history. Commercial boat trips operate from 1st April to end of September from Anstruther and usually give 2 - 3 hours ashore on the island to enjoy the walk.', 56.1831, -2.5497),
('43ef995d-9af9-524b-a834-77940704a502', 'Ardnamurchan Point and Bay MacNeil, Portuairk', 'https://www.walkhighlands.co.uk/fortwilliam/ardnamurchanpoint.shtml', 9.5, 185, 3.5, 'This excellent circuit from Portuairk gives grand views out to the Isles en route to the superb sandy beach of McNeil Bay. Ardnamurchan Point lighthouse - the most westerly point on the UK mainland, now housing a cafe and visitor centre - is visited by a detour along the minor road.', 56.7317, -6.18697),
('43f67ebc-a608-5068-8f4c-353480a2d40d', 'Loch na Bo, near Lhanbryde', 'https://www.walkhighlands.co.uk/moray/loch-na-bo.shtml', 2.5, 8, 1.0, 'A pleasant woodland circuit of Loch na Bo, a man-made loch with a beautiful woodland setting to the south of Llanbryde.', 57.6207, -3.2036),
('440e984b-c870-5e76-9502-7d241e772cc5', 'Cairn Table, near Muirkirk', 'https://www.walkhighlands.co.uk/glasgow/cairn-table.shtml', 8.75, 353, 3.0, 'A proper hill walk to the summit of a proper Ayrshire hill. This circular route offers variety by returning via the old Muirkirk to Sanquhar drover''s road. The walk is relatively straightforward but there is a very boggy section on the approach, over which progress is aided by some boardwalks and new pathwork.', 55.5147, -4.06617),
('443667c0-58e0-5893-ac06-9a1748f61bee', 'Archbank and Frenchland, Moffat', 'https://www.walkhighlands.co.uk/galloway/archbank-frenchland.shtml', 5.75, 99, 2.0, 'This enjoyable waymarked circuit from Moffat explores the rolling fields, paths and pastures to the northeast side of this old Spa town.', 55.3329, -3.4438),
('4451f046-1bc3-526d-9e71-3e07443303d3', 'St Catherine''s Bay, Stronsay', 'https://www.walkhighlands.co.uk/orkney/st-catherines-bay.shtml', 6.25, 50, 2.0, 'This linear out-and-back walk along quiet tarmac lanes links the village and harbour at Whitehall - the ferry port for Stronsay - to the very beautiful sandy beach at St Catherine''s Bay.', 59.1416, -2.5972),
('44830807-1a81-54ee-95e3-3da7d7635b43', 'Jubilee Bridge & Castle Stalker, near Port Appin', 'https://www.walkhighlands.co.uk/argyll/castlestalker.shtml', 3.5, 22, 1.5, 'This easy walk crosses the impressively long and rickety Jubilee Bridge across the tidal marshes of Loch Laich. The walk then follows a cycletrack and the shoreline to a good viewpoint of Castle Stalker before returning by the same route.', 56.5644, -5.38006),
('44950bb1-f5ae-528e-8991-81fbcee36917', 'Belhaven Bay, near Dunbar', 'https://www.walkhighlands.co.uk/lothian/belhaven-bay.shtml', 6.0, 5, 2.0, 'The superb dune-backed beach at Belhaven Bay is amongst the finest in East Lothian. The Bay is part of the John Muir Country Park; this route heads out across the sands before returning via the salt flats at the mouth of the River Tyne and through the plantations. There may be signed diversions/exclusion zones during tern nesting season, please follow any instructions.', 56.0005, -2.561),
('44f647fd-db65-5d9c-98bd-08b4ec6e20a4', 'Fife Coastal Path 7: Anstruther to Crail', 'https://www.walkhighlands.co.uk/fife-stirling/anstruther-crail.shtml', 6.75, 52, 2.0, 'This is one of the most popular sections of the Fife Coastal Path, linking the largest of the East Neuk fishing ports - Anstruther - with perhaps the most photographed - Crail. The going is straightforward and the views over to the Isle of May and the Bass Rock are excellent.', 56.223, -2.7008),
('452a9334-787b-52b2-b304-a6084b4f447a', 'Coulin Pass - Achnashellach to Torridon', 'https://www.walkhighlands.co.uk/torridon/Coulinpass.shtml', 15.0, 455, 7.0, 'This excellent linear walk starts at Achnashellach Station and follows the River Làir with good views of Fuar Tholl, Sgòrr Ruadh and Beinn Liath Mhòr before descending to a pretty waterfall and Scots pines at Easan Dorcha. A level section leads to Loch Coulin with great views of Beinn Eighe and then skirts Loch Clair with views of Liathach to reach the main road through Torridon - quite a short cut from the road route! This route can be shortened by taking the forestry track and Coulin Pass variation, which is the traditional route though less scenic.', 57.4818, -5.32941),
('455db148-1db6-5b65-996b-bca325f78e8f', 'Port Ellen standing stones loop', 'https://www.walkhighlands.co.uk/islay-jura/port-ellen.shtml', 5.0, 63, 1.5, 'This route follows a loop around minor roads to the east of picturesque Port Ellen, which sits right on a sandy beach. The walk gives easy going and visits three ancient standing stones.', 55.6298, -6.18597),
('45b32e57-4a83-5f02-ba9a-f6af5307fa83', 'Tiumpan Head circuit, Point', 'https://www.walkhighlands.co.uk/outer-hebrides/tiumpan-head.shtml', 1.75, 51, 1.0, 'Fine coastal scenery on this short circular route taking in Tiumpan Lighthouse. The cliffs are popular with nesting seabirds.', 58.2604, -6.1392),
('45b5cb4f-59eb-5c65-90b9-2e46cb805277', 'Aberlady Bay and Gullane Point', 'https://www.walkhighlands.co.uk/lothian/aberlady-gullane.shtml', 9.0, 55, 3.5, 'Aberlady Bay is a beautiful local nature reserve (the first in Britain when declared in 1952) and is renowned especially as a bird-watching venue. This circular walk heads through the reserve to take in the fine sandy beach before continuing to the village of Gullane and returning inland. Note that dogs are not permitted on the nature reserve.', 56.0144, -2.8495),
('45c7bc78-210b-5eb1-8114-fb36ed998e1d', 'Crater Loch: Lochan ''S Airde Beinn', 'https://www.walkhighlands.co.uk/mull/crater-lake.shtml', 3.0, 138, 1.5, 'Climb to the top of volcanic ''S Airde Beinn to walk round the rim of Crater Loch. On a clear day there are stunning views and the walk, although short, has a rugged mountain feel.', 56.5982, -6.1144),
('45f1b798-98bd-564d-9171-4e28b9833b2b', 'Laggan circuit, from Lochranza', 'https://www.walkhighlands.co.uk/arran/laggan.shtml', 11.5, 330, 4.0, 'This fine circuit begins with a climb over moors revealing stunning views across the Clyde islands; it then descends to the remote cottage at Laggan for a return along a rugged section of the Arran Coastal Way.', 55.7055, -5.28405),
('46193130-4455-540f-91f6-0e72b6dfa313', 'Calgary Point, Feall and Crossapol Bays', 'https://www.walkhighlands.co.uk/islands/calgary-point.shtml', 12.9, 130, 3.5, 'Calgary Point is the westernmost tip of Coll. This circular walk crosses the magnificent Feall and Crossapol beaches and through the RSPB Coll nature reserve. It runs across ground which is heavily grazed by cattle, and is crucially important for its rare ground-nesting birds; if you decide to bring dogs here regardless, they really must be kept on a lead / under tight control.', 56.5898, -6.6412),
('46311489-e46d-53f0-a0a1-8fa5e3505e4a', 'Beinn Mholach, from Dalnaspidal', 'https://www.walkhighlands.co.uk/perthshire/beinn-mholach.shtml', 23.5, 476, 7.5, 'Beinn Mholach is a retiring Corbett, hidden away from roads, its rocky summit being the highest point of an area of rough heather moorland and bogs. The effort of reaching its massive cairn is extensive views at the heart of the Highlands.', 56.8308, -4.22154),
('463b4314-dd31-55c2-8a78-fbdd07e88029', 'Hartfell Spa, near Moffat', 'https://www.walkhighlands.co.uk/galloway/hartfell-spa.shtml', 5.5, 232, 2.5, 'This adventurous little excursion ascends above a burn which scours the western slopes of Hart Fell to discover a historic spa. Dating back to 1748 the spa provided healing waters which were bottled; today it has a really hidden feel - a torch should be carried to best see the spa.', 55.3782, -3.4611),
('4645e102-7722-546e-b6f8-08fc52094692', 'Mayar and Driesh, Glen Clova', 'https://www.walkhighlands.co.uk/angus/mayar-driesh.shtml', 14.5, 835, 5.5, 'A stunning ascent through picturesque Corrie Fee leads up to the extensive rolling plateau above - visiting the summits of Mayar and Driesh. With the descent on the excellent Kilbo path back to Glendoll forest at the head of Glen Clova, in summer conditions this makes a straightforward round for two Munros.', 56.8704, -3.17584),
('46679083-579b-5037-8bfe-af49bae1ea92', 'Barnhill and the Corryvreckan Whirlpool', 'https://www.walkhighlands.co.uk/islay-jura/corryvreckan.shtml', 21.0, 408, 7.5, 'This long walk leads out to the northernmost point of Jura - overlooking the wild Gulf of Corryvreckan with its often raging currents - site of the famous whirlpool. The first section follows a rough track to Barnhill - where George Orwell wrote 1984 - before continuing to the old Kinuachdrachd harbour and then becomes very rough and boggy for the final stretch to the Carraig Mhòr at the furthest tip of the island.', 56.0703, -5.746),
('466ba3f9-ec5f-5543-8ac4-4b6dce4d5663', 'Southern Cuillin and Coire Ghrunnda', 'https://www.walkhighlands.co.uk/skye/sgurrnaneag.shtml', 15.0, 1159, 11.0, 'The southernmost Cuillin peaks have the finest sea views in the whole range, and give a long, rough day. Sgùrr nan Eag involves moderate scrambling; Sgùrr Dubh Mòr (which can be omitted) is a hard scramble.', 57.203, -6.2914),
('467011fc-2312-5c42-b55b-b10f90c8bebf', 'Ben Lawers and Beinn Ghlas', 'https://www.walkhighlands.co.uk/perthshire/ben-lawers.shtml', 11.0, 942, 6.0, 'Ben Lawers - the tenth highest Munro - is the culminating point of the sprawling range of mountains on the north side of Loch Tay. Its great height is undermined by a high level car park to begin the ascent, and this is one of the most popular hills in Scotland. A second Munro - Beinn Ghlas - is crossed en-route and is barely noticed by many.', 56.511, -4.26287),
('468a716e-04a9-57a5-ae46-b3f0c8abe790', 'Beinn nan Oighreag, Glen Lochay', 'https://www.walkhighlands.co.uk/perthshire/beinn-nan-oighreag.shtml', 15.5, 803, 5.5, 'Ranking amongst the highest of the Corbetts, Beinn nan Oighreag was briefly thought to top 3000 feet. The approach given here from Glen Lochay is perhaps the most attractive, following an old path to the shielings of the Allt Dhuin Croisg.', 56.4867, -4.3736),
('46b4d6ad-35b6-5e6c-bdd5-bcfd8259e863', 'Cùl Beag', 'https://www.walkhighlands.co.uk/ullapool/cul-beag.shtml', 10.5, 729, 5.0, 'Cùl Beag is perhaps one of the less climbed of the strange, monolithic peaks of Coigach, but it is a hill of great character and a stunning viewpoint. The shortest ascent is from Linneraineach, but the longer eastern approach gives a gentler route.', 58.0227, -5.0757),
('47600cb4-19a3-53fd-b6a0-c0b84f7bd590', 'Dochgarroch Locks & Caledonian Canal, Inverness', 'https://www.walkhighlands.co.uk/lochness/caledonian-canal.shtml', 12.0, 10, 4.0, 'This deservedly popular and almost level walk follows the Caledonian Canal towpath from Inverness to the locks at Dochgarroch, returning on the far bank; there is usually plenty of activity on the water. There''s a cafe if needed at the half way point.', 57.4613, -4.2395),
('47d38b95-b384-5daf-b321-27b8f0ab6d11', 'Oldshoremore Bay circuit', 'https://www.walkhighlands.co.uk/sutherland/oldshoremore-bay.shtml', 8.0, 165, 4.0, 'Follow the coast to three beautiful sandy bays with rough headlands in between and for the second half return on an inland minor road. It is possible to shorten the walk by cutting back up to the inland road from Polin or Chaligaig Bay.', 58.4774, -5.0828),
('47fcde49-cb18-5f80-8a16-d255fadb08fb', 'Aldouran Glen, Leswalt', 'https://www.walkhighlands.co.uk/galloway/aldouran-glen.shtml', 3.0, 69, 1.0, 'Explore the countryside around Leswalt on this walk which heads up through the Woodland Trust reserve of the Aldouran Glen.', 54.9306, -5.0948),
('480874a9-9c30-580b-b20a-43894fe94345', 'Staneydale Temple', 'https://www.walkhighlands.co.uk/shetland/staneydale-temple.shtml', 1.5, 19, 0.75, 'This short walk visits one of Shetland''s most ancient archaelogical sites. The Staneydale Temple''s real purpose isn''t known - it may have been used for religious ceremonies but could also have been the house of a chieftain or a village hall.', 60.2345, -1.475),
('480dd07c-1054-57c9-b770-af8ea5ccf827', 'Mull Head, Deerness', 'https://www.walkhighlands.co.uk/orkney/mull-head.shtml', 6.75, 196, 3.0, 'Mull Head is the furthest point of Deerness and offers one of the finest coastal circuits on Mainland Orkney. The route has a dramatic gloup, impressive cliffs and geos as well wonderful sea views - but the highlight is the narrow path leading out onto the Brough of Deerness. The walk can be extended by linking with the Covenanters'' Memorial route.', 58.9562, -2.7146),
('481f566c-c0ee-5831-b3cf-6bae68bf9d28', 'Callendar Park and House, Falkirk', 'https://www.walkhighlands.co.uk/fife-stirling/callendar-park.shtml', 5.25, 92, 1.5, 'Callander Park is a vast area of wooded parkland within easy reach of the centre of Falkirk. The highlight is Callander House, one of Scotland''s finest Baronial Mansions.', 55.9957, -3.7758),
('486cf5e4-66e8-550f-a889-585f9ceb1d01', 'Silverbridge riverside circuit, near Garve', 'https://www.walkhighlands.co.uk/lochness/Silverbridge.shtml', 3.5, 49, 1.5, 'Every step of this short circular walk is a delight, passing through beautiful woodland close to the banks of a dramatic foaming river. The river is crossed at each end of the walk by picturesque old stone bridges.', 57.6369, -4.6784),
('4882f6bd-c0a3-5d42-852a-5d4fef56c2e8', 'Sail Chalmadale, from Dougarie', 'https://www.walkhighlands.co.uk/arran/sail-chalmadale.shtml', 10.5, 490, 5.5, 'This rough moorland ascent climbs to the lonely summit of a granite-studded peak via Glen Iorsa, one of Arran''s quieter corners.', 55.5802, -5.36211),
('489153ab-1e15-5257-be53-5ad6682165bb', 'Rocks of Solitude river circuit, Edzell', 'https://www.walkhighlands.co.uk/angus/edzell.shtml', 10.5, 75, 3.0, 'Follow the river North Esk upstream as it squeezes through an impressive gorge and enjoy woodland paths and a minor road through pleasant countryside to complete the circuit from picturesque Edzell. <', 56.8124, -2.6574),
('48cd8b71-640d-5ba1-ad6f-135d1aaf6d3d', 'Rubers Law, from Denholm', 'https://www.walkhighlands.co.uk/borders/rubers-law.shtml', 10.0, 437, 3.5, 'Rubers Law rises as a prominent cone over the countryside east of Hawick. The summit is the site of an iron age fort as well as being a superlative viewpoint. This ascent begins from Denholm, but a return via Gilboa Wood makes for a longer, varied circuit.', 55.4579, -2.6843),
('496e423b-95b0-57d3-9c30-6bec4f0c72a1', 'Beinn Mhòr and the Mull of Oa', 'https://www.walkhighlands.co.uk/islay-jura/oa-beinn-mhor.shtml', 8.5, 252, 3.5, 'This dramatic cliff-top walk runs from the American Monument at the Mull of Oa, following the coastline past the dramatic headland of Dun Athad before climbing to the summit of Beinn Mhor, the highest hill on the Oa peninsula.', 55.5976, -6.31717),
('49700e45-a2b8-5bc1-a38a-547b1e9802ec', 'Lamb Island and Threave Estate, Castle Douglas', 'https://www.walkhighlands.co.uk/galloway/threave-estate.shtml', 5.5, 43, 1.5, 'This walk explores the countryside of the Threave Estate, owned by the National Trust for Scotland. It winds a varied route through the pleasant landscape, and visits a bird hide on Lamb Island in the middle of the River Dee. The walk can be extended - and should be - by following the Threave Castle circuit.', 54.9337, -3.9589),
('49b321df-92c0-5f1e-ac6d-9cc27cc7006f', 'Coral Beaches, near Culduie', 'https://www.walkhighlands.co.uk/torridon/Coralbeach.shtml', 6.3, 210, 2.0, 'This enchanting short walk follows an ancient path over to two hidden but beautiful coral beaches.', 57.3911, -5.8059),
('49c273bd-442a-549b-87e4-04ad70ca1e9f', 'Beinn Dhubh, Losgaintir', 'https://www.walkhighlands.co.uk/outer-hebrides/beinn-dhubh.shtml', 11.5, 574, 5.0, 'Beinn Dhubh and its neighbour Beinn Losgaintir appear unremarkable, rounded hills from a distance. However their superb position overlooking the Luskentyre Sands on the one hand, and the mountains of North Harris on the other, ensures they make for a shorter hillwalk with sensational views. A tough route for Grade 3.', 57.8711, -6.9054),
('49d7c6b0-9d27-502f-a7c5-1c3a62f72510', 'Tuquoy and Mae Sand, Westray', 'https://www.walkhighlands.co.uk/orkney/mae-sand.shtml', 6.25, 20, 2.0, 'This circular walk explores the southern the Ness of Tuquoy, heading along the coast to visit a 12th century Norse kirk. The walk then continues on an often overgrown path to reach Mae Sand - a spectacular beach.', 59.2763, -2.9512),
('49fe0596-b375-5c40-a467-1dc56ffc8a6e', 'Dundeugh Forest, near Dalry', 'https://www.walkhighlands.co.uk/galloway/dundeugh.shtml', 7.0, 91, 2.0, 'This pleasant ramble follows tracks to make a circuit around Dundeugh Forest - now an island between the Water of Deugh, Kendoon Loch and the Water of Ken.', 55.169, -4.202),
('4a16c32b-2b7c-575d-bcb7-f383f49d2017', 'The Forest of Deer, near Fetterangus', 'https://www.walkhighlands.co.uk/aberdeenshire/forest-of-deer.shtml', 6.5, 60, 2.0, 'This country walk passes through arable fields and several plantations, collectively known as the Forest of Deer. The highlight is the Pitfour Observatory, a viewing tower in Drinnies Wood which is open in the summer months.', 57.5448, -2.0456),
('4a2910b2-0f31-5516-8b67-0b4571ed5c20', 'The Vat of Kirbuster and Lamb Head, Stronsay', 'https://www.walkhighlands.co.uk/orkney/vat-of-kirbuster.shtml', 12.5, 174, 4.5, 'The Vat of Kirbuster is a gloup or blow hole whose entrance is spanned by a spectacular rock arch. It is just one of the highlights of this excellent circuit, which also has large seabird colonies in the season. The return is along quiet tarmac lanes.', 59.1023, -2.5578),
('4a2f5634-9b2f-538c-910d-ac11f36fec86', 'Loch Tay from Killin', 'https://www.walkhighlands.co.uk/perthshire/loch-tay-walk.shtml', 4.3, 10, 1.5, 'This stunningly beautiful short walk offers great views over Loch Tay and the Rivers Lochay and Dochart. The walk is level and easy to follow, but prone to flooding and boggy sections. The final rougher and boggier loop is optional and should be omitted unless there has been a dry spell.', 56.47, -4.31503),
('4a37db9b-dfbb-5d0d-a861-70c7db28e4ec', 'Ryvoan Pass - Glenmore to Nethy Bridge', 'https://www.walkhighlands.co.uk/cairngorms/ryvoan-pass.shtml', 15.5, 149, 5.0, 'Ryvoan Pass is rarely used as a through route these days, but if you can time this linear walk for the buses, it makes a magnificent outing, with beautiful Lochan an Uaine on the ascent and the wonderful Abernethy Forest on the long descent to Nethy Bridge.', 57.1652, -3.675),
('4a64fc3b-418a-58da-a7ed-d112afb47a7a', 'The Old Fort and Inverlochy Castle, Fort William', 'https://www.walkhighlands.co.uk/fortwilliam/inverlochy-castle.shtml', 4.5, 24, 1.5, 'This straightforward walk from the centre of Fort William heads along the riverside to reach the romantic ruins of Inverlochy Castle. The return runs by the railway and then through a suburb.', 56.8215, -5.1078),
('4ac8c376-c1c6-509e-bf4c-610e71911fa9', 'Beinn Lora, Benderloch', 'https://www.walkhighlands.co.uk/argyll/beinn-lora.shtml', 6.0, 368, 2.5, 'Whilst Beinn Lora may only be 308 metres high, its fine position ensures that the magnificent views from its summit match those from many a Munro. The approach uses waymarked forestry walks (most of the conifers have now been felled) but the section before the final pull up to the top is very wet.', 56.4882, -5.40382),
('4ad1625d-7895-5086-8623-004fa61a3b4b', 'Cornish Hill and Loch circuit, Stinchar bridge', 'https://www.walkhighlands.co.uk/glasgow/cornish-loch.shtml', 5.25, 158, 2.0, 'This circular walk climbs up above the vast forests of the Carrick onto the wild open hills, giving superb views and visiting the lonely shores of Cornish Loch.', 55.2295, -4.5222),
('4b0b06d4-6649-559b-8b2c-5a726f6ff2e0', 'Eas a'' Chual Aluinn - Britain''s highest waterfall', 'https://www.walkhighlands.co.uk/ullapool/eas-a-chual-aluinn.shtml', 9.75, 521, 5.5, 'This rough walk takes you into the heart of Assynt''s rocky landscape, past pretty lochans and streams to reach the top of Britain''s highest waterfall, Eas a'' Chual Aluinn. The route leads to the best vantage point near the top of the falls, although the entire drop into the deep glen below cannot be seen.', 58.2165, -4.998),
('4b591101-e624-5972-8f82-35acbb0121ae', 'Sgùrr Èilde Mòr and Binnein Beag, Mamores', 'https://www.walkhighlands.co.uk/fortwilliam/sgurreildemor.shtml', 20.0, 1582, 11.0, 'These two Munros are the easternmost of the Mamores range. They stand apart from the rest of the ridge as isolated cones of scree, giving arduous ascends but wonderful views.', 56.7168, -4.9628),
('4b9afd8f-92a5-5210-bb20-c2b2ce53e0c4', 'Càrn a'' Chuilinn, via Glen Doe', 'https://www.walkhighlands.co.uk/lochness/carn-a-chuilinn.shtml', 17.25, 681, 6.0, 'Càrn a'' Chuilinn is a wild Corbett on the western fringe of the Monadhliath. In recent years a major hydro electric scheme has been build underground here; the large tracks used for the construction scar the landscape but ease the approach.', 57.1428, -4.6521),
('4bd2956b-ad5a-57f8-848f-7d5e296e8b9f', 'Buidhe Bheinn, from Kinloch Hourn', 'https://www.walkhighlands.co.uk/fortwilliam/buidhe-bheinn.shtml', 12.0, 1070, 6.0, 'This fine Corbett rises steeply above Kinloch Hourn and provides one of Scotland''s classic views, along Loch Hourn to Ladhar Bheinn. Excellent stalkers paths make this an enjoyable ascent, and the ridge between the two peaks is very rocky and rugged.', 57.1046, -5.3863),
('4bdd65a5-ffa6-5880-957f-e618372b8034', 'The Loch Mullardoch Munros', 'https://www.walkhighlands.co.uk/lochness/mullardoch-munros.shtml', 29.0, 1826, 14.0, 'This fine group of Munros make for a spectacular ridge-walk in an extremely remote part of the Highlands. The tiring walk back along the north side of Loch Mullardoch completes an extremely long day.', 57.3399, -4.9615),
('4c10b074-64af-5f30-97e6-a0c8228c53a1', 'Sandgreen circular, Gatehouse of Fleet', 'https://www.walkhighlands.co.uk/galloway/sandgreen.shtml', 12.5, 104, 4.0, 'This long but easy circular follows tracks and minor roads through oakwoods and open countryside to visit the sandy beach at Sandgreen and back to near Gatehouse of Fleet.', 54.8801, -4.1745),
('4c3cc90f-70e9-5525-be68-c726b5245ae7', 'Start Point Lighthouse, Sanday', 'https://www.walkhighlands.co.uk/orkney/start-point.shtml', 3.75, 5, 2.0, 'This fantastic tidal walk to the lighthouse at Start Point has views to North Ronaldsay and Fair Isle lighthouses on a clear day. Can only be done at low tide.', 59.281, -2.4061),
('4c56f381-7ebe-5c69-94d7-394b5ef39c09', 'Ardyne and the Chinese Ponds', 'https://www.walkhighlands.co.uk/argyll/ardyne.shtml', 3.0, 123, 1.0, 'This enjoyable waymarked walk climbs through birchwoods in the most southerly part of Cowal. It gives good views over the Isle of Bute, the Cumbraes and the Firth of Clyde, and visits the Chinese Ponds - part of a seemingly forgotten Oriental garden.', 55.8779, -5.0186),
('4c6b14dc-4f64-527e-91cd-0f6a83225d89', 'Creag Mac Ranaich and Meall an t-Seallaidh', 'https://www.walkhighlands.co.uk/lochlomond/creag-mac-ranaich.shtml', 20.5, 984, 8.0, 'This pair of Corbetts are hidden and out of sight from most of the major routes through the glens. Creag Mac Ranaich is a hill of character with craggy buttresses on its upper slopes, whilst the higher Meall an t-Seallaidh takes the form of a long ridge. Together they make an enjoyable round from Lochearnhead.', 56.3853, -4.2803),
('4c8102a5-a532-529a-a719-d6c47e6dda3b', 'Loch Trool trail, Glen Trool', 'https://www.walkhighlands.co.uk/galloway/loch-trool.shtml', 9.0, 236, 3.0, 'Loch Trool is one of the real gems of the Galloway Forest park, a beautiful and tranqul body of water that was once the scene of a fierce battle. This enjoyable walk makes a complete circuit around the loch.', 55.0801, -4.5124),
('4c99b7cd-b054-5227-9b60-881a35c25718', 'Monument and Bennan Hill, Straiton', 'https://www.walkhighlands.co.uk/glasgow/bennan-hill.shtml', 8.25, 396, 3.0, 'An excellent circuit over the hills overlooking one of Scotland''s favourite villages, located in what is known as Ayrshire''s ''Rambling Territory''.', 55.3118, -4.5554),
('4cb5bd80-a0bd-55e5-ab49-428ba63fb950', 'Greeto Mast and the Gogo Glen, Largs', 'https://www.walkhighlands.co.uk/glasgow/greeto-bridge.shtml', 4.5, 253, 2.0, 'This walk follows a new path up over the moors above Largs, offering panoramic views back over the town and the islands beyond. It then descends into the deep, richly wooded glen of the Gogo Water.', 55.794, -4.8532),
('4cd87466-471b-5dd1-ae28-72022fd24d61', 'Loch an Eilein, Rothiemurchus', 'https://www.walkhighlands.co.uk/cairngorms/loch-an-eilein.shtml', 7.0, 70, 2.0, 'Loch an Eilein is an extremely beautiful sheet of water, reflecting the magnificent pines of Rothiemurchus Forest in which it lies; a ruined island castle is the final touch to help make this one of the most popular short walks in Scotland. The route is described here with an optional extension around the quieter Loch Gamhna; another possible extension is to ascend Ord Ban for wonderful views.', 57.1542, -3.8251),
('4cf6e0e0-d800-5599-a9b0-ba277953e406', 'Sgùrr a'' Mhaoraich, Loch Cuaich', 'https://www.walkhighlands.co.uk/fortwilliam/sgurramhaoraich.shtml', 14.0, 1077, 7.0, 'This solitary Munro in the remote area around Loch Cuaich has a good stalkers path for the ascent and is a very fine viewpoint.', 57.0848, -5.2781),
('4d1a8d30-d4d7-5a84-95bb-4e01a9894075', 'Loch Ba, Knock, near Gruline', 'https://www.walkhighlands.co.uk/mull/loch-ba.shtml', 7.75, 5, 2.5, 'This easy-going walk takes you into the heart of the mountains of Mull without any climbing required. Follow the shore of Loch Ba to Knockantivore keeping an eye out for sea eagles and deer.', 56.4772, -5.9869),
('4d5e8834-b2e9-509d-9ec5-efb9c20d5e56', 'Alva Glen', 'https://www.walkhighlands.co.uk/fife-stirling/alva-glen.shtml', 2.5, 172, 1.5, 'The Alva Glen is a steep-sided cleft scored in the southern front of the Ochils range. This short walk up it follows a dramatic path, easy at first, which climbs up into this ravine. The upper part involves a steep ascent with precipitous slopes and ends at a viewpoint overlooking the Smuggler''s Cave in the floor of the gorge.', 56.157, -3.7973),
('4d697b78-4665-516b-88e9-c1ec72f8d829', 'Moruisg and Sgùrr nan Ceannaichean', 'https://www.walkhighlands.co.uk/torridon/Moruisg.shtml', 12.0, 978, 7.0, 'Moruisg is rather a sprawling mountain but is a superb viewpoint. The ascent line given here has the one merit of directness, but continuing the walk onto Sgùrr na Ceannaichean follows an enjoyable ridge making for a good, fairly moderate mountain walk.', 57.5176, -5.20773),
('4d8b78ef-780b-59bf-8d22-4a153d023121', 'Macleod''s Maidens', 'https://www.walkhighlands.co.uk/skye/macleodsmaidens.shtml', 17.0, 589, 6.0, 'A fairly strenuous walk out to Idrigill Point to visit a group of impressive sea stacks.', 57.3961, -6.5672),
('4db1a62e-2ce3-5a8c-b36d-8dbb8b425ac6', 'Càrn Eige and Mam Sodhail', 'https://www.walkhighlands.co.uk/lochness/carn-eige.shtml', 28.0, 1727, 13.0, 'Càrn Eige and Mam Sodhail are the two highest mountains north of the Great Glen and spectacular viewpoints. This long, wild mountain walk around a horse-shoe of ridges becomes something of an epic by the (optional) addition of the very remote Munro of Beinn Fhionnlaidh.', 57.2734, -4.9618),
('4dd07f95-1a39-5c3a-bcc2-317dfee5087c', 'Drumadoon Point, Blackwaterfoot', 'https://www.walkhighlands.co.uk/arran/drumadoon-point.shtml', 3.5, 53, 2.0, 'This excellent walk heads out along the sandy beach from Blackwaterfoot, visiting a low headland before taking a dramatic rocky path through a boulderfield beneath the impressive basalt cliffs of The Doon.', 55.5039, -5.3399),
('4dec83f2-c9a6-5574-b0f3-7b58f7c72e6e', 'Ben Mór Coigach and Sgùrr an Fhìdhleir', 'https://www.walkhighlands.co.uk/ullapool/ben-more-coigach.shtml', 10.5, 870, 7.0, 'Ben Mór Coigach and Sgùrr an Fhìdhleir make a fantastic short but steep day. Ben More Coigach rises like a great sea-wall and the airy and dramatic Garbh Choireachan ridge has sweeping views in all directions. This horseshoe route then ascends the pointed peak of the Fiddler, Sgùrr an Fhìdhleir. Prominent as a massive triangle of rock from Stac Pollaidh, its north face falls away vertically beneath the summit.', 57.9844, -5.2805),
('4dfb5247-96ea-5cde-ad80-83af27563454', 'Devil''s Beef Tub circuit from Moffat', 'https://www.walkhighlands.co.uk/galloway/devils-beef-tub.shtml', 22.5, 521, 6.0, 'The route - which is the first stage of the Annandale Way but also a fine circular walk in its own right - follows a path besides the river Annan out of Moffat then takes a minor road and farm tracks to a final steep climb onto the moorland hills that wall Annandale to the north. A splendid high level walk crosses these hills to Annandale Head from where there is a descent back down to the minor road and the outward route back to Moffat.', 55.3293, -3.4459),
('4dfc08c0-5fee-59a2-9818-1a460881d968', 'Cruach Innse and Sgùrr Innse', 'https://www.walkhighlands.co.uk/fortwilliam/cruach-innse.shtml', 13.0, 890, 7.0, 'This pair of Corbetts may be dwarfed by the massive Munros all around them, but provide an enjoyable hillwalk in their own right. Both hills - and especially Sgùrr Innse - have extensive rocky ground and great character.', 56.8682, -4.86347),
('4e0f7993-27a6-5eec-819b-7c3d736d5fd3', 'Cockburn Law & Edin''s Hall broch, Abbey St Bathans', 'https://www.walkhighlands.co.uk/borders/cockburn-law.shtml', 10.25, 345, 3.5, 'This delightful circular walk climbs up to the open summit of Cockburn Law for extensive views across the Borders, before visiting the remains of an iron-age broch - a real rarity in lowland Scotland. The route crosses the Whiteadder Water by a suspension bridge before a return using minor roads and tracks.', 55.8498, -2.38038),
('4e1b9c5e-94bc-550d-9235-8d9f55d1a71d', 'The Bin, Huntly', 'https://www.walkhighlands.co.uk/aberdeenshire/the-bin.shtml', 6.0, 180, 1.5, 'The Bin Forest is a short distance from Huntly and has several popular waymarked trails. This is the longest, waymarked as the Gallon of Water Trail, which climbs to the summit with good views over the surrounding countryside.', 57.4653, -2.8263),
('4e2b19e2-7ed2-580c-ba62-38cbd2f7e9a2', 'Beinn a'' Bhuiridh, near Loch Awe', 'https://www.walkhighlands.co.uk/argyll/beinn-a-bhuiridh.shtml', 11.5, 862, 6.0, 'Beinn a'' Bhuiridh is really the final peak on the Ben Cruachan horseshoe of ridges, though its steep northern slope means that most people do not include this Corbett in their Cruachan round. Here we describe it as a hillwalk in its own right, along the east ridge over Monadh Driseig - rough terrain initially but with great views.', 56.4107, -5.0287),
('4e50fb79-acbf-5bce-bc85-8392dd3ae1de', 'Hill of Alyth and Hill of Loyal, Alyth', 'https://www.walkhighlands.co.uk/perthshire/hill-of-alyth.shtml', 6.4, 250, 2.5, 'This circuit rises steeply from the pretty village of Alyth to the top of the Hill of Loyal and then the Hill of Alyth both of which have great views over the Sidlaw hills and into the southern Cairngorms.', 56.6226, -3.2302),
('4e7404ea-ca42-5dc5-8262-3bd5d91c397e', 'Ben Bhraggie, Golspie', 'https://www.walkhighlands.co.uk/sutherland/ben-bhraggie.shtml', 9.5, 396, 4.5, 'The steep pull up Ben Bhraggie (or Beinn a''Bhragaidh to give it its proper, Gaelic name) is well rewarded by excellent views over the coastline and inland hills - on a clear day both coasts of Scotland can be seen. The massive Sutherland monument, locally known as the ''The Mannie'', marks the top from where this circuit takes a gentler route down on forest tracks initially. The circuit is then extended by returning down the dramatic Big Burn gorge.', 57.9739, -3.9757),
('4e74c810-e026-5289-8991-3f70b9854fb4', 'Beinn a'' Choin, near Inversnaid', 'https://www.walkhighlands.co.uk/lochlomond/beinn-a-choin.shtml', 8.75, 697, 6.0, 'Beinn a'' Choin is a rugged and wild tract of moorland and rocky hills lying to the north of Ben Lomond. The obvious horseshoe route to the summit around Coire Arklet has no parking area, so this route instead climbs the mountain from the RPSB car park at Garrison Farm.', 56.2507, -4.6672),
('4e867a16-dff6-5fc7-9a68-c703b3ec3786', 'Scourie to Tarbet', 'https://www.walkhighlands.co.uk/sutherland/scourie-tarbet.shtml', 5.5, 154, 2.0, 'This one-way walk links the two beautiful harbours of Scourie and Tarbet passing numerous small lochs and rocky heather moorland. The going is rough and boggy and care needs to be taken to keep to the path. The time and distance given do not include a return to the start.', 58.3518, -5.1519),
('4e980ac0-68da-5ab2-8e54-6b75f9330a08', 'River Kelvin and canals circuit', 'https://www.walkhighlands.co.uk/glasgow/kelvin-canal.shtml', 8.0, 106, 1.5, 'This enjoyable urban circuit from Glasgow''s West End begins along the Kelvin Walkway before climbing up to reach the Maryhill Locks on the Forth and Clyde Canal. The canal towpath is then used along the branch towards the city centre, before cutting back to the side through the streets of Kelvinside.', 55.8742, -4.27989),
('4ed5cc9c-00a5-537c-bc9c-e52b16dcbb57', 'Calderglen, East Kilbride', 'https://www.walkhighlands.co.uk/glasgow/calderglen.shtml', 2.75, 55, 1.0, 'Calderwood estate was once dubbed ''one of the loveliest of western glens, magnificent in its grouping of craggy heights, sprinkled with trees and with the amber-tinted Calder winding through the richly wooded and festooned valley''. It was opened to the public in the early 1900s under the ownership of the Scottish Cooperative Society, but the formal gardens and indeed the whole estate later fell into disrepair, with the Castle itself being demolished in the 1950s. Today the estate is a Country Park and this circular walk explores its attractive wooded glens.', 55.7484, -4.1466),
('4f0dfbbb-0668-5d4e-9181-c505be77fd6e', 'Market Loch, near Craighouse', 'https://www.walkhighlands.co.uk/islay-jura/market-loch.shtml', 5.0, 189, 2.5, 'Climb up to the outflow of the suprisingly large Loch a'' Bhaile-Mhargaidh - known locally as Market Loch - on this out-and-back route. The loch is the source of the Jura Whisky distillery.', 55.8256, -5.9587),
('4f0ec789-b4c0-55cd-94ac-b36d414b61cf', 'Ben More (Mull) from Dhiseig', 'https://www.walkhighlands.co.uk/mull/ben-more-mull.shtml', 9.25, 945, 6.5, 'This is the most straightforward route up and down Ben More, Mull''s only Munro, and makes for a great hillwalk avoiding the need for any scrambling. Phone the Benmore Estate (01680 300229) Aug - 20 Oct for dates of deer stalking - no stalking on Sundays.', 56.4492, -6.0679),
('4f734b6c-055a-5aaa-8307-27503f499c10', 'Dunskey Glen, near Portpatrick', 'https://www.walkhighlands.co.uk/galloway/dunskey-glen.shtml', 4.75, 100, 1.5, 'This enjoyable woodland walk heads down to visit the coast at Port Kale and returns past a gloomy waterfall. The walk is usually open from March to mid-October.', 54.8528, -5.1081),
('4f9e4103-5b59-5cf9-9222-f0f673cb857c', 'Ben Loyal', 'https://www.walkhighlands.co.uk/sutherland/ben-loyal.shtml', 13.75, 804, 6.5, 'Ben Loyal has a very distinctive profile, leading to it being known as the Queen of Scottish Mountains. Rising in an isolated position above the north coast, it makes a fantastic day out. The long ridge with four peaks offers superb 360 degree views of bog, moor, mountains and sea.', 58.4575, -4.4281),
('4fbb52af-3b95-559f-9b01-00ef66db6892', 'Loch Achaidh na h-Inich from Balmacara', 'https://www.walkhighlands.co.uk/kintail/lochachaidhnahinich.shtml', 11.5, 380, 4.0, 'This longer circuit from Balmacara leads through some very attractive woodland, visiting and passing around a remote loch. The return walk passes through a felled former area of forestry and there are some good views. There is the opportunity to link this walk with several other of our routes.', 57.2927, -5.64139),
('4fda3f4c-71e2-5356-b357-7c1e98cc6e15', 'Coille Dalavil', 'https://www.walkhighlands.co.uk/skye/coille-dalavil.shtml', 12.5, 217, 5.0, 'The start looks unpromising, however once over the first stretch of moorland the walk reaches a beautiful pine and beech woodland by a remote loch before continuing the deserted remains of Dalavil and a fantastic outlook over the sea to the Cuillins. If you don''t mind very rugged going, the walk can be extended along the coast to Tarskavaig.', 57.0907, -5.926),
('4ffcabc2-4f2d-5776-b267-420179f0ea86', 'Aonach Buidhe, via Glen Elchaig', 'https://www.walkhighlands.co.uk/kintail/aonach-buidhe.shtml', 33.0, 965, 10.0, 'Aonach Buidhe is a remote Corbett at the heart of one of the wildest parts of the Highlands. The easiest approach is along beautiful Glen Elchaig - greatly eased by the user of a mountain bike (saving four hours off the time given). The upper slopes on this route are undistinguished.', 57.3169, -5.4221),
('5004ee5b-46eb-52b3-b833-a38f0c3a9e2c', 'Meall a'' Bhuachaille circuit, Glenmore', 'https://www.walkhighlands.co.uk/cairngorms/meallabhuachaille.shtml', 8.5, 543, 4.5, 'Meall a'' Bhuachaille is a great choice for a first hillwalk in the Cairngorms, being easily accessible and having the benefit of great paths to the summit as well as superb views. Here is a chance to experience the beauty and wildness of the Cairngorms without the length and remoteness of some of the Munro walks. The walk described offers great variety, with ancient Caledonian pines, lochs, forests and a windswept ridge; it can easily be extended to a full days hillwalk by continuing over Creagan Gorm to Craigowrie.', 57.1675, -3.6936),
('50060711-7f06-5278-b917-1a64d34b0028', 'Lammer Law and Hopes Reservoir', 'https://www.walkhighlands.co.uk/lothian/lammer-law.shtml', 14.5, 352, 5.0, 'Lammer Law, though not the highest of the Lammermuirs, is perhaps the best known, the massive cairn on its summit commanding extensive views on a fine day. This grand circular walk gives a real feeling of open space, and the descent past the Hopes reservoir is picturesque.', 55.8695, -2.73385),
('5083b766-193b-5ce5-8729-8aa84eb83c72', 'Norman''s Law, from Luthrie', 'https://www.walkhighlands.co.uk/fife-stirling/normans-law.shtml', 8.25, 280, 3.0, 'The Ochils range extends eastwards far into Fife and Norman''s Law is the final summit of any consequence. It offers superb views in all directions as the high point of this enjoyable circuit.', 56.3641, -3.0844),
('508ae322-81c0-5c7f-8e8c-b37f5eadc509', 'Glen Loy Oakwood, near Gairlochy', 'https://www.walkhighlands.co.uk/fortwilliam/glenloy.shtml', 4.5, 100, 2.0, 'A quiet walk through forestry, visiting a tract of ancient, hidden oak woodland. Good chance to see wildflowers and wildlife.', 56.8933, -5.0401),
('50c2e95a-7a4b-5ad3-89b6-f1f42ced6f27', 'Balfour coast walk, Shapinsay', 'https://www.walkhighlands.co.uk/orkney/balfour-shapinsay.shtml', 8.0, 62, 3.5, 'Balfour is the tiny but attractive capital of Shapinsay, served by regular ferry from Kirkwall. The walk takes views of the Scots Baronial Castle (private) and offers a mix of easy grassy walking and rougher tidal shoreline with the chance to see seals as well as plentiful birdlife. The return is along a minor road, visiting a hide overlooking the RSPB''s Mill Dam reserve. This walk should not be attempted at high tide.', 59.0318, -2.9087),
('50e8fef9-2ac3-5945-bbc4-da425fe9990d', 'Inverallochy and Whitelinks Bay', 'https://www.walkhighlands.co.uk/aberdeenshire/inverallochy.shtml', 6.0, 32, 2.0, 'Inverallochy is an eighteenth century former fishing village; the walk heads from the harbour through the village and continues across the fine sands of Whitelinks Bay before returning behind the golf course.', 57.6801, -1.9434),
('515d8916-60b9-5a90-bbf5-c2dfc05b88d5', 'Quoyness Cairn, Sanday', 'https://www.walkhighlands.co.uk/orkney/quoyness-cairn.shtml', 8.25, 14, 2.5, 'Quoyness Cairn is an 5000 year old large chambered burial cairn - one of the most impressive in Scotland, and similar in style to Maes Howe though less grand in construction. Situated next to the sea on Els Ness this out-and-back route, described from Lady, also takes in the Little Sea, popular with wading birds. It is possible to greatly shorten the walk by driving it as far as a parking area on the Quoy Ayre.', 59.2542, -2.5506),
('517d87ae-35ab-59d1-9af8-e0bd11b27b92', 'Glenan Bay, Portavadie', 'https://www.walkhighlands.co.uk/argyll/glenan-bay.shtml', 3.5, 110, 1.5, 'This boggy but very scenic shorter walk passes through oakwoods and climbs up to the abandoned village of Glenan, a lonely spot, as well as visiting an attractive bay and shoreline.', 55.8775, -5.3134),
('517efd39-2efb-594c-9d85-de42d9f303a7', 'Tràigh Gheal and Tireragan', 'https://www.walkhighlands.co.uk/mull/traigh-gheal.shtml', 9.5, 182, 4.0, 'Tràigh Gheal is one of the most beautiful and secluded sandy beaches on Mull. The walk to it, however, through the Tireragan nature reserve, is overgrown and boggy, an Indiana Jones-style yomp requiring determination and perserverance. The area is owned by a charity who are encouraging its ecological restoration.', 56.2993, -6.3428),
('5211dd87-53ba-5f66-9e21-605e289a893b', 'Liathach, Glen Torridon', 'https://www.walkhighlands.co.uk/torridon/Liathach.shtml', 11.5, 1326, 10.0, 'Liathach is rated by many mountaineers and hillwalkers as Scotland''s finest mountain, challenged only by An Teallach and the Cuillin of Skye. Its traverse is an expedition that will be remembered forever.', 57.5527, -5.4516),
('52a016e3-31c7-5bf4-8835-813323c0cefb', 'Sorisdale and Tràigh Tuath', 'https://www.walkhighlands.co.uk/islands/sorisdale.shtml', 2.75, 12, 1.0, 'This magical short walk at the extreme northern end of Coll heads through a former crofting village which was almost deserted but now partly reoccupied, to visit a couple of truly superb beaches.', 56.6813, -6.45899),
('52ddfeb7-efb9-5fbb-b779-5c1e8b593775', 'Meikle Tap, near Banchory', 'https://www.walkhighlands.co.uk/aberdeenshire/meikle-tap.shtml', 7.0, 231, 2.0, 'Not to be confused with the better knownMither Tapof Bennachie, the Meikle Tap is the easternmost summit of the Hill of Fare massif. It provides for a straightforward circuit with excellent views towards Aberdeen.', 57.1228, -2.42604),
('5307101f-d784-520c-9513-9eb6bd9838fc', 'Cargill''s Leap and the Knockie, Blairgowrie', 'https://www.walkhighlands.co.uk/perthshire/cargills-leap.shtml', 5.8, 175, 2.5, 'Well-loved by Blairgowrie folk, this varied circuit follows the River Ericht upstream with its waterfalls, woodlands and many old mills. The return is over the Knockie, a viewpoint looking out over the town to the Sidlaw hills beyond.', 56.5941, -3.33698),
('53368c22-3b09-5189-b073-2f21e3dde58e', 'Cìr Mhòr and Beinn Tarsuinn', 'https://www.walkhighlands.co.uk/arran/cir-mhor.shtml', 17.25, 1164, 9.0, 'This route ascends the two Corbetts on the west side of Glen Rosa, bypassing the A'' Chir ridge and culminating with the ascent of Cìr Mhòr - a fine peak which must rank amongst the most impressive Scottish mountains.', 55.5916, -5.17462),
('5342df2b-f80d-5af9-88ff-be7438d019ac', 'Stob Ban (Mamores) and Mullach nan Coirean', 'https://www.walkhighlands.co.uk/fortwilliam/stobban.shtml', 13.0, 1155, 8.0, 'Stob Ban is one of the finest peaks in the Mamores, its quartzite summit giving magnificent views. A very fine ridge traverse links it to its westerly neighbour Mullach nan Coirean, giving an excellent circuit.', 56.7695, -5.0372),
('535ab117-f873-54f7-9de2-5384bc7cbe4d', 'Silver Sands of Morar', 'https://www.walkhighlands.co.uk/fortwilliam/silversandsmorar.shtml', 3.5, 110, 1.5, 'The Silver Sands of Morar are a celebrated series of beautiful sandy beaches which pepper the coastline from Arisaig to Morar. Most are easily accessible from the roadside but this walk visits one of the least frequented beaches, crossing some rough and wet ground on the way.', 56.9688, -5.82245),
('535dd9c8-0674-5eee-afd8-92989d62a024', 'Rerwick Head, Tankerness', 'https://www.walkhighlands.co.uk/orkney/rerwick-head.shtml', 1.3, 14, 0.6666666666666666, 'A short coastal stroll around Rerwick Head, the northernmost point of Tankerness. The walk passes the varied crumbling but extensive remains of a battery from the second World War.', 58.9893, -2.8042),
('538830e7-44d6-5d31-9ba1-d2571c77e214', 'Downie''s Loup waterfall, Gargunnock', 'https://www.walkhighlands.co.uk/glasgow/downies-loup.shtml', 4.0, 183, 1.0, 'A short climb to below the impressive crags of the Gargunnock Hills escarpment where a waterfall cascades over the cliff. Gargunnock is an attractive village with a pub serving food.', 56.1247, -4.08409),
('53a2ab24-16f9-59a6-bd38-4625babd0e7e', 'Out Skerries circuit: Bruray and Housay', 'https://www.walkhighlands.co.uk/shetland/out-skerries.shtml', 11.75, 226, 5.0, 'The isolated island group of Out Skerries is the most easterly part of Shetland - and indeed of Scotland. Locally known simply as Skerries, the group consists of three main islands - Housay and Gruray, which are linked by a bridge, and the now uninhabited island of Grunay. There are certain days each week when a day visit is possible, by ferry or by air. This walk runs right around the coastline of the two connected islands. As might be expected from their position, Skerries are renowned for their birdwatching opportunities with all sorts of rarities stopping over on migration.', 60.4226, -0.7508),
('5412d52a-ae12-53ba-bfa7-e92f2145576e', 'Monreith Estate, near Port William', 'https://www.walkhighlands.co.uk/galloway/monreith-estate.shtml', 2.5, 8, 1.0, 'This pleasant walk makes a circuit of the White Loch of Myrton on the Monreith estate, passing through mature woodland.', 54.7551, -4.5561),
('548bdc5a-be21-585e-867c-0d06e925404c', 'Old Town, Edinburgh', 'https://www.walkhighlands.co.uk/lothian/old-town.shtml', 3.5, 86, 1.5, 'The Old Town is Edinburgh''s medieval heart. It is centred on the Royal Mile which runs along the crag-and-tail from the Castle down to Holyrood Palace, and it is packed with notable architecture and fascinating history, being home to some of the world''s earliest ''high rise'' buildings.', 55.9519, -3.1917),
('5491c10f-e29d-52d7-be85-28ecb867244b', 'Reekie Linn, Glen Isla', 'https://www.walkhighlands.co.uk/angus/reekie-linn.shtml', 1.0, 30, 0.6666666666666666, 'The Reekie Linn is the most impressive waterfall in the region, its great power making it an awesome sight especially in spate. The very short walk to it is very pleasant through deciduous woodland on the rim of a deep and dangerous gorge.', 56.6702, -3.2221),
('54c20cce-5e4e-59dd-a854-f2bb80ab5008', 'Melvich Beach', 'https://www.walkhighlands.co.uk/sutherland/melvich-beach.shtml', 1.75, 16, 0.75, 'This short walk leads out to Melvich Beach - one of the finest of the north coast''s many superb sandy beaches.', 58.5566, -3.9144),
('54d877ca-fc67-59d4-a0cc-17f6bee09860', 'Butt of Lewis circuit, Eoropie, Ness', 'https://www.walkhighlands.co.uk/outer-hebrides/butt-of-lewis.shtml', 6.25, 116, 2.0, 'The Butt of Lewis is the dramatic northern extremity of Lewis, the tower of its slender brick lighthouse standing proud against the storms that often rage here - a spot claimed to be the windiest in Britain. This superb circular walk takes in the cliff-top scenery as well as the stunning Eoropie beach - and the route can easily be extended if you wish to take in the bridge to the historic stack of Dun Eistean.', 58.5003, -6.2623),
('54ee2882-669a-59b8-919c-a8077a04bdb1', 'Fife Coastal Path 9: Kingsbarns to St Andrews', 'https://www.walkhighlands.co.uk/fife-stirling/kingsbarns-st-andrews.shtml', 13.5, 140, 4.0, 'A lovely section of the Fife Coast Path, with unspoilt beaches, rocky shore, and an inland section along riverside and over farmland.  NOTE: There is a tidal section near the Buddo Rock, approximately two-thirds of the way along, that is not possible at high tide - check tide times before setting out. This is a one-way walk; return is possible by bus.', 56.3033, -2.6455),
('55151303-c902-5ca6-b012-3833ed2fd86f', 'Castle Tioram and the Silver Walk circuit', 'https://www.walkhighlands.co.uk/fortwilliam/castletioram.shtml', 5.75, 270, 3.5, 'The Silver Walk is one of the truly special paths of the Highlands, a fascinating route cut out of the rock through truly spectacular scenery. Add in stunning Castle Tioram, a deserted hamlet, pine-fringed hill lochs and a view out to the Isles, and you have a stone-cold classic half-day walk - surely one of Scotland''s finest.', 56.7809, -5.8251),
('5533a519-57f5-5f12-a480-e8b96c55dabb', 'Dunblane to Ashfield riverside walk, Dunblane', 'https://www.walkhighlands.co.uk/fife-stirling/dunblane-ashfield.shtml', 4.25, 74, 1.5, 'A scenic and straightforward riverside walk linking Dunblane, with its attractive Cathedral and interesting main street, with the pretty village of Ashfield. The walk can be combined with the Bridge of Allan to Dunblane walk and a bus can be caught to return to either start.', 56.1875, -3.9652),
('553eb231-230a-5a3e-932a-c03e218a9ce4', 'Ardentinny Forest walks', 'https://www.walkhighlands.co.uk/argyll/ardentinny.shtml', 6.0, 167, 2.0, 'Ardentinny is a forestry village in a beautiful location on the western shore of Loch Long. This scenic route starts from the waterfront and links the various waymarked trails to make a longer route, as well as visiting an idyllic pebble beach.', 56.0548, -4.9081),
('554ea880-1bcc-5478-8db5-fee8d559c6fa', 'Knockman Wood, Newton Stewart', 'https://www.walkhighlands.co.uk/galloway/knockman-wood.shtml', 4.5, 111, 1.5, 'The start may be in an unpromising commercial plantation, but this circuit through Knockman Wood turns oat to be a delight, with semi-natural oakwoods interspersed with more open ground. The route visits a neolithic chambered cairn as well as the outlines of archaeological remains from medieval times.', 54.9758, -4.4876),
('554fbeb0-1547-52fe-8d71-fa8d787d7d82', 'Great Cumbrae Inner Circle', 'https://www.walkhighlands.co.uk/glasgow/cumbrae-inner-circle.shtml', 11.5, 221, 3.5, 'This circular walk links the ferry pier at the northern end of Great Cumbrae with the town of Millport on its southern coastline. It does so by following the quiet country lanes at the heart of the island, also visiting the highest point; there are superb views throughout.', 55.7866, -4.8986),
('558e5653-fc68-5d73-8420-b6554875b6ae', 'The Ring of Steall, Mamores', 'https://www.walkhighlands.co.uk/fortwilliam/ringofsteall.shtml', 16.0, 1676, 12.0, 'The Ring of Steall is a real classic mountain route combining the traverse of four Munros with scrambling along narrow, rocky aretes. The route takes in An Gearanach, Stob Choire a Chàirn, Am Bodach and then follows the Devils Ridge to Sgùrr a''Mhaim.', 56.7777, -5.00034),
('55a4533b-5486-52de-822a-d9ece5ea3b04', 'Rockcliffe to Sandyhills', 'https://www.walkhighlands.co.uk/galloway/rockcliffe-sandyhills.shtml', 7.25, 266, 3.5, 'This superb linear coastal walk links picturesque Rockcliffe with the sandy beach at Sandyhills. In between there is some excellent coastal and clifftop scenery with great views up and down the coastline as well as across the Solway Firth. An infrequent bus service leads back to the start - or you could walk (doubling the time and distance).', 54.8637, -3.7918),
('55a78399-a77c-5bd0-8c3d-f9588da54ba5', 'Macleod''s Tables', 'https://www.walkhighlands.co.uk/skye/macleodstables.shtml', 11.0, 691, 6.0, 'Macleod''s Tables are two curious flat-topped hills prominent in views from many parts of Skye. Their ascent gives a very rough, pathless moorland walk but with great views.', 57.4079, -6.5703),
('55b18bd1-7ae5-5bb7-94ee-a25509865590', 'Loch Garten and Garten woods', 'https://www.walkhighlands.co.uk/cairngorms/loch-garten.shtml', 9.0, 110, 2.5, 'This circuit visits the Garten pinewoods which are being restored to a natural state by the RSPB. It includes a visit to Loch Garten - famous for its Osprey eyrie- and the more secretive Loch Mallachie. These special woods are home to the rare capercaillie, and dogs should be kept on a short lead during the very sensitive breeding season between 1 April and 15 August.', 57.2499, -3.7378),
('55c0cd77-feba-593d-84e2-a323f4ee0564', 'Armadale hill and woodland', 'https://www.walkhighlands.co.uk/skye/armadale.shtml', 6.0, 202, 2.0, 'This pleasant woodland walk on the Armdale Estate leads up to moorland viewpoint providing stunnings views over Sleat and the waters of the Sound to the mountains of the mainland.', 57.0649, -5.9004),
('55c53781-45b2-59da-bdfe-4e3b5ae64f85', 'Quinag: three Corbetts', 'https://www.walkhighlands.co.uk/ullapool/quinag.shtml', 14.0, 1130, 8.5, 'Quinag is a magnificent and complex mountain with three summits attaining Corbett status. The ascent of all three is one of the finest hillwalks in Scotland, with fine peaks, dramatic ridges and stunning views. If the full walk is too much, the ascent of the first peak (with a return the same way) is a short and fairly straightforward hillwalk with rewards out of all proportion to the effort involved. The mountain is under the stewardship of the John Muir Trust.', 58.1996, -5.0089),
('5604185d-6481-51cc-bf60-6421caf623ab', 'Morrone Birkwood, Braemar', 'https://www.walkhighlands.co.uk/cairngorms/morrone-birkwood.shtml', 4.5, 120, 2.0, 'Morrone birkwood (birk is Scots for birch) clothes the flanks of the hill rising south of Braemar. It is regarded as one of the finest examples of ''downy'' birchwoods in the UK and with vast areas of juniper. This fine circuit explores the nature reserve and has some wonderful views into the Cairngorms.', 57.0032, -3.4128),
('56393e4c-02fe-5b5d-a72e-664102f29bf7', 'Chanonry Point and Swallows Den, Fortrose', 'https://www.walkhighlands.co.uk/lochness/Chanonry.shtml', 8.0, 154, 4.0, 'This excellent walk visits Chanonry Point - the best place in Britain for dolphin-watching - as part of a circuit including both great beaches and fine views.', 57.5817, -4.1304),
('56d56c4f-83f2-5c87-a395-07827a6b2bff', 'Callander to Falls of Leny circuit', 'https://www.walkhighlands.co.uk/lochlomond/callander-leny.shtml', 7.5, 55, 3.0, 'The Falls of Leny provide an impressive target on this straightforward walk from Callander. Starting from the town centre the route follows the combined cycle-walkway along the old railway line following the river upstream and then returns through oak woodland before rejoining the cycle track.', 56.2442, -4.2187),
('56db6b42-f11c-541c-b87e-040a0b5b8eea', 'Càrn Dearg (Bhrunachain), Glen Roy', 'https://www.walkhighlands.co.uk/fortwilliam/carn-dearg-bhrunachain.shtml', 9.0, 674, 6.0, 'Càrn Dearg is one of four Corbetts accessible from Glen Roy, no less than three of which are called Càrn Dearg. This is the highest of the hills around the glen; the upper slopes are featureless moorland, the lower slopes steep and scarred by the famous ''parallel roads''.', 56.9793, -4.7487),
('57025f9c-8678-53e1-9223-f9e69208aa11', 'East Lomond circuit, Falkland', 'https://www.walkhighlands.co.uk/fife-stirling/east-lomond.shtml', 7.0, 380, 3.5, 'This superb walk has a bit of everything; a start in beautiful, historic Falkland, a challenging climb to a windswept summit, extensive views and a descent down a fascinating ravine.', 56.2531, -3.208),
('573b1913-af33-57f4-b7d9-de3dfeee9381', 'Beinn na Caillich, from Inverie', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-na-caillich-knoydart.shtml', 21.5, 1048, 9.0, 'Beinn na Caillich is the most westerly of Knoydart''s main hills, and is perhaps the Corbett furthest from the UK road network. The ferry to Inverie, however, makes it into a daywalk of reasonable length. The summit plateau is uncharacteristic of Knoydart, but the distant views are superb.', 57.0383, -5.6852),
('574a4e35-70b8-5656-85de-136f1b7a8985', 'Castle Sinclair Girnigoe and Noss Head', 'https://www.walkhighlands.co.uk/sutherland/castle-sinclair-girnigoe.shtml', 9.0, 84, 3.5, 'This varied circuit takes in the dramatic cliffs between Staxigoe and Noss Head and then visits Castle Sinclair Girnigoe, and then returns on minor roads through farmland. Can also be walked as a linear walk if transport is arranged from Noss Head.', 58.4567, -3.0566),
('57b6edbf-9e98-5e12-af99-e203e87889ee', 'Inchrory and Strath Avon circuit, near Tomintoul', 'https://www.walkhighlands.co.uk/cairngorms/inchrory.shtml', 29.75, 644, 8.5, 'This long circuit visits the lonely upper reaches of Strath Avon, far into the mountains, before returning via the extensive grouse moors. The route passes through very remote country, far from help, though most of it follows good tracks. The pathless section can be avoided if necessary which makes this also a good route for mountain bikers.', 57.2419, -3.3856),
('57ec0b58-54bd-577c-b854-1136d8bed070', 'Daingean Trail, Glengarry', 'https://www.walkhighlands.co.uk/fortwilliam/daingean.shtml', 0.75, 41, 0.75, 'This easy-going walk exploring the atmopsheric remains of the abandoned settlement at Daingean. The walk is short but has fine views over Loch Garry and beyond. It was opened with interpretative boards and information on site but these have all been removed - the path and ruins remain.', 57.0856, -4.90784),
('57f5a91d-5fba-5f11-886a-1d478fc6f299', 'Plean Country Park, Plean', 'https://www.walkhighlands.co.uk/fife-stirling/plean-country-park.shtml', 2.5, 52, 0.75, 'Plean Country Park was once the grounds for the now ruined Plean House, a late 18th century mansion. Later the area was a centre for coal-mining, but the old bings have now been recolonised by nature. There are three waymarked walks through the woods here - this is the longest.', 56.0599, -3.8845),
('58151bbc-555d-5f6f-aef5-01b2539ac8e3', 'Garbh Bheinn, Loch Leven', 'https://www.walkhighlands.co.uk/fortwilliam/garbh-bheinn-loch-leven.shtml', 6.0, 865, 6.0, 'Garbh Bheinn has a fine conical form and encloses the southern side of Loch Leven. The ascent is short but unremittingly steep, with outstanding views throughout.', 56.7019, -5.035),
('58195d6e-8647-5feb-9855-f0177d730fc4', 'Cata Sand and Tres Ness, Sanday', 'https://www.walkhighlands.co.uk/orkney/tres-ness.shtml', 9.5, 10, 3.0, 'Tres Ness is a peninsula linked tenuously to Sandy by a long spit of impressive dunes dividing Cata Sands from the Bay of Newark. This walk heads out over the sands to visit the furthest point - it is best avoided at high tide when the easiest walking below the dunes would be covered. Prepare to be dive-bombed by arctic terns in nesting season.', 59.2581, -2.5214),
('58609c47-c36c-574b-a7d4-2dd370916439', 'Dumgoyne and Earl''s Seat, near Killearn', 'https://www.walkhighlands.co.uk/glasgow/dumgoyne-earls-seat.shtml', 10.5, 709, 4.0, 'The distinctive wee steep peak of Dumgoyne is a popular local landmark. This route combines it with a moorland ramble to Earl''s Seat with extensive views north and the possibility of a dram on return.', 56.0149, -4.3646),
('58be792a-0a7f-53b1-ad92-88a799add2c3', 'Goatfell, from Brodick Castle', 'https://www.walkhighlands.co.uk/arran/goatfell.shtml', 10.5, 874, 6.0, 'A fine pyramidal peak and a magnificent viewpoint, Goatfell is the highest of the mountains on Arran and the culminating point of some dramatic granite ridges. This is the most popular and straightforward route of ascent.', 55.5921, -5.1563),
('58ca065c-8a5d-5237-9197-e42934d38fb8', 'Island of Noss National Nature Reserve', 'https://www.walkhighlands.co.uk/shetland/noss.shtml', 8.25, 230, 4.5, 'One of the best walks in Shetland, this coastal circuit around the stunning Island of Noss visits some of Europe''s finest seabird colonies. The highlight is the approach to Noss Head - a magnificent gannetry - but there are superb views, puffins, a fine beach and the chance to see otters or even whales out in the sound.', 60.1504, -1.0468),
('591cf888-8188-57ea-af32-d37043ddd7aa', 'Arichonan Clearance Village', 'https://www.walkhighlands.co.uk/argyll/arichonan.shtml', 2.0, 110, 0.75, 'This short walk visits the haunting ruins of Arichonan, a township which was the scene of a riot during the Highland Clearances. The site has fine views down Caol Scotnish.', 56.0607, -5.571),
('595bf0d8-e894-54f1-a85b-fa5ee5890ec6', 'Upper Findhorn moors and glens, Strathdearn', 'https://www.walkhighlands.co.uk/lochness/upper-findhorn.shtml', 20.5, 468, 6.5, 'Strathdearn winds far into the heart of the Monadhliath range. Little visited by walkers, this is a remote and lonely corner of the Highlands. This circular route uses good landrover tracks to explore the moors and glens of the area. Grouse-shooting takes place here and could restrict access on certain days in the season.', 57.2351, -4.1367),
('5a17f1a5-5cb4-54b1-8bd5-05f6ec9fd6a2', 'Aonach Eagach', 'https://www.walkhighlands.co.uk/fortwilliam/aonacheagach.shtml', 9.5, 1100, 9.0, 'Famed as the narrowest ridge on the British mainland (though Liathach and An Teallach must run it close), the Aonach Eagach gives a thrilling and spectacular traverse for keen and experienced scramblers, linking the Munros of Meall Dearg and Sgòrr nam Fiannaidh. The route is a grade 2/3 scramble, and is included in some climbing guides as a ''Moderate'' rock climb; it involves probably the trickiest scrambling on any Walkhighlands route. Ensure you have the necessary skills and experience, choose a dry day (the rocks are slippery when wet) and leave plenty of time to complete the route in daylight. If in any doubt, it is best to hire aguide.', 56.6666, -4.9824),
('5a27af6f-8a30-5db2-87e4-5053ef8c2503', 'Torridon Trail - boathouse walk', 'https://www.walkhighlands.co.uk/torridon/Lochtorridon.shtml', 1.5, 40, 1.0, 'Easy waymarked walk with beautiful views across Loch Torridon. The walk includes a beauiful section of shoreline.', 57.5283, -5.52636),
('5a330ed7-ee49-52dd-b00e-634c20692d97', 'Countesswells forest trails', 'https://www.walkhighlands.co.uk/aberdeenshire/countesswells.shtml', 4.75, 60, 1.5, 'Just beyond the western fringes of Aberdeen - between Cults and Kingswells - several small areas of forestry provide for short, pleasant walks. This route combines several of the waymarked paths in Countesswells Forest.', 57.1314, -2.2162),
('5a6de76c-6dfa-5b8c-8621-ed731380948a', 'Loch an t-Sabhail circuit, Little Assynt', 'https://www.walkhighlands.co.uk/ullapool/little-assynt.shtml', 4.5, 150, 2.0, 'Assynt''s interior is a wild landscape of rough and rocky moorland, speckled with crags and hillocks and dotted with hundreds of lochans. Away from the monolithic mountains it is little visited; this superb route gives a good introduction to this wilderness with the benefit of a fine path underfoot.', 58.1768, -5.1412),
('5abc79f5-9b8a-5f09-90f1-597a391ea6a5', 'Gloup Voe and Scordaback, Yell', 'https://www.walkhighlands.co.uk/shetland/gloup.shtml', 4.0, 154, 2.0, 'Traverse the steep high slopes of the dramatic inlet of Gloup Voe to reach the head of the sea loch and remains of an old fishing haaf, the route climbs over rough moorland to reach the small summit viewpoint of Scordaback - an easier route is to return along the Gloup. The route can be done as an extension of theSands of Breckonroute to make a much longer walk.', 60.7211, -1.0736),
('5ae507d8-5a14-52d9-ba0c-d61eab0ea7b1', 'Hill of Rowan, Tarfside, Glen Esk', 'https://www.walkhighlands.co.uk/angus/hill-of-rowan.shtml', 7.25, 197, 2.5, 'The Hill of Rowan is a low, heathery summit with a fine position, dividing upper Glen Esk from Glen Tarf. It is a prominent landmark due to the huge memorial on the summit, visible for miles around; a visit makes a very fine low moorland walk.', 56.9058, -2.8348),
('5b029ac9-2cdc-5938-8277-2639d159eb70', 'Bioda Buidhe', 'https://www.walkhighlands.co.uk/skye/biodabuidhe.shtml', 3.0, 230, 2.0, 'The Quiraing is often extremely busy, but far fewer people venture along the ridge on the opposite side of the road towards the summit of Bioda Bhuidhe. This short walk along the Trotternish Ridge offers simply fantastic views.', 57.6282, -6.2903),
('5b2449fb-0def-590e-b91e-1794ab7ebabc', 'Green Lowther and Lowther Hill, Wanlockhead', 'https://www.walkhighlands.co.uk/galloway/lowther-hills.shtml', 11.5, 541, 3.5, 'The Lowther Hills have steep flanks but gentle rolling summits. The two highest, Green Lowther and Lowther Hill, both have radio masts or other impedimentia on their summits - including a (private) tarmac road. This walk climbs both as well as the lower but unspoilt East  Mount Lowther; the views are superb.', 55.3968, -3.7775),
('5b29d176-6ea6-5b60-86b8-988c16a3de51', 'Binnein Riabhach, Port Mòr', 'https://www.walkhighlands.co.uk/islay-jura/binnein-riabhach.shtml', 5.75, 128, 2.0, 'The western coastline of Colonsay is wild and rugged with some impressive cliff scenery. This walk is particularly rewarding in early summer when the cliffs are home to nesting seabirds.', 56.0733, -6.2409),
('5b527454-6bcc-585e-b08d-76589721dfdf', 'Ronas Hill, Northmavine', 'https://www.walkhighlands.co.uk/shetland/ronas-hill.shtml', 6.5, 284, 3.0, 'Ronas Hill is the highest summit in Shetland, rising as a broad dome of stony, granite tundra above the great plateau of North Roe. This is a wild and windswept place but the views are superb, and the track up to the masts on Collafirth Hill makes for a high level start.', 60.534, -1.3919),
('5c45d1d6-a10c-5783-9fe5-c24e25f00f5c', 'Slioch, near Kinlochewe', 'https://www.walkhighlands.co.uk/torridon/Slioch.shtml', 19.0, 1144, 9.0, 'The view of the craggy fortress of Slioch across the waters of Loch Maree is one of the classics of Scotland featured in countless calendars. At close quarters Slioch offers a reasonably straightforward ascent given that formidable appearance, and the summit views over Loch Maree and into the Fisherfield wilderness are sensational.', 57.6085, -5.2866),
('5cb1c103-997e-5c51-80d5-ae3bbcf9e560', 'Montrose Basin, near Montrose', 'https://www.walkhighlands.co.uk/angus/montrose-basin.shtml', 5.75, 8, 2.0, 'Montrose Basin is a large tidal basin of mud, sand, salt marsh and reed bed. It is an important local Nature Reserve and a great place to visit for birdwatchers. This walk visits parts of the western fringe of the basin, including two hides.', 56.7226, -2.5425),
('5ccd59fb-d929-5c77-8f96-ffcd8700595b', 'Dùn Cuithir archeological walk, Allasdale', 'https://www.walkhighlands.co.uk/outer-hebrides/dun-cuithir.shtml', 8.0, 194, 4.5, 'A rough moorland walk on the western side of Barra, exploring several archaelogical sites. The route is waymarked with posts - there is mostly no path- although these have a tendency to be knocked down by grazing cows, so careful navigation is required at times.', 57.0022, -7.5003),
('5cef66ef-822c-5048-8995-440b43565157', 'Windy Gyle circuit, Cheviots', 'https://www.walkhighlands.co.uk/borders/windy-gyle.shtml', 10.25, 426, 4.0, 'This fine hill circuit uses grassy tracks to make a horsehoe in a remote part of the Cheviots - visiting the huge and ancient cairn on the summit of Windy Gyle.', 55.4607, -2.23502),
('5d4f5b08-1d70-57bc-8dac-f7d2f4fed0dd', 'John Brown''s Memorial walk, Priesthill', 'https://www.walkhighlands.co.uk/glasgow/john-brown-memorial.shtml', 2.5, 44, 1.5, 'A short, but very rough linear walk to a martyr''s grave in the wild moorland north of Muirkirk.', 55.5564, -4.03047),
('5d564203-440f-5313-a506-0bb64d49e4e7', 'Acharn Woods, Killin', 'https://www.walkhighlands.co.uk/perthshire/acharn-woods.shtml', 6.0, 130, 2.0, 'This easy walk follows a wooded old railway line and then tracks through forestry plantation with felled areas allowing good views towards the Tarmachan Ridge.', 56.4615, -4.32132),
('5deace90-1efe-5a86-8fbf-120f5d0917c0', 'Heritage Trail: Tolsta to Lional', 'https://www.walkhighlands.co.uk/outer-hebrides/heritage-trail.shtml', 21.5, 471, 7.0, 'The Heritage Trail follows a traditional route linking the old summer shielings along a very remote but atmospheric stretch of the Lewis'' coastline. Far from help or easy escape routes for much of the way and with no formal path, it is a challenging route across unforgiving terrain.', 58.3562, -6.2206),
('5e1a3837-fc75-5b2e-ac04-c2f27e1b9012', 'Corstorphine Hill', 'https://www.walkhighlands.co.uk/lothian/corstorphine-hill.shtml', 4.5, 124, 1.5, 'The most westerly of Edinburgh''s Seven Hills, Corstorphine Hill provides an enjoyable woodland walk with superb views looking out over the city and across the Forth.', 55.9625, -3.278),
('5e1ea9c3-bc7c-50d5-9a93-dc5a9167dfa4', 'Seaton Cliffs and Auchmithie, Arbroath', 'https://www.walkhighlands.co.uk/angus/arbroath-cliffs.shtml', 13.0, 320, 4.0, 'This classic coastal walk explores the Seaton Cliffs which extend north from Arbroath and have a wealth of red sandstone formations. The walk continues as far as Auchmithie - where there is a popular restaurant; the return is by the same outward coastal route or you could shorten the walk by taking a bus back to Arbroath.', 56.5609, -2.5574),
('5e5a6a76-2417-5524-8c59-9a09b67d940d', 'Ardviourlie Woodland Observatory, Ardviourlie', 'https://www.walkhighlands.co.uk/outer-hebrides/ardviourlie.shtml', 3.5, 183, 2.0, 'With the rugged and rocky landscape of North Harris, Ardviourlie Woodland is a welcome change. Planting began in 2000 as part of the Millennium Forest Programme, at 100ha it is now the largest area of woodland in North Harris. This short, circular route has incredible views over the glen with Eagles regularly seen soaring above.', 57.9944, -6.7629),
('5e7bb6bb-935d-5f02-a20a-474f0f0f4290', 'Findhorn circular, Findhorn', 'https://www.walkhighlands.co.uk/moray/findhorn.shtml', 4.5, 2, 1.5, 'A lovely circular walk taking in Findhorn village, the shingle spit overlooking Findhorn Bay, the sandy beach and dunes. Findhorn has a couple of good cafes, two pubs and a shop.', 57.663, -3.6162),
('5e80aecc-00cf-5908-b8ac-1aa9a729eb2b', 'Sands o'' Wright, South Ronaldsay', 'https://www.walkhighlands.co.uk/orkney/sands-of-wright.shtml', 6.0, 59, 2.0, 'A scenic golden beach and shingle ayre (spit) combine in this pleasant and varied stroll around the minor roads and coastline on South Ronaldsay.  The walk could be extended by a detour toHoxa Head.', 58.8255, -2.9995),
('5e8232fd-0b1c-5554-8895-22522d2754bc', 'Bullers of Buchan to Boddam', 'https://www.walkhighlands.co.uk/aberdeenshire/bullers-boddam.shtml', 8.0, 252, 3.5, 'This fine linear coastal walk takes in some of the finest clifftop scenery on the Aberdeenshire coastline, with stacks, arches and birdlife galore. The start and finish are served by bus, and for a longer walk it is possible to begin at Cruden Bay.', 57.4326, -1.8238),
('5e9df0c5-9d37-5d1d-9b7c-6aae29ccfcb3', 'Tràigh Hornais, Clachan Sands', 'https://www.walkhighlands.co.uk/outer-hebrides/clachan-sands.shtml', 5.5, 7, 1.0, 'A straightforward walk along a beautiful wide sandy beach backed by machair which is a riot of colourful flowers in the summer months. The walk can be cut short by returning at any point, or extended by venturing onto the adjacent Tràigh Lingeigh, the next beach to the north.', 57.6688, -7.2431),
('5ea28f94-10d7-5bcc-ba62-e9008d29d6cb', 'Leacanashie and Ardaneaskan circuit', 'https://www.walkhighlands.co.uk/torridon/Ardaneaskan.shtml', 5.0, 260, 2.0, 'A short, quiet circuit through forestry and around the coast.', 57.3601, -5.57396),
('5eabb60d-1a50-5981-b819-4e635bc31a4b', 'West Port Beach (Machrihanish Bay)', 'https://www.walkhighlands.co.uk/argyll/west-port-beach.shtml', 4.5, 3, 2.0, 'Westport Beach with Machrihanish Dunes as its backdrop, is a beautiful, long beach popular with surfers, beachcombers and walkers. This walk along the beach from the north end allows you to make your walk as far or as short as you want.', 55.4742, -5.711),
('5ed30502-8151-5a31-9196-de6d0fb22a46', 'Mountain End trail, Clints of Dromore, Fleet Valley', 'https://www.walkhighlands.co.uk/galloway/clints-of-dromore-outbye.shtml', 6.5, 246, 3.5, 'This walk extends the easy In-Bye route by heading up over the top of the craggy Clints of Dromore. The route over the top is mostly waymarked but is rough and often very wet in places. The views are good, however, and it offers a chance to visit ''Hush'' - a sculpture by Matt Baker.', 54.9477, -4.2583),
('5ef96f3b-e24c-50cf-afc7-730b61541f6c', 'Lyrawa Hill and Scad Head, Hoy', 'https://www.walkhighlands.co.uk/orkney/lyrawa-hill.shtml', 3.75, 111, 2.0, 'Head up to the viewpoint on Lyrawa Hill before descending over heather moorland to the WWII anti-aircraft battery at Scad Head, now a peaceful spot to watch wildlife. The walk then follows the route of a WWII railway uphill to return steeply to the start.', 58.8793, -3.249),
('5f01afec-cde7-58da-96b1-d770405451bb', 'Helli Ness, Greenmow', 'https://www.walkhighlands.co.uk/shetland/helli-ness.shtml', 4.25, 84, 2.0, 'A short walk over the low hill of the Ward of Greenmow before an exploration of the headland of Helli Ness and a coastal return via a couple of large glacial erratic rocks.', 60.0423, -1.2032),
('5f6ed484-8002-552f-80ee-c0b094b718ca', 'Meall na h-Aisre, from Garva Bridge', 'https://www.walkhighlands.co.uk/cairngorms/meall-na-h-aisre.shtml', 13.0, 611, 5.0, 'Meall na h-Aisre is a typical Monadhliath hill, with rounded uppermost slopes. If climbed on its own it as described here it makes for a relatively short day. Keen baggers could extend the walk across some very boggy terrain toGairbeinn.', 57.0199, -4.436),
('5f863814-a791-5396-83fb-de2e78f07b41', 'Laggan Point circuit, Bowmore', 'https://www.walkhighlands.co.uk/islay-jura/laggan-point.shtml', 14.0, 49, 4.0, 'An easy walk from Bowmore with many bird watching opportunities and a chance to visit a beach. The return section on main road can be busy and not suitable for children.', 55.7568, -6.2879),
('5f9f46c1-e550-5fab-81b9-840bd18e97ac', 'The Buck of Cabrach', 'https://www.walkhighlands.co.uk/aberdeenshire/the-buck.shtml', 4.6, 285, 2.0, 'This prominent cone-shaped peak has a road high on its flanks, making for a short ascent, though the intial stretch is across very boggy ground. Good all round views and pictish-style carvings near the summit.', 57.3161, -2.964),
('5fa5e7af-b2fa-571c-9067-e1007322601f', 'Nairn to Cawdor by the river, Nairn', 'https://www.walkhighlands.co.uk/moray/nairn-cawdor.shtml', 9.0, 55, 2.0, 'This pleasant linear riverside walk leads from Nairn to Cawdor mostly along the banks of the River Nairn through lovely countryside. Infrequent bus (schooldays and school start and finish times only) links Cawdor to Nairn, check timetables first, or arrange pick up or walk route in both directions - Cawdor has a deli/cafe as well as the Castle.', 57.585, -3.8684),
('5ff86cba-69ff-5e30-893a-8e4ddd5f042e', 'Gleann Beag and the Glenelg Brochs to Suardalan', 'https://www.walkhighlands.co.uk/kintail/Suardalan.shtml', 14.0, 265, 5.0, 'An easy going but increasingly wet walk combining the fascinating iron age brochs of Glen Beag with the wild open moorland at the head of the glen.', 57.1949, -5.59472),
('60198e8a-9d2c-5f2f-8919-ab1fbc849a44', 'Beinn Dearg Mòr and Beinn Dearg Bheag, Gruinard', 'https://www.walkhighlands.co.uk/ullapool/beinn-deargs-fisherfield.shtml', 35.25, 1450, 15.0, 'Beinn Dearg Mòr and Bheag rise across Loch na Sealga from mighty An Teallach, but are in no way overshadowed by their famous neighbour. These magnificent peaks have dramatic rock architecture, a very remote but spectacular location, and superlative views; they rank amongst not just the finest Corbetts but amongst the finest of all Scotland''s mountains.', 57.8637, -5.4379),
('6024c84c-5a65-58bc-a4c3-3abb4b7a2eae', 'Wallace Monument and Abbey Craig', 'https://www.walkhighlands.co.uk/fife-stirling/wallace-monument.shtml', 2.5, 172, 1.0, 'The Wallace Monument, immensely impressive on its wooded summit, is one of Scotland''s best known landmarks and a national icon. This short walk visits the base of the monument and explores the woods, with excellent views over Stirling and towards the Ochils.', 56.1397, -3.9198),
('6033ab69-264a-5226-979f-4da74b376e28', 'River Inver and Glencanisp circuit', 'https://www.walkhighlands.co.uk/ullapool/glencanisp.shtml', 7.5, 210, 3.0, 'This superb circuit heads up the beautifully wooded River Inver before following an old path across the moors to reach a beautiful loch with amazing mountain views.', 58.1513, -5.2409),
('603b7239-b7df-5b57-a85f-a13c5a0102c5', 'Berneray Explorer', 'https://www.walkhighlands.co.uk/outer-hebrides/berneray.shtml', 12.25, 156, 4.5, 'The island of Berneray is just off the northern coast of North Uist and is linked to it by a new road causeway. It is explored by this excellent and very varied walk, taking in the views from its highest hill, a standing stone, the picturesque thatched hostel, and one of the most magnficent beaches in the UK.', 57.7151, -7.1913),
('606f3a11-00e5-5d53-8af2-2d944aae07bc', 'Holy Isle - Mullach Mòr ascent', 'https://www.walkhighlands.co.uk/arran/holy-island.shtml', 7.5, 425, 3.5, 'Arran''s Holy Isle is a magical place. Owned by the Samye Ling Tibetan Buddhist centre in Galloway and used as a base for courses as well as a home to nuns, the island has a real feeling of peace. This is the more strenous of our two walking options on the island, climbing up to the rocky summit of Mullach Mòr - a real mountain in minature.', 55.5336, -5.08849),
('608a957e-582e-5487-b476-33d98f0ffe83', 'Camas nan Geall and Bourblaige', 'https://www.walkhighlands.co.uk/fortwilliam/camasnangeall.shtml', 6.75, 227, 3.0, 'This attractive walk heads along a fascinating stretch of coastline, passing a sandy beach, interesting rock formations and archaeological remains. Bourblaige was a village which was brutally cleared by landlords the Riddell family in 1838; it is the best preserved of such villages in Ardnamurchan.', 56.6825, -5.98118),
('60d4cc4d-9113-5fda-afd4-7471b9be2a0d', 'Callander Crags', 'https://www.walkhighlands.co.uk/lochlomond/callander-craig.shtml', 4.0, 300, 2.0, 'This fine circuit takes you high above Callander through mixed woodland to visit Callander Crags (Craig on OS maps) and the Jubilee Cairn. From the top there are sweeping views of Callander and into the wild area of moorland to the north. This woodland walk can be combined with a visit to Bracklinn Falls by walking up the road from the car park to join the Bracklinn Falls route.', 56.2464, -4.2068),
('60ea628f-d435-5d54-833d-01d92e825d83', 'Beinn Udlaidh and Beinn Bhreac-liath, Glen Orchy', 'https://www.walkhighlands.co.uk/argyll/beinn-udlaidh.shtml', 12.0, 911, 6.0, 'This pair of Corbetts provide an enjoyable hillwalk above Glen Orchy. Beinn Bhreac-liath lacks distinction, but Beinn Udlaidh has a prominent landmark - a distinctive quartzite dyke which extends almost from the summit ridge down to the glen.', 56.4913, -4.799),
('6132d2ba-4edc-5eb5-a161-aecb590ba412', 'Beinn Airigh Charr, from Poolewe', 'https://www.walkhighlands.co.uk/torridon/beinn-airigh-charr.shtml', 22.25, 984, 8.0, 'The fairly long approach to Beinn Airigh Charr is well rewarded by some of Scotland''s most magnificent views, whetting your appetite for longer expeditions into the Letterewe and Fisherfield Forest wilderness areas to the north or the Torridon mountains seen across Loch Maree. The route is described as an out-and-back walk, but the return can be varied by heading round the north side of Loch Kernsary.', 57.7658, -5.6027),
('615b63e0-65e3-5be1-9eb5-557d4e8db3b6', 'Tiorga Mòr', 'https://www.walkhighlands.co.uk/outer-hebrides/tiorga-mor.shtml', 16.25, 720, 7.0, 'Tiorga Mòr is the most westerly of the main Harris hills and thus is a superlative viewpoint. After an initial boggy section on the approach, the northwest ridge makes for a fine route of ascent; the descent via Tiorga Beag is again wet but provides a grand view of the massive overhanging precipice of Sròn  Uladal.', 57.9611, -6.9862),
('617dbad6-37a7-56bc-b692-2fabc8d76e5b', 'Musselburgh and the Firth', 'https://www.walkhighlands.co.uk/lothian/musselburgh.shtml', 6.5, 2, 2.0, 'Head from the centre of Musselburgh out around the Firth of Forth and Levenhall Links before returning past the racecourse. The walk is popular with birdwatchers, both for the sea birds on the Firth and the roosting birds on the ash lagoons of the links.', 55.9431, -3.0486),
('61b5c0bb-5363-5110-aa79-345f7b097c1b', 'Kinpurney Hill and Monument, Newtyle', 'https://www.walkhighlands.co.uk/angus/kinpurney-hill.shtml', 5.5, 283, 2.0, 'A good mixed walk alongside an old mill stream and then onto open country to the large tower at the top of Kinpurney Hill in the Sidlaws, which has excellent views. Fairly steep climb with return by the same route.', 56.5603, -3.1432),
('61db0cbd-a24d-594f-ade9-9c0ad3d9d7d0', 'Kirkton Glen, Balquhidder', 'https://www.walkhighlands.co.uk/lochlomond/kirkton-glen.shtml', 9.0, 380, 2.5, 'Kirkton Glen is a forested valley running north from Balquhidder. The glen is on the line of an old right of way over the hills to Ledcharrie in Glen Dochart but these days is more often visited on a circular walk from the south end. There are good views of the surrounding mountains.', 56.358, -4.3707),
('61de8592-7e6c-54b2-b2bb-fd1505da0aa2', 'Meall Buidhe & Sròn  a'' Choire Chnapanich, Pubil', 'https://www.walkhighlands.co.uk/perthshire/sron-a-choire-chnapanich.shtml', 15.75, 921, 6.5, 'This remote pair of Corbetts rise at the head of beautiful Glen Lyon. Meall Buidhe - not be confused with its namesake Munro nearby - is a rounded dome with a great outlook across Rannoch Moor. The lower Sròn  a'' Choire Chnapanich is a grassy perch atop steep slopes plunging to Loch an Daimh.', 56.544, -4.50676),
('61fbb2d1-4ffa-5b16-9ae5-7a3b539c6afc', 'Great Trossachs Path 2: Trossachs Pier to Callander', 'https://www.walkhighlands.co.uk/lochlomond/great-trossachs-path-2.shtml', 19.0, 315, 5.5, 'Stage 2 of the Great Trossachs Path follows minor roads and forestry tracks to skirt around Loch Achray, reaching Brig o''Turk (and its famous tearoom). From here a shared mountain bike path follows higher ground above Loch Venachar to eventually finish at the town of Callander which has all facilities.', 56.2334, -4.4284),
('61fd08ff-0f95-58e2-b667-7b75e3b5fa8c', 'Lang Craigs Circuit, Dumbarton', 'https://www.walkhighlands.co.uk/glasgow/lang-craigs.shtml', 14.0, 319, 4.5, 'This circular route climbs from the streets of Dumbarton through the grounds of Overtoun House to climb up to a view point on Lang Craigs overlooking the Firth of Clyde before descending on a forestry track to pick up the cycle path running adjacent to the A82 and then back through the streets of Dumbarton.', 55.9471, -4.5621),
('621df0bc-46da-5264-9535-6b9f00d5f953', 'Keiss Castle and Nybster Broch, Nybster', 'https://www.walkhighlands.co.uk/sutherland/keiss-castle.shtml', 5.5, 137, 3.0, 'A fantastic coastal walk, rugged in part, taking in the remains of an iron-age broch, stunning coastal scenery to reach the impressive ruins of cllifftop Keiss Castle before returning by the same route. Can be combined with a visit to the Caithness Broch Centre at Auckengill.', 58.5552, -3.0839),
('627ae070-42d9-5328-9d2c-77459e366215', 'Beinn Dàmh (or Ben Damph)', 'https://www.walkhighlands.co.uk/torridon/Beinndamh.shtml', 12.0, 980, 6.0, 'This popular Corbett offers a stunning introduction to the mountains of Torridon. Beinn Dàmh is a superb viewpoint for both mountains and sea, and exhibits dramatic Torridonian sandstone architecture without the difficulty of some of its higher neighbours.', 57.5282, -5.52648),
('628de9bd-1cd2-5511-87b1-3e631781a2ec', 'Brecklet Trail, Ballachulish', 'https://www.walkhighlands.co.uk/fortwilliam/brecklet.shtml', 3.0, 116, 1.5, 'This waymarked trail climbs high above the old Ballachulish Slate Quarries giving stunning views; the return walk is through dense forestry plantations but visits some hidden ruins.', 56.6783, -5.13011),
('62aaea65-d561-5dc1-ae30-199511f736a2', 'Easdale explorer, Isle of Easdale', 'https://www.walkhighlands.co.uk/argyll/easdale.shtml', 2.25, 35, 1.0, 'Wander around the pretty cottages and old slate quarries then climb to the highest point on the tiny but fascinating car-free island of Easdale. Leave plenty of time to soak up the atmosphere, watch for wildlife or visit the museum or cafe.', 56.2924, -5.654),
('62feff5c-6a44-561c-aae5-26fe75c83c7a', 'Mount Battock via Clachnaben', 'https://www.walkhighlands.co.uk/aberdeenshire/mount-battock.shtml', 25.0, 1023, 8.0, 'Mount Battock is the highest point on a vast expanse of rolling, peaty moorland and is the most easterly of the Corbetts. Usually approached via Glen Esk, this longer route from the east visits the great granite tor of Clachnaben along the way.', 56.9718, -2.579)
INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('63229db0-2e42-5462-ab71-0e29528203a5', 'Delgatie Castle and Woods, near Turriff', 'https://www.walkhighlands.co.uk/aberdeenshire/delgatie-woods.shtml', 3.75, 70, 1.0, 'A short forestry walk through mixed woodland and forestry plantations with an uphill section and a good view of Delgatie Castle which can be visited from the walk.', 57.5447, -2.4094),
('633d286e-6875-5f3a-8a1e-75a7ce298280', 'Badenoch Way', 'https://www.walkhighlands.co.uk/cairngorms/badenoch-way.shtml', 17.5, 120, 6.0, 'The varied Badenoch Way leads from Dalraddy to near Kingussie, following the River Spey for much of the route and passing moorland, farmland and forestry before ending at the RSPB reserve at Invertromie overlooking the Insh Marshes.', 57.1519, -3.888),
('637f6ed3-7ee7-56b0-b2ac-5cc3f8c6ade1', 'Càrn na Nathrach, from Glen Hurich', 'https://www.walkhighlands.co.uk/fortwilliam/carn-na-nathrach.shtml', 17.25, 886, 7.0, 'Càrn na Nathrach lies hidden from most views amongst a group of higher peaks. It is a fine viewpoint, however, and the ascent along its long and rough ridge makes an enjoyable, surprisingly strenuous outing.', 56.7462, -5.5744),
('6380f491-0855-5128-acc3-b8ebf4165d43', 'Lynn Glen, near Dalry', 'https://www.walkhighlands.co.uk/glasgow/lynn-glen.shtml', 2.0, 32, 0.75, 'A short walk in a beautiful wooded glen featuring dramatic waterfalls and native trees. Carved wooden features and some fairy houses make it popular with small children.', 55.7011, -4.72757),
('6383c66b-068b-5b1b-81fa-8605b0e3ed66', 'The Mull of Kintyre', 'https://www.walkhighlands.co.uk/argyll/mull-of-kintyre.shtml', 4.0, 305, 2.0, 'The Mull of Kintyre is the blunt southwestern headland that marks the end of Scotland. Immortalised in song by Paul McCartney, the Mull is a simple but steep tarmac walk with stunning views across to Ireland as well as along the coast.', 55.3088, -5.7866),
('63ceaad1-4380-51f7-b2e1-573ae8daa6b5', 'Priestlaw Hill circular from Whiteadder Reservoir', 'https://www.walkhighlands.co.uk/lothian/priestlaw-hill.shtml', 11.0, 234, 4.0, 'This enjoyable and peaceful circuit follows the route of the old Herring Road from Whiteadder Reservoir to climb up into the Lammermuirs. The walk then leads to the summit of Priestlaw Hill before returning past the reservoir.', 55.8702, -2.57167),
('64040e0e-f0de-5ec9-911a-fbf2ed9aba7a', 'Balmedie Country Park, Balmedie', 'https://www.walkhighlands.co.uk/aberdeenshire/balmedie.shtml', 2.0, 10, 1.0, 'Pass through the magnificent dunes to reach the sweeping sandy beach at Balmedie and watch the North Sea waves crash in. Return past some world war two pill boxes to the car park where there is a good children''s play area and toilets. The walk can easily be extended by exploring the many paths amidst the dunes.', 57.2533, -2.0408),
('640c4fa3-6231-5417-8fb8-afa3dbae231b', 'Sgòrr an Fharaidh and the Finger of God', 'https://www.walkhighlands.co.uk/islands/finger-of-god.shtml', 5.75, 386, 3.0, 'This obscure hill rising above Cleadale in the northern part of Eigg gives an unexpectedly spectacular short hillwalk. A very steep ascend leads up to a grand walk along a fine escarpment, with views down over fabulous rock scenery to the beautiful beaches at bays of Laig and the Singing Sands, with the mountains of Rum and Skye making a fine backdrop.', 56.92, -6.1468),
('6427649c-a4ae-51e7-a79f-5f2a4a9f5b17', 'Dùn Nosebridge, near Mulindry', 'https://www.walkhighlands.co.uk/islay-jura/dun-nosebridge.shtml', 2.25, 22, 0.75, 'Follow a track through pleasant farmland to climb the impressive ramparts of Dùn Nosebridge, an iron-age fort with good views of the Islay hills beyond.', 55.7585, -6.2036),
('6447bec8-056c-59e5-80d3-1b7419bc291b', 'Loch Coruisk circuit (access by boat)', 'https://www.walkhighlands.co.uk/skye/lochcoruisk.shtml', 7.0, 122, 4.0, 'Loch Coruisk, at the very heart of the Cuillin,  is the most magnificent of all Scottish freshwater lochs. Whilst you are very likely to get wet feet from the boggy terrain, this is a small price to pay for the superlative mountain scenery along the way. If walking only one side of the loch, the south side has easier going and the best views.', 57.1977, -6.163),
('649aa80b-2caa-57c2-95fe-08dad9454126', 'Dundurn - St Fillans Hill, St Fillans', 'https://www.walkhighlands.co.uk/perthshire/dundurn.shtml', 4.7, 110, 2.5, 'Dundurn is a small but steep isolated rocky knoll, the site of a Pictish fort as well as the cell of Saint Fillan. It offers fine views and provides an interesting place to explore from the village to which Fillan gave his name.', 56.3909, -4.11418),
('64bb6b73-118b-5314-bb39-227102929f40', 'Allt a'' Chonais Pinewood, Craig', 'https://www.walkhighlands.co.uk/torridon/Glencarron.shtml', 6.0, 150, 2.0, 'This walk follows a vehicle track to a beautiful old native pinewood, with great views over the Coulin Forest peaks across Strathcarron.', 57.4913, -5.27229),
('64c0e599-7224-5988-ac5f-c6a4eb4bd0ed', 'Badbea - Clearance Village', 'https://www.walkhighlands.co.uk/sutherland/badbea.shtml', 2.0, 120, 1.0, 'Badbea is the haunting site of a now abandoned settlement. Though beautiful, it is a windswept and bleak spot. Following the Highland Clearances people were forced to live here, having been cleared from the fertile straths inland.', 58.1637, -3.5569),
('64e425f7-8e95-5220-a39d-5b66be75f6b7', 'North Sannox viewpoint walk', 'https://www.walkhighlands.co.uk/arran/sannox-forest.shtml', 4.0, 216, 1.5, 'Climb steeply through regenerating native woodland above North Sannox to reach a trig point with superb views over both the sea and Arran''s granite mountains.', 55.6722, -5.15889),
('64ee2cce-bf27-5b52-a48c-9823a9599f5f', 'Cliad Bay and the northwest coast', 'https://www.walkhighlands.co.uk/islands/cliad-bay.shtml', 9.25, 113, 3.5, 'Explore a wild stretch of the stunning western coastline of Coll. The route crosses some superb sandy beaches, home to seals, to reach a miniature rocky peak before returning along the quiet road.', 56.6468, -6.5588),
('64fb901a-100e-5f84-a398-ee7d12bbeda7', 'The Tarmachan Ridge', 'https://www.walkhighlands.co.uk/perthshire/meall-nan-tarmachan.shtml', 13.0, 783, 7.0, 'Meall nan Tarmachan is one of the easier Munros to reach in good weather thanks to a high level start point, but it is really just the start of a rocky ridge traverse which is one of the most interesting in the Southern Highlands. There is a short, avoidable scramble on the descent from Meall Garbh.', 56.5108, -4.2628),
('655135a9-520a-5e30-910e-412893063598', 'The Hill of Christ''s Kirk, Insch', 'https://www.walkhighlands.co.uk/aberdeenshire/hill-of-christs-kirk.shtml', 6.75, 246, 2.0, 'This prominent small hill offers fine views over the surrounding countryside and the ruined castle on top of neighbouring Dunnideer.', 57.3374, -2.61635),
('65587559-6015-5715-ad86-537426d219af', 'Dùn na Cuaiche, Inveraray', 'https://www.walkhighlands.co.uk/argyll/dun-na-cuaiche.shtml', 4.75, 236, 2.5, 'The monument on Dùn na Cuaiche is a prominent landmark from Inveraray; it is a wonderful viewpoint and visiting it makes a great objective for a walk.', 56.2382, -5.07394),
('65664e7e-c296-57f4-b46d-18e0b290b5de', 'Plockton Coral Beach, Plockton', 'https://www.walkhighlands.co.uk/kintail/plockton-coral-beach.shtml', 1.4, 31, 0.6666666666666666, 'This short walk to a beautiful and secluded coral beach. It makes a great place to watch for wildlife or just enjoy the fine setting.', 57.3326, -5.67545),
('6591421f-fa35-58d6-b8ac-615fad163982', 'Neptune''s Staircase and the Canal, Banavie', 'https://www.walkhighlands.co.uk/fortwilliam/neptunesstaircase.shtml', 4.5, 25, 1.5, 'This easy-going walk follows the banks of the Caledonian Canal - built by Thomas Telford. The route takes in the entrance to the canal from the sea at Loch Linnhe, as well as the famous Neptune''s Staircase - a spectacular flight of lochs.', 56.8453, -5.09681),
('65b2310f-768c-5790-9589-a652ae8d6b5b', 'Beinn an t-Sìdhean, Strathyre', 'https://www.walkhighlands.co.uk/lochlomond/beinn-an-t-sidhean.shtml', 7.25, 493, 3.5, 'Beinn an t-Sìdhean is a steep-sided hill that shelters Strathyre from the westerly winds. Its flanks are extensively clothed with forestry plantations but from the moorland above there are stunning views over Loch Lubnaig. The walk is described to the true summit, but there are a couple of fine stops along the way that make grand objectives for a slightly shorter walk in their own right.', 56.3223, -4.33),
('65df8192-27cc-5829-947c-cee382936644', 'Glen Loin and Coiregrograin, Arrochar', 'https://www.walkhighlands.co.uk/lochlomond/glen-loin.shtml', 17.5, 455, 5.5, 'This straightforward but long circuit runs through the glens and corries to the north of Arrochar. It offers fine views throughout of the peaks of the Arrochar Alps.', 56.206, -4.7448),
('665cca03-f1c5-50b7-a1f2-dbe71990903e', 'Rogie and Contin forests circuit, near Contin', 'https://www.walkhighlands.co.uk/lochness/Rogiecontin.shtml', 5.75, 160, 2.0, 'This enjoyable walk begins by visiting the popular but dramatic cascade of Rogie Falls. It then escapes the crowds by heading up into the attractive area of forestry beyond, with a loop linking up with Contin forestry car park and an attractive stretch of riverbank.', 57.5902, -4.6074),
('6663a47c-0ea6-5b4c-bc63-4d84e9f920ff', 'Coire Àrdair, Creag Meagaidh', 'https://www.walkhighlands.co.uk/fortwilliam/coire-ardair.shtml', 12.0, 430, 4.5, 'Climb up to the lochan in Coire Àrdair to view the magnificent cliffs of Creag Meagaidh. The first part of this moderate walk, which follows a very good path, passes through the regenerating woodland of the National Nature Reserve.', 56.952, -4.4959),
('669ca71d-ae30-5984-8c3d-b76e3cf47ef7', 'Whitefarland Bay, Feolin Ferry', 'https://www.walkhighlands.co.uk/islay-jura/whitefarland-bay.shtml', 3.5, 18, 1.0, 'This short walk explores the coastline immediately north of Feolin Ferry - enabling it to be done as a foot passenger using the ferry from Islay. The outward route follows a modern track but the return uses the rougher but more interesting old route immediately by the shoreline - it may be covered at high tides.', 55.8483, -6.0902),
('66af0f23-50df-5679-971d-8af85a148212', 'Hill of Tarvit and Scotstarvit from Ceres', 'https://www.walkhighlands.co.uk/fife-stirling/hill-of-tarvit.shtml', 10.25, 232, 4.0, 'This walk heads west from the attractive historic village of Ceres, visiting a National Trust mansion house, a fine viewpoint and a medieval tower.', 56.2918, -2.9708),
('66b030dc-5d6f-574f-97cc-4eec11ad145a', 'St Ninian''s Cave from Kisdale, near Whithorn', 'https://www.walkhighlands.co.uk/galloway/st-ninians-cave.shtml', 3.25, 57, 1.0, 'Take a short hike down to the coastline to visit St Ninian''s Cave - a place of retreat and prayer for Scotland''s first saint, who set up his church in Whithorn in 397 AD.', 54.7004, -4.4358),
('66c8328d-eaae-50f2-9552-a888c02b4fba', 'Hutcheson''s Monument circuit, Isle of Kerrera', 'https://www.walkhighlands.co.uk/argyll/kerrera-hutcheson.shtml', 9.0, 190, 4.0, 'Visitors to Oban can''t help but notice the massive obelisk monument at the north end of the isle of Kerrera, guarding the entrance to the harbour. This walk is a circuit of the northern half of Kerrera and includes a visit to the monument with its fine views.', 56.4003, -5.51839),
('66e9f081-cb32-5b3c-9a0d-7b20fa2d3117', 'Sidlaws: Craigowl and Auchterhouse hill', 'https://www.walkhighlands.co.uk/angus/sidlaw-hills.shtml', 7.5, 333, 3.0, 'The Sidlaws have long been a favourite stomping ground for Dundonians, with the masts on the summit of Craigowl being a prominent landmark for miles around. This hillwalk takes in the three main summits for superb views towards the city and Tay as well as across Strathmore to the Angus Glens.', 56.5343, -3.03419),
('67306eb5-0e52-544b-bfac-6b0a6e4039d1', 'The Forth Bridges, Queensferry', 'https://www.walkhighlands.co.uk/lothian/forth-bridges.shtml', 5.5, 80, 1.5, 'The spectacular original Forth Bridge has long been an icon of Scotland, carrying the mainline railway across the Firth of Forth. It was joined by the road bridge in 1964 - now only used by buses, taxis, cyclists and walkers - and then the striking Queensferry Crossing completed in 2017. This walk - which crosses the footway on the road bridge - offers great views of the Forth as well as the bridges. The route is linear but starts and finishes at the rail stations on either side of the Firth; there are regular services so you can return to the start by taking a train over the Rail Bridge. Note that the bridge is closed to walkers at times of high wind.', 55.9864, -3.38214),
('67f554ac-8313-5478-9f59-2002270b6a0d', 'Kiltearn Church circuit, Evanton', 'https://www.walkhighlands.co.uk/ullapool/kiltearnchurch.shtml', 5.75, 48, 1.5, 'This easy circuit from Evanton visits the ruins of Kiltearn Church and the shores of the Cromarty Firth - including an old salmon fishing bothy.', 57.6632, -4.3365),
('68852feb-9b4c-5f2b-8cee-6f2f1642ef85', 'Crathes Castle and the River Dee from Banchory', 'https://www.walkhighlands.co.uk/aberdeenshire/banchory-crathes.shtml', 8.25, 57, 2.5, 'This linear walk follows the course of the mighty - and beautiful - River Dee for much of its length between Banchory and the Milton of Crathes craft village. Crathes Castle can then be easily visited by a detour, before catching a bus back from Milton to Banchory.', 57.0502, -2.5008),
('68b7386d-7ae1-5587-a015-5b119834e865', 'Ord Hill, near North Kessock', 'https://www.walkhighlands.co.uk/lochness/ord-hill.shtml', 4.5, 195, 1.0, 'Ord Hill is a forested ridge on the Black Isle, just across the Kessock Bridge and overlooking Inverness. There are two waymarked routes from a car park on the northwest side of the hill. This route makes use of some of these paths but begins from the larger car park on the north side of the A9.', 57.5032, -4.2476),
('691f1a76-09ac-5ac5-80af-5066f1f447f8', 'Creagan na Beinne, Ardtalnaig', 'https://www.walkhighlands.co.uk/perthshire/creagan-na-beinne.shtml', 18.0, 775, 6.0, 'Creagan na Beinne is a very rounded hill, a Corbett above the southern side of Loch Tay. Its traverse makes for a moderate day''s hillwalking - boggy in places - with a return along a stretch of the Rob Roy Way.', 56.5276, -4.1119),
('69244289-cecc-57c7-ae51-28da057dcdb5', 'Gylen Castle circuit, Isle of Kerrera', 'https://www.walkhighlands.co.uk/argyll/kerrera-gylen.shtml', 11.0, 275, 4.5, 'This superb circuit explores the southern half of the beautiful Isle of Kerrera. Easily reached by a short ferry ride from just south of Oban, the walk has fine views out to other islands and visits the well-preserved and wonderfully atmospheric remains of Gylen Castle.', 56.4003, -5.51804),
('69478291-f708-5159-b115-3f151e53e33d', 'Tolmount and Tom Buidhe via Loch Callater', 'https://www.walkhighlands.co.uk/cairngorms/tolmount.shtml', 26.5, 841, 10.0, 'Tolmount and Tom Buidhe are two of the least distinguished Munros, Tom Buidhe in particular being a rounded hummock in the centre of a vast rolling plateau. The approach via Loch Callater is long but probably the most scenic approach, with Tolmount from this direction at least having a conical shape and some craggy corrie scenery.', 56.9774, -3.39),
('6957d839-6be0-5c7b-b0e1-34f7ba743b8c', 'Loch Shiel viewpoints walk, Polloch', 'https://www.walkhighlands.co.uk/fortwilliam/loch-shiel.shtml', 4.5, 102, 1.5, 'Enjoy truly stunning views over Loch Shiel on this straightforward circular walk with a remote feel.', 56.7585, -5.6135),
('697e74d2-b5e2-5c13-b40d-b43c813a8720', 'Leitir Easaidh all-abilities path, Little Assynt', 'https://www.walkhighlands.co.uk/ullapool/leitir-easaidh.shtml', 2.5, 25, 0.75, 'There are few walks in the northwest set-up for wheelchairs (and those who don''t want to get wet boots!) so Leitir Easaidh is all the more welcome. This trail visits two lochs with picturesque shelters and toilets, and has stunning views across this wild landscape to the surrounding mountains.', 58.1863, -5.11),
('6984c851-92de-53a9-b1fd-7ae80ddd2c53', 'Shiaba and Scoor, near Bunessan', 'https://www.walkhighlands.co.uk/mull/shiaba.shtml', 6.25, 129, 2.0, 'Over 350 people lived at Shiaba at the end of the eighteenth century. Now, like many other cleared villages on Mull and across the Highlands, there are only sheep wandering around the ghostly ruins of this haunting spot.', 56.2971, -6.1819),
('6a199174-fff5-5c6b-baa3-25855dd56c3c', 'Norham Bridge and Milne Graden, Norham', 'https://www.walkhighlands.co.uk/borders/norham-bridge.shtml', 10.5, 112, 3.0, 'A beautiful stretch of the River Tweed - marking the boundary between Scotland and England - begins this walk, heading upstream from Norham Bridge through into the Milne Graden Estate. The return follows country roads.', 55.7188, -2.17746),
('6a8fbf9b-fed0-57e1-ab7d-95e0febb54e2', 'Banvie burn and bridges, Blair Atholl', 'https://www.walkhighlands.co.uk/perthshire/banvie-burn.shtml', 6.5, 178, 2.0, 'This straightforward explores part of the Atholl Estate above the castle, including a loop through a beautifully-wooded gorge and a visit to a folly.', 56.7744, -3.84331),
('6aa431fa-0a6d-510f-a0c6-0981f624eb30', 'Eildon Hills, from Melrose', 'https://www.walkhighlands.co.uk/borders/eildon-hills.shtml', 9.5, 525, 4.0, 'The three shapely summits of the Eildon Hills are a celebrated landmark. They make for a classic half-day, yet steep, hillwalk from the attractive town of Melrose.', 55.5975, -2.7173),
('6ab6c78d-48b9-5462-9be7-ccc101c29c45', 'Corrieyairack Pass: Laggan to Fort Augustus', 'https://www.walkhighlands.co.uk/cairngorms/corrieyairack-pass.shtml', 39.5, 732, 12.0, 'The Corrieyairack Pass, originally built as a military road by General Wade, leads across the Monadhliath mountains from Laggan in Badenoch to Fort Augustus on Loch Ness. This linear walk climbs to a height of over 770m through remote terrain, and has also become popular with mountain bikers. The route is shared with the Beauly - Denny power line which detracts from the otherwise very wild and remote feel of the pass. The length can be shortened by 17km by driving the first section almost to Melgarve. The pass now forms part of the Scottish National Trail.', 57.0196, -4.2832),
('6ad0df51-39f0-59df-a3b9-cbd175e80e8c', 'No Ness and the Broch of Burraland, Sandwick', 'https://www.walkhighlands.co.uk/shetland/no-ness.shtml', 8.25, 180, 3.5, 'This superb coastal walk heads around the delightful No Ness peninsula from Sandwick. There is some fine coastal cliff scenery around the peninsula - particularly on the east side - before the route reaches the secluded remains of a broch looking across the Sound to its more famous counterpart on Mousa.', 59.9958, -1.2234),
('6b364644-02e1-57c6-a778-04d5cc0614d1', 'Rosal and the Strathnaver Clearances', 'https://www.walkhighlands.co.uk/sutherland/rosal-strathnaver.shtml', 4.0, 82, 1.5, 'Strathnaver is notorious as the scene of the some of the most brutal Highland Clearances. This walk visits the sad remains of Rosal which was once one of many thriving villages in the Strath. Interpretative boards help visitors to imagine life as it would once have been here, a task made easier by one Donald Macleod, a native of the village who wrote about his life here.', 58.3532, -4.2395),
('6b529fce-f92a-52eb-9d46-0ec3c43c7981', 'Ardwell Bay and Doon broch', 'https://www.walkhighlands.co.uk/galloway/ardwell-bay.shtml', 3.0, 42, 1.0, 'Ardwell Bay has a fine sandy beach, looking across to Northern Ireland on the western side of the Rhins. This short circular also visits the remains of an iron-age broch.', 54.7621, -4.9992),
('6b7767fe-ebf5-5e5c-a65b-20892f6b9f0f', 'Puck''s Glen', 'https://www.walkhighlands.co.uk/argyll/pucks-glen.shtml', 2.5, 126, 1.5, 'Deservedly the most popular short walk in the region, Puck''s Glen is a dark and atmospheric defile. A tumbling burn, criss-crossed by bridges, is enclosed by rocky walls heavily hung with mosses and overshadowed by dense trees.', 56.0122, -4.9743),
('6b9c11af-9bfe-556c-bc06-770e82d53294', 'Lowlandman''s Bay, Ardfernal', 'https://www.walkhighlands.co.uk/islay-jura/lowlandmans-bay.shtml', 9.25, 115, 4.0, 'This straightforward walk follows a long track round above Lowlandman''s Bay, frequented by seals, to reach a jetty on the Rubha an Leim peninsula - a beautiful spot. The return is back the same way, or by a much rougher route along the shore initially (the walk grade and bog factor assumes the track is walked in both directions).', 55.877, -5.9109),
('6b9d3255-4026-5463-8af2-2c8002b17596', 'Duncraig Castle from Plockton', 'https://www.walkhighlands.co.uk/kintail/Duncraig.shtml', 6.0, 180, 3.0, 'This truly stunning short circular walk from Plockton leads through fine coastal woodland with picturesque views across Loch Carron, visiting Duncraig Castle.', 57.3381, -5.65118),
('6bcfdd99-dedc-5099-b696-43ac351aa2cb', 'Largo Law, from Upper Largo', 'https://www.walkhighlands.co.uk/fife-stirling/largo-law.shtml', 3.25, 215, 1.5, 'Largo Law - the eroded plug of an ancient volcano - rises sharply above the farmland and fields of eastern Fife. It is a superb viewpoint, though the ascent is very steep. A sign advises that dogs are not permitted on the hill by the farmer between March to November (due to the presence of cattle), and should be kept on a lead / under close control due to sheep at other times.', 56.2226, -2.93216),
('6bd843e6-2461-54a3-9da6-eb26466465a7', 'Torridon village walk, Torridon', 'https://www.walkhighlands.co.uk/torridon/torridon-village.shtml', 6.1, 32, 2.0, 'This route combines two walks from the edge of Torridon village. The first heads past a deer farm to reach a hide and a beautiful stretch close by the shore of Loch Torridon, visiting the site of an open air church. It then joins the road at Fasag (shop/cafe) from where the second walk takes a path keeping above the road and loch to visit the site of a ruined township. The return is back along the minor road through the village.', 57.543, -5.5017),
('6bd8a730-782e-5c61-b50a-66ffee616249', 'West Lomond from Craigmead', 'https://www.walkhighlands.co.uk/fife-stirling/west-lomond.shtml', 8.0, 271, 3.5, 'A classic short hillwalk over West Lomond and descending with good views of Ballo Reservoir. Can be combined with an ascent of East Lomond to make a longer route.', 56.2418, -3.2477),
('6be27339-650a-5d74-bbf9-c40ea41b8c74', 'Saligo Bay beach and arches, Rhinns of Islay', 'https://www.walkhighlands.co.uk/islay-jura/saligo-bay.shtml', 5.25, 22, 2.5, 'Explore the dunes and perfect sand of Saligo Bay before venturing along the coast to a natural arch and impressive cliff formations.', 55.8101, -6.4523),
('6bf7a130-739b-540b-9763-4fd7cc5067a7', 'Lime Craig circuit, near Aberfoyle', 'https://www.walkhighlands.co.uk/lochlomond/highland-boundary-fault.shtml', 6.0, 310, 2.5, 'This fine waymarked route climbs up through the forest to Lime Craig - a fine viewpoint on the Highland Boundary fault. The route begins at The Lodge Forest Visitor Centre, an information and cafe run by the Forestry Commission. It takes in a wildlife hide, fine oakwoods, commercial forestry, high waterfalls and good views.', 56.1826, -4.3861),
('6c0de9ae-3471-58a8-8036-3a6e0de8e210', 'Eday Heritage Walk, Eday', 'https://www.walkhighlands.co.uk/orkney/eday-heritage-walk.shtml', 10.0, 130, 3.5, 'This figure of eight loop takes in many of the highlights of Eday including a standing stone, chambered cairns, open moorland, cliffs, a bird hide and farmland.', 59.2138, -2.7565),
('6c3e69b3-9d04-5bdd-a3bd-bd30e0cc4553', 'Dufftown, Craigellachie and Aberlour circuit', 'https://www.walkhighlands.co.uk/moray/dufftown-aberlour.shtml', 20.0, 315, 6.0, 'Follow an off-shoot of the Speyside Way along an old railway from Dufftown to Craigellachie, to turn south along the Spey to Aberlour, before climbing over moor, forest and farmland.', 57.4449, -3.1285),
('6c5988ac-393d-5d25-b9cf-c62c9769d152', 'Clauchland Hills and Corriegills, Brodick', 'https://www.walkhighlands.co.uk/arran/clauchlands.shtml', 10.75, 308, 4.0, 'This superb circuit heads along crest of the low hill ridge south of Brodick, giving panoramic views over the bays of both Brodick and Lamlash.', 55.5764, -5.1385),
('6c7ed987-0dee-5b61-acf3-6d65ae83772a', 'MacKinnon''s Cave, near Gribun', 'https://www.walkhighlands.co.uk/mull/mackinnons-cave.shtml', 3.5, 130, 2.0, 'MacKinnon''s Cave is reckoned to be the longest sea cave in all the Hebrides. This short but challenging walk visits the cave, once regarded as one of the showplaces of Mull and visited by Johnson and Boswell. The coastal setting is superb but the walk crosses awkward slippery boulders and is only accessible below half tide. A torch is essential to explore the cave.', 56.4235, -6.1388),
('6c9609d9-a80e-5ad1-9e61-98cb7699839f', 'Glen Duror forest', 'https://www.walkhighlands.co.uk/argyll/duror.shtml', 5.25, 160, 2.0, 'This out and back walk leads through the Glen Duror forest plantations to visit Taigh Seamus a'' Ghlinne - an bothy said to be the birthplace of James of the Glen. James was hung after he was alledgedly framed in the legendary Appin murder -  as described in Robert Louis Stevenson''s classic novel, Kidnapped.', 56.6457, -5.25645),
('6d2121b8-ffc4-51eb-8250-1cde01d5ba73', 'Dùn Coillich, near Aberfeldy', 'https://www.walkhighlands.co.uk/perthshire/dun-coillich.shtml', 7.0, 414, 3.5, 'A stunning and rugged area being managed by volunteers from the Highland Perthshire Community Land Trust for the restoration of its native woodland, Dùn Coillich is a wonderful place for a half day walk. The route described here climbs to the summit of the hill before returning through beautiful and varied woods.', 56.6517, -4.0096),
('6d400d16-181f-5047-9550-70d5d482fa42', 'Signal Rock and An Torr, Glencoe', 'https://www.walkhighlands.co.uk/fortwilliam/signalrock.shtml', 2.5, 91, 1.5, 'One of the few short walks in Glencoe, this ramble explores the woodland in the central part of the Glen, and visits Signal Rock, where according to legend the signal was given to begin the Glencoe Massacre.', 56.6619, -5.05696),
('6d40766f-e280-5dcb-814c-18660e70b6ad', 'Barony Hill, Dailly', 'https://www.walkhighlands.co.uk/glasgow/barony-hill.shtml', 11.0, 309, 3.0, 'This enjoyable circuit is deep in the rural countryside of South Ayrshire. There are extensive views from the summit of Barony Hill. Parts of the descent can be boggy unless the weather has been dry, and some sections are very overgrown in summer.', 55.2782, -4.7247),
('6d71c7a7-6d62-51d6-a4e4-4aba7944b51b', 'Portskerra pier and jetty', 'https://www.walkhighlands.co.uk/sutherland/portskerra.shtml', 2.0, 56, 0.75, 'This short loop links the pier and the jetty at the old fishing and crofting village of Portskerra by means of a coastal path, returning via minor roads. The walk visits the Drownings Memorial which commemorates those who died in three separate tragedies here.', 58.5657, -3.9241),
('6d859efd-1f29-5bf4-a8e8-b263314ea2f8', 'Diabaig to Inveralligin', 'https://www.walkhighlands.co.uk/torridon/Inveralligin.shtml', 8.0, 350, 3.5, 'A challenging coastal walk between two picturesque settlements, passing through spectacularly rugged and rocky scenery.', 57.5756, -5.68507),
('6d97ecde-3872-5af6-ab39-243acb6b4d35', 'River Dee and Cambus o'' May circuit, Ballater', 'https://www.walkhighlands.co.uk/cairngorms/cambus-o-may.shtml', 12.75, 120, 4.0, 'This enjoyable waymarked circuit heads down Deeside to explore the strath to the east of Ballater. The highlight of the walk is the beautiful suspension footbridge at Camus o''May.', 57.0499, -3.0411),
('6de0e78a-80cc-5360-b7b0-31c4580d8736', 'Windy Hill, Muirshiel Country Park', 'https://www.walkhighlands.co.uk/glasgow/windy-hill.shtml', 2.0, 95, 0.75, 'This short and easy ascent to a hilltop in the Muirshiel Country Park rewards with excellent views.', 55.8324, -4.6972),
('6de537c3-f7c5-50e7-9f63-02032f526f00', 'Mither Tap from the Bennachie Centre', 'https://www.walkhighlands.co.uk/aberdeenshire/mither-tap.shtml', 6.0, 398, 3.0, 'Climb to the finest peak on Bennachie, the impressive Mither Tap, with its rocky granite summit surrounded by the remains of a historic hill fort. Return across moorland and through mixed woodland, leaving time to visit the Bennachie Visitor Centre where this route starts.', 57.2845, -2.5013),
('6eac3f89-aaee-5f19-8371-0fbc236ecab2', 'Deer Hill (Cnoc nan Gabhar), Carradale', 'https://www.walkhighlands.co.uk/argyll/deer-hill.shtml', 5.75, 229, 2.0, 'This waymarked forestry walk climbs to the summit of Cnoc nan Gabhar to the north of Carradale. The reward is a stunning panorama taking in much of the east coast of Kintyre as well as the Arran mountains and Ailsa Craig.', 55.589, -5.4748),
('6ed28dcb-d5eb-5ed6-bb9d-4260fe70c6c7', 'Cove Harbour circuit, Cove', 'https://www.walkhighlands.co.uk/borders/cove-harbour.shtml', 4.5, 84, 2.0, 'Explore the fascinating natural harbour, beach and tunnel at Cove Harbour and then head along the clifftops before returning on a minor road.', 55.9382, -2.3535),
('6ef25524-8e05-5665-8dc5-2b032bbb9afb', 'River Spey & old railway, by Grantown-on-Spey', 'https://www.walkhighlands.co.uk/cairngorms/river-spey-grantown.shtml', 3.0, 23, 0.75, 'This short walk follows the Speyside Way along the old railway line near Grantown on Spey before returning on a rougher path right beside the Spey. Views of woodland, farmland, distant hills and the beautiful River Spey.', 57.3162, -3.6028),
('6f11206e-8937-5326-9a2f-2296e062c9d9', 'Brothers Ridge - Sgùrr a Bhealaich Dheirg', 'https://www.walkhighlands.co.uk/kintail/Brothersridge.shtml', 10.0, 1274, 8.0, 'The eastern neighbours of the Five Sisters are the three Munros Sgùrr a Bhealaich Dheirg, Sàileag and Aonach Meadhoin, often collectively known as the Brothers of Kintail. They give a very fine ridgewalk themselves, and are in no way overshadowed by their more famous siblings.', 57.1696, -5.2945),
('6f13872d-d49f-5ba7-8b6d-e9be08dfa905', 'Urgha and Maraig circuit', 'https://www.walkhighlands.co.uk/outer-hebrides/urgha-maraig.shtml', 19.0, 761, 6.0, 'This circular walk takes in the superbly engineered old footpath from Urgha to Rhenigidale, with stunning coastal views, before following a quiet minor road to the east of Todun. The return is then along the old path over Braigh an Ruisg and past Lochanan Lascadail.', 57.9043, -6.7551),
('6f532bd1-86b3-5074-8b50-ac4ae77bc190', 'Garbh Bheinn and Belig', 'https://www.walkhighlands.co.uk/skye/garbhbheinn.shtml', 10.0, 1070, 7.0, 'Garbh Bheinn is a magnificent peak, one of the Cuillin outliers, and its traverse involves only a little moderate scrambling. Belig too is a fine summit, and completes an enjoyable horse-shoe route.', 57.2644, -6.0915),
('6f55745b-8506-5cb3-b839-d901d752aa4d', 'An Sgarsoch and Càrn an Fhidhleir', 'https://www.walkhighlands.co.uk/cairngorms/an-sgarsoch.shtml', 42.0, 1059, 12.0, 'These two rounded, featureless hills are given distinction by their remoteness. In the heart of the wild country between the main Cairngorms and the Atholl ranges, few Munros can match these peaks for the feeling of solitude or open space. The day could be shortened by the use of a mountain bike on the approach.', 56.9894, -3.5435),
('6f656a8d-1121-520b-90d4-22154a5a2399', 'Strontian Lead Mines via Ariundle Oakwoods', 'https://www.walkhighlands.co.uk/fortwilliam/strontian-mines.shtml', 10.5, 438, 4.0, 'A fantastic walk taking in the beautiful oakwoods of Ariundle, the rugged open moorland with fine views of the surrounding mountains, and the lead mines which once employed 600 miners on these moors.', 56.7108, -5.55379),
('6f80fd8d-92a5-5b78-b8c7-1b50321f6853', 'Clatteringshaws Loch and Benniguinea', 'https://www.walkhighlands.co.uk/galloway/clatteringshaws.shtml', 8.0, 211, 2.0, 'This short walk heads along the shores of Clatteringshaws Loch - an extensive reservoir to visit the Bruce''s Stone before climbing through forestry to a viewpoint high above the loch with views to Merrick and the surrounding hills.', 55.0598, -4.2702),
('6fa2bb78-4228-5470-8fd9-ef66dfd10872', 'Dunardry, near Cairnbaan', 'https://www.walkhighlands.co.uk/argyll/dunardry.shtml', 4.5, 195, 2.0, 'This short, waymarked forestry walk climbs from a car park overlooking the Crinan Canal to reach a superb panoramic viewpoint above the trees.', 56.061, -5.4971),
('6fba8c1d-bd34-5180-9c47-46bdb2b0e57c', 'Loch Venachar forestry walk', 'https://www.walkhighlands.co.uk/lochlomond/loch-venachar.shtml', 7.0, 210, 2.0, 'A circular walk following a forestry track climbing to a hidden lochan to the south of Loch Venachar. The return is made along the shores of the loch with fine views.', 56.222, -4.2715),
('7005707d-28ec-5423-afe9-85c7a96ff6dd', 'The Grey Corries', 'https://www.walkhighlands.co.uk/fortwilliam/greycorries.shtml', 21.5, 1544, 10.0, 'The Grey Corries is the long chain of mountains set to the east of the Nevis Range. Well seen from the popular viewpoint of the Commando Memorial near Spean Bridge, their summits are covered with the quartzite scree that gives these mountains their name.  The traverse of the Grey Corries main ridge gives a long and demanding but superb mountain walk. The route as described takes in the main three Munros, leaving a fourth for a separate walk.', 56.8727, -4.8682),
('7016a7e6-e39d-5730-97e7-69f152deb330', 'Càrn Chuinneag, Strath Carron, Ardgay', 'https://www.walkhighlands.co.uk/sutherland/carn-chuinneag.shtml', 18.5, 769, 6.5, 'This twin-summited Corbett is a good viewpoint, rising above a little visited but very attractive corner of the Highlands. The approach leads through some fine woodland and much of the ascent uses superb stalkers'' paths.', 57.8653, -4.5905),
('701f7213-5f3e-58f6-8ad3-ee0c76180590', 'Ledmore and Migdale Forest, near Spinningdale', 'https://www.walkhighlands.co.uk/sutherland/spinningdale.shtml', 8.75, 252, 3.5, 'This excellent circuit takes in the native woodland of Ledmore and Migdale forest, visiting the shores of Loch Migdale and climbing to two fine moorland viewpoints high above the Dornoch Firth.', 57.8861, -4.2477),
('704206c4-d928-57cb-a30d-260ea339fb2a', 'Tràigh an Iar, Malacleit', 'https://www.walkhighlands.co.uk/outer-hebrides/traigh-an-iar.shtml', 9.5, 4, 2.0, 'Tràigh an Iar - a 4km long crescent of perfect sand - is one of the finest beaches on North Uist. This simple walk heads along the beach of Tràigh Vallaigh first to reach it. You can make this walk as long or as short as you wish.', 57.6508, -7.3691),
('7083edb7-922f-5ad7-be44-d54d0ae4d4ab', 'Darn Walk: Bridge of Allan to Dunblane', 'https://www.walkhighlands.co.uk/fife-stirling/darn-walk.shtml', 4.25, 83, 1.5, 'This beautiful linear walk links Bridge of Allan to Dunblane, close by the river for much of the route, following the line of an ancient path known as the Darn Road which is reputed to date back to Roman times. The return can be made by bus or train.', 56.1559, -3.951),
('7097949c-5726-51e8-8231-172af763d762', 'Houss Ness, East Burra', 'https://www.walkhighlands.co.uk/shetland/houss-ness.shtml', 6.25, 145, 3.0, 'A straightforward walk around a headland with a natural arch and sea stacks taking in the high point of the Ward of Symbister.', 60.0633, -1.3247),
('70a49fbb-1c23-5900-873b-93f5b1b34cf4', 'Rothesay and Canada Hill', 'https://www.walkhighlands.co.uk/argyll/rothesay.shtml', 5.25, 135, 2.0, 'This short walk explores the fine Victorian resort town of Rothesay and includes a climb up to Canada Hill viewpoint.', 55.8382, -5.0557),
('70dd894f-e1d4-5342-b247-d36035234ee5', 'The Haining lochside circuit, Selkirk', 'https://www.walkhighlands.co.uk/borders/the-haining.shtml', 2.75, 52, 1.0, 'A lovely short walk around the loch and grounds of The Haining House, an attractive Palladian mansion on the outskirks of the interesting small town.', 55.5463, -2.8422),
('70ede8ce-342f-5cc2-8fdc-8bb57a23eafc', 'Uath Lochans and Farleitter Crag', 'https://www.walkhighlands.co.uk/cairngorms/uath-lochans.shtml', 5.25, 186, 2.0, 'This group of four small lochs set amidst the wild scenery and pines of Glen Feshie is a real hidden gem. This route heads around the lochans before climbing along the wooded rim of Farleitter Crag for sublime views. The pines are often busy with red squirrels.', 57.0965, -3.9243),
('710db53a-6ffa-5717-b685-3f131daa7b70', 'Rois-Bheinn round, Inverailort', 'https://www.walkhighlands.co.uk/fortwilliam/rois-bheinn.shtml', 19.0, 1649, 10.0, 'A true West Highland classic, this round of three great Corbetts offers some of the most outstanding views along the western seaboard. A rugged and challenging day that will live long in the memory.', 56.8733, -5.6689),
('711398e6-77f1-541f-b9b4-a8f0bd62b46b', 'Mid Howe Broch and Cairn, Rousay', 'https://www.walkhighlands.co.uk/orkney/mid-howe-broch-cairn.shtml', 5.25, 103, 3.0, 'A circular walk packed with archaeological gems. Explore both the hugely impressive Midhowe stalled Cairn and Midhowe Broch before passing the remains of a 13th century ceremonial hall, 16th century church and ongoing dig site where neolithic and viking buildings are being uncovered.', 59.1593, -3.0929),
('715f3b12-4408-5fe7-b84a-9f958da01552', 'Brimmond Hill, near Westhill', 'https://www.walkhighlands.co.uk/aberdeenshire/brimmond-hill.shtml', 3.5, 133, 1.5, 'This straightforward walk heads directly from a parking area up a good path to the summit of Brimmond Hill, before returning on a path round the sounthern slopes. Whilst Brimmond is bedecked with various masts and other paraphernalia, the cairned summit is just beyond and commands an excellent view over Aberdeen and the North Sea.', 57.1685, -2.2572),
('719c68f6-7e68-5e33-b46f-6ff15b7bdde2', 'Kilchattan Bay circular', 'https://www.walkhighlands.co.uk/argyll/kilchatten-bay.shtml', 8.0, 220, 3.5, 'This classic circuit is the finest walk on Bute; it also forms the first stage of the West Island Way. The walk features some beautiful coastal scenery, an atmospheric ruined chapel and many superb views.', 55.7471, -5.0159),
('71e83536-e36e-570b-8ec0-dd89abba3180', 'The Complete Fair Isle explorer', 'https://www.walkhighlands.co.uk/shetland/complete-fair-isle.shtml', 15.75, 607, 7.0, 'Fair Isle is a difficult place to get to - but well rewards those who make the effort. This magnificent walk takes in most of the island''s superb coastal scenery. It begins from the airstrip with the ascent of Ward Hill before following the dramatic and wild western coastline down to Malcolm''s Head. It then traverses the southern coast before heading up the east side, passing the remarkable Sheep Rock before reaching the bird observatory (currently closed as destroyed by fire in 2019 - new building sheduled to reopen autumn 2023) and North Haven - where the ferry boat calls - before returning to the airstrip.', 59.5339, -1.6287),
('72029817-962e-53cc-875a-03dcb33a6c9a', 'Ellon Circular Walk, Ellon', 'https://www.walkhighlands.co.uk/aberdeenshire/ellon.shtml', 4.0, 44, 1.5, 'An exploration of the main historical and wildlife features of Ellon.', 57.3641, -2.0721),
('72504927-e9f2-5ecf-9f27-4ed375dc5466', 'The Callanish Stones', 'https://www.walkhighlands.co.uk/outer-hebrides/callanish-stones.shtml', 3.75, 48, 1.0, 'The Standing Stones of Callanish are one of the most important prehistoric sites in the UK, with the 5,000 year old central circle and avenues of impressive upstanding gneiss being the most iconic image of the Isle of Lewis. This walk combines the main site with two further stone circles nearby.', 58.1957, -6.7429),
('7275e1a1-cb37-5cef-8bff-88b7a525741b', 'Camperdown, Templeton & Clatto, Dundee', 'https://www.walkhighlands.co.uk/angus/camperdown.shtml', 9.5, 104, 3.5, 'Camperdown is a huge country park on the edge of Dundee. Combined with neighbouring Templeton Woods and Clatto Country Park it makes for an enjoyable walk within easy reach of the city.', 56.4839, -3.04086),
('727de369-083e-5d4d-b1a0-2d987cf505db', 'Meall Glas and Sgiath Chuil from Glen Dochart', 'https://www.walkhighlands.co.uk/lochlomond/meall-glas.shtml', 15.5, 1182, 9.0, 'Meall Glas and Sgiath Chuil attract little attention from Glen Dochart, being set well back from the road across moorland. This circular walk visits both; although there is a fair amount of boggy ground the two hills are good viewpoints.', 56.4148, -4.5172),
('72aec620-792a-5800-b2b7-62e9a9a1133e', 'Inverarnie Esker Trail, Littlemill near Daviot', 'https://www.walkhighlands.co.uk/lochness/littlemill.shtml', 4.75, 51, 1.5, 'Walk along ridges and look at pools left behind by glaciers which moved across this landscape thousands of years ago. This is a good short walk to brush up on your geography and enjoy the wildlife of the pines and pools at Littlemill.', 57.401, -4.1639),
('73034b30-4cd3-5505-9500-f7391e3ecd9c', 'Loudoun Hill, near Darvel', 'https://www.walkhighlands.co.uk/glasgow/loudon-hill.shtml', 2.5, 161, 1.0, 'Pass the Spirit of Scotland sculpture commemorating historic victories that both Bruce and Wallace fought here, before tackling the short but steep ascent of Loudoun Hill, an iconic landmark and spectacular viewpoint.', 55.6142, -4.20385),
('73292e04-857c-537c-8daf-701c784618d9', 'Cleanhill Wood, Aberchirder', 'https://www.walkhighlands.co.uk/aberdeenshire/aberchirder.shtml', 1.6, 30, 0.75, 'This short woodland stroll from the planned village of Aberchirder (also known as Foggieloan or just Foggie) rises gently to reach a fine viewpoint over the strath of the River Deveron. Locals simply call it ''The Hill''.', 57.5595, -2.6333),
('736756c7-4953-56bc-95ee-3835c6d76b40', 'River Esk and Rowanburn Circuit, Canonbie', 'https://www.walkhighlands.co.uk/galloway/canonbie.shtml', 13.5, 98, 4.0, 'A great, varied circuit from the village of Canonbie taking in sections of the River Esk and Liddel Water, woodland and farmland.', 55.0792, -2.95126),
('7395e846-6b82-5262-b9b9-aff13af8e1ac', 'River Spey and woodland walk, Boat of Garten', 'https://www.walkhighlands.co.uk/cairngorms/boat-of-garten.shtml', 9.75, 94, 3.0, 'This very pleasant circuit from Boat of Garten follows the River Spey and then heading inland through delightful woodland bursting with widlife. These special woods are home to the rare capercaillie, and dogs should be kept on a short lead during the very sensitive breeding season between 1 April and 15 August.', 57.2491, -3.7516),
('73df0e6e-bd63-524a-bdc8-54764585c18a', 'Corryhabbie Hill, Glen Rinnes', 'https://www.walkhighlands.co.uk/moray/corryhabbie-hill.shtml', 12.75, 525, 5.0, 'A straightforward moorland circuit that traverses the summit of Corryhabbie Hill, giving with extensive views over Glenlivet, Ben Rinnes and towards the Cairngorms.', 57.3775, -3.2164),
('740a4bde-0eb0-58ef-839b-14644ede2212', 'Balloch Wood, Creetown', 'https://www.walkhighlands.co.uk/galloway/creetown-balloch-wood.shtml', 5.0, 122, 1.0, 'This short walk from Creetown climbs up through the community-owned Balloch Wood - home to red squirrels and roe deer - to reach the former curling pond, a local beauty spot. The return is on quiet minor roads.', 54.9017, -4.3792),
('741e992f-110a-54de-86f6-77f73e77f5cd', 'Machrihanish and the Gauldrons', 'https://www.walkhighlands.co.uk/argyll/machrihanish.shtml', 4.5, 35, 1.5, 'This short walk explores the coastline to the west of the stunningly situated village of Machrihanish. There are good sandy beaches, superb views across to Rathlinn island and Ireland, and great bird-watching opportunities.', 55.4236, -5.7345),
('744f4766-a7ce-58dc-8091-c8bf701a1a3d', 'Càrn a'' Choire Ghairbh and Aonach Shasuinn, Affric', 'https://www.walkhighlands.co.uk/lochness/affric-corbetts.shtml', 24.5, 1228, 10.0, 'The round of these two Corbetts makes for a demanding day from beautiful Glen Affric. They offer some splendid views of the higher mountains around them, as well as down the glen.', 57.2649, -4.9853),
('74507fb9-002d-58b7-98d7-86df8fd87d7f', 'Castle Campbell and Dollar Glen', 'https://www.walkhighlands.co.uk/fife-stirling/dollar-glen.shtml', 4.0, 184, 2.0, 'This classic shorter walk explores of the gorges of the Dollar Glen and has been popular with visitors and locals alike since Victorian times. There are many footbridges, viewpoints, waterfalls and the impressive Castle Campbell. It''s a good walk to interest children although steep; care should be taken in many places.', 56.1634, -3.67156),
('7456b7a8-d108-5f12-bc2e-36660c8ead76', 'Kilmun Arboretum', 'https://www.walkhighlands.co.uk/argyll/kilmun-arboretum.shtml', 2.0, 122, 1.0, 'Kilmun Arboretum was originally planted with almost 300 different species by the Forestry Commission as a test station in the 1930s, to see which trees would grow well in the conditions here. It is now part of a project run by the Royal Botanic Gardens in Edinburgh to produce seed from endangered species to enable them to be grown elsewhere. This circuit combines the two waymarked trails that explore the arboretum to provide a short walk, with nearly 160 species of tree on view.', 55.9985, -4.9461),
('7467dd90-d266-54ac-b78d-624e9b1e7b57', 'Culardoch and Creag an Dail Bheag, Keiloch', 'https://www.walkhighlands.co.uk/cairngorms/culardoch.shtml', 23.75, 853, 8.5, 'These two rounded Corbetts on the fringes of the Cairngorms are conveniently climbed together. Culardoch offers extensive views into Aberdeenshire whereas Càrn Liath is a belvedere for admiring the granite tors of nearby giants Ben Avon and Beinn a''Bhuird.', 57.0057, -3.338),
('746accec-98bb-5a43-8f7a-f955d1a95c65', 'The Complete Falls of Clyde circuit', 'https://www.walkhighlands.co.uk/glasgow/complete-falls-clyde.shtml', 10.25, 336, 3.5, 'This extended circuit from the World Heritage Site of New Lanark visits the spectacular Falls of Clyde from both banks of the fine wooded gorge - combining the two shorter circuits on either side and a section of the Clyde Walkway to make a full loop.', 55.664, -3.778),
('7490476e-1f14-5a2b-b500-37e668a59f7d', 'Kinloch Forest and Leitir Fura', 'https://www.walkhighlands.co.uk/skye/kinlochforest.shtml', 6.5, 170, 3.0, 'A delightful walk through fine woodland. The views across the Sound of Sleat to the mainland are superb.', 57.1777, -5.7989),
('75ec663a-d3cc-5ce4-9806-158c4e1cec22', 'West Kip, East Kip and Scald Law from Threipmuir', 'https://www.walkhighlands.co.uk/lothian/west-kip.shtml', 11.75, 496, 5.5, 'This excellent circuit from the north side of the Pentlands tackles West and East Kip - the shapeliest of the range - en route to Scald Law, the highest. It then returns to the start via Green Cleuch.', 55.8609, -3.3328),
('7624a4ef-0ba8-5d53-8fff-b3f306dada63', 'Machrie Moor stone circles', 'https://www.walkhighlands.co.uk/arran/machrie-moor.shtml', 4.25, 42, 1.5, 'With the remains of no less than six stone circles, Machrie Moor is the best known archaelogical site on Arran. This out-and-back walk visits several groups of atmospheric standing stones set amongst the bleak moorland.', 55.5456, -5.3386),
('767962ba-b90d-541e-9cfc-cdb6d555aa67', 'Dùn Scaith Castle, Tokavaig', 'https://www.walkhighlands.co.uk/skye/dunscaith.shtml', 2.0, 20, 0.6666666666666666, 'This very short walk leads to the dramatic remains of Dùn Scaith Castle. The views are quite simply sensational, well justifying the drive along the switchback road to reach the start.', 57.1342, -5.9688),
('7689e20e-5d4c-5cd4-80af-3ab4f111360c', 'Creach Bheinn & Fuar Bheinn: Galmadale round', 'https://www.walkhighlands.co.uk/fortwilliam/creach-bheinn.shtml', 16.0, 1428, 9.0, 'The finest walk on the Morvern peninsula, this classic horseshoe follows the ridges enclosing Glen Galmadale, including the two Corbetts, Fuar Bheinn and Creach Bheinn and the Fiona Beinn na Cille. A good deal of ascent and descent it involved, making this a more strenuous outing than might be imagined.', 56.6213, -5.4791),
('76f8524e-426d-5d38-b7c2-cc90112deca2', 'Earshaig Lochans, near Beattock', 'https://www.walkhighlands.co.uk/galloway/earshaig-lochans.shtml', 1.6, 8, 0.5, 'This short stroll follows a path around a group of small but attractive lochans; there are many benches suitable for picnics.', 55.307, -3.4975),
('770cba46-139c-532f-b10d-9c8bd7cda754', 'Ardskenish and Dun Ghallain', 'https://www.walkhighlands.co.uk/islay-jura/ardskernish.shtml', 9.5, 121, 3.5, 'Explore the southwestern coastline of Colonsay on this route which crosses the golf course before following a track out to the sands, bays and machair of Ardskenish.', 56.0649, -6.2421),
('770f9b32-54c5-5846-93f8-713b8c90095f', 'The Dùn, Aberfeldy', 'https://www.walkhighlands.co.uk/perthshire/the-dun.shtml', 4.75, 247, 1.5, 'This quiet walk climbs Dun Hill which rises to the south of Aberfeldy, which was the site of a small hillfort. There are stunning views both from the lane on the way up and from the summit.', 56.6157, -3.86652),
('772593a2-0de9-50ca-945d-e4d1eabef6c4', 'Sgùrr an Utha', 'https://www.walkhighlands.co.uk/fortwilliam/sgurr-an-utha.shtml', 9.0, 757, 6.0, 'Sgùrr na Utha is a rather sprawling but extremely rocky mountain to the northwest of Glenfinnan. It gives a fairly short hillwalk; the summit offers superb views of the nearby mountains and along the length of lonely Loch Beoraid.', 56.8778, -5.4924),
('773bda4e-5786-5806-b468-1a36b53c41a9', 'Am Basteir', 'https://www.walkhighlands.co.uk/skye/ambasteir.shtml', 14.0, 1175, 7.0, 'Am Basteir (''The Executioner'') is a spectacular peak at the back of Coire Basteir, in the centre of the famous view from Sligachan, accompanied by the jagged Basteir Tooth. The ascent of the ridge is an airy scramble with a notorious ''bad step'' - but the whole walk is through stunning surroundings.', 57.2891, -6.1769),
('774407dd-9ec1-542e-baae-54ef4aa4a4fa', 'Culbin Forest and the Gut', 'https://www.walkhighlands.co.uk/moray/the-gut.shtml', 9.5, 35, 3.0, 'This slightly longer circuit in Culbin Forest visits several interpretation points and includes a section along the back of the tidal mudflats - a great place for birdwatchers.', 57.6311, -3.6805),
('77573e1b-7bab-5cd8-9060-6fb8cddc79e4', 'The Fara, Dalwhinnie', 'https://www.walkhighlands.co.uk/cairngorms/the-fara.shtml', 21.5, 775, 7.5, 'The Fara is amongst the biggest as well as the highest of the Corbetts - a broad ridge running along the north side of Loch Ericht from Dalwhinnie to Ben Alder lodge. After an initial steep climb up the ridge offers very simple walking in good conditions, with superb views, making this an enjoyable hillwalk.', 56.9327, -4.2469),
('77695829-860e-543d-8350-2b7ec7b01918', 'Maol Chean-dearg ascent, Coulags', 'https://www.walkhighlands.co.uk/torridon/Maolcheandearg.shtml', 14.0, 932, 7.0, 'Maol Chean-dearg, named bald red head on account of its red sandstone boulder summit and lower band of white quartzite, is a  popular Munro. The ascent involves a pleasant walk in along the Fionn abhainn with good views of the prow of Meall nan Ceapairean on the way. The section of scree is steep but short and the route above this presents no difficulties. There are great views from the summit, particularly of Torridon to the north.', 57.4498, -5.40744),
('779cf3df-e227-585d-a740-6ce36a40613a', 'Beinn Tharsuinn, near Alness', 'https://www.walkhighlands.co.uk/ullapool/beinn-tharsuinn.shtml', 17.0, 621, 5.0, 'Beinn Tharsuinn is a rounded heathery hill whose position in Easter Ross makes for a fine viewpoint, especially over the Cromarty Firth. It is, however, almost completely pathless, and the ascent has some tough going in deep heather. The alternative descent route given here is even rougher.', 57.7682, -4.2537),
('77ab9309-b583-56f6-8890-0b0b395ce107', 'Tom a'' Chòinich & Toll Creagach, Glen Affric', 'https://www.walkhighlands.co.uk/lochness/Tollcreagach.shtml', 16.5, 1096, 8.0, 'These are the easiest of the Munros to reach from Glen Affric, but still a substantial walk. The two peaks are contrasting in character; Toll Creagach is a very rounded mountain with mossy upper slopes, but Tom a'' Chòinich is a more shapely peak with rocky ridges.', 57.2744, -4.9587),
('77dd7f02-bdf8-53c8-96c9-bf8b434760a8', 'Cùl Mòr', 'https://www.walkhighlands.co.uk/ullapool/culmor.shtml', 13.5, 808, 5.5, 'A popular and - given its dramatic outline - reasonably straightforward Corbett with superb views over the other isolated monoliths of Assynt and Coigach including Stac Pollaidh and Suilven.', 58.0367, -5.0693),
('77e6e02d-35f7-5aa5-bfe1-7e2ca42d336a', 'Dunnottar Woods, near Stonehaven', 'https://www.walkhighlands.co.uk/aberdeenshire/dunnottar-woods.shtml', 3.5, 90, 1.5, 'This pleasant woodland walk on the fringes of Stonehaven is given added interest by follies built by the owners of the now-demolished Dunnottar House. Much of the walk follows a red waymarked trail, but our route diverges from this at several points to make a complete circuit and visit all the follies.', 56.9507, -2.2267),
('7815384c-a76d-5c85-b1f4-434f93206ade', 'Gamelshiel Castle and Spartleton Hill', 'https://www.walkhighlands.co.uk/lothian/spartleton.shtml', 7.0, 212, 3.0, 'An easy hill circuit passing the ruins of Gamelshiel Castle before climbing to the summit of Spartleton Hill. The route then crosses the moor to descend via the ancient Herring Road back to Whiteadder Reservoir.', 55.8697, -2.56688),
('786c980b-4a9f-5e5f-a5a7-a50033a9ae6b', 'Portree Forest and bay', 'https://www.walkhighlands.co.uk/skye/portreebay.shtml', 5.0, 120, 2.0, 'A lovely mixed walk starting from Las (formerly the Aros Centre) on the outskirts of Portree and including a steep walk through forestry and then open views over Portree bay followed by a walk along the salt marsh next to the water. Good opportunities for bird watching on this pleasant circuit.', 57.402, -6.2008),
('7875ed13-049e-530f-ac7a-54d6d8c6fba1', 'Castle Dounie and the Crinan Trail', 'https://www.walkhighlands.co.uk/argyll/dounie-castle.shtml', 6.5, 265, 3.0, 'This fine walk climbs high above the sea to give stunning views of Jura, Scarba and the Argyll coastline. Starting from picturesque Crinan harbour, it ascends to a dramatically situated iron-age fort on an airy summit. The first section of path can be covered by the sea at the very highest tides.', 56.0886, -5.5643),
('78814f01-337f-5984-a06a-fd163f8f8572', 'Meall na Fearna, from Loch Earn', 'https://www.walkhighlands.co.uk/perthshire/meall-na-fearna.shtml', 12.25, 730, 5.5, 'Meall na Fearna is an eastern outlier of Ben Vorlich, its summit rising above a rather boggy, knolly plateau. This approach heads up attractive Glen Vorlich.', 56.3814, -4.21578),
('789c97d9-5e33-5ee5-bde3-5bdd979b79e6', 'Culter Fell circular, near Biggar', 'https://www.walkhighlands.co.uk/glasgow/culter-fell.shtml', 18.5, 923, 6.5, 'Culter Fell is the most popular, highest and most shapely of this rolling range of hills on the Lanarkshire / Borders boundary, south of Biggar. On its own it makes a straightforward short hillwalk; as described here it is the first part of a longer, rough round above the reservoir, passing over Gathersnow Hill and finally Hudderstone, before a straightforward descent with grand views.', 55.5634, -3.5378),
('78bff071-557c-5daf-b8f0-39a376444837', 'Kingscross Point, Whiting Bay', 'https://www.walkhighlands.co.uk/arran/kingscross-point.shtml', 3.5, 60, 1.5, 'This easy going circuit on paths and minor roads heads along the coast to Kingscross Point with fabulous views to Holy Isle and after rounding the point turns inland to return via pleasant country lanes.', 55.4999, -5.094),
('78e05801-6c03-52f3-b75f-d2a8d041d32a', 'Gairloch Beach and Pier', 'https://www.walkhighlands.co.uk/torridon/gairloch-beach.shtml', 3.5, 85, 1.0, 'This short but varied walk takes in the stunning Gaineamh Mhòr beach of Gairloch before climbing across to the pier at Charlestown. The return walk is via the Flowerdale Arboretum.', 57.7171, -5.6839),
('791b47f1-d8d6-5406-9609-b02408aa33fa', 'Biod an Athair and Dunvegan Head', 'https://www.walkhighlands.co.uk/skye/biodanathair.shtml', 9.0, 481, 5.0, 'A rough moorland and clifftop walk around Dunvegan Head, with the highlight dramatic Biod an Athair, perhaps the most impressive perch amongst Skye''s sea cliffs.', 57.4934, -6.7065),
('79494dd2-124b-567e-b2d8-342cf78a0ba7', 'Ben Lui and Beinn a''Chlèibh', 'https://www.walkhighlands.co.uk/argyll/ben-lui.shtml', 10.0, 1078, 7.0, 'Ben Lui is regarded as one of the grandest and most elegant mountains in the Southern Highlands, with a magnificent appearance when seen up the Cononish Glen from Dalrigh. The shortest route to it is from Glen Lochy, enabling easy inclusion of its less impressive neighbour Beinn a''Chlèibh.', 56.4099, -4.85552),
('794c3589-46ea-56b2-843d-095a9e372ae6', 'The Merrick via Loch Valley, from Glen Trool', 'https://www.walkhighlands.co.uk/galloway/merrick-loch-valley.shtml', 15.0, 881, 6.0, 'This alternative approach to the Merrick has the advantage of enabling a circular route. However the route up Loch Valley - though attractive - is very boggy.', 55.0922, -4.4861),
('79948489-10cf-54f6-a8c1-e75f8c373a4f', 'Torrieston Forest, by Pluscarden Abbey', 'https://www.walkhighlands.co.uk/moray/torrieston.shtml', 4.75, 99, 1.5, 'The Torrieston forest walks are set in Monaughty Wood, a short distance along the glen from Pluscarden Abbey. There are two waymarked loops; the route combines both.', 57.6116, -3.4),
('7997fa26-f8f4-567d-9dd1-f2344061cc39', 'The Cairnwell Munros', 'https://www.walkhighlands.co.uk/cairngorms/cairnwell.shtml', 13.0, 595, 6.0, 'The Cairnwell is the most prominent of the group of three Munros on the west side of the Cairnwell pass. The Cairnwell and Càrn Aosda are made easily accessible but also scarred by the ski developments; Càrn a''Ghèoidh provides a wilder diversion.', 56.8868, -3.4149),
('79f2b63b-b300-5790-aa70-cbcb1be55f41', 'Beinn na Cro, Torrin', 'https://www.walkhighlands.co.uk/skye/beinnnacro.shtml', 4.0, 565, 3.5, 'Beinn na Cro is probably the least visited of the Red Hills, but it gives a short and straightforward shorter hillwalk with no scree and wonderful views. An excellent walk for an afternoon after a cloudy or wet morning.', 57.2275, -6.0358),
('79ff8f4c-0635-5aad-bc64-1e56ed9ef526', 'Ruthven and Glen Tromie Circuit', 'https://www.walkhighlands.co.uk/cairngorms/ruthven.shtml', 10.5, 310, 5.0, 'This interesting and varied walk combines the impressive ruins of Ruthven Barracks, a crossing of remote and unmarked heather moorland, a descent through the beautiful birchwoods of Glen Tromie and then finally a popular walk through the RSPB reserve overlooking the Insh Marshes.', 57.071, -4.0395),
('7a009dae-4c2b-531f-a262-a8f2896a971c', 'Hallaig, from North Fearns, Raasay', 'https://www.walkhighlands.co.uk/skye/hallaig.shtml', 6.5, 242, 2.0, 'This stunningly beautiful walk follows a superb old grassy footpath as far as a monument to the celebrated Gaelic poet Sorley MacLean, overlooking Hallaig - the subject of his most famous poem. The walk continues to explore the ruins of the village of Hallaig; this shorter section is much rougher with no clear path and can be omitted if preferred, reducing the route to a Grade 1 walk.', 57.3505, -6.004),
('7aa7dab3-bd58-59be-8cdb-5480f6386664', 'Dunnet Head', 'https://www.walkhighlands.co.uk/sutherland/dunnet-head.shtml', 17.0, 240, 6.5, 'Dunnet Head is the most northerly point of mainland Britain. This superb and challenging coastal walk approaches it along the top of its fine sandstone cliffs, rich in birdlife and now a nature reserve. There are superb views, particularly across the sea to Hoy.', 58.6225, -3.3671),
('7ad7711b-945e-58d9-8787-3a4ba2d5ca29', 'Craigston Castle, near Turrif', 'https://www.walkhighlands.co.uk/aberdeenshire/craigston-castle.shtml', 4.5, 68, 1.5, 'Craigston Castle is an impressive stately home, dating from the seventeenth century. A series of new accessible paths have been made in the woods and policies; this route follows the longest of them, making a very pleasant circuit.', 57.5857, -2.40296),
('7ae94ebe-e264-5db0-9887-725297426699', 'Àrd Mòr , Bettyhill', 'https://www.walkhighlands.co.uk/sutherland/bettyhill.shtml', 3.0, 108, 1.5, 'Àrd Mòr is the high peninsula north of Bettyhill village. The walk around it is very rough and pathless and is best left for experienced walkers; it gives superb coastal views.', 58.5303, -4.2251),
('7b02611a-952b-5e37-a51b-a5ff222d80ae', 'Àrd Airigh and Garbh Eilean hide, Sunart Oakwoods', 'https://www.walkhighlands.co.uk/fortwilliam/ardairigh.shtml', 1.5, 65, 1.0, 'An easy short walk through beautiful ancient oak woodlands; the walk visits an excellent wildlife hide on the shores of Loch Sunart. This is a great place to watch for otters, whilst seals and herons are likely to be seen on most visits.', 56.6943, -5.68242),
('7b0ef40b-2293-5d43-b559-88b408528358', 'The Complete Bennachie, from Rowantree', 'https://www.walkhighlands.co.uk/aberdeenshire/complete-bennachie.shtml', 16.75, 853, 7.0, 'Bennachie is an iconic Aberdeenshire hill with many summits. This route - starting up the Maiden''s Causeway Path - makes for a longer walk on Bennachie than our other options, visiting most of the tops with a good deal of ascent and descent.', 57.3097, -2.5117),
('7b232669-5dca-57d9-af17-c2f53a40d3b9', 'Loch Àrd and Ghleannain Loch, near Aberfoyle', 'https://www.walkhighlands.co.uk/lochlomond/loch-ard.shtml', 6.75, 160, 2.5, 'This fine forestry circuit follows a track up to the attractive Ghleannain Loch before descending to reach Loch Àrd. The return walk beside the latter loch is pure delight.', 56.1786, -4.4198),
('7b4e4243-9be1-5780-92d3-6094233ed37c', 'Lì a Tuath (North Lee), near Lochmaddy', 'https://www.walkhighlands.co.uk/outer-hebrides/li-a-tuath.shtml', 9.5, 283, 4.5, 'The two Lee hills - Lì a Tuath and Lì a Deas - are prominent landmarks in North Uist, rivalling the higher Eabhal. Lì a Tuath is the more shapely of the pair and a magnificent viewpoint. Its twin peaks are climbed on this waymarked route, approaching across the boggy moors.', 57.5945, -7.19892),
('7b543bc8-9551-5462-9280-835533db41b6', 'Fraochaidh, from Ballachulish', 'https://www.walkhighlands.co.uk/fortwilliam/fraochaidh.shtml', 21.0, 1113, 8.0, 'Fraochaidh is a neglected but impressive mountain rising above Duror, hidden from most by Beinn a''Bheithir. Its lower slopes above Duror and Glen Creran are forested, but this long approach along the ridge from Ballachulish avoids the trees and shows off the most imposing views of the mountain.', 56.6783, -5.12979),
('7bdb6fcb-eb4d-5d52-82e4-3ecee778c05a', 'North Berwick Law, North Berwick', 'https://www.walkhighlands.co.uk/lothian/north-berwick-law.shtml', 6.75, 198, 2.5, 'Climb to the top of conical North Berwick Law for fabulous views over the coast, the Bass Rock and across to Edinburgh and the Pentlands. This circuit takes time to explore the coast and town of North Berwick.', 56.049, -2.719),
('7be4abe6-138b-5510-8ee5-f0431b7a8090', 'Killiechonate Forest, Spean Bridge', 'https://www.walkhighlands.co.uk/fortwilliam/killiechonate-forest.shtml', 4.5, 105, 1.5, 'A pleasant figure of eight walk combining forest, mountain views and riverside on the outskirts of Spean Bridge. Can also be started from Spean Bridge railway station.', 56.8908, -4.9116),
('7bf7f3b2-c025-568b-a2f2-cd5082cb7a1d', 'Covenanters Memorial, Deerness, Mainland', 'https://www.walkhighlands.co.uk/orkney/covenanters-memorial.shtml', 4.25, 52, 2.0, 'This straightforward but enjoyable circuit visits the Covenanters'' Memorial on the Deerness coastline - which commemorates hundreds of prisoners who were killed in a shipwreck offshore.', 58.954, -2.7408),
('7c38c678-b675-5b85-af73-40d21c178e41', 'Blackhope Scar and the Moorfoots', 'https://www.walkhighlands.co.uk/lothian/blackhope-scar.shtml', 17.75, 532, 6.0, 'The Moorfoots are known for their tough, boggy terrain but give extensive views. This circular route from the Gladhouse Reservoir visits one of their major summits - Blackhope Scar - and two further Donalds.', 55.7635, -3.1304),
('7c66b01e-f9cc-554e-b658-4fd23f05e522', 'Sgùrr Chòinnich and Sgùrr a''Chaorachain', 'https://www.walkhighlands.co.uk/torridon/Sgurrchoinnich.shtml', 20.5, 1251, 8.0, 'The traverse of these two Munros gives an excellent hillwalk; an enjoyable ridge links the two summits at a high level though the approach is fairly long.', 57.4913, -5.27236),
('7c927e12-df7b-5279-9c75-bb7e4bf7459b', 'Little Druim Wood and the Brig o'' Turk loop', 'https://www.walkhighlands.co.uk/lochlomond/brig-o-turk.shtml', 5.5, 140, 2.0, 'This figure-of-eight walk explores the beautiful native woodland and open countryside around Brig o'' Turk. It combines several shorter waymarked loops and gives some excellent views.', 56.2266, -4.342),
('7c99d409-c513-529d-b60f-8b17c42c381b', 'Craobh Haven to Ardfern out-and-back', 'https://www.walkhighlands.co.uk/argyll/craobh-haven.shtml', 8.5, 253, 2.5, 'This out-and-back walk across the Craignish peninsula links the marina and pub at Craobh Haven with the village of Ardfern - also with a fine inn, enabling walkers to enjoy a lunch mid-walk. The time and distance given is for the return walk.', 56.2107, -5.5567),
('7cbd2b7e-6c25-51fa-b51d-7a3d67c39c9b', 'Lochbuie Explorer', 'https://www.walkhighlands.co.uk/mull/lochbuie.shtml', 8.0, 38, 2.0, 'Lochbuie is at the very end of a tiny winding road and must enjoy one of the most stunning locations on Mull. This straightforward walk explores its environs, taking in a tiny church, a grand house, a medieval castle, a sandy beach, a mausoleum and even a prehistoric stone circle - all backed by beautiful scenery. Cafe near the start.', 56.3559, -5.8729),
('7cc6f893-ce60-5e96-b265-168cb666f04f', 'Mangurstadh beach and cliffs, Uig', 'https://www.walkhighlands.co.uk/outer-hebrides/mangurstadh.shtml', 3.25, 111, 1.0, 'This superb short walk visits the beautiful sandy beach at Mangurstadh before continuing above dramatic sea cliffs. It then visits the township of Mangurstadh before returning via the dunes behind the beach.', 58.1641, -7.082),
('7ce21b95-922f-5777-9058-65afe77c20bb', 'Plockton Crags and the two lochs', 'https://www.walkhighlands.co.uk/kintail/Plocktoncrags.shtml', 8.75, 324, 3.5, 'The transmitter mast on Càrn a Bhealaich Mhòir is prominent in views from Plockton; reaching it is a much easier walk than might be expected. The walk has stunning views and passes two attractive lochs.', 57.3293, -5.64154),
('7cea2ae3-2dce-56df-a462-ace0d273e7d3', 'Clisham (An Cliseam) horseshoe', 'https://www.walkhighlands.co.uk/outer-hebrides/clisham-horseshoe.shtml', 14.0, 1016, 9.0, 'The long approach to Clisham (An Cliseam in Gaelic and on OS maps) over the dramatic and rugged ridges of Mulla-Fo-Thuath and Mulla-Fo-Dheas is a Hebridean classic, with views to match. The route makes a full days'' hillwalking but is much more demanding than the standarddirect route up Clishamfrom the A859.', 57.9864, -6.7636),
('7d26d3ab-5dbf-5660-a9b5-bf56065801e0', 'Murray''s Monument, near Newton Stewart', 'https://www.walkhighlands.co.uk/galloway/murray-monument.shtml', 3.0, 144, 1.0, 'This short waymarked walk lies in the heart of the Galloway Forest park. It climbs up to the impressive obelisk of the Murray Monument - with good views - before returning through the woods and past an attractive waterfall.', 55.02, -4.3622),
('7d438c35-8b55-5bd7-ac12-e7c20b73ab35', 'St Abb''s Head, St Abbs', 'https://www.walkhighlands.co.uk/borders/st-abbs-head.shtml', 6.25, 110, 2.0, 'St Abb''s Head is a dramatic coastal headland, ringed by cliffs and famed for its seabird colonies. This walk takes you around the Mire Loch and up around the cliffs of the Head, a National Nature Reserve. It is a straightforward route and provides good views of the highly populated bird nesting areas and a lighthouse that has been in service since 1862. There is a tea room and toilets adjacent to the car park.', 55.8997, -2.1405),
('7d69d96b-5b68-5b73-98ed-1e218a9fca99', 'MacDuff''s Monument and Lynedoch Obelisk, Scone', 'https://www.walkhighlands.co.uk/perthshire/scone.shtml', 9.2, 270, 3.0, 'This fine circular walk - also known as the Scone 200 - was created in 2005 to celebrate the bicentenary of the moving of Scone from its original position near Scone Palace. It includes an ascent to, not just one but two hilltop monuments - MacDuff''s folly and the Lynedoch Obelisk, both with excellent views. The gentle descent leads over the golf course before a final meander through Scone itself.', 56.4143, -3.4086),
('7da3e66d-d667-5df2-88ba-5fe79b3106c8', 'Inchree Falls, near Onich', 'https://www.walkhighlands.co.uk/fortwilliam/inchreefalls.shtml', 5.0, 278, 2.5, 'This forestry walk combines a visit to a fine series of waterfalls with a stroll along an ancient military road.', 56.7205, -5.22132),
('7dc79356-add3-58db-9dc9-8a8d89e56a03', 'Craiglockhart Hills', 'https://www.walkhighlands.co.uk/lothian/craiglockhart.shtml', 4.5, 153, 2.0, 'Craiglockhart is one of the less known of Edinburgh''s famed Seven Hills, but offers superb views over the city. This varied short walk takes in both the Easter and Wester summits as well as the boating pond - originally made for curling.', 55.9253, -3.23416),
('7dcd3e7a-77b3-5062-818f-d3b8b81a99c7', 'Pykestone Hill and Drumelzier Law, Drumelzier', 'https://www.walkhighlands.co.uk/borders/pykestone-hill.shtml', 15.0, 696, 5.5, 'This enjoyable hillwalk climbs the three Donalds arranged around the Drumelzier Burn. Pykestone Hill and Middle Hill both have flat summits, but Drumelzier Law is set apart from the main range and has a more impressive outline as well as fine views.', 55.5922, -3.37198),
('7e508951-fb91-51b2-935d-25df82ef0b01', 'Raven''s Rock Gorge, near Rosehall', 'https://www.walkhighlands.co.uk/sutherland/ravens-rock-gorge.shtml', 1.5, 38, 0.5833333333333334, 'Hidden deep in a forest, Raven''s Rock Gorge is a beautiful spot. There was once a superb circular walk which followed a series of boardwalks and constructed pathways to head through the gorge, but this was lost following landslides. The route described consists of two short out-and-back walks to see the bear sculpture and viewpoints above it.', 57.9715, -4.5416),
('7e5a8fa3-60cf-52dc-9f39-d8117e30a920', 'Foinaven circuit', 'https://www.walkhighlands.co.uk/sutherland/foinaven.shtml', 18.5, 982, 9.0, 'Though it just misses Munro status, spectacular Foinaven is one of the finest mountains in Sutherland - or perhaps in Scotland. This complex mass of quartzite screes has a magnificent ridge and several superb corries. The complete traverse is one of the grandest of walks but is very long with difficult transport arrangements; this circular route is shorter and takes in the highest summit.', 58.4658, -4.9022),
('7e659e40-05e7-57c1-bf7c-82cd96ca4dee', 'The Pineapple and Dunmore Estate, near Airth', 'https://www.walkhighlands.co.uk/fife-stirling/pineapple-dunmore.shtml', 4.75, 18, 1.5, 'The Pineapple is perhaps Britain''s most surprising building - a unique folly built by the Earl of Dunmore in 1761. As well as the Pineapple, this walk continues through the Dunmore Estate, visiting a ruined tower, the estate village, and the banks of the River Forth.', 56.0761, -3.7845),
('7ed64aa2-2001-56be-a9e7-8f9ce86fea18', 'Bagh an Inbhire (Inver Bay)', 'https://www.walkhighlands.co.uk/skye/bagh-an-inbhire.shtml', 3.0, 160, 1.5, 'This short walk follows a delightful old path downhill through woodland and past waterfalls to reach a peaceful pebble beach with a stunning outlook.', 57.3998, -6.0608),
('7ed9db6a-61d9-54a1-90ba-3eedd85ec6ee', 'Strathy Point', 'https://www.walkhighlands.co.uk/sutherland/strathy-point.shtml', 2.5, 42, 1.0, 'Strathy Point projects sharply out from the central section of Scotland''s northern coastline. Visiting its lighthouse makes for a straightforward walk with some excellent coastal views including a dramatic arch. It is also a great place to watch for cetaceans, with whales and dolphins frequently seen in the summer months.', 58.5894, -4.0193),
('7efa1d54-5400-5aec-936b-4fa9e4074b91', 'Dunsinane and King''s Seat, Collace', 'https://www.walkhighlands.co.uk/perthshire/dunsinane.shtml', 6.5, 378, 4.0, 'This short hillwalk climbs up first to Dunsinane - made famous by Shakespeare''s MacBeth - before continuing on a rough heather ridge out to King''s Seat. There are excellent views throughout.', 56.4745, -3.2887),
('7efeeda5-0645-5fb0-91ec-cf7c4e0ef886', 'Carron Valley Reservoir shore trail', 'https://www.walkhighlands.co.uk/glasgow/carron-valley-reservoir.shtml', 4.25, 65, 1.5, 'This short waymarked walk explores the southern shores of the Carron Valley reservoir, giving some excellent views across the water.', 56.0304, -4.05413),
('7f0d3bc8-2066-5fee-a4b2-0691279edffc', 'Meall a'' Ghiubhais, Loch Maree', 'https://www.walkhighlands.co.uk/torridon/Meallaghuibhais.shtml', 9.0, 930, 6.0, 'Meall a Ghiubhais is a steep, rugged Corbett situated just north of Beinn Eighe. It gives excellent views over Beinn Eighe and its eastern summit is one of the best viewpoints for Loch Maree. The ''Mountain Trail'' is used for half of the ascent.', 57.6308, -5.34836),
('7f218e9b-bccc-5a72-ae17-289086bc46c1', 'Angus Coast: Broughty Ferry to Carnoustie', 'https://www.walkhighlands.co.uk/angus/broughty-ferry-carnoustie.shtml', 13.0, 10, 3.5, 'A one-way walk along the coastline from Broughty Ferry on the edge of Dundee to the golf town of Carnoustie. The coastline is flat and the route can be done on a cyclepath, but our variant keeps closer to the coast at some points where possible.', 56.4669, -2.8732),
('7f4dd757-9892-5b88-a983-3ec2c00b8daf', 'Muckle Roe and the Hams', 'https://www.walkhighlands.co.uk/shetland/muckle-roe.shtml', 11.5, 286, 5.5, 'Many Shetlanders regard this circuit visiting the southern coast of Muckle Roe to be the finest in the archipelago. The section from the lighthouse to the Hams is rugged and rocky but the coastal scenery is superb. Muckle Roe is linked to mainland Shetland by a bridge. Please note that the walk crosses grazing land and has many ground-nesting birds; if taken, dogs should be kept on a lead.', 60.3492, -1.4177),
('7f78907e-2044-5e25-8301-314259d4ba5a', 'Sandwick beach and Framgord, Unst', 'https://www.walkhighlands.co.uk/shetland/framgord.shtml', 7.5, 91, 3.0, 'A fabulous sandy beach and coastal walk taking in a number of Viking sites including the remains of a longhouse and chapel. The walk can be combined withMu Ness and the Castle from Uyeasoundroute to make a longer outing.', 60.6923, -0.8679),
('7f7cbe41-f9f3-58f0-a95c-6dea4c92f3b4', 'Binscarth Wood, Finstown, Mainland', 'https://www.walkhighlands.co.uk/orkney/binscarth-wood.shtml', 4.0, 47, 1.5, 'A linear walk from Finstown along an old drover''s road through a rare patch of Orcadian woodland before emerging onto moorland and passing the Loch of Wasdale. The time and distance given are for the return walk.', 59.0083, -3.1219),
('7fba530c-7553-5b56-a3f6-f162dbbc17ef', 'Turnaichaidh and Machir Bay, Kilchoman', 'https://www.walkhighlands.co.uk/islay-jura/kilchoman.shtml', 5.75, 194, 3.0, 'This short hillwalk has plenty of interest; a rugged ascent to a wild hilltop, a truly magnificent sandy beach, and a spectacularly carved Celtic Cross from the 14/15th centuries.', 55.7823, -6.44247),
('7fc20756-89c2-5280-9be9-3ddb3db01e44', '39 Steps, Ardrishaig', 'https://www.walkhighlands.co.uk/argyll/ardrishaig.shtml', 3.25, 165, 1.0, 'This forestry walk climbs up amongst the trees and tumbling streams above Ardrishaig for some great views across Loch Fyne. The route is waymarked though the signs are very worn.', 56.0059, -5.4509),
('7fe507c0-3ade-5932-9a08-02b5230f6c3f', 'Beinn a'' Bhùird', 'https://www.walkhighlands.co.uk/cairngorms/beinn-a-bhuird.shtml', 28.0, 959, 9.0, 'Beinn a''Bhùird is the eleventh highest mountain in Britain, a vast high plateau in the eastern Cairngorms. The shortest approach is up Glen Quoich and follows a the former line of a bulldozed track - now restored by the NTS - high onto the mountain. Even this route is a long walk.', 57.0017, -3.4554),
('7fe60f01-1b56-5ca4-a622-74220adeba41', 'Cassley Falls and Rosehall Forest', 'https://www.walkhighlands.co.uk/sutherland/achness-falls.shtml', 4.0, 70, 2.0, 'This beautiful woodland and riverside walk visits the Cassley Falls - marked as the Achness Falls on Ordnance Survey maps. There is a beautiful log cabin constructed by the local community at the start, that houses information and interpretation.', 57.9804, -4.5731),
('8020754e-6841-5aef-b7f0-a0c8d10bcf95', 'Torry Battery and Girdle Ness, Aberdeen', 'https://www.walkhighlands.co.uk/aberdeenshire/girdle-ness.shtml', 3.75, 55, 1.0, 'Girdle Ness is the headland that guards the southern side of Aberdeen harbour. The short walk around it takes in the lighthouse, sea views and Torry Battery - built to defend the harbour in 1860; if you are lucky you might catch sight of one of the dolphins which frequently visit the mouth of the harbour. There is a cafe at the Greyhope Bay Centre at Torry Battery.', 57.1418, -2.06),
('803c5456-6d45-5e29-9a6d-cdf55553ffcf', 'Meall an Fhudair, near Inverarnan', 'https://www.walkhighlands.co.uk/lochlomond/meall-an-fhudair.shtml', 14.5, 901, 6.0, 'Meall an Fhudair is a sprawling and rather neglected Corbett, immediately north of the Arrochar Alps and lacking their fine outlines. It does, however, have a great feeling of wildness and solitude and some fine views.', 56.3396, -4.72095),
('806494e0-24b7-5219-9e6f-28d4b1f16ab4', 'Bac an Eich, Strathconon', 'https://www.walkhighlands.co.uk/lochness/bac-an-eich.shtml', 20.5, 738, 7.0, 'Rising above the upper reaches of Strathconon, Bac an Eich is a neglected Corbett offering some fine views. The route described here uses stalkers'' paths which loop around the mountain, avoiding the steepest slopes and ascending from the back.', 57.5226, -4.96225),
('80999aba-93cc-5ecd-89bf-a849e84fea9b', 'Dulnain Bridge & Curr Woods, Dulnain Bridge', 'https://www.walkhighlands.co.uk/cairngorms/dulnain-bridge.shtml', 8.5, 86, 3.0, 'This circular route from Dulnain Bridge explores Curr Wood to the south and west of the village, including a visit to the Speyside Centre and views over Strathspey to the Cairngorms.', 57.3038, -3.664),
('80c03dd1-1a36-5b99-b12d-a375b150325f', 'Forsinain Trail, Strath Halladale', 'https://www.walkhighlands.co.uk/sutherland/forsinain.shtml', 6.5, 116, 2.0, 'The waymarked Forsinain Trail crosses the peat bogs and forestry at the heart of the Flow Country and is a good chance to see peat restoration in action. Look out for dragonflies, and birds such as hen harriers and red throated divers - but also watch your step as the route is very wet.', 58.4118, -3.878),
('80ca3bd4-7dc9-516a-a804-65abfa8e38c2', 'Vertish Hill, Hawick', 'https://www.walkhighlands.co.uk/borders/vertish-hill.shtml', 8.5, 218, 3.0, 'This waymarked circular walk climbs south from Hawick, visiting Williestruther Loch and over Vertish Hill, with good views over the town.', 55.4231, -2.79192),
('80d009db-a89a-55b2-acd1-683aca730d5e', 'Eas Mòr, Loch Garbad and the Library in the Woods, Kildonan', 'https://www.walkhighlands.co.uk/arran/eas-mor.shtml', 5.25, 195, 2.0, 'This enjoyable walk climbs above a dramatic gorge with a fine waterfall, before an optional detour up to visit a remote and peaceful hill loch. The return leads past the Library in the Woods.', 55.4495, -5.13394),
('80d5d350-c591-5c04-928c-e9d169975ef9', 'Sgòrr Ruadh, Achnashellach', 'https://www.walkhighlands.co.uk/torridon/Sgorrruadh.shtml', 16.0, 931, 7.0, 'Sgòrr Ruadh is a majestically-sculpted sandstone peak which shows an impressive face above Coire Làir. Munro-baggers often climb this peak in combination with Beinn Liath Mhor, in which case the latter peak is best climbed first.', 57.4818, -5.3292),
('81872689-8359-5281-924c-81142e2acd98', 'Rum Cuillin traverse', 'https://www.walkhighlands.co.uk/islands/rum-cuillin.shtml', 21.0, 1902, 14.0, 'The Rum Cuillin provide one of the finest but most demanding hill circuits in all Scotland; an unsurpassed combination of mountain and sea with unforgettable views. The route is extremely arduous; whilst the scrambling is mostly straightforward, careful route finding is essential - the route is also very committing with few escape options. It covers the 5 major summits on Rum, including 2 Corbetts and a Fiona.', 57.0134, -6.2815),
('81a6e9e1-2408-540c-a6ab-f2e80d642933', 'An Caisteal and Beinn a''Chròin, near Crianlarich', 'https://www.walkhighlands.co.uk/lochlomond/an-caisteal.shtml', 14.0, 1045, 7.0, 'Two fine Munros with rewarding ridge walking and great views over a wide expanse from Loch Lomond to Ben Nevis. The walking is mostly on good grassy ground underfoot with a final section that can be boggy.', 56.379, -4.643),
('81af5e54-c783-520b-be2a-ec00e10b215c', 'River Annan and Brydekirk circuit, Annan', 'https://www.walkhighlands.co.uk/galloway/river-annan.shtml', 10.5, 42, 4.0, 'Follow the banks of the River Annan between the eponymous town and the village of Brydekirk. There are paths on both sides along wooded banks rich in wildflowers in early summer, making for a beautiful riverside circuit.', 54.9872, -3.26376),
('81b98633-773d-5eed-b7a3-45befb8e4739', 'Rutherford Monument walk, Gatehouse of Fleet', 'https://www.walkhighlands.co.uk/galloway/rutherford-monument.shtml', 6.0, 122, 2.5, 'This excellent walk climbs amongst the lowly but rugged area of little hills on the western edge of Gatehouse of Fleet. With Pictish stone carvings, superb views, an impressive monument and romantic church ruins, it has plenty of interest.', 54.8811, -4.1851),
('81d040a0-f57b-55c4-ac44-14185544bbc4', 'Falls of Pattack', 'https://www.walkhighlands.co.uk/cairngorms/falls-of-pattack.shtml', 4.5, 98, 1.5, 'The true Falls of Pattack are somewhat hidden away, but are much more impressive than the better known lower falls near the main road at Feagour. This easy out-and-back walk follows a good track until a final short path leads to the best viewpoint looking over the falls.', 56.9779, -4.3785),
('81f0e38f-8ec1-50e8-aeef-d78c263aaa2f', 'Loch an Torr circuit', 'https://www.walkhighlands.co.uk/mull/loch-an-torr.shtml', 10.25, 167, 3.5, 'A mix of dense forestry plantations and open moorland, this walk makes a wide circuit around Loch an Torr with a short section on the road. The route follows landrover tracks throughout - signed as cycle paths - and offers better underfoot conditions than most on Mull.', 56.5946, -6.15228),
('8200227f-99de-5c1f-9d8a-57b46f68c90b', 'Portsoy and Sandend circular', 'https://www.walkhighlands.co.uk/aberdeenshire/portsoy-sandend.shtml', 9.25, 128, 3.0, 'This lovely stretch of coastline joins the fascinating Portsoy, with its heritage harbour and buildings to the picturesque village and fabulous beach at Sandend. The return is on a minor road through farmland with sea views.', 57.6846, -2.6907),
('820674f8-cf81-5463-be9b-57a43742d456', 'Bochastle and the Falls of Leny', 'https://www.walkhighlands.co.uk/lochlomond/falls-of-leny.shtml', 7.5, 220, 2.0, 'This circular walk follows a forestry track across the Bochastle Hill and the lower slopes of Ben Ledi, with some excellent views. It then descends steeply to join the cycle route for the return, with the opportunity to detour to visit the powerful cascade of the Falls of Leny.', 56.2452, -4.2487),
('820ef8b7-b830-513d-9f9c-cf745845302a', 'Spey Bay circuit, Spey Bay', 'https://www.walkhighlands.co.uk/moray/spey-bay.shtml', 6.5, 5, 2.0, 'This is a beautiful short walk which follows the Speyside Way at first before crossing the golf course to return along the shore with the chance of spotting the Moray Firth dolphins. A good walk to combine with a visit to the wildlife centre at Spey Bay.', 57.6738, -3.0938),
('82196e76-62c2-55fd-8605-3e266b7b7ec0', 'Caolas Explorer', 'https://www.walkhighlands.co.uk/islands/caolas.shtml', 8.25, 42, 3.0, 'This circular walk mostly follows tracks and minor roads around the easternmost part of Tiree. As you''d expect, there is the usual visit to a perfect sandy beach, in this case An Traigh-lochain overlooking Gunna Sound.', 56.5394, -6.7735)
INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('82208ad8-e083-5f05-a992-fea5c5b7380c', 'Haddo House and Country Park, near Tarves', 'https://www.walkhighlands.co.uk/aberdeenshire/haddo-house.shtml', 4.25, 45, 1.5, 'Explore the beautiful parkland of Haddo House, taking in sculptures, lakes, magnificent trees and rhododendrons, bird hides, an impressive children''s play area and the chance to visit the stately House, shop and tearoom.', 57.4008, -2.2218),
('824be88f-8632-5749-aa37-d0762df7644b', 'Gualachaolish, near Lochdon', 'https://www.walkhighlands.co.uk/mull/gualachaolish.shtml', 8.0, 147, 3.0, 'A rough and wet path with fantastic views over Loch Spelve leads to the ruins at Gualachaolish, with the chance to explore a nearby graveyard and enjoy the wildness of the area.', 56.4236, -5.6986),
('82576de8-19b7-51ae-8880-725a2d2130b9', 'Nigg Church and the Bishops'' walk', 'https://www.walkhighlands.co.uk/ullapool/nigg-bishops.shtml', 2.0, 25, 0.75, 'Nigg Church is well worth a visit to see the stunning Pictish carved cross-slab inside. The walk is a short one, looping down from the church to the shores of Nigg Bay along an ancient route by the burn. The Bishop of Ross is said to have sailed from his seat in the Black Isle to his summer holiday home at Nigg, coming ashore at Nigg Bay and using the path now known as the Bishops Walk.', 57.7189, -4.0081),
('8266a102-558e-5704-989c-2ef291c8ea87', 'Sannox to Lochranza: Cock of Arran', 'https://www.walkhighlands.co.uk/arran/cock-of-arran.shtml', 15.75, 119, 6.0, 'The second stage of the Arran Coastal Way - a great linear walk in its own right - is regarded as one of the finest of the route. It sticks close to a remote section of Arran''s shore, with lovely views across the water to the Isle of Bute and Ayrshire. After passing the cottage at Laggan (where a steep inland alternative climbs the hill before descending to Lochranza) the route becomes rocky and boggy in places before passing the Cock of Arran. Finally an easier section of path and road lead into Lochranza with good views of the castle.', 55.6618, -5.1558),
('827d548a-7981-52b4-8bf2-bb7856b8fdbb', 'Uiginish Point, near Colbost', 'https://www.walkhighlands.co.uk/skye/colbost.shtml', 3.0, 110, 2.0, 'A short, pathless walk around the end of the Uiginish peninsula visiting a small lighthouse and ruined broch. Excellent views of Loch Dunvegan and a good place to watch for otters and seals.', 57.4401, -6.5965),
('82acb57c-e15d-5957-8bc8-53729b5097a6', 'River Oich, Fort Augustus', 'https://www.walkhighlands.co.uk/lochness/Riveroich.shtml', 6.0, 33, 2.0, 'This is a straightforward walk on forest tracks and a lovely path alongside the River Oich. There is the chance of seeing red squirrels amongst the Scots pines.', 57.1426, -4.7002),
('83012a7e-80d3-55a9-8e5c-03dba11d1f5d', 'Filiscleitir chapel, Sgiorgarstaigh, Ness', 'https://www.walkhighlands.co.uk/outer-hebrides/filiscleitir-chapel.shtml', 10.75, 142, 3.0, 'A fairly easy walk in north Lewis, past the peat cuttings of today''s crofters to reach the remains of the traditional summer sheiling village of Filiscleitir where the dramatic clifftop ruins of a chapel can be explored.', 58.4705, -6.2152),
('833a4c2f-6050-5add-b738-b4f77215c324', 'Auchnafree Hill from Loch Turret', 'https://www.walkhighlands.co.uk/perthshire/auchnafree-hill.shtml', 18.25, 623, 6.0, 'Auchnafree Hill has an indistinguished summit of a rather sprawling moorland. However, it overlooks the impressive glacial trench of Loch Turret, making for an enjoyable hillwalk.', 56.4155, -3.9127),
('83441e0d-c445-5ce1-8539-7801cdc53d8c', 'Uyea circuit from Sandvoe, Northmavine', 'https://www.walkhighlands.co.uk/shetland/uyea.shtml', 15.5, 418, 5.5, 'This superb circular walk follows the northern coast of Mainland Shetland to view the remote tidal island of Uyea and its surrounding stacks and skerries. The return is on an inland track passing lochans where you may spot rare birds.', 60.5991, -1.3382),
('8360ada1-93d7-5423-8c5f-19b54858be49', 'Clashmach Hill, Huntly', 'https://www.walkhighlands.co.uk/aberdeenshire/clashmach-hill.shtml', 9.0, 257, 3.0, 'Clashmach Hill is an open ridge lying southwest of Huntly. The ascent offers a pleasant walk with extensive views; the alternative descent is a little rougher.', 57.4441, -2.7912),
('83c5251f-5e87-5514-a556-b4a368a9a0ad', 'Dornoch links and Embo circular', 'https://www.walkhighlands.co.uk/sutherland/dornoch-embo.shtml', 8.5, 90, 3.5, 'An excellent circuit taking in the historic buildings of Dornoch, the world famous golf course, and the bracing sandy shore to the pier at Embo and back to Dornoch. This walk can be linked to the Dornoch Point walk by continuing along the shore instead of returning to the town at the Lifeboat Station.', 57.88, -4.028),
('83fa8b0f-bf2c-5fdb-b6a0-d14f4c94cffe', 'Cawdor Burn circular, Cawdor', 'https://www.walkhighlands.co.uk/moray/cawdor-burn.shtml', 3.5, 8, 1.0, 'This short walk is an ideal leg-stretcher to combine with a visit to Cawdor Castle. The tiny village itself has a country pub and a deli / cafe.', 57.526, -3.9282),
('844561ef-2c8f-5bbc-b3aa-f55e0f738fe2', 'Meall Fuar-mhonaidh, near Drumnadrochit', 'https://www.walkhighlands.co.uk/lochness/Mealfuarmhonaidh.shtml', 9.0, 535, 5.0, 'Meall Fuar-mhonaidh may not be well known by name, but it is the most prominent summit around Loch Ness and provides a straightforward hillwalk with good views.', 57.2801, -4.5047),
('8456708f-b679-5ccf-a011-c1d11789d552', 'Càrn na h-Easgainn, near Moy', 'https://www.walkhighlands.co.uk/lochness/carn-na-h-easgainn.shtml', 6.25, 307, 3.0, 'Follow a landrover track up through birchwoods and then over the moors on this straightforward climb up to a rounded summit. Càrn na h-Easgainn offers extensive views for the modest effort required.', 57.3792, -4.055),
('8458f609-cd25-536f-a848-72b43b51bbce', 'Torrs Warren, near Dunragit', 'https://www.walkhighlands.co.uk/galloway/torrs-warren.shtml', 6.25, 27, 2.0, 'Torrs Warren is a forestry plantation at the back of Luce Bay. This walk follows a long section of forest track before heading to the edge of the dunes and to Ringdoo Point. It is not waymarked and - although easy to follow to the point - the alternative route back could be difficult to locate.', 54.8667, -4.8938),
('84656e2e-6bf6-50a9-b8e8-9fd2f30e95a1', 'Carleatheran and Stronend,  near Kippen', 'https://www.walkhighlands.co.uk/glasgow/carleatheran.shtml', 23.25, 631, 6.5, 'Explore the escarpment of the Fintry and Gargunnock hills to reach the high points of Carleatheran and Stronend both with great views over Flanders Moss to the mountains beyond. Can be boggy and needs careful navigation in poor weather.', 56.1039, -4.16778),
('8481db74-c893-5db2-9e9f-ccc7f8276140', 'Badvoon Forest circuit, near Ardgay', 'https://www.walkhighlands.co.uk/sutherland/badvoon-forest.shtml', 9.5, 221, 3.0, 'This lonely circuit to the south of Ardgay heads through both forestry and across boggy heather. The walk is well off the beaten track and offers views over the Dornoch Firth. Please respect the privacy of the residents of Badvoon House and keep dogs under tight control.', 57.8686, -4.3599),
('84a96508-d0fb-5d6b-8bbe-604524a9caf3', 'Falls of Acharn and the stone circle, near Kenmore', 'https://www.walkhighlands.co.uk/perthshire/falls-of-acharn.shtml', 5.5, 260, 2.0, 'This very beautiful walk, short but steep, heads through a Victorian ''Hermit''s Cave'' to view the dramatic Falls of Acharn. The walk makes a loop around a lovely gorge, but also includes a detour to a stone circle with great views over Loch Tay.', 56.57, -4.02695),
('84b920fb-fdbb-5cc2-9b59-20845fa7d6d7', 'Beinn Dearg from near Blair Atholl', 'https://www.walkhighlands.co.uk/perthshire/beinn-dearg.shtml', 29.0, 990, 9.0, 'The remote position of Beinn Dearg makes for a long hillwalk, although the terrain is straightforward in good summer conditions making for fast walking. The views are extensive and with a different route for the return the route makes for an enjoyable day.', 56.7745, -3.84344),
('84cb1b4d-a3b4-57ef-be32-52d5fa222dc1', 'Kingarth and Funtulich circuit, Glen Lednock', 'https://www.walkhighlands.co.uk/perthshire/kingarth.shtml', 7.0, 58, 2.5, 'This straightforward circuit takes in the beautiful and peaceful middle reaches of Glen Lednock''s farmland where you may well see Red Kites. The return by the road is usually fairly quiet.', 56.3929, -4.0019),
('84d546d6-4e6d-5e3e-8724-2d23f0098aea', 'Beinn Liath Mhòr a''Ghiubhais Li', 'https://www.walkhighlands.co.uk/ullapool/beinn-liath-mhor-ghiubhais.shtml', 8.5, 524, 4.0, 'This rounded and uncelebrated Corbett makes for a short but rough outing from Loch Glascarnoch. The hill is redeemed by the fine views from the summit.', 57.7196, -4.8753),
('84efd925-0af3-5874-8fe5-2dee170463fb', 'The Binn and Kinghorn Loch, from Burntisland', 'https://www.walkhighlands.co.uk/fife-stirling/the-binn-burntisland.shtml', 10.5, 242, 3.5, 'The steep escarpment of the Binn is a dramatic backdrop for Burntisland, and provides stunning views over the town and across the Forth. The history is interesting too, as the route continues to Kinghorn loch. The return can done along the coast and beaches if the tide is low; otherwise there''s a pavement alongside the road.', 56.0592, -3.22927),
('84f461fc-674c-50ac-9ec2-c298bd9d4e92', 'Brothers'' Point (Rubha nam Brathairean), Staffin', 'https://www.walkhighlands.co.uk/skye/brotherspoint.shtml', 3.5, 238, 2.0, 'A short walk out to Rubha nam Brathairean (Brothers'' Point) - a dramatic headland marking the easternmost point of Trotternish.', 57.585, -6.1577),
('84f6ab15-f029-511e-a4c6-cf5f3f5cc0d8', 'Loch Cuithir and Diatomite railway', 'https://www.walkhighlands.co.uk/skye/lochcuithir.shtml', 11.0, 172, 3.0, 'The walk starts with a fabulous viewpoint over the Lealt gorge and is a gentle walk to a picturesque loch with impressive views of the Trotternish ridge. Plenty of historical interest from the remains of the diatomite railway.', 57.5659, -6.1547),
('852c378f-268f-5b96-a0a4-fea148cf0374', 'Beinn Edra from Glen Uig', 'https://www.walkhighlands.co.uk/skye/beinnedra.shtml', 12.0, 565, 5.0, 'Beinn Edra is the highest point on the northern half of the Trotternish Ridge. The ascent from Glen Uig is boggy in parts but there are fine views higher up.', 57.5849, -6.3336),
('85b033be-b997-5153-b4f5-25243b493969', 'Càrn na Saobhaidhe, via Dunmaglass', 'https://www.walkhighlands.co.uk/lochness/carn-na-saobhaidhe.shtml', 26.5, 647, 7.5, 'Càrn na Saobhaidhe is the highest summit on the vast, sprawling peaty moorland that makes up the northern Monadhliath. A remote place, it can be approached from Coignafearn in Strathdearn, from Garthebeg, or via a bulldozed track which reaches right to the summit from Dunmaglass as described here. The walk up the ugly track can become tedious, and a windfarm is currently being constructed east of this route which can mean heavy lorries using the track. Due to the profusion of new tracks, carefully navigation is required - gps is useful.', 57.2897, -4.3123),
('85b0f2c8-689c-5113-ade4-ba2df5b7edb5', 'Totches Baulk and the Jed, Jedburgh', 'https://www.walkhighlands.co.uk/borders/jedburgh.shtml', 4.25, 156, 1.5, 'This short but hilly circuit around the town of Jedburgh climbs up to Totches Baulk - an ancient pathway - for views over the town. It then descends past the castle to reach the River Jed.', 55.4775, -2.5529),
('85b47636-cd25-5938-9f3f-8fb9e2d6f63d', 'Scald Law and Carnethy Hill, Flotterstone', 'https://www.walkhighlands.co.uk/lothian/scald-law.shtml', 12.25, 609, 5.5, 'Scald Law is the highest of the Pentlands; this classic approach reaches it via a very fine switchback ridge, taking in the shapely Carnethy Hill along the way. The return follows the minor road by the Loganlea and Glencorse Reservoirs.', 55.855, -3.2269),
('85f04509-b260-5c0f-acc0-45ccf766f3b3', 'Beinn a'' Chochuill & Beinn Eunaich', 'https://www.walkhighlands.co.uk/argyll/beinn-eunaich.shtml', 13.5, 1221, 6.5, 'These two Munros offer a good mountain day, with great views of Glen Etive and Ben Cruachan. The ridge between the two is pleasant with no difficulties although the final descent from Beinn Eunaich is unpleasantly steep.', 56.4145, -5.02331),
('862a170a-4b77-5997-9896-490119fbab07', 'Morrone ascent, Braemar', 'https://www.walkhighlands.co.uk/cairngorms/morrone.shtml', 12.0, 650, 5.0, 'Morrone is a Corbett that sits above Braemar and makes a lovely hill circuit on a fine day. With 360 degree views of the surrounding Cairngorm peaks and over Braemar itself, this walk with a pretty riverside return route makes a great half day excursion.', 57.0058, -3.3984),
('863612cc-516f-54f1-9764-248dfb6e686f', 'Jenkins Park, near Fort Augustus', 'https://www.walkhighlands.co.uk/lochness/Jenkinspark.shtml', 7.75, 196, 2.5, 'This circular walk climbs through forestry plantations along the route of part of one of General Caulfeild''s great military roads. There are many glimpses of views over Fort Augustus and up the Great Glen. The walk can be linked by part of the Great Glen Way to the walk at Allt na Criche.', 57.1491, -4.6837),
('863d0e71-fd31-5fb4-aeda-d1d53e194ccd', 'Airlie Monument and Dykehead circuit', 'https://www.walkhighlands.co.uk/angus/airlie-monument.shtml', 6.2, 210, 2.0, 'The Airlie Monument is a familar landmark in the lower reaches of Glen Clova and Glen Prosen, prominently sited on Tulloch Hill between the two. It is well worth a visit for the fine views as well as to see the monument itself - a memorial to the ninth Earl of Airlie who died in the Boer war. The route starts from the beautiful Scott-Wilson memorial, and extends the usual short ascent to make a very pleasant circular walk.', 56.7332, -3.0294),
('867a315b-d26f-531d-81b3-915454aa3611', 'Stockbridge and the Royal Botanic Garden Edinburgh', 'https://www.walkhighlands.co.uk/lothian/stockbridge-botanic-gardens.shtml', 7.5, 114, 3.0, 'Head out from central Edinburgh to explore the wonders of the Royal Botanic Gardens and Stockbridge, one of the most desirable neighbourhoods in the capital.', 55.9515, -3.19116),
('874ec721-b8c7-54ac-8761-af8a48383e09', 'Scalasaig Explorer', 'https://www.walkhighlands.co.uk/islay-jura/scalasaig-explorer.shtml', 8.0, 224, 4.0, 'This enjoyable circuit explores the surroundings of Scalasaig. The route climbs up to the Lord Colonsay monument before following the ''old road'' up to a fine viewpoint. The return takes in the abandoned fishing village of Riasg Buidhe before a pathless final section along the coastline. The walk can be shortened by omitting the monument and Riasg Buidhe sections.', 56.0809, -6.19376),
('884fbdc2-194f-5e47-8733-7078895abd1a', 'Sail Mhòr, from Ardessie', 'https://www.walkhighlands.co.uk/ullapool/sail-mhor.shtml', 12.0, 825, 6.0, 'Sail Mhòr is the final termination of the An Teallach range, a blunt final upthrust which plunges with steep crags on its northern side down to Little Loch Broom. Its position ensures that it is a sensational viewpoint.', 57.8537, -5.2862),
('8872c693-7c2e-5655-95be-f40cc760fc26', 'Beinn a'' Chaisgein Mòr, via Carnmore from Poolewe', 'https://www.walkhighlands.co.uk/torridon/beinn-a-chaisgein-mor.shtml', 45.0, 1280, 14.0, 'Beinn a'' Chaisgein Mòr is a truly remote mountain, well hidden from most roads at the very heart of the great Fisherfield Forest. It can be approached from Gruinard to the north but the route given here makes use of the superb stalkers paths leading to the dramatic causeway between the Fionn Loch and the Dubh Loch near Carnmore. Most walkers will opt to either wildcamp near the causeway, or use the very basic shelter at Carnmore Stable. Cycling is also a good option with easy approach as far as the woods above Kernsary, then muddy track and single track suitable for MTB to Fionn Loch.', 57.7656, -5.6027),
('889d7736-17ff-50f1-a3f5-2831f5a3bac5', 'Meikle Says Law', 'https://www.walkhighlands.co.uk/lothian/meikle-says-law.shtml', 10.0, 263, 4.0, 'Meikle Says Law is the highest of the Lammermuir hills but is not the most distinguished, being marked only by a triangulation pillar in the midst of very extensive moorland. The ascent still gives an enjoyable walk across lonely country, with burns to cross on the outward route and rough going on the return.', 55.8646, -2.6203),
('88ae2a01-5854-5d81-82bf-d05f6ff5ecea', 'Hoxa Head, South Ronaldsay', 'https://www.walkhighlands.co.uk/orkney/hoxa-head.shtml', 2.7, 26, 1.0, 'A short clifftop walk visiting two WWII gun batteries and offering superb views over Scapa Flow, Flotta and Hoy. The walk could be done as an extension to theSands of Wrightroute.', 58.8235, -3.025),
('88cd0a0d-7616-5f08-bc83-85a1ae379506', 'Ben Hee, from West Merkland', 'https://www.walkhighlands.co.uk/sutherland/ben-hee.shtml', 13.25, 765, 6.0, 'Ben Hee - which appears to be a fairly rounded hill from the A838 road - has some hidden corries and steeper slopes on its eastern and northern sides. It gives a reasonably straightforward hillwalk - revealing spectacular views.', 58.2571, -4.77333),
('88d9ec79-1ab8-51fb-80b3-d1b60e1a6ba1', 'Isle of Flodaigh seals, off Benbecula', 'https://www.walkhighlands.co.uk/outer-hebrides/flodaigh.shtml', 1.75, 16, 1.0, 'A pleasant short walk to a sea inlet overlooking a small island where seals bask at low tide. Also a good spot to linger on a fine day and watch for birds and otters.', 57.4762, -7.2677),
('892c6743-158e-5c65-8a94-5f89b135d28b', 'Airthrey Loch & Hermitage Woods, Stirling University', 'https://www.walkhighlands.co.uk/fife-stirling/stirling-university.shtml', 4.5, 112, 1.5, 'The easy circuit around Airthrey Loch at the heart of the University of Stirling campus has lovely views of Dumyat and plenty of wildlife; this route adds a steep climb through the woods for superb views over Stirling, its castle and the Wallace Monument.', 56.145, -3.9223),
('89537327-f1aa-5235-b380-981337f5b6fb', 'Sannox to North Sannox', 'https://www.walkhighlands.co.uk/arran/north-sannox.shtml', 4.0, 26, 1.5, 'This short out-and-back walk along the coast to North Sannox has a sandy beach, a dramatic rock wall, a beautiful picnic spot and superb views to the mountains. It also can provide an easy link to further walks on this section of the Arran coastline.', 55.6615, -5.1554),
('89aed0b3-cd6b-5772-a50f-539849a090f0', 'Belmont to Lund, Unst', 'https://www.walkhighlands.co.uk/shetland/belmont-lund.shtml', 7.75, 129, 3.0, 'This linear walk starts at the Belmont ferry terminal on Unst. It heads to the remains of a coastal broch before a rough moorland section visiting an abandoned settlement and another broch site. From the latter it descends to reach the beautifully situated Lund church, at the southern end of a sandy beach. A track then leads to a minor road, passing a fine standing stone. The walk as described ends at the junction beyond - either pre-arrange a lift from here, return via the outward route (doubling the time and distance given), or walk a further 1km to meet a bus on the A968 if the timetable permits (infrequent service).', 60.6833, -0.9658),
('89b1fb3a-5374-5173-933b-cbc52e6e289f', 'Campsie Glen, Clachan of Campsie', 'https://www.walkhighlands.co.uk/glasgow/campsie-glen.shtml', 0.85, 35, 0.5, 'A very short and popular walk into the Campsie Glen with the option to extend it to include a steep climb and waterfall walk. Refreshments, toilets and bike hire at start.', 55.9891, -4.2288),
('89f63238-c6cc-5765-84a1-fbaee2813780', 'Neist and Milovaig clifftop coast walk', 'https://www.walkhighlands.co.uk/skye/milovaig.shtml', 11.0, 351, 5.0, 'This superb clifftop coastal walk makes an excellent extension to a visit to Neist Point. Dramatic cliff scenery and great views to the Outer Hebrides.', 57.43, -6.7788),
('8a158dc9-6471-5be2-a04c-1cf9d272b781', 'Tràigh na Cille, near Kilninian', 'https://www.walkhighlands.co.uk/mull/traigh-na-cille.shtml', 1.25, 44, 0.5, 'Compared to the famed white sands of nearby Calgary Bay, Tràigh na Cille is little known or visited. Its black sands, however, are a stunningly beautiful place for a short wander.', 56.532, -6.2241),
('8a1e5211-2e94-508b-ae43-020e328734db', 'Loch Oich circuit, Invergarry', 'https://www.walkhighlands.co.uk/fortwilliam/lochoich.shtml', 17.0, 495, 6.0, 'This moderate walk makes a circuit around attractive Loch Oich utilising the Great Glen Way along the eastern shores and the Invegarry Link higher above the loch on the western side.', 57.0684, -4.80386),
('8a553a81-86a7-55df-b806-32781d8dd103', 'Flotta island explorer', 'https://www.walkhighlands.co.uk/orkney/flotta.shtml', 15.24, 244, 4.5, 'From many viewpoints around the Scapa Flow, Flotta appears to be dominated by its great oil terminal, but there is actually plenty here for a visitor to explorer. Its strategic location at the main southern entrance to Scapa Flow has led to the island being dotted with the remains of defences from the world wars, and on a fine day the views from its coastline take in all the islands surrounding this great natural harbour.', 58.8376, -3.128),
('8a6e76b7-2d60-5bbf-9bcd-81c5ffa70e7a', 'Caisteal Uisdein, near Earlish', 'https://www.walkhighlands.co.uk/skye/caistealuisdean.shtml', 4.5, 37, 2.0, 'This easy and secluded short walk visits the remains of a seventeenth century castle with a grim story to tell. It stands in a lovely spot on the Loch Snizort coastline.', 57.5513, -6.3749),
('8a894e2d-95d3-5cc1-9273-6fe5700e4621', 'Broughton Heights and Trahenna Hill circuit', 'https://www.walkhighlands.co.uk/borders/broughton-heights.shtml', 13.5, 613, 5.0, 'Broughton Heights is the highest of the fine range of hills lying to the east of the village. With grassy ridges and steep heathery slopes, the hills gives some superb views. This route takes in Broughton Heights itself before returning over Hammer Head to take in Trahenna Hill.', 55.6164, -3.4112),
('8b41f527-8351-580f-8f15-ee4dd7cf59f5', 'Pennan to Aberdour Bay', 'https://www.walkhighlands.co.uk/aberdeenshire/pennan.shtml', 7.0, 160, 0.0, 'This linear route links the picturesque Pennan - made famous by the film Local Hero - with Aberdour Bay, with spectacular red sandstone caves and arches. The route between runs inland,  following farm paths and tracks across the pleasant rolling countryside. The route described is linear - if no transport has been arranged from Aberdour it is necessary to return the same way (times and distances given are one-way only).', 57.6791, -2.2627),
('8b652f4f-1358-5cc7-b1e4-5e6b92458ee0', 'Beinn Iaruinn and Leana Mhor, Glen Roy', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-iaruinn.shtml', 8.75, 786, 5.0, 'Beinn Iaruinn rises very steeply above the rollercoaster road up Glen Roy, with the northern arm of its corrie being the most usual route of ascent. Combining the hill with neighbouring Leana Mòr , however, makes for a more enjoyable walk avoiding the steepest slopes.', 56.9524, -4.7962),
('8b67c7ff-4583-586c-af22-6a10f43d8bfd', 'Marwick Head and the Kitchener Memorial, Mainland', 'https://www.walkhighlands.co.uk/orkney/marwick-head.shtml', 5.25, 100, 2.0, 'This clifftop route through the RSPB Reserve at Marwick Head leads to the Kitchener Memorial overlooking the final resting place of HMS Hampshire.', 59.0969, -3.3467),
('8b6dbb53-2026-5a30-a3e4-2396bc51f0be', 'Meall Beag, Donside', 'https://www.walkhighlands.co.uk/cairngorms/meall-beag.shtml', 3.25, 180, 1.0, 'A short walk on forest paths and tracks with some steep climbs and good views over the rolling landscape of Strathdon.', 57.2121, -3.0013),
('8b77f3d4-6f56-5be1-aeeb-50557c147f04', 'Gleouraich and Spidean Mialach', 'https://www.walkhighlands.co.uk/fortwilliam/spideanmialach.shtml', 12.0, 1130, 7.0, 'These two fine, steep and rocky Munros are in fairly close proximity to the road and some excellent stalkers paths make this an enjoyable and easier climb than most high peaks in the Northwest.', 57.0757, -5.2532),
('8b788bc8-5252-5908-84a1-ef4b4b8fe32c', 'Leannach Forest circuit', 'https://www.walkhighlands.co.uk/lochlomond/leannach.shtml', 8.0, 160, 2.5, 'This easy forestry circuit has great views over the core of the Trossachs, with its lochs and tree-clad hills. Part of the Queen Elizabeth Forest Park, the route has fine views of Ben A''an across Loch Achray and also of Ben Venue, a popular peak above Loch Katrine.', 56.213, -4.394),
('8b856406-2f38-5fa0-bab7-7a8a942f4923', 'Macquarie Mausoleum, Gruline', 'https://www.walkhighlands.co.uk/mull/macquarie-mausoleum.shtml', 1.5, 8, 0.6666666666666666, 'Less of a walk than somewhere to visit, the Macquarie Mausoleum is reached by a short, easy walk through pleasant farmland. The track is suitable for baby buggies, three gates to open on the route.', 56.4906, -5.98946),
('8bce9463-c5bf-543f-b80d-d0ba3b61360c', 'Beinn Stacath, from Glen Buckie', 'https://www.walkhighlands.co.uk/lochlomond/beinn-stacath.shtml', 12.75, 653, 5.5, 'Unnamed on Ordnance Survey maps, Beinn Stacath is sometimes spelt Stacach and is also known by the names Stob Fear-tomhais or  Ceann na Baintighearna, (the latter is actually its northern top above the forestry flanking Loch Voil). The approach from Glen Buckie in the east is the most straightforward, up boggy and rather featureless slopes.', 56.327, -4.38009),
('8c1a8e2b-a9d9-5901-ab01-9311415e5e25', 'Baosbheinn, near Gairloch', 'https://www.walkhighlands.co.uk/torridon/baosbheinn.shtml', 23.0, 1190, 9.0, 'This fine sandstone mountain, a Corbett, has great character. Baosbheinn is a magnificent viewpoint both for the higher Torridon mountains and over the sea to the islands.', 57.6873, -5.59741),
('8c387e1e-fd95-544b-bdf2-eeb306c242e5', 'Sgùrr Dhomhnuill via Ariundle Oakwoods', 'https://www.walkhighlands.co.uk/fortwilliam/sgurr-dhomhnuill.shtml', 17.75, 913, 8.5, 'Sgùrr Dhomhnuill is the highest mountain in Ardgour; a steep-sided, conical peak at the heart of a wild and rugged area. The Ariundle Oakwoods provide a magnificent approach.', 56.711, -5.5542),
('8c47f954-6e32-50c8-b8ae-2192f10d2da2', 'Gaick Corbetts: An Dun and Meall Creag an Loch', 'https://www.walkhighlands.co.uk/perthshire/gaick-corbetts.shtml', 28.0, 959, 10.0, 'The two, steeply flanked Corbetts that rise on either side of Loch an Duin at the top of the Gaick Pass give an excellent hillwalk in a unique corner of Scotland, with a feeling of remoteness. The tops of the hills are flat and spacious, but are divided from their neighbours by great ice-gouged trenches. A mountain bike could be used to shorten the approach.', 56.8064, -4.093),
('8c538d70-3ed8-59f1-bdd4-7e67101cf8be', 'Urquhart Bay Woods, Drumnadrochit', 'https://www.walkhighlands.co.uk/lochness/Urquhartwoods.shtml', 2.0, 8, 0.75, 'A short stroll through fine alder woodland managed by the Woodland Trust, feeling a world away from the busy tourist hub of Drumnadrochit. There used to be a footbridge giving access to the shores of Loch Ness, but now this optional extension involves crossing a river - possible only when water levels are low.', 57.3319, -4.4683),
('8c71297f-8779-54c9-9f2a-a4c1347b4d97', 'Falls of Shin', 'https://www.walkhighlands.co.uk/sutherland/falls-of-shin.shtml', 3.25, 90, 1.0, 'The Falls of Shin is one of the best known sights in the area. They are renowned not for their height, but for their great power, and salmon can often be seen attempting to pass up the falls in the summer and early autumn.  This walk combines a visit to the falls, down the river and back through the woods before making a loop through higher woodland with some lovely views.', 57.9602, -4.4079),
('8c8fbd22-620d-5726-b7e9-75471b9fcf4f', 'Ben Donich, via Rest and Be Thankful', 'https://www.walkhighlands.co.uk/lochlomond/ben-donich.shtml', 7.5, 575, 4.5, 'With a high-level start point, a direct path and fine views, Ben Donich makes an excellent objective for a shorter hillwalk. There is a little rocky ground with a slight scramble down before the summit to add a little character.', 56.2219, -4.8599),
('8cbbe6b2-3557-51f7-8983-cf74a8888034', 'Clackmannan and the Towers', 'https://www.walkhighlands.co.uk/fife-stirling/clackmannan.shtml', 6.25, 78, 2.0, 'This circular links the old county town of Clackmannan with the new one, Alloa, visiting two fine medieval tower houses along the way. There are views towards the Ochils, but the walk does head through the large housing estates which now surround the Alloa tower.', 56.1073, -3.7519),
('8cbe7dca-9a43-59ac-bb53-de7e67b040c5', 'Ben Hope', 'https://www.walkhighlands.co.uk/sutherland/ben-hope.shtml', 7.5, 946, 6.0, 'The most northerly of the Munros, Ben Hope rises as a fine isolated peak and is a magnificent viewpoint. The ascent is short but steep and gives a grand introduction to the vast wilderness of the extreme North.', 58.3904, -4.6328),
('8d23386f-da82-5a08-8904-2c02e4c2ad72', 'Doune Hill and Beinn Eich, from Luss', 'https://www.walkhighlands.co.uk/lochlomond/doune-hill.shtml', 18.5, 966, 6.5, 'Doune Hill is the highest of the grassy, sculpted Luss Hills. The approach along the ridge from Beinn Eich makes a fine walk, but the return through Glen Mollochan is boggy.', 56.1028, -4.6397),
('8d5b3784-4f28-57de-9f54-8226a3e605ed', 'Tomintoul village circular', 'https://www.walkhighlands.co.uk/cairngorms/tomintoul-circular.shtml', 4.25, 72, 1.0, 'Tomintoul is reputedly the highest village in the Highlands. This waymarked circular walk explores the immediate environs of the village, visiting a bird hide as well as giving some superb views up Strath Avon towards the Cairngorms.', 57.251, -3.3789),
('8d9ad40d-09d2-5b9b-a535-066b96ac8fe3', 'Beinn Alligin', 'https://www.walkhighlands.co.uk/torridon/Beinnalligin.shtml', 10.5, 1190, 8.0, 'Beinn Alligin means the Mountain of Beauty or Jeweled Mountain - and it lives up to the name. This is the easiest of the three famous Torridon ridge traverses, with spectacular views and stunning terrain. It includes a traverse of the Horns, which offer reasonably straightforward summer scrambling.', 57.5589, -5.56391),
('8dc58f72-d5c4-5720-8c55-2480070de47a', 'Bellabeg forest walk, Strathdon', 'https://www.walkhighlands.co.uk/cairngorms/bellabeg.shtml', 3.5, 119, 1.0, 'This pleasant circular walk climbs through forestry and gives excellent views over Strathdon.', 57.2041, -3.0726),
('8de0cc31-11ca-5677-a42e-a163c0cfd3ae', 'Abriachan Trails', 'https://www.walkhighlands.co.uk/lochness/Abriachan.shtml', 9.2, 261, 3.5, 'This superb and varied walk takes in both woodland and open moors using trails laid out by the Abriachan Forest Community Trust. There are excellent views and a great many things to see along the way.', 57.3863, -4.4297),
('8de1c963-fec5-549c-9310-f3fdf0caebac', 'Lady Mary''s walk and Laggan Hill circular', 'https://www.walkhighlands.co.uk/perthshire/laggan-hill.shtml', 9.0, 220, 2.5, 'This excellent and varied circuit takes in the beautiful Lady Mary''s Walk along the River Earn, a climb over Laggan Hill, a visit to Crieff''s MacRosty Park and the Glenturret Distillery.', 56.3896, -3.854),
('8debd1be-7ba8-5fd9-8364-f6946fc30721', 'Fraserburgh Bay and Waters of Philorth', 'https://www.walkhighlands.co.uk/aberdeenshire/fraserburgh-bay.shtml', 6.5, 10, 1.5, 'Walk across the fabulous golden sand of Fraserburgh Bay and then follow the Philorth Water, a rare habitat for many seabirds. Cross the dunes before returning along the beach with good views of Fraserburgh and Kinnaird Head lighthouse.', 57.6852, -2.0019),
('8e222b00-d484-5608-bd1e-3972754be6c0', 'Berwickshire Coast Path 4: Eyemouth to Berwick', 'https://www.walkhighlands.co.uk/borders/eyemouth-berwick.shtml', 19.0, 340, 6.0, 'The final stage of the Berwickshire Coastal Path runs from the fishing port of Eyemouth to Berwick-upon-Tweed, across the Border in England. The route has some splendid coastal scenery with striated cliffs and a fine natural arch.', 55.8734, -2.09187),
('8e2e06f0-bec0-5d38-84d0-05775155beff', 'Scalloway and Bur Wick', 'https://www.walkhighlands.co.uk/shetland/scalloway.shtml', 6.75, 142, 3.0, 'Scalloway - with its impressive ruined castle - was the ancient capital of Shetland. This circular walk heads round the rough coastline to the west of the town to the bay of Bur Wick before returning via a hill track.', 60.137, -1.2757),
('8e4fc8ea-7ac0-535c-a91e-3fe98d265cac', 'Yellowcraig Beach circuit, from Dirleton', 'https://www.walkhighlands.co.uk/lothian/dirleton-fidra.shtml', 7.85, 55, 2.5, 'Yellowcraig must rank as one of the finest beaches in East Lothian, a stunning stretch of sand with views to the islands of Fidra, Craigleith and the Bass rock. It is the main draw of this excellent circular walk beginning from the picturesque village of Dirleton, famed for its grand castle. The return passes through some of Scotland''s most exclusive housing developments.', 56.0453, -2.7809),
('8e52e4be-c124-5ae2-a26b-731c4c68fba8', 'Ben Aigan', 'https://www.walkhighlands.co.uk/moray/ben-aigan.shtml', 8.0, 275, 3.0, 'Ben Aigan is largely covered with forestry plantations but the summit area rises clear to give some of the most extensive views over Moray, from the coastal plain to the distant Cairngorms. The ascent is a straightforward hillwalk.', 57.5263, -3.1151),
('8e52f90a-dcff-5744-88c6-47961ad6f1ba', 'Dog Falls and Coire Loch, Glen Affric', 'https://www.walkhighlands.co.uk/lochness/Dogfalls.shtml', 6.0, 254, 2.5, 'This stunningly beautiful walk leads through ancient Caledonian Pine Forest. Foaming cascades in a dramatic rocky gorge, stunning natural woodland of pine and birch, a beautiful lochan, and superb views up the glen to the mountains; everything you could wish for on a forest walk is here.', 57.3125, -4.8523),
('8e8ab231-c422-5589-a0fc-fbb1b6ec7cb3', 'Moul of Eswick and Ling Ness, South Nesting', 'https://www.walkhighlands.co.uk/shetland/moul-of-eswick.shtml', 7.75, 172, 3.0, 'This circular coastal walk explores two headlands in the little visited district of South Nesting. The area is a great place to watch for otters.', 60.266, -1.1194),
('8ea8cc2e-1d4e-5dd9-940f-4377e996fb31', 'Buachaille Etive Mòr', 'https://www.walkhighlands.co.uk/fortwilliam/buachailleetivemor.shtml', 13.0, 1110, 9.0, 'Buachaille Etive Mòr is one of the best known and loved of all the Munro peaks.  The epic view of the mountain from the main A82 road makes it appear quite unassailable and is one of the most photographed sights in Scotland.', 56.6644, -4.9045),
('8ebef624-e9f0-54ed-b1a1-a9eb480adb95', 'Elgin Explorer', 'https://www.walkhighlands.co.uk/moray/elgin-riverside.shtml', 4.5, 18, 2.0, 'This short walk is an exploration of the former Cathedral City of Elgin. The route begins in the heart of the town, visits the High Street, the ruins of the Cathedral, and the banks of the River Lossie before finishing with a visit to the prominent monument to the Duke of Gordon.', 57.6486, -3.3159),
('8ed85d41-ff85-5574-bac9-9e972e887d4c', 'Culzean Castle Country Park, from Maidens', 'https://www.walkhighlands.co.uk/glasgow/culzean-castle.shtml', 9.0, 116, 3.5, 'This enjoyable walk from Maidens sets out along the coast to visit the Culzean Castle Country Park. The route has a bit of everything - beach, fine woodlands, sea views, attractive lochs and a truly spectacular stately castle. The grounds are free to enter from Maidens but you would need to buy a ticket to visit the castle itself, or a grounds ticket for a more extended visit to the gardens.', 55.3371, -4.8127),
('8f1b9789-1c8a-5783-a6b7-cd6bab95200d', 'Creag an Dubh Loch and Broad Cairn, Glenmuick', 'https://www.walkhighlands.co.uk/cairngorms/creag-an-dubh-loch.shtml', 23.0, 813, 8.0, 'Whilst the nearby cliffs of Lochnagar are famed and celebrated, the magnificent beetling black precipice of Creag an Dubh-loch is much less known. This fine hillwalk visits this great crag and its lonely loch before ascending Broad Cairn to make a higher level return above Loch Muick. A second Munro, Cairn Bannoch, could easily be added to the route.', 56.9523, -3.1362),
('8f294c56-00fb-5b53-bce7-46729ecba15a', 'Spectacle E''e falls circular, Strathaven', 'https://www.walkhighlands.co.uk/glasgow/strathaven.shtml', 5.5, 96, 2.0, 'This circular walk from the bustling market town of Strathaven heads out along the road and then down to cross the Avon Water before visiting a ruined mill and the Spectacle E''e waterfalls. The falls were named as a result of an incident involving a local man who fell in love with the miller''s daughter. The miller disapproved of the union and ended their relationship. As revenge the lad placed an eye glass in the mill''s thatch, causing it to catch fire and the mill to be burned to the ground.', 55.6765, -4.0659),
('8f495e26-8a45-56ff-81ef-77c1c772b1db', 'An Ruadh-stac', 'https://www.walkhighlands.co.uk/torridon/an-ruadh-stac.shtml', 15.0, 1060, 7.0, 'An Ruadh-stac is a steep-sided Corbett, a near neighbour of the Munro Maol Chean-dearg. Though slightly lower, it is perhaps the finer of the two peaks and provides a more dramatic and challenging ascent.', 57.4498, -5.40741),
('8f6d9e07-36ed-5caf-af30-210e58922a63', 'Dollar to Tillicoultry on the Devon Way', 'https://www.walkhighlands.co.uk/fife-stirling/dollar-tillicoultry.shtml', 5.0, 5, 1.25, 'This popular section of the Devon Way runs along an old railway line and has good views of the Ochils, and the River Devon, although the busy main road is a continuous presence. Popular with families, cyclists and dog walkers, it can be done with baby buggies and it is possible to return by bus.', 56.1629, -3.671),
('8fab8f38-ac1b-5842-8b87-7bb51eec8816', 'Plockton Explorer', 'https://www.walkhighlands.co.uk/kintail/Plockton.shtml', 3.25, 43, 1.0, 'Explore one of Scotland''s most picturesque villages - taking in the bay, the beautiful cottages, some hidden corners and a fine viewpoint looking to Applecross and the Isle of Skye.', 57.3378, -5.651),
('8fb89469-ad68-51cf-a129-e9dfa1872e42', 'The Paps of Jura', 'https://www.walkhighlands.co.uk/islay-jura/paps-of-jura.shtml', 16.5, 1401, 10.0, 'The round of the Paps of Jura is a bona fide Scottish classic hillwalk. These three great cones of rock and scree give a challenging walk with views that are - on a clear day - unforgettable.', 55.8789, -5.9268),
('9020c0fd-2659-5647-b5a6-4de5a407b32c', 'Monks Rigg and Braid Law, Nine Mile Burn', 'https://www.walkhighlands.co.uk/lothian/monks-rigg.shtml', 6.5, 251, 3.0, 'Follow the old Monks Road up over Cap Law into the heart of the Pentlands before returning via an old path through the Braid Law col. This fairly straightforward hillwalk gives some great views.', 55.8057, -3.3145),
('902289e5-94d4-5c00-9b56-0ab1138c8d42', 'Kerloch, from the north', 'https://www.walkhighlands.co.uk/aberdeenshire/kerloch.shtml', 10.0, 413, 3.5, 'Kerloch is the highest hill of the foothills of the Mounth range that lie to the east of the Cairn o'' Mount. Although isolated, this fine viewpoint can be reached via a network of forestry tracks.', 57.0149, -2.4968),
('90250d66-7466-58ef-a20a-d9bf480b3046', 'Ben Oss and Beinn Dubhchraig, near Tyndrum', 'https://www.walkhighlands.co.uk/argyll/ben-oss.shtml', 17.0, 1230, 8.0, 'Ben Oss and Beinn Dubhcraig are satellites of mighty Ben Lui. Although the mountains themselves are not particularly distinguished, the approach walk leads through natural pine and birch forest and is very picturesque, though also very wet. Beinn Dubhcraig offers a fine view down Loch Lomond, whilst the Ben Lui looks simply magnificent from Ben Oss.', 56.425, -4.6868),
('90277502-f9e3-5c7c-ae17-f0560bc936b9', 'Dumyat by the hill path', 'https://www.walkhighlands.co.uk/fife-stirling/dumyat.shtml', 7.0, 290, 2.5, 'Dumyat is the fierce little cub of the Ochils, far lower than the main range but rocky packed with character. It has a superb position on the fringe of the range overlooking Stirling and the Central Belt; the views are superb. A perfect first hillwalk on a fine day, this route avoids the very steep slopes on the southern flank of the hill.', 56.1562, -3.9171),
('9037448a-fa87-509a-b456-86aae219174d', 'Bridge over the Atlantic circuit, Seil', 'https://www.walkhighlands.co.uk/argyll/clachan-seil.shtml', 5.75, 85, 2.0, 'This enjoyable circuit heads from the Bridge over the Atlantic at the north end of Seil to the delightful Phuilladobhrain Anchorage, a good place for birdwatching and otter spotting. This is then followed by a rougher coastal walk (difficult at highest tides) to Camuslaich before returning by the road.', 56.3177, -5.5836),
('9050d6c0-8e17-529b-97bd-cf90a9dd8b5a', 'Bone Caves circuit, near Inchnadamph', 'https://www.walkhighlands.co.uk/ullapool/bonecaves.shtml', 4.5, 210, 2.0, 'This beautiful and popular walk leads up a limestone valley to visit the dramatic Bone Caves. These cave openings on a steep slope at the foot of a cliff have been excavated and were found to contain the remains of species such as lynx, reindeer and polar bear which once roamed the area.', 58.1157, -4.9666),
('90606a6d-f211-5835-8e9c-f0fad6a7117c', 'Arbroath Town Trail', 'https://www.walkhighlands.co.uk/angus/arbroath.shtml', 9.25, 62, 3.0, 'Arbroath is an old fishing port, famed for its ''smokies'' - smoked haddock still produced in tiny smokeries in the harbour area. It''s best known for its Abbey and the Declaration of Arbroath which was signed there - an assertion of Scottish Independence from the days of King Robert the Bruce.', 56.5561, -2.5843),
('908348ab-2120-534f-897b-1adbee3054fc', 'St Ninian''s Cave from Burrowhead', 'https://www.walkhighlands.co.uk/galloway/burrowhead-st-ninians.shtml', 7.25, 135, 3.0, 'Discover St Ninian''s Cave as the finale to this dramatic clifftop walk along the Machar coastline.', 54.6831, -4.4047),
('9086bf4b-55ed-5723-bc59-285be232dfa1', 'Kirkcudbright Explorer', 'https://www.walkhighlands.co.uk/galloway/kirkcudbright.shtml', 9.5, 125, 2.5, 'Kirkcudbright is an attractive and fascinating small town. Known as the Artists town, it was associated with both the Glasgow Boys and the Scottish Colourists, and even today has several galleries. This short exploration takes in the historic buildings of the town centre before heading around the St Mary''s Isle peninsula and climbing up into Barhill Wood.', 54.8373, -4.051),
('9086f67b-3d4b-5289-a8fe-8c4a211e8150', 'Nairn East Beach, Kingsteps and Culbin', 'https://www.walkhighlands.co.uk/moray/nairn-dunes.shtml', 10.0, 45, 3.0, 'Varied walk taking in the beach and dunes to the east of Nairn, then a section of the Culbin forest before returning along a minor road to Kingsteps from where a path leads back to the dunes. The route usually involves an easy beach paddle but can be impassable at high tides.', 57.5903, -3.86),
('90b06569-65f1-58a8-a99f-7a49f8f83251', 'Duirinish and Drumbuie coast', 'https://www.walkhighlands.co.uk/kintail/Duirinish.shtml', 3.0, 35, 1.0, 'This idyllic short walk heads round a beautiful section of coastline, with wonderful views throughout. There is a good chance of seeing seals or otters.', 57.32, -5.69063),
('90b2e1eb-c568-530c-aa45-f365cfd8ad30', 'Dùn Ara and Glengorm Castle, near Tobermory', 'https://www.walkhighlands.co.uk/mull/dun-ara.shtml', 3.75, 92, 1.5, 'This out-and-back walk leads from the splendid Glengorm Castle across the pastures to the site of an old fort at Dùn Ara on the coast. There are wide sea views, with perhaps the opportunity to spot an otter or - for the brave - try a dip in the open sea ''bathing pool''.', 56.636, -6.1743),
('90b727a3-6b92-56cf-8756-e0ca4e5188c0', 'Flodigarry Fossils Walk, Flodigarry', 'https://www.walkhighlands.co.uk/skye/flodigarry.shtml', 1.5, 47, 1.0, 'A short walk exploring the coastline at Flodigarry (Flòdaigearraidh) - one of the best spots on Skye for hunting fossils.', 57.6619, -6.2525),
('910a5619-e0aa-59eb-a963-bc9676a8f474', 'Old Aberdeen and beach circuit', 'https://www.walkhighlands.co.uk/aberdeenshire/old-aberdeen.shtml', 8.0, 90, 3.0, 'An unexpected mixture of fabulous sea front, picturesque riverside and woodland combined with an exploration of the cobbled streets and ancient buildings, university and cathedral of Old Aberdeen.', 57.1556, -2.0787),
('917440ad-da94-5ea7-8d48-55b234e217c8', 'Bessie''s Hill and Castle O''er, near Eskdalemuir', 'https://www.walkhighlands.co.uk/galloway/eskdalemuir.shtml', 9.0, 178, 3.0, 'This walk links the sites of two iron-age hill-top forts rising above a blanket of forestry to give open views above the River White Esk. The forts are linked by a forest track and the return is along a quiet and attractive minor road.', 55.2451, -3.182),
('918e7925-a695-592b-b43c-3b0e05727cc2', 'The Dounie, Rothes', 'https://www.walkhighlands.co.uk/moray/dounie-rothes.shtml', 5.0, 140, 2.0, 'This excellent short circular walk visits the Dounie glens to the west of Rothes, with some very pleasant woodland, interesting features and lovely views.', 57.5274, -3.2067),
('91fc38b2-186b-5ca4-b5f0-893ac6eaea3c', 'Herring Road and Clints Dod, near Stenton', 'https://www.walkhighlands.co.uk/lothian/herring-road.shtml', 19.0, 491, 5.5, 'An enjoyable circuit over the open heathery moors of the eastern Lammermuirs, giving fine views towards the North Sea. The Herring Road - and ancient route used by fishwives carrying creels of fish to market in Lauder and by the folk from the hills bringing herring back from Dunbar for use during the winter; it passes through an area occupied by a new windfarm.', 55.9445, -2.609),
('920f7872-c2aa-5488-a873-0be453bbe9d0', 'Ben Tianavaig, Braes', 'https://www.walkhighlands.co.uk/skye/bentianavaig.shtml', 5.5, 424, 3.0, 'Ben Tianavaig makes for one of Scotland''s finest short hillwalks, with a beautiful coastal position, a dramatic escarpment and simply sensational views.', 57.3724, -6.1458),
('9251933e-6f8e-5e75-b164-fad31ef86d41', 'Aberfeldy and Kenmore: Urlar circuit', 'https://www.walkhighlands.co.uk/perthshire/aberfeldy-kenmore.shtml', 22.0, 680, 7.0, 'This very varied walk takes in the picturesque Birks of Aberfeldy, the bleak moorlands around the Urlar burn and a return route along the Rob Roy Way, through pastures and forests with good views of Strath Tay.', 56.6157, -3.86651),
('929efcfc-6f46-503f-a016-cae629c7471c', 'Bishop Hill circular from Holl Reservoir', 'https://www.walkhighlands.co.uk/fife-stirling/bishop-hill.shtml', 12.0, 273, 4.0, 'Bishop Hill is the more neglected of the main summits of the Lomond Hills, a wedge of moorland presenting a steep flank to its western side above Loch Leven. This route from the east uses tracks and a hill-path to make a circuit.', 56.2178, -3.2527),
('92d4e4e0-388a-5b86-bd75-d038ecfe3629', 'Clisham (An Cliseam) direct route', 'https://www.walkhighlands.co.uk/outer-hebrides/clisham-direct.shtml', 5.25, 629, 4.0, 'This steep but rapid ascent of Clisham (An Cliseam in Gaelic and on OS maps) is rewarded with superb views over mountain and sea. The approach is boggy and the ascent steep; there is no path at first, higher up a clear path winds a route through the boulders.', 57.951, -6.7786),
('92e28039-9ca1-5d46-88c7-436601ce432b', 'Sands of Rothiesholm circuit, Stronsay', 'https://www.walkhighlands.co.uk/orkney/sand-of-rothiesholm.shtml', 5.75, 13, 2.0, 'The Sand of Rothiesholm is perhaps Stronsay''s finest sandy beach. This circular walk runs the length of the beach before making a rougher return along the north shore of the peninsula.', 59.1082, -2.6356),
('934b208f-010b-5dc8-aa3c-ed939fa59edd', 'Devilla Forest - Four Lochs, near Kincardine', 'https://www.walkhighlands.co.uk/fife-stirling/devilla-forest.shtml', 9.0, 64, 3.0, 'Devilla Forest is not the monotonous plantation you might expect, with many deciduous trees scattered amongst the Scots Pines, and a series of hidden lochs, each with its own unique character. The wildlife includes red squirrels, dragonflies and wildfowl.', 56.0655, -3.6656),
('93726ae7-b549-587f-b4d2-9a32bb1daa23', 'Glen Nant Oakwoods, near Taynuilt', 'https://www.walkhighlands.co.uk/argyll/glen-nant.shtml', 3.25, 126, 1.5, 'This waymarked forest circuit leads through the beautiful oakwoods of Glen Nant, once a hive of activity as charcoal burners produced fuel for the nearby Bonawe Furnace. There are views across to Ben Cruachan.', 56.3962, -5.21063),
('9375ffad-b167-553a-9436-42ca6340a346', 'East Cairn Hill and Mount Maw circuit, West Linton', 'https://www.walkhighlands.co.uk/lothian/east-cairn-hill.shtml', 13.75, 488, 5.5, 'This grand circuit follows the open ridges of the more remote Western Pentlands. There are superb views throughout, over the main Pentlands range, over Edinburgh and the Forth Bridges, and into the Borders. The return follows the Thieves'' Road - an old cattle droving route.', 55.7762, -3.3935),
('938e5269-844b-5940-a470-10ea2341de6f', 'Cladh Hallan Roundhouses, nr Daliburgh (Dalabrog)', 'https://www.walkhighlands.co.uk/outer-hebrides/hallan.shtml', 3.0, 8, 1.0, 'This short circular walk visits the Cladh Hallan roundhouses, which date back to the late Bronze Age. It then heads down to visit the magnificent beach which runs along the length of South Uist.', 57.1703, -7.4036),
('9406891a-fd29-5a1b-aaee-19fc125e9e1c', 'Conic Hill, Balmaha', 'https://www.walkhighlands.co.uk/lochlomond/conic-hill.shtml', 4.0, 350, 3.0, 'Conic Hill is a sharp little summit rising above Balmaha. Right on the Highland Boundary Fault, this short hillwalk offers truly fantastic views over Loch Lomond and its many islands.', 56.086, -4.5381),
('9413c90c-dd23-5823-bf17-a2b1d9fc01a6', 'Succoth Circuit, Arrochar', 'https://www.walkhighlands.co.uk/lochlomond/succoth.shtml', 3.75, 100, 1.5, 'A straightforward circular walk that climbs up above Loch Long to give great views over Arrochar and the surrounding mountains. The walk then continues down through forestry and returns through the hamlet of Succoth.', 56.2059, -4.7511),
('9448d22f-868a-5c78-8247-0305c026af54', 'Meall Chuaich, Drumochter', 'https://www.walkhighlands.co.uk/cairngorms/meall-chuaich.shtml', 14.0, 614, 5.0, 'Meall Chuaich is a rather rounded Munro lacking any great character. Its position sitting slightly apart from the main Cairngorms ensures it is a superb viewpoint for upper Badenoch and Strathspey, as well as the Creag Meagaidh and Ben Alder ranges.', 56.9512, -4.2148),
('94778d5b-9a2e-55ce-bc67-3ae1ec69e4b5', 'Kippford and Rockcliffe circular', 'https://www.walkhighlands.co.uk/galloway/kippford-rockcliffe.shtml', 5.5, 140, 2.0, 'A popular wooded coastal walk between the two picturesque waterside villages of Kippford and Rockcliffe, taking in two optional viewpoints. Cafe and pubs in Kippford.', 54.8798, -3.8141),
('948b75ce-c2e3-5292-950e-a1f484d6d94c', 'Wigtown explorer', 'https://www.walkhighlands.co.uk/galloway/wigtown.shtml', 8.5, 70, 2.0, 'If you can pull yourself away from browsing the bookshops, this route explores something of Wigtown''s environs, including a visit to the Martyrs'' Stone where people were drowned for their beliefs, and the bird-rich marshland around the head of Wigtown Bay.', 54.8685, -4.4427),
('948ce8ab-fd1d-5ae4-9de0-4d4c230e1536', 'Ben Klibreck', 'https://www.walkhighlands.co.uk/sutherland/ben-klibreck.shtml', 14.25, 930, 7.0, 'Ben Klibreck is a huge, isolated massif rising high at the heart of the vast, empty moorlands that comprise the central part of Sutherland. This route avoids the worst of the bogs by making an enjoyable approach along the ridge, through there are still a couple of wet sections. The fabulous summit views are of a remarkably empty land.', 58.2085, -4.4993),
('949cfbc5-b46e-5975-b192-bed17da8f690', 'Beinn Dearg - the Four Munros circuit', 'https://www.walkhighlands.co.uk/ullapool/beinndearg.shtml', 27.0, 1569, 11.0, 'Beinn Dearg is the highest summit on this fine round of four Munros. The second peak, remote Cona Mheall, is on the opposite side of impressively rocky and wild Coire Ghranda whilst Meall nan Ceapraichean and Eididh nan Clach Geala extend the route to give a grand traverse with spectacular views across towards Assynt.', 57.8198, -5.0625),
('94a2c922-8436-5ec8-bbfc-70f75882f000', 'Beinn Bhan, Glen Loy', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-bhan.shtml', 8.5, 771, 5.0, 'This straightforward Corbett makes a good short day out. The ascent is something of a treadmill but is rewarded by a plateau traverse on perfect springy turf with superb views to Ben Nevis, Loch Arkaig, Loch Lochy and all the surrounding mountains.', 56.9015, -5.0793),
('94b09c01-5c6e-5d95-b182-75e48f48c17e', 'Dunnottar Castle, from Stonehaven', 'https://www.walkhighlands.co.uk/aberdeenshire/dunnottar-castle.shtml', 5.0, 144, 2.0, 'Dunnottar Castle is the most spectacular of all ruined coastal fortresses, perched on a gigantic rocky outcrop almost detached from the mainland. It is the highlight of this short coastal circuit which extends southwards from the harbour at Stonehaven. For the return you can retrace your steps to make the most of the scenery, ride the Land Train service (summer only), or follow the path as described beside a minor road.', 56.961, -2.2016),
('94fe34f2-7491-5d19-865d-c4d9fc6178b9', 'Knockan Crag trail', 'https://www.walkhighlands.co.uk/ullapool/knockancrag.shtml', 2.0, 185, 1.0, 'This interpretative trail brings the geology of the Moine Thrust to life as the path climbs past the exposed rocks and up onto the top of the Knockan Crag. From here there are spectacular views over Assynt. The trail includes sculptures and poetry as well as places to sit and a treasure hunt for younger children.', 58.0335, -5.0709),
('950636db-c911-52f8-b66d-5a05eed70b67', 'Inver Walk and Pine Cone Point, Dunkeld', 'https://www.walkhighlands.co.uk/perthshire/inver-walk.shtml', 10.6, 186, 3.0, 'This excellent waymarked walk is full of interest. It leads into the lower section of the Hermitage and offers a chance to detour up to Pine Cone Point - a modern folly with a fine view. The route then returns along the banks of the mighty River Tay, passing Niel Gow''s Oak and through the hamlet of Inver.', 56.5616, -3.60731),
('950d1bdc-1f1c-5768-b9fe-12ea27146fba', 'Beinn Bhragair, Pairc Shiaboist', 'https://www.walkhighlands.co.uk/outer-hebrides/beinn-bhragair.shtml', 6.75, 243, 2.5, 'This short hillwalk to the summit of Beinn Bhragair is rewarded with excellent views in all directions. An easy approach on an old road is followed by a short, steep climb which is often boggy underfoot.', 58.314, -6.6698),
('95120f8e-c04b-53c8-8f3a-d3b12b5c0661', 'Kirriemuir Explorer', 'https://www.walkhighlands.co.uk/angus/kirriemuir.shtml', 4.75, 107, 1.5, 'The town of Kirriemuir is not just the Gateway to the Angus Glens - it''s well worth a visit in its own right. This walk explores the town''s most interesting features - many associated with its most famous son, JM Barrie - the creator of Peter Pan. It also ascends Kirriemuir Hill for views towards the Glens, and returns through the Den.', 56.6716, -3.0044),
('9529b348-fcbc-5865-bf3e-3ca361d7c85b', 'Brodie Castle and Pond', 'https://www.walkhighlands.co.uk/moray/brodie-castle.shtml', 3.25, 16, 1.0, 'This pleasant short walk heads through the grounds of Brodie Castle, visiting its woodland lake and a 1,200 year old Pictish carved stone. The walk is famed for its daffodils in the spring. The castle itself is well worth a visit (admission charge).', 57.5956, -3.7144),
('9567c203-c1be-5f5a-a3f8-e141b4ff7d76', 'River Averon, Alness', 'https://www.walkhighlands.co.uk/ullapool/river-averon.shtml', 6.0, 150, 1.5, 'This pleasant circuit from the town of Alness runs out through the golf course at first before exploring the mature woodland on the banks of the River Averon.', 57.6968, -4.2575),
('957144fa-1c44-5975-99ea-ea268aba64c0', 'Applecross and Milltown circuit', 'https://www.walkhighlands.co.uk/torridon/milton-applecross.shtml', 3.75, 75, 1.0, 'This circuit around Applecross explores the nearby woods, crofts and loch all providing havens for wildlife. The route also visits a broch, a reconstructed round house and some historic barns. The return route has good sea views;  this short walk should leave plenty of time to explore the shore and visit the renowned Inn.', 57.4336, -5.8141),
('95a5e64e-6a7e-5665-87c7-4c1c2742c42e', 'Torinturk and Dùn a''Choin Dhuibh', 'https://www.walkhighlands.co.uk/argyll/torinturk.shtml', 2.5, 120, 1.0, 'This short forestry circuit visits some fascinating archaeological remains including a hill-top Dun or iron-age fort with stunning views.', 55.8196, -5.4998),
('95dd1efc-d8ec-5dc0-8295-a0f4e5f38ec6', 'Beinn Bhan, near Kishorn', 'https://www.walkhighlands.co.uk/torridon/Beinnbhan.shtml', 14.0, 995, 7.0, 'This majestic Applecross mountain really deserves far more renown. Beinn Bhan has dramatic fluted corries on its eastern flanks which look fantastic from the easy walk along the plateau edge giving this route the drama of the Torridon mountains without the exposure or need for scrambling; the views are simply stunning. The steep (but grassy) descent on the circular route can be avoided by returning from the summit by the outward route.', 57.4194, -5.60814),
('960af15c-b004-5d6e-9ba0-5386ec46c7ef', 'Wildcat Trail, Newtonmore', 'https://www.walkhighlands.co.uk/cairngorms/wildcattrail.shtml', 10.25, 110, 3.5, 'The Wildcat Trail is an orbital route around Newtonmore taking in the banks of the River Spey, open heather moorland, wooded glens and burbling burns. The route can either be walked as a whole or in sections, as there are various paths linking the Trail to different start points in Newtonmore. Strathspey is one of the last strongholds of the Scottish wildcat, a species in severe danger of extinction. In recent years a captive breeding program at the nearby Highland Wildlife Park has led to releasing of more wildcat to help the population recover.', 57.0593, -4.1195),
('961f47d8-792f-5ef4-ad4a-9caee156c02a', 'Ben Cruachan and Stob Daimh', 'https://www.walkhighlands.co.uk/argyll/ben-cruachan.shtml', 13.75, 1376, 9.0, 'Ben Cruachan is one of the finest Munros in the southern Highlands, with jagged peaks and fine rocky ridges as well as stunning views. The ridge walk to Stob Dàimh (misspelt Diamh on some OS maps) makes for a classic circuit around the Cruachan reservoir.', 56.3937, -5.11198),
('96369af8-c7a3-5aca-a5b1-c74374b3df23', 'Meall nan Subh, Glen Lochay', 'https://www.walkhighlands.co.uk/perthshire/meall-nan-subh.shtml', 12.75, 602, 4.0, 'The private tarmac road over the Lairig nan Lunn makes an ascent of Meall nan Subh one of the easier Corbetts, although the final slopes are rough, pathless and steep. The summit proves to be a fine viewpoint.', 56.4989, -4.476),
('965fd390-ab55-5207-ada5-d51caa930e97', 'Inverfarigaig and the Falls of Foyers', 'https://www.walkhighlands.co.uk/lochness/Inverfarigaig.shtml', 10.25, 428, 4.5, 'Varied hill and shore walk with good views of Loch Ness, taking in the Falls of Foyers.', 57.2807, -4.4537),
('966ef532-f86c-5f4b-8f86-e6dea4970c50', 'Stob Dubh, Glen Etive', 'https://www.walkhighlands.co.uk/fortwilliam/stob-dubh.shtml', 11.5, 1005, 8.0, 'This imposing Corbett rises impressively from Glen Etive and gives a grand hillwalk when tackled by its northeast ridge. Not to be confused with its nearby namesake Munro on Buachaille Etive Beag.', 56.6181, -4.9396),
('96704568-d850-5223-8f4e-5fd78b80d4fa', 'Bad na Sgalag pinewood circuit', 'https://www.walkhighlands.co.uk/torridon/badnasgalag.shtml', 7.0, 235, 2.5, 'A delightful circuit through the replanted and regenerating Loch Bad na Sgalag native pinewood. There are waterfalls and lochs and a chance to see wildlife; but the second half of the route is very boggy.', 57.6873, -5.59739),
('9681e37f-18e2-58d5-b559-568189069745', 'Loch Sligachan', 'https://www.walkhighlands.co.uk/skye/lochsligachan.shtml', 11.0, 175, 5.0, 'The footpath along the north shore of Loch Sligachan was once the main route north to Portree; today it gives a pleasant, peaceful walk with good views; you can have a drink at Sligachan before heading back.', 57.3205, -6.113),
('9683ec0b-eb89-58bb-b3bb-f6ed40ba03ed', 'Meall Tairneachan and Farragon Hill', 'https://www.walkhighlands.co.uk/perthshire/farragon-hill.shtml', 17.25, 878, 6.5, 'Between Loch Tummel and Aberfeldy is an area of lumpy, heathery hills and minor summits, with two Corbetts: Meall Tairneachan and the more distinctive Farragon Hill. Below the top of the former is a working open-cast Barytes mine and the hills are scored with hard tracks; this route follows the mine road up to the first hill and through the mine before making a pathless, more rugged approach to Farragon Hill. The mine is a dangerous industrial site; obey any instructions and if possible visit at the weekend.', 56.6812, -3.99299),
('9697d809-038c-569c-b6b3-3328480074ac', 'Esha Ness and Tangwick circuit, Northmavine', 'https://www.walkhighlands.co.uk/shetland/esha-ness.shtml', 13.75, 330, 5.0, 'This exploration around the coastal cliffs of the Esha Ness peninsula is a real Shetland classic - a superb walk with some magnificent cliff scenery as well as the chance to see seabirds, seals and otters.', 60.4897, -1.6264),
('96b98239-5d4e-5d81-8dd5-86bacc2779ea', 'Balcary Bay and Rascarrel, near Auchencairn', 'https://www.walkhighlands.co.uk/galloway/balcary-bay.shtml', 7.5, 208, 3.0, 'A Galloway coastal classic, this walk heads along the dramatic clifftops and the shoreline between Balcary Point and Rascarrel. It is deservedly popular.', 54.8265, -3.8374),
('96bd2f1c-7ae0-5b92-bdc1-434c353a1645', 'Gruinard Bay and the Eas Dubh falls', 'https://www.walkhighlands.co.uk/torridon/gruinardbay.shtml', 3.0, 90, 1.0, 'This short walk combines a visit to a beautiful sandy beach with a brief but rough hike up a beautiful glen to reach an attractive waterfall.', 57.8523, -5.45185),
('97013596-1afe-5f83-8c86-76d1783e48c4', 'Great Trossachs Path: Inversnaid to Trossachs pier', 'https://www.walkhighlands.co.uk/lochlomond/great-trossachs-path-1.shtml', 28.5, 534, 8.0, 'The Great Trossachs Path stretches from the banks of Loch Lomond at Inversnaid to Callander, linking the West Highland Way with the Rob Roy Way. Designed for both walkers and off-road cyclists, this first section of the 48km route ends at Trossachs Pier on Loch Katrine.', 56.243, -4.6852),
('9703bebb-c0b1-52c9-af06-b94b06daf49d', 'Glen Cloy and the Fairy Glen, Brodick', 'https://www.walkhighlands.co.uk/arran/glen-cloy.shtml', 9.75, 220, 3.0, 'This straightforward circular walk from Brodick leads through some lovely woodland, reaches a fine viewpoint, and returns along forestry roads and good footpaths.', 55.5783, -5.15111),
('971d41c5-e3fa-5cc9-825d-13d26ab6ee5b', 'Sandaig (Camusfearna)', 'https://www.walkhighlands.co.uk/kintail/Sandaig.shtml', 4.25, 132, 2.0, 'A short walk to visit the beautiful and atmospheric Sandaig bay. This peaceful spot was immortalised as Camusfearna in ''Ring of Bright Water'' - the famous book by Gavin Maxwell telling of his life with his pet otters at this lonely spot.', 57.1738, -5.66806),
('9725806b-4a7d-5f2e-b358-4a9ea923971a', 'River Nith circuit, Carronbridge', 'https://www.walkhighlands.co.uk/galloway/carronbridge.shtml', 3.0, 23, 1.0, 'This short circular walk from Carronbridge heads down to and along an attractive section of the River Nith.', 55.2663, -3.7811),
('972abcfd-e58f-5221-a638-121466248372', 'Cairnsmore of Carsphairn', 'https://www.walkhighlands.co.uk/galloway/cairnsmore-of-carsphairn.shtml', 11.5, 656, 5.0, 'There is Cairnsmore O Fleet and Cairnsmore O Dee and Cairnsmore O Carsphairn - the greatest of the three; or so says an old rhyme. The Cairnsmore of Carsphairn is a grassy summit that rises high above its nearest neighbours; it offers a short ascent with excellent views.', 55.2229, -4.2696),
('972bcf6e-b4d2-5724-9d0a-64a109fc9838', 'Càrn Ealasaid from the north', 'https://www.walkhighlands.co.uk/cairngorms/carn-ealasaid.shtml', 10.25, 472, 3.5, 'Càrn Ealasaid can be climbed quickly from the Lecht summit via the ski-area, or easily from Allergue to the south using a landrover track up Càrn Vaich. This northern approach is rougher but more unspoilt; the descent given is pathless and very rough but you could more easily retrace your steps.', 57.2201, -3.2863),
('9735cb88-1808-5e94-a724-7f62bf23a7f2', 'The Wastard circuit, Rosehearty', 'https://www.walkhighlands.co.uk/aberdeenshire/rosehearty.shtml', 9.2, 119, 3.5, 'The wild and rugged area stretching west along the coastline from Rosehearty is known as the ''Wastard''. This is combined with quiet country lanes and a visit to the impressive Mounthooly Doocot to make a great circuit.', 57.6988, -2.11489),
('9797dfb2-816d-54b5-8ed7-3feb48b6244f', 'Luinne Bheinn and Meall Bhuidhe, Inverie, Knoydart', 'https://www.walkhighlands.co.uk/fortwilliam/luinne-bheinn.shtml', 27.0, 1586, 13.0, 'These two remote Knoydart Munros may be less celebrated than Ladhar Bheinn, but they still provide a superlative and challenging mountain walk. Rough, rocky summits packed with character and wonderful views.', 57.0386, -5.6854),
('97b766db-1a34-5e5d-af0d-1c03893407da', 'Struie Hill, near Edderton', 'https://www.walkhighlands.co.uk/ullapool/struie-hill.shtml', 6.5, 285, 2.5, 'Struie Hill - a craggy hill topped by a radio transmitter - is a prominent feature in the landscape around the Dornoch Firth. The climb to its summit may be muddy at times, but it rewards with spectacular views over the firth, out of all proportion to the effort involved. Struie - at the opposite end of the ridge above the B9176 road - is a sub 2000 summit but is not visited on this route to the mast, which is the finer viewpoint.', 57.8392, -4.2037),
('97d1c05b-73c5-5141-89d4-f2337cb36151', 'Fairy Pool and Riverside walk, Glen Tanar', 'https://www.walkhighlands.co.uk/cairngorms/glen-tanar-riverside.shtml', 4.75, 70, 2.0, 'This delightful walk on the Glen Tanar estate combines forestry and farmland with a long, pretty riverside section. The walk is waymarked (combining the Fairy Lochan and Riverside paths), the visitor centre has information on the wildlife to be found on the estate. Toilets near the start and parking charge.', 57.057, -2.8594),
('980f5422-f607-5f28-b347-b430a0ee0afe', 'Càrn an Fhreiceadain from Kingussie', 'https://www.walkhighlands.co.uk/cairngorms/carn-an-fhreiceadain.shtml', 18.0, 682, 5.0, 'An easy climb over grouse moorland to this Corbett with good views out over the Monadhliath mountains and also down to Kingussie.', 57.0808, -4.0549),
('9833fa5c-aab9-59df-9e9d-35b66c63ab1b', 'Underground/Overground Canal Circular, Falkirk', 'https://www.walkhighlands.co.uk/fife-stirling/falkirk-tunnel.shtml', 2.5, 30, 1.0, 'A great short circular walk taking in the spectacular canal tunnel and then returning along urban paths and residential streets. The start can also be reached by walking 1km from the centre of Falkirk, or 3km along the Union Canal from the Falkirk Wheel.', 55.9926, -3.7945),
('9878ebf2-4443-530b-ad43-2744a84392d6', 'Balquhidder to Brig O''Turk via Glen Finglas', 'https://www.walkhighlands.co.uk/lochlomond/balquhidder-turk.shtml', 14.5, 295, 6.0, 'This moorland through route links Ballimore, near Balquhidder to Brig O''Turk via picturesque Glen Finglas. Transport needs to be arranged to return to the start. A superb remote walk with dramatic scenery on an old drover''s route.', 56.327, -4.3802),
('987cd2b4-62a1-55a6-86b6-3f605aacdc6a', 'River Dee riverside walk, Braemar', 'https://www.walkhighlands.co.uk/cairngorms/braemar-riverside.shtml', 5.0, 60, 2.0, 'This pleasant circular walk from Braemar takes in the confluence of the two main rivers, the Dee and the Clunie and then climbs gently through birch woods to return to the centre of the village. There are good open views up the strath and the chance to explore the pretty centre of Braemar.', 57.0079, -3.3983),
('987ee463-5444-5e9e-8c82-f1f3b8a79412', 'Kirkwall Explorer and the Peedie Sea', 'https://www.walkhighlands.co.uk/orkney/kirkwall-explorer.shtml', 3.25, 3, 1.0, 'Explore the historic heart of Kirkwall, including the impressive St Magnus Cathedral and the narrow streets where the notorious ball-game the Ba is played, before heading out to the Peedie Sea and the busy harbour.', 58.9849, -2.9623),
('9889aabe-d8f2-573a-872c-9419a3eef441', 'Meall a'' Phùbuill, from Glen Loy', 'https://www.walkhighlands.co.uk/fortwilliam/meall-a-phubuill.shtml', 15.0, 738, 6.0, 'Meall a''Phùbuill is a rather rounded Corbett in a little visited area of moors and rounded hills above the heads of Glen Loy and Gleann Suileag. This is a worthwhile walk with some interesting views.', 56.9146, -5.1338),
('989b61a0-49bc-58f1-bc8f-56f9bb1889bc', 'Sgùrr a'' Mhuilinn and Meallan nan Uan, Strathconon', 'https://www.walkhighlands.co.uk/lochness/sgurr-a-mhuilinn.shtml', 13.0, 1085, 7.0, 'This pair of Corbetts make for a fine hillwalk from the upper reaches of lovely Strathconon. It is well worth including the more northerly outlying top for a grand panorama of the Fannichs and northwest Highlands across Strath Braan.', 57.5482, -4.852),
('98a53934-6f6c-5a55-985a-33d20d7e2e0d', 'Commando Memorial & High Bridge, Spean Bridge', 'https://www.walkhighlands.co.uk/fortwilliam/commando-memorial.shtml', 4.5, 82, 1.5, 'This easy circular route links two historic sites, passing through lovely woodland by the River Spean, with great views to Ben Nevis throughout. The ruins of High Bridge are dangerous and must not be accessed.', 56.8985, -4.9448),
('98e618c5-9b1b-5425-9c68-b8cec2fee15b', 'Slaggan Bay beach, near Aultbea', 'https://www.walkhighlands.co.uk/torridon/slaggan.shtml', 10.0, 100, 3.0, 'A pleasant and straightforward walk passing a loch with waterlilies and the ruins of Slaggan before reaching the sandy beach at Slaggan Bay. The walk can be extended to a long circuit by heading north along the coastline from the beach, round Greenstone Point and back by Opinon.', 57.8866, -5.56536),
('98f38068-8159-50b9-a8bd-c0c2404ea7b7', 'Pulpit Hill and Gallanach, Oban', 'https://www.walkhighlands.co.uk/argyll/gallanach.shtml', 7.0, 180, 2.0, 'Beginning with a climb to the fine viewpoint of Pulpit Hill above Oban, this walk explores the countryside immediately to the south of the town. It can either be walked as an approach to Kerrera, as a one-way walk with the bus back (school times/dates only so careful planning needed), or as described here, as a circuit in its own right.', 56.412, -5.47253),
('99018b3f-ce65-520b-b452-f50a4715fed6', 'Sand to Applecross Bay', 'https://www.walkhighlands.co.uk/torridon/Sandapplecross.shtml', 7.0, 183, 2.0, 'An easy linear walk between the beautiful sandy bays at Sand to the more pebbly Applecross Bay with great views over to Raasay, Skye and Rona. The walk can be done in either direction or as a return walk - the time and distance given are for one way.', 57.4748, -5.86482),
('99040b81-6cfc-5db9-b954-48b2ba8d64aa', 'Drummond Hill and Black Rock, Kenmore', 'https://www.walkhighlands.co.uk/perthshire/drummond-hill.shtml', 7.0, 270, 2.0, 'Drummond Hill has three waymarked walks; this route combines the two shorter ones to visit the Black Rock viewpoint over Loch Tay, Kenmore and the enormous Taymouth Castle before returning through woods where red squirrels, crossbills and the rare capercaillie live.', 56.59, -4.00196),
('990542f4-54f0-52a0-824b-8c019e5cb810', 'Suilven', 'https://www.walkhighlands.co.uk/ullapool/suilven.shtml', 20.0, 947, 9.0, 'Suilven may be only 731 metres high, but its remarkable outline make it one of Scotland''s best known and most easily identified mountains. Its position in the heart of Assynt''s cnoc-and-loch landscape and superb views make it one of the finest peaks in Britain.', 58.1461, -5.2174),
('99154d90-b4ac-58b0-97c1-a94f7fb08674', 'Meall Dearg from the north', 'https://www.walkhighlands.co.uk/fortwilliam/meall-dearg.shtml', 8.5, 905, 6.0, 'If you want to avoid the scrambling on the Aonach Eagach, this approach to Meall Dearg - the Munro in the centre of the ridge - avoids any scrambling. The going is boggy but the summit rewards with fabulous views of this amazing ridge.', 56.7016, -5.03586),
('99583a09-a745-5615-814b-a37f3f8276eb', 'Yarrows Archaeology Trail', 'https://www.walkhighlands.co.uk/sutherland/yarrows.shtml', 3.5, 110, 2.0, 'The moorlands south of the Loch of Yarrows are rich in archaeological remains. From bronze-age chambered cairns to a fine iron-age broch this walk offers much for the imaginative walker to see. It is usually very wet underfoot, however, and more strenuous than the distance suggests.', 58.3751, -3.1884),
('996f9865-a42f-5545-9edf-8e021f99188c', 'Loch Coulin and Loch Clair', 'https://www.walkhighlands.co.uk/torridon/Lochclair.shtml', 9.6, 110, 3.5, 'This stunning, almost level circuit heads  past Loch Clair and then around Loch Coulin. The views of Beinn Eighe and Liathach from across the water must rank amongst the finest mountain views as seen from a low level walk anywhere in Scotland.', 57.5691, -5.342),
('997b8726-098f-5b65-a86d-ec74de09bbbc', 'Càrn Mòr , from Loch Arkaig', 'https://www.walkhighlands.co.uk/fortwilliam/carn-mor.shtml', 21.0, 1015, 7.5, 'Càrn Mòr is a little known peak amongst the rugged mountains just south of Knoydart, taking the form of an east-west ridge between Glen Dessary and Glen Pean. The western half is as complex and rocky as the renowned Rough Bounds; this route ascends via the east ridge, giving a rugged hillwalk with some good views.', 56.9714, -5.3124),
('998da449-aa50-52a9-8acb-8c1759b63690', 'Ken - Dee Marshes, near Laurieston', 'https://www.walkhighlands.co.uk/galloway/ken-dee-marshes.shtml', 5.75, 28, 1.5, 'The Ken - Dee marshes are a reserve managed by the RSPB. Look out for red kites, Greenland whitefronted and Greylag geese, willow tits and pied flycatchers on this enjoyable ramble to two hides overlooking the loch and marsh.', 54.9936, -4.0347),
('99aac996-5bb8-5a29-8a03-406c6cd8053d', 'Flowerdale Glen, Gairloch', 'https://www.walkhighlands.co.uk/torridon/Flowerdale.shtml', 4.75, 156, 2.0, 'A delightful waymarked walk up a sheltered glen to an attractive waterfall. The Flowerdale Glen was given its English name by the MacKenzies of Gairloch (the owners of the estate) after its impressive displays of wild flowers.', 57.713, -5.67795),
('99adf183-6d4c-5951-9bd7-dda780fd29a7', 'Ceannabeinne Township Trail, near Durness', 'https://www.walkhighlands.co.uk/sutherland/ceannabeinne.shtml', 1.0, 65, 0.75, 'This short walk round the site of an abandoned village makes a tour of information boards telling the story of the Clearance of this beautiful spot. The coastal views are superb.', 58.5518, -4.6882),
('99e210f6-6950-5756-94a2-587c15eb05d5', 'Sgùrr nan Ceathreamhnan group, Alltbeithe', 'https://www.walkhighlands.co.uk/lochness/Ceathreamhnan.shtml', 20.0, 1484, 11.0, 'Strenuous walk over some of the remotest mountains in Britain. Sgùrr nan Ceathreamhnan is a magnificent peak; whilst Mullach na Dheiragain is prized for its inaccessibility.', 57.2322, -5.1834),
('9a349b17-1f0e-51ce-b4c5-5876948eacaa', 'Westerwick coast, from Silwick', 'https://www.walkhighlands.co.uk/shetland/westerwick.shtml', 8.5, 280, 3.5, 'The coastline stretching west from Silwick and past Westerwick has some of (if not the) most spectacular cliff scenery in the UK, with arches, magnificent stacks and caves. This walk takes in the best section of the coast before taking shortcuts on the return.Please note that this walk crosses sensitive grazing land, including lambs and calves; please close all gates and note that the owner requests that dogs should be left at home.', 60.1635, -1.475),
('9a5f8e4e-5b76-5571-adf0-e06e8d36d982', 'Talmine and Achininver Beach circuit', 'https://www.walkhighlands.co.uk/sutherland/talmine.shtml', 10.0, 190, 4.0, 'This varied excursion is a rough walk around Melness which comprises a series of crofting townships including Talmine. The route follows coastal cliffs, a tiny bay, a superb and little visited sandy beach and a moorland crossing with excellent views.', 58.5341, -4.4266),
('9a7297bf-a7b3-5b6c-9cbd-aeceefbe4524', 'Kilmartin Glen', 'https://www.walkhighlands.co.uk/argyll/kilmartin-glen.shtml', 5.25, 30, 2.0, 'Kilmartin Glen is said to be one of the richest areas in Europe for prehistoric remains, with fine chambered cairns, standing stones and cup and ring marked rocks. This walk links the most impressive of the monuments close to Kilmartin village.', 56.1334, -5.4862),
('9aedc0ba-b70a-5f62-9332-9abdb3a3429c', 'River Eachaig circuit', 'https://www.walkhighlands.co.uk/argyll/river-eachaig.shtml', 7.0, 20, 2.0, 'This fairly level walk explores the banks of the rivers Eachaig and Massan, as well as the neighbouring natural woods and plantations, from Benmore gardens.', 56.026, -4.9811),
('9af539b7-0865-59fb-88bc-6ae3ab3a54bc', 'Strath of Arisaig', 'https://www.walkhighlands.co.uk/fortwilliam/strath-of-arisaig.shtml', 4.5, 18, 1.5, 'This simple stroll from Arisaig follows farm tracks through the green and fertile woods and farmland south of the village, returning via the coast road.', 56.9099, -5.8477),
('9b0a27c8-c112-58f9-be08-be8ae8a8081f', 'Carraig Fhada and the Singing Sands', 'https://www.walkhighlands.co.uk/islay-jura/carraig-fhada.shtml', 4.5, 76, 1.5, 'This excellent short walk heads across the fine sandy beach of Kilnaughton Bay and the Singing Sands of Tràigh Ban, as well as visiting the unusual lighthouse of Carraig Fhada.', 55.6308, -6.22179),
('9b2ad1cb-4d31-5f93-bde3-28eca2bb7170', 'Glais Bheinn and the Table of Lorn, near Lochaline', 'https://www.walkhighlands.co.uk/fortwilliam/table-of-lorn.shtml', 20.5, 530, 5.0, 'This scenic circuit takes in the shores of Loch Aline before climbing on open moorland to the summit of Glais Bheinn, a superb viewpoint. A detour from here leads to the flat-topped Table of Lorn, before a descent via boggy moorland and a stony hydro track.', 56.5617, -5.73757),
('9b4b9f1d-d833-5263-bd04-af5f4c6496a4', 'Meall Ghaordaidh from Glen Lochay', 'https://www.walkhighlands.co.uk/perthshire/meall-ghaordaidh.shtml', 9.5, 895, 6.0, 'Meall Ghaordaidh (named on some OS maps as Meall Ghaordie) is one of the less distinguished Munros, the usual ascent from Glen Lochay being up a broad grassy shoulder, though the upper section is rockier and the summit rewards with a good view. The Glen Lyon side looks more interesting but is little visited.', 56.4961, -4.39556),
('9b5aa310-b68d-567e-b4db-9d5716932633', 'Scallastle Forest Walk, near Craignure', 'https://www.walkhighlands.co.uk/mull/scallastle.shtml', 4.75, 161, 1.5, 'This very attractive walk leads through regenerating woodland with good views to the hills and across the Sound of Mull. The loop at the end is steeper, rougher and boggier, leading up and down both sides of the Scallastle River past waterfalls; it could be omitted if you want to keep things easy.', 56.4743, -5.7159),
('9b5b2e00-f7b9-50b7-8649-0319a188b75a', 'Corserine and the Rhinns of Kells, Forrest Lodge', 'https://www.walkhighlands.co.uk/galloway/corserine.shtml', 16.5, 903, 7.0, 'To the east of Merrick are vast areas of forestry plantations. The great Rhinns of Kells ridge, however, rises proudly above the treeline and offers an excellent rugged hillwalk. The high point is Corserine, a Corbett and an extensive viewpoint over much of Galloway.', 55.1494, -4.2725),
('9b63e239-91f0-5695-8320-58cf5eda64d6', 'Ben Lomond', 'https://www.walkhighlands.co.uk/lochlomond/ben-lomond.shtml', 12.0, 990, 5.5, 'Ben Lomond is one of the most popular Munros, rewarding the 30,000 people who make it to the top with truly fantastic views of the length of Loch Lomond and its islands. The view to the north reveals range beyond range of mountains into the Highlands. The path up is well made, but the optional return down the Ptarmigan ridge is steep and rocky, and muddy lower down.', 56.1525, -4.6431),
('9b95817f-51c7-5628-b045-f0efe3f78335', 'The Ringing Stone, Dun Mòr broch and Gott Bay', 'https://www.walkhighlands.co.uk/islands/ringing-stone.shtml', 10.0, 18, 3.5, 'This excellent circular walk explores some of Tiree''s most interesting features - the cup-marked Ringing Stone on the lonely north coast and the fine broch of Dun Mòr , finishing with a bracing stroll across the island''s largest beach at Gott Bay (Tràigh Mhor). Note that the return route is flooded in winter / early spring.', 56.526, -6.7951),
('9b97a0c5-03cd-5d71-9b48-b85e4b63c525', 'Hopeman to Lossiemouth', 'https://www.walkhighlands.co.uk/moray/hopeman-lossiemouth.shtml', 9.0, 95, 3.0, 'This excellent one-way coastal walk has a fine cliff-top section with coves and sea-stacks, and finishes with a long walk across a huge sandy beach. If starting from Elgin you can catch a bus out to Hopeman and another bus back from Lossiemouth. Alternatively, if you have the time and energy you can reverse your walk back to the start.', 57.71, -3.4333),
('9bacde67-7ec1-57b6-aa86-5e775ca520bc', 'Minch Moor circuit from Traquair', 'https://www.walkhighlands.co.uk/borders/minch-moor.shtml', 8.75, 394, 4.5, 'With its summit just a short distance from the Southern Upland Way, Minch Moor makes for a popular short hillwalk from Traquair, with great views. The alternative return route described is rougher underfoot and requires more careful navigation.', 55.6001, -3.0629),
('9c59f42f-66f8-5a80-be9e-3893fc6e365e', 'Chatelherault Country Park, near Hamilton', 'https://www.walkhighlands.co.uk/glasgow/chatelherault.shtml', 7.5, 184, 3.0, 'This circular walk passes high above the picturesque Avon Gorge within the Clyde Valley Woodlands National Nature Reserve.', 55.7618, -4.0146),
('9ca1019a-3e6c-56be-8e32-9f3b688c89c9', 'Angus Coast: Carnoustie to Arbroath', 'https://www.walkhighlands.co.uk/angus/arbroath-carnoustie.shtml', 11.0, 29, 3.0, 'A one-way walk along the Angus coast from Carnoustie to Arbroath where the train (or bus) can be caught for the return. Almost level, most of the route follows a cycle paths.', 56.4997, -2.7083),
('9ca98356-40a8-5011-b37b-2ec21fed4e1b', 'Garnets Walk, Port William', 'https://www.walkhighlands.co.uk/galloway/port-william.shtml', 3.75, 32, 1.0, 'A short circular walk inland from Port William with pleasant views along the coast and of the neighbouring farmland.', 54.7598, -4.5839),
('9cb68472-3300-58d1-ba56-a78b4897d499', 'Loch Coille-Bharr and the Beavers', 'https://www.walkhighlands.co.uk/argyll/loch-coille-bharr.shtml', 5.0, 50, 2.0, 'A pleasant circuit of Loch Coille Bharr, taking in the Beaver Detective Trail where you will see signs of the re-introduced beavers or even the creatures themselves. The almost level route also visits an abandoned settlement, an ancient cross slab and well. The area is good for wildlife and birdwatching.', 56.0567, -5.5615),
('9cd90aea-9873-55a2-beb5-755548e0291b', 'Sgùrr Thuilm and Sgùrr nan Coireachan', 'https://www.walkhighlands.co.uk/fortwilliam/sgurrthuilm.shtml', 23.5, 1428, 12.0, 'This pair of Munros lie just south of the Rough Bounds of Knoydart but share the fine rugged and demanding character of their northern neighbours. They give a long but superb mountain day out with grand views. Fairly easy cycling to just beyond Corryhully bothy.', 56.8711, -5.4364),
('9d04d86f-9db3-5738-8292-78abba9969dd', 'Screapadal', 'https://www.walkhighlands.co.uk/skye/screapadal.shtml', 5.5, 300, 2.0, 'This relatively gentle walk leads to the remains of the deserted village of Screapadal. This peaceful spot has impressive views over to Applecross. The return route gives the chance to see the ruins of Brochel castle.', 57.4407, -6.0363),
('9d168ccf-1612-5548-b241-9b5cbc6685d5', 'Water of Leith: Balerno to Slateford', 'https://www.walkhighlands.co.uk/lothian/water-of-leith-1.shtml', 8.25, 20, 3.0, 'This first part of the Water of Leith walkway follows the line of the old railway beside the river from the village of Balerno, passing the fringes of Currie, Juniper Green and Colinton before taking to waterside paths through the sylvan Colinton Dell.', 55.8877, -3.339),
('9d179205-c5ea-53ad-88cc-ccb34b46f81b', 'Whiteness Point from Nairn', 'https://www.walkhighlands.co.uk/moray/whiteness-point.shtml', 16.5, 25, 4.0, 'Whiteness Point is a long sandy spit that extends for several miles west of Nairn. A habitat of seals, it gives a bracing walk with views across the Moray Firth to the Black Isle and far beyond.', 57.5892, -3.8796),
('9d1a48ee-1144-5549-bc0b-d440b9b81095', 'Duff House and the Bridge of Alvah, Banff', 'https://www.walkhighlands.co.uk/aberdeenshire/bridge-of-alvah.shtml', 8.5, 122, 2.5, 'This enjoyable circular walk begins at the magnificent Duff House - now a museum and part of the National Gallery of Scotland - and takes in part of the former estate. The focal point is the 17th century Bridge of Alvah, towering high over the impressive gorge of the River Deveron.', 57.6586, -2.5225),
('9dccc7dc-ea69-5217-a5c0-61829a652bac', 'Cort-ma Law, near Lennoxtown', 'https://www.walkhighlands.co.uk/glasgow/cort-ma-law.shtml', 9.0, 351, 3.5, 'After a steep climb this route follows the edge of an escarpment of the Campsie Fells with great views to complete a horsehoe taking in the summit of Cort-ma Law.', 55.9935, -4.2256),
('9dd9c979-3aad-5156-b8e5-b33a466a72cc', 'Creag Meagaidh circuit', 'https://www.walkhighlands.co.uk/fortwilliam/creagmeagaidh.shtml', 21.0, 1080, 10.0, 'Creag Meagaidh is a magnificent massif, a bare plateau fringed by some of the grandest cliffs in Scotland. This traverse also takes in two further neighbouring Munros and makes for a memorable day.', 56.9521, -4.49592),
('9df01654-9333-532f-b8e5-3977bd8584e4', 'Sgùrr Mhic Bharraich', 'https://www.walkhighlands.co.uk/kintail/sgurr-mhic-bharraich.shtml', 9.5, 787, 6.5, 'Sgùrr Mhic Bharraich is the final summit of the great range of mountains on the south side of Glen Shiel. This pathless Corbett gives a short day and an escape from the busier mountains nearby, as well as excellent views.', 57.2121, -5.4152)
INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('9e01be8d-6f4c-585a-9ef7-b83de58e24b9', 'Pirnmill Hills: Mullach Buidhe of Beinn Bharrain', 'https://www.walkhighlands.co.uk/arran/pirnmill-hills.shtml', 14.0, 892, 7.0, 'Compared to their illustrious neighbours on the eastern side of Arran, the Pirnmill hills are unfrequented and unassuming. However, a round of these hills provides a very enjoyable day with fine views. Notwithstanding the OS map, Beinn Bharrain is the name of the whole hill, with Mullach Buidhe the highest of its summits.', 55.6443, -5.383),
('9e277e31-84fb-5696-9fc5-c73620161f7f', 'Canisp', 'https://www.walkhighlands.co.uk/ullapool/canisp.shtml', 12.0, 710, 6.0, 'Canisp is a fine cone-shaped Corbett when seen from the west, and appears as a steep wall seen from the north. Its eastern slopes are much more open lower down and give the shortest ascent, the chief reward of which are the superb views of the surrounding Assynt peaks.', 58.0996, -4.9708),
('9e31f829-334a-51fe-bfa9-983a59b3b57e', 'Tom na h-Airidh, Helensburgh', 'https://www.walkhighlands.co.uk/lochlomond/tom-na-h-airidh.shtml', 7.25, 200, 3.0, 'Climb through oak woodland and forestry plantation - battling the mud and trees - to reach the summit of Tom na h-Airidh for fine views over Gare Loch, the Firth of Clyde, Bute and Arran and the Arrochar Alps.', 56.0167, -4.72899),
('9e535f9f-856c-5a3c-95ce-d2b1ca6bcc8a', 'Beinn Narnain and Beinn Ìme', 'https://www.walkhighlands.co.uk/lochlomond/beinn-ime.shtml', 13.5, 1325, 7.0, 'The compact group of mountains known as the Arrochar Alps are renowned for their steep, rugged and rocky nature. The direct ascent of Beinn Narnain as described here is very rough and rocky, with some slight scrambling - a tougher start than many ascents in the Southern Highlands. Beinn Ìme - the highest of the range - is much smoother from this direction - a long steady grind from the bealach.', 56.206, -4.7507),
('9e651c48-e71a-57a5-84a8-418b3669990d', 'The Keen of Hamar, Unst', 'https://www.walkhighlands.co.uk/shetland/keen-of-hamar.shtml', 5.5, 94, 2.0, 'This circular route explores the Keen of Hamar National Nature Reserve - renowned for its rare flowers. It then climbs above the dramatic coastal cliffs before returning along the side of Balta Sound. A final road stretch passes a hotel and Unst''s legendary furnished bus stop.', 60.7646, -0.8248),
('9e9ba3af-c029-57a9-b1b4-0d1c598bad92', 'Forsnabhal and Clibh circuit, Uig', 'https://www.walkhighlands.co.uk/outer-hebrides/forsnabhal.shtml', 10.0, 252, 4.0, 'This circular exploration of the Uig area offers great variety: a low summit, lonely lochs, trackless peat bogs, a dramatic glen and views over sensational sandy beaches.', 58.2, -7.013),
('9ec55d35-9075-5232-8cb0-4695b6a799f2', 'Ley Way, Crathes Castle', 'https://www.walkhighlands.co.uk/aberdeenshire/crathes-castle.shtml', 6.75, 114, 2.0, 'The longest of thee waymarked woodland walks in the parkland of Crathes Castle, this route - also known as the Red Squirrel trail - takes in a variety of woodland as well as countryside views and passing the castle and famous gardens. There is a charge for parking.', 57.062, -2.4385),
('9ecc755a-247b-507a-bdc3-dfbdc5845945', 'Whaligoe Steps and the Cairn of Get', 'https://www.walkhighlands.co.uk/sutherland/whaligoe-steps.shtml', 3.0, 125, 1.5, 'This walk combines a visit to two remarkable attractions. The Whaligoe steps, all 330 of them, descend a cliff-face to one of the least-accessible harbours you could imagine, whilst inland is the Cairn of Get, a very well preserved chambered cairn. Extreme care is needed on the steps.', 58.3508, -3.1655),
('9f80f32d-537f-5ce9-b6d5-ced4386f5852', 'Loch na Davie circuit, Lochranza', 'https://www.walkhighlands.co.uk/arran/loch-na-davie.shtml', 16.5, 294, 5.5, 'A surprisingly rough and wild circuit through glens and over passes in the north of the island to reach remote Loch na Davie, reputedly the source of the purest water in Scotland.', 55.7055, -5.29708),
('9feb8045-b8df-5fe4-a8a6-68dc1cb3a1e1', 'Moine Mhòr and Dunadd', 'https://www.walkhighlands.co.uk/argyll/moine-mhor.shtml', 1.2, 58, 0.75, 'This is really two separate very short walks on the edge of the Moine Mhor, the Great Moss - one of Britain''s finest boglands and a National Nature Reserve. The second part of the walk ascends the miniature hill of Dunadd, a remarkable historic site that is tied in with the very beginnings of the Kingdom of Scotland.', 56.1055, -5.4996),
('a03ca819-f765-5fb8-b393-b37f18f2ffd4', 'A'' Ghlas Bheinn and the Falls of Glomach', 'https://www.walkhighlands.co.uk/kintail/Aghlasbheinn.shtml', 21.0, 1196, 9.0, 'A Ghlas Bheinn is a relatively small Munro, seeming at first glance to be rather overshadowed by neighbouring Beinn Fhada. On closer aquintance it is revealed as a rocky mountain of great character. The ascent here is combed with a visit to the Falls of Glomach - the finest in Scotland.', 57.2348, -5.3809),
('a05a0aa8-b50c-51b9-89ec-47034e82644a', 'Urie Ness, Fetlar', 'https://www.walkhighlands.co.uk/shetland/urie-ness.shtml', 4.25, 58, 2.0, 'This short walk from Fetlar''s ferry terminal follows the soggy coastline out to Urie Ness and its ruins. This is a good area to look for otters, before the route continues by climbing inland to reach the further haunting ruins at Urie itself - a reminder of the Highland Clearances which swept the island.', 60.6292, -0.9318),
('a05c9d3a-d2d1-5920-a9b1-d6d06f387a20', 'Marsco from Sligachan', 'https://www.walkhighlands.co.uk/skye/marsco.shtml', 14.0, 742, 6.0, 'Marsco is the finest of the Red Hills and is well seen from Sligachan. Despite not even being high enough for Corbett status, the summit is a fantastic viewpoint with swathes of blue sea and jagged mountains all around.', 57.2905, -6.1717),
('a05d6583-49b4-5559-874a-f7c5a3471224', 'The Fossil Tree and Burg', 'https://www.walkhighlands.co.uk/mull/fossil-tree.shtml', 18.75, 465, 7.0, 'MacCulloch''s Fossil Tree is a geological wonder at the western tip of the Ardmeanach Peninsula. The walk to it is both remote and challenging - and no place for those with a fear of heights. It is set amidst stunning coastal scenery. The final section on the shore is tidal - check the tide times before setting out and try to reach this section whilst the tide is still receding. For further information on this fascinating area, see Ben Dolphin''s article ''The Lost World of Mull''.', 56.3728, -6.0866),
('a08f1b21-e823-53ab-a73c-aa1cac9e4493', 'Bennachie: Oxen Craig and Mither Tap', 'https://www.walkhighlands.co.uk/aberdeenshire/bennachie.shtml', 9.25, 490, 4.0, 'Climb the two highest peaks of Bennachie, Oxen Craig and Mither Tap and enjoy fabulous sweeping views. The circuit returns over Craigshannoch.', 57.3093, -2.5634),
('a0912700-52f5-5313-926c-d76af5dadd69', 'Sgòr Gaibhre and Càrn Dearg from Corrour', 'https://www.walkhighlands.co.uk/fortwilliam/sgor-gaibhre.shtml', 21.75, 973, 8.0, 'Sgòr Gaibhre and Càrn Dearg are a pair of unspectacular Munros in the heart of the wild area around Loch Ossian. They can be approached from the south, or alternatively from Corrour railway station which isn''t accessible by road and has the advantage of a start at almost 400m.', 56.7604, -4.6907),
('a0a8d04d-174e-5a65-b774-be4115c66f99', 'Uig Sands', 'https://www.walkhighlands.co.uk/outer-hebrides/uig-sands.shtml', 4.0, 82, 1.0, 'The magnificent sands at Tràigh Uig are renowned as one of the finest of all Scotland''s beaches. This out-and-back walk crosses the beach and an iconic footbridge before visiting the historic Baile na Cille burial ground.', 58.1846, -7.0256),
('a0c0162f-f230-520b-8a6c-f46d18cfbe79', 'Tarnash Falls and Dunnyduff Wood, Keith', 'https://www.walkhighlands.co.uk/moray/keith.shtml', 5.5, 93, 1.5, 'This walk explores the countryside to the east of Keith, passing through attractive decidious woodland and visiting a waterfall.', 57.5387, -2.9509),
('a0c40443-8bee-5020-9a26-40929df34af4', 'Geallaig and the Gairn', 'https://www.walkhighlands.co.uk/cairngorms/geallaig.shtml', 17.0, 427, 7.0, 'Geallaig is an extensive heathery hill that encloses the northern side of Deeside from Balmoral to Ballater. A superb viewpoint, it is climbed easily following rough tracks; this route extends the outing by continuing on tracks down to a remote stretch of Glen Gairn, making for an enjoyable outing - with easy conditions underfoot.', 57.0852, -3.1886),
('a0c4fc69-3af0-5d18-b3a5-14227c457eb7', 'Tobermory Lighthouse circuit, Tobermory', 'https://www.walkhighlands.co.uk/mull/tobermory-lighthouse.shtml', 5.5, 172, 2.0, 'This short walk follows an excellent path through the woods from Tobermory out to the picturesque lighthouse at Rubha nan Gall. There are great views over the water to Ardnamurchan. You can either return the same way, or via a rougher, steeper route that runs higher along the hillside before skirting the golf course to return to Tobermory.', 56.6206, -6.0686),
('a0d9d2bc-843a-5ff9-a0cf-b520abe0baae', 'Pressendye, Tarland', 'https://www.walkhighlands.co.uk/aberdeenshire/pressendye.shtml', 14.6, 556, 4.5, 'Pressendye is a superlative viewpoint, making a great destination for this circular walk from Tarland, signposted as the ''Skyline circuit''. The route is very varied, with fertile farmland, country roads and tracks, a moorland ridge and woodland paths.', 57.1276, -2.8595),
('a1044844-b9d2-5fef-8dbd-83ff2737dfdb', 'Sgòr Buidhe circuit, Ballater', 'https://www.walkhighlands.co.uk/cairngorms/sgor-buidhe.shtml', 11.5, 410, 3.5, 'This fine moorland walk leaves Ballater along the old railway line before taking a forest up onto the moorland of Sgòr Buidhe. It then continues across the open moors with excellent views before descending through the woods and finishing alongside the River Dee.', 57.0501, -3.0406),
('a114ba38-a84f-5042-a657-6bf288505547', 'Auchtermuchty Common circuit, Auchtermuchty', 'https://www.walkhighlands.co.uk/fife-stirling/auchtermuchty.shtml', 7.0, 141, 2.0, 'A pleasant circuit climbing through farmland above Auchtermuchty with good views across to the Lomond Hills, returning through wood and common land.', 56.2911, -3.22942),
('a125eddb-f8aa-5936-9b65-0763bccb3b51', 'Den of Alyth, Alyth', 'https://www.walkhighlands.co.uk/perthshire/den-of-alyth.shtml', 3.5, 82, 1.5, 'Explore this deep-sided wooded valley where the Burn of Alyth tumbles down. Although described here from the first car park on the road out of Alyth, it is possible to start from the centre of Alyth.', 56.6237, -3.247),
('a148610c-7946-58e2-b7b8-ec8766ef9ec0', 'Dunfermline Explorer walk, Dunfermline', 'https://www.walkhighlands.co.uk/fife-stirling/dunfermline.shtml', 3.5, 79, 1.0, 'In 2022 Dunfermline became Scotland''s newest city - yet its history is long and illustrious, and is the final resting place for seven Scottish Kings. This walk explores the heritage around the town centre, beginning in lovely Pittencrieff Park (known to locals as the Glen), and visiting historic buildings including the Abbey, the Abbots House, the birthplace of Andrew Carnegie and St Margaret''s Cave.', 56.0697, -3.47164),
('a15ca79d-c79a-5413-95fd-4fab16762d39', 'Cnoc Croit na Maoile (Ord Hill), Muir of Ord', 'https://www.walkhighlands.co.uk/lochness/Ordhill.shtml', 4.0, 155, 2.0, 'A short but at times fairly steep out-and-back ascent through open woodland and heather moorland to the trig point on Cnoc Croit na Maoile. The summit offers spectacular views over the Black Isle, Cromarty and Beauly Firths to the east and the Affric mountains to the west.', 57.4998, -4.5003),
('a18d5fd6-1a88-58d6-8fea-0b18f87daad0', 'Sgùrr a'' Mhadaidh Ruadh, from Glenhinnisdal', 'https://www.walkhighlands.co.uk/skye/redfox.shtml', 11.0, 725, 6.0, 'A walk up a peaceful glen gives access to the dramatic central section of the Trotternish Ridge. The highlight is a visit to Sgurr a'' Mhadaidh Ruadh - the Peak of the Red Fox - which projects out from the ridge.', 57.5442, -6.3016),
('a1b68297-455c-5ee6-a962-043376389611', 'Cramond Island and Cramond Brig, Cramond', 'https://www.walkhighlands.co.uk/lothian/cramond-island.shtml', 8.75, 36, 3.0, 'Cramond Island - connected to the shoreline of Edinburgh only at low tide - is a fascinating place to visit, but requires careful planning to fit with tide times. There is a free car park in Cramond but it''s often busy on weekends, it is also possible to get a bus to Cramond. If using public transport, another bus can be picked up at Cramond Brig to return to the city centre or you can walk back along the outward riverside section.', 55.9754, -3.2992),
('a1d6b4a5-7aeb-52eb-88c2-6c46baf36e0b', 'Parallel Roads of Glen Roy', 'https://www.walkhighlands.co.uk/fortwilliam/parallel-roads.shtml', 4.0, 180, 1.5, 'This short but rough walk has excellent views of the famous Parallel Roads which stand out as horizontal ridges on both sides of the Glen. There is not a path for the whole route so navigation skills are required.', 56.9279, -4.7982),
('a1e3419b-2a4d-5531-9621-d382e15d9a03', 'Mull Coast to Coast - Killiechronan to Salen', 'https://www.walkhighlands.co.uk/mull/coast-to-coast.shtml', 4.25, 96, 2.0, 'Mull narrows in its central part to a slender neck, and only 4km separates the head of the sea-loch Loch na Keal from the Sound of Mull. This linear coast-to-coast walk thus crosses the island in the space of a short walk - though it is very wet underfoot in places. The walk requires either a drop-off at the start, a taxi ride for the return or doubling the distance by walking back - there is no public transport to the start.', 56.4987, -6.0006),
('a201177e-6bc2-520f-a0b3-928e33201d30', 'The Sgùrr of Eigg', 'https://www.walkhighlands.co.uk/islands/an-sgurr.shtml', 8.0, 403, 4.0, 'Climb to the top of the incredible and unique Sgùrr of Eigg for truly fantastic views over the other Small Isles and across to Skye and Ardnamurchan. The route is fairly straightforward given the formidale appearance of the Sgurr, but it does involve a steep climb and very simply rocky scrambling along the ridge - care is needed.', 56.8773, -6.1305),
('a20b41d4-b1cb-5509-8a56-b5f319ea1601', 'Singing Sands from Ockle', 'https://www.walkhighlands.co.uk/fortwilliam/ockle-singing-sands.shtml', 16.0, 460, 4.5, 'Follow an ancient path across rugged coast to the Singing Sands before returning by the same route with good views to the Small Isles.', 56.7612, -6.00158),
('a233e6fe-058f-5af0-8a1d-9eb9de2fbadd', 'Ramasaig to Orbost', 'https://www.walkhighlands.co.uk/skye/ramasaigorbost.shtml', 22.5, 974, 10.0, 'The classic Skye coastal walk, many guidebook writers have claimed this to be the most dramatic cliff-top walk in Britain. It is a long and challenging route, and requires more effort than many mountain ascents. The route is linear and neither end is served by public transport, so two cars will probably be required.', 57.4002, -6.7237),
('a2430c85-76fc-50af-81ed-dfaa040b91e3', 'Inverbroom waterfall, gorge & river circuit', 'https://www.walkhighlands.co.uk/ullapool/inverbroom-gorges.shtml', 9.0, 441, 5.0, 'This delightful circular walk follows an enchanting path across the flanks of Strath More, passing through beautiful native woodland. The path ascends and descends constantly, crossing tiny footbridges and visiting a dramatic gorge with a fine hidden waterfall. The return follows stretches of the River Broom.', 57.7786, -5.0357),
('a26f7a09-31e8-5df0-a14a-6ec757993338', 'Barnaline Oakwoods and Avich Falls, near Dalavich', 'https://www.walkhighlands.co.uk/argyll/dalavich-oakwoods.shtml', 5.25, 109, 2.0, 'Dalavich has some fine remnant oakwoods overlooking Loch Awe. There are two waymarked trails here; our route describes both, taking in the old oakwoods first before returning to the start and heading off to visit the Avich Falls.', 56.2743, -5.2808),
('a28b54ea-69b8-5113-9de5-05797fa8fd22', 'West Coast Walk 1: Stromness to Bay of Skaill', 'https://www.walkhighlands.co.uk/orkney/stromness-bay-of-skaill.shtml', 19.0, 324, 7.0, 'Leaving Stromness via the Point of Ness with great views of Hoy, this classic walk climbs to Black Craig and continues along the dramatic scenery that the west coast of Mainland Orkney provides, passing impressive sea stacks at Yesnaby to reach the neolithic village of Skara Brae (entrance charge) and the white sands of Skaill Bay. This is a linear route and transport is needed for the return.', 58.9657, -3.2952),
('a2d71d31-1cb5-5214-8c3a-28e1f51f66a7', 'Balloch Castle Country Park', 'https://www.walkhighlands.co.uk/lochlomond/balloch-castle.shtml', 3.5, 60, 1.0, 'A lovely circular walk through Balloch Country Park, with good views over Loch Lomond and a visit to a well-planted walled garden and the outside of Balloch House.', 56.0142, -4.5826),
('a2e182c6-8181-5473-8a81-497afdd0a5be', 'Staffin slipway and An Corran beach circuit', 'https://www.walkhighlands.co.uk/skye/staffin.shtml', 4.0, 164, 2.0, 'A short walk on well defined paths and minor roads exploring the crofting village of Staffin and its coast.', 57.6266, -6.2051),
('a302310b-a728-512e-ae9c-3f91ebcc667a', 'Garrabost archaeology walk, Point', 'https://www.walkhighlands.co.uk/outer-hebrides/garrabost.shtml', 2.5, 26, 1.0, 'This short walk exploring a chambered cairn and standing stone on Point (named the Eye peninsula on maps) near Stornoway - a peaceful exploration of a couple of Lewis'' less visited archaeological sites.', 58.219, -6.2245),
('a304bb47-ebe8-5333-94e3-9cdb7b169ba4', 'Achmelvich Beach and Alltan''abradhan', 'https://www.walkhighlands.co.uk/ullapool/achmelvich-beach.shtml', 6.0, 170, 2.0, 'Achmelvich bay has a stunning and popular beach; this walk leads from it along a good path north above the coastline to visit a ruined old mill and hidden sandy cove. There is also the option to hunt for a hidden hermit''s ''castle''.', 58.1695, -5.3018),
('a30e9f43-ad1c-501e-a8d1-ea900b660cc1', 'Cairn-mon-earn, Durris Forest', 'https://www.walkhighlands.co.uk/aberdeenshire/cairn-mon-earn.shtml', 7.2, 197, 2.5, 'This short ascent on forestry tracks leads to the summit of Cairn-mon-earn - a very fine viewpoint for Deeside, above the Durris Forest.', 57.0088, -2.36227),
('a319b708-47d7-5433-85f5-a4834d5866bb', 'Castlehill Trails, Glen Devon', 'https://www.walkhighlands.co.uk/fife-stirling/castlehill.shtml', 4.25, 150, 1.5, 'This is the longer option of two fine waymarked circular walks from the Castlehill Reservoir in Glen Devon. The walk passes through native woodland and gives excellent views.', 56.2114, -3.6189),
('a3203b55-9033-59a0-8b6e-c6e23603d72e', 'Sannox Horseshoe', 'https://www.walkhighlands.co.uk/arran/sannox-horseshoe.shtml', 15.0, 1693, 12.0, 'This classic but very challenging route makes a circuit of the mountains surrounding Glen Sannox. Ascending via a classic scramble up Cioch na h-Oighe, the route descends loose ground to the Saddle before an extremely steep climb up to the dramatic peak of Cìr Mhòr. The route then crosses the granite tors of Caisteal Abhail before further scrambling leads down to the Witches'' Step, which is bypassed before the final section of ridge and return across the moor.', 55.6617, -5.15582),
('a34533ce-fc95-545d-b7c5-4901b0a0bb99', 'Dornoch Point', 'https://www.walkhighlands.co.uk/sutherland/dornoch-point.shtml', 6.5, 19, 2.5, 'An excellent, and often breezy, coastal walk with good opportunities to spot sea birds, seals and many different shells. From the Point there are good views up the Dornoch Firth to the mountains beyond.', 57.8798, -4.0279),
('a3458a44-6623-514f-ad60-3f5c4ce5db22', 'Sanaigmore Bay, Rhinns of Islay', 'https://www.walkhighlands.co.uk/islay-jura/sanaigmore.shtml', 4.25, 25, 1.5, 'Explore the beautiful beach at Sanaigmore Bay before heading along the coast to discover the perfect hidden beach at Port Ghille Greamhair.', 55.8498, -6.4169),
('a38c459c-d746-5abb-b947-61c5a2ecfd39', 'Tullyfergus circuit, near Blairgowrie', 'https://www.walkhighlands.co.uk/perthshire/tullyfergus.shtml', 7.5, 200, 2.5, 'This enjoyable loop begins through the dense forestry plantations of Drimmie Wood but later leads onto the lovely Tullyfergus estate on fine old drove roads with a fine lochan, woods and wild flowers.', 56.6278, -3.3249),
('a3979ab7-803b-5ced-bf69-06b23a50cb2f', 'Fyvie Castle, Fyvie', 'https://www.walkhighlands.co.uk/aberdeenshire/fyvie-castle.shtml', 4.5, 26, 1.5, 'A short walk from the village of Fyvie to the neighbouring castle and grounds, including a lochside path with ducks and other wildlife and flowering rhododendrons in the spring.', 57.4294, -2.3952),
('a3d2b3d8-4cae-5417-8f16-f08cf2a6caa9', 'Biod an Fhithich, south Glenshiel', 'https://www.walkhighlands.co.uk/kintail/biodanfhithich.shtml', 6.5, 648, 5.0, 'A steep but rewarding walk to the summit of Biod an Fhithich (Point of the Ravens) where there are great views of the Saddle and the Forcan ridge and also down Loch Duich. The option of descending along the ridge to Shiel Bridge to make a longer and more strenuous route is also described.', 57.1758, -5.36372),
('a3e8f629-2f84-51cc-be83-ed2b2e0a9c54', 'Singing Sands, near Kentra', 'https://www.walkhighlands.co.uk/fortwilliam/singingsands.shtml', 9.5, 137, 3.5, 'The singing sands is a magical place at any tide or weather. This, there and back, walk on tracks has a delightful first half next to the water and then through forestry plantation before emerging at the white sands.', 56.7413, -5.84496),
('a4348e46-d90a-56b5-9e5a-c3e5d232f888', 'Cnoc na Sroine, Salen', 'https://www.walkhighlands.co.uk/mull/salen.shtml', 6.25, 176, 2.5, 'This very enjoyable walk from Salen follows a lovely rising grassy track to Glenaros House, with fine views over the Sound of Mull. It then climbs over the rougher moors, visiting an iron-age fort with a superb outlook, before turning to Salen via some attractive native woodland.', 56.5177, -5.9498),
('a45b9310-1a28-5b40-a9ab-b0e62f0daddf', 'Airigh-drishaig and Uags circuit, Toscaig', 'https://www.walkhighlands.co.uk/torridon/airigh-drishaig.shtml', 19.5, 680, 8.0, 'This very challenging walk uses two old paths that head to the southernmost part of the Applecross peninsula from Toscaig - to the old settlements of Airigh-drishaig (now a second home) and Uags (now a bothy). The two were once linked by a path high above the coast - this has now vanished, so only walkers who don''t mind a challenge, rough ground and careful navigation can still make the circuit. For those less confident, Airigh-Drishaig (and Uags) can be visited by simpler out-and-back routes.', 57.3727, -5.81064),
('a4662775-3631-5985-a913-9b77f7931318', 'Beinn Fhionnlaidh', 'https://www.walkhighlands.co.uk/argyll/beinn-fhionnlaidh.shtml', 14.5, 980, 6.0, 'Beinn Fhionnlaidh is a straightforward Munro forming a long west-east ridge from Glen Creran. It is a  good viewpoint with views out to sea to the west and inland giving an unfamiliar aspect of Glencoe and Glen Etive.', 56.5904, -5.20007),
('a4d8c664-3e22-5f40-a905-dffec709e8d9', 'Kylerhea Otter Hide trail', 'https://www.walkhighlands.co.uk/skye/kylerheaotter.shtml', 2.25, 43, 1.0, 'Easy walk with lovely views over the Kyle strait to the mainland. The hide at the midway point gives a good opportunity to spot otters, seals and other wildlife. Picnic tables and toilets near start.', 57.2273, -5.6686),
('a4e383e2-d16f-5fe3-9670-77bbe70ac118', 'Creag Rainich, via Loch a''Bhraoin', 'https://www.walkhighlands.co.uk/ullapool/creag-rainich.shtml', 17.5, 620, 7.0, 'When approached from the east, Creag Rainich has rounded and fairly gentle, open slopes compared to the jagged drama of some of its neighbours. The summit, however, is a stunning viewpoint into the Fisherfield Forest.', 57.7374, -5.09),
('a5074aba-baec-5e6a-b098-88690de25b43', 'Beinn Odhar Bheag and Beinn Mhic Cedidh', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-odhar-bheag.shtml', 14.0, 1282, 7.0, 'Beinn Odhar Bheag is a rather underated mountain - a very fine and rugged peak towering above the west side of Loch Shiel. In combination with Beinn Mhic Cedidh it makes for an enjoyable, rough round.', 56.8737, -5.5191),
('a50a9016-caeb-56dd-b451-50832ee6f0b8', 'River Beauly and Lovat Bridge circuit', 'https://www.walkhighlands.co.uk/lochness/Beaulyriver.shtml', 8.0, 35, 2.5, 'This lovely circular walk takes in a beautiful stretch along the River Beauly, with wonderful wild flowers in the early summer. The return route is peaceful and particularly good for autumn colours.', 57.4613, -4.5073),
('a50c4536-71cd-53ba-8360-83640b402251', 'Pitcarmick Loop, Kirkmichael', 'https://www.walkhighlands.co.uk/perthshire/pitcarmick-loop.shtml', 6.75, 169, 2.5, 'This varied waymarked walk explores the countryside on either side of Glen Derby above Kirkimichael - visiting a pinewood with many log cabins, and returning with an open moorland section offering stunning views across Strathardle.', 56.7228, -3.5049),
('a5252d5d-aa7f-570d-ac70-bab4294284af', 'Morven and Maiden Pap', 'https://www.walkhighlands.co.uk/sutherland/morven.shtml', 16.75, 942, 8.0, 'Morven - the highest summit in  Caithness - is a hill of great character, rising in isolation as a majestic conical peak. This route makes the ascent before continuing over the moors to reach Maiden Pap, which is something of a Morven in miniature, though even steeper. The whole round - which also passes the tors of Smean - makes for a classic though boggy outing.', 58.253, -3.5809),
('a5615567-75a8-5f3a-bf91-573977fbbf30', 'Fort Augustus Explorer', 'https://www.walkhighlands.co.uk/lochness/fort-augustus.shtml', 7.75, 42, 2.5, 'Fort Augustus enjoys a fine location midway along the Great Glen, with a picturesque setting along a flight of locks through which the Caledonian Canal descends to the head of Loch Ness. This walk explores the surrounding lanes and tracks as well as a stretch alongside the canal.', 57.1464, -4.6816),
('a56aaef2-bb39-5255-bbfe-e51eb5d5f821', 'Rubha Coigich circuit, Reiff', 'https://www.walkhighlands.co.uk/ullapool/rubha-coigich.shtml', 18.0, 370, 7.0, 'This circuit of the low lying westermost peninsula of Coigach gives rough going. Good coastal scenery and superb sea and mountain views are the reward.', 58.0724, -5.4532),
('a59d9455-c137-5c9e-8395-02decb9b7d68', 'Aonach Mòr and Beag via the Gondola', 'https://www.walkhighlands.co.uk/fortwilliam/aonachs-gondola.shtml', 9.5, 860, 5.5, 'Those looking for the fastest way to climb the two Aonach peaks can approach from the north, riding the Nevis Range gondola for almost half of the ascent. This option gives a fairly short hillwalk with stunning views although the summits are extremely exposed and the plateau requires very skilled navigation. The route may not please purists who wish to climb the mountains under their own steam - these can instead use theroute from Glen Nevis.', 56.8364, -4.9729),
('a5a850be-4f86-5964-b1ab-7168ad8e12a4', 'Mallaig circuit', 'https://www.walkhighlands.co.uk/fortwilliam/mallaig.shtml', 3.0, 129, 1.5, 'This pleasant circuit has good views over Mallaig harbour and across Loch Nevis to Knoydart. A good way to spent spare time whilst waiting for a ferry.', 57.0044, -5.82373),
('a61013b0-517a-5d97-8938-0d571d648f55', 'Crichope Linn, near Thornhill', 'https://www.walkhighlands.co.uk/galloway/crichope-linn.shtml', 4.5, 97, 1.5, 'This dramatic hidden ravine - spelt Chrichope on some maps - was once a renowned showplace, but it is now neglected and almost forgoten, its many footbridges long since removed. This short circular walk explores the gorge before returning along tracks and minor roads.', 55.2415, -3.72068),
('a62d52d9-a152-5095-a10c-12995970ccf8', 'Garbh Bheinn of Ardgour', 'https://www.walkhighlands.co.uk/fortwilliam/garbh-bheinn-ardgour.shtml', 8.0, 978, 6.0, 'Garbh Bheinn is a magnificent mountain, rough as any in Ardgour and famed for the great climbing crags on its eastern flanks. The route described here is out and back along the Sròn  a'' Gharbh Choire Bhig ridge which offers superlative views throughout.', 56.6832, -5.38449),
('a680a54c-5c7b-58be-bb39-24431d4570e2', 'Taynish National Nature Reserve, near Tayvallich', 'https://www.walkhighlands.co.uk/argyll/taynish.shtml', 9.5, 180, 3.5, 'The stunningly beautiful Taynish peninsula is a National Nature Reserve. One of the largest original oakwoods remaining in Britain, the reserve offers a bit of everything; peaceful loch shores, woodland, wildlife and views.', 56.0065, -5.6312),
('a693c953-4eca-5e0c-a9bf-d3744947b4a5', 'Gartmorn Dam circuit, near  Alloa', 'https://www.walkhighlands.co.uk/fife-stirling/gartmorn-dam.shtml', 4.5, 8, 1.5, 'This pleasant and popular circuit around Scotland''s oldest reservoir offers much for the serious bird watcher or family outings to see the ducks.', 56.1266, -3.7529),
('a698f00e-95c3-5909-a591-f59aabd13848', 'Scalpay and Eilean Glas Lighthouse, near Tarbert', 'https://www.walkhighlands.co.uk/outer-hebrides/isle-of-scalpay.shtml', 10.0, 199, 3.0, 'This circular route explores much of the island of Scalpay (Scalpaidh in Gaelic), now joined to Harris by a bridge, and visits the impressive Eilean Glas lighthouse.', 57.8745, -6.6902),
('a69ccd5e-47c8-590d-ab42-3f59f3bb3f29', 'Locherwood & Lady Muir Trail, Clyde Muirshiel', 'https://www.walkhighlands.co.uk/glasgow/locherwood.shtml', 7.25, 138, 2.5, 'This is the longer of the two waymarked walks that begin through the Locherwood Community Woodland. It''s possible to extend the walk across the moors to Windy Hill, and link to Muirshiel.', 55.8413, -4.6322),
('a6a94b9f-a664-53cd-a389-9ded3ad35002', 'Burghead and Clarkly Hill', 'https://www.walkhighlands.co.uk/moray/clarkly-hill.shtml', 7.5, 82, 2.0, 'This route begins with an exploration of the fishing village of Burghead, taking in the harbour and the historic Pictish Fort. It then follows a stretch of coastline along a disused railway, before returning inland via Clarkly Hill with views across the Moray Firth.', 57.6989, -3.4882),
('a706d914-0235-5bfa-bf93-b9740082bb18', 'Archer''s Stone and Wade''s Road, Slochd', 'https://www.walkhighlands.co.uk/cairngorms/archers-stone.shtml', 12.5, 178, 3.5, 'This unfrequented circuit is packed with interest. It takes in a section of General Wade''s old road over the Slochd, crosses the fine Sluggan Bridge, and visits an intruiging memorial. There are areas of beautiful regenerating Scots Pine woods along the way.', 57.2907, -3.9137),
('a72f150d-a858-588f-bc99-39b9b7195fc2', 'Kirkhill & Pond circuit, Leith Hall', 'https://www.walkhighlands.co.uk/aberdeenshire/leith-hall-kirkhill.shtml', 3.2, 30, 1.0, 'A pleasant circuit through the parkland and farmland of Leith Hall, a stately home owned by the National Trust for Scotland. The first part of the walk around a large pond is suitable for some wheelchairs and buggies. The walk visits a bird hide and ice house.', 57.3564, -2.766),
('a7479d28-89a6-5c83-9e9d-d525cabbe917', 'Stob an Aonaich Mhòir, from Loch Rannoch', 'https://www.walkhighlands.co.uk/perthshire/stob-an-aonaich-mhoir.shtml', 28.5, 649, 8.5, 'This remote hill enjoys a superb position above Loch Ericht, making it a wonderful viewpoint, revealed only at the last moment to most walkers. The usual approach involves many kilometres along a private tarmac road - if you only use a bicycle to help reach one hill, it should probably be this one.', 56.6921, -4.4151),
('a7887aeb-89ff-5760-94e3-519695f9880a', 'Coffin Road circuit, Bays', 'https://www.walkhighlands.co.uk/outer-hebrides/coffin-road.shtml', 14.5, 277, 5.0, 'Follow the route used by pall-bearers to carry the dead from the Bays district over to the west side of Harris for burial on the machair. The return can be made using the old main road.', 57.8335, -6.843),
('a78c01e4-cacf-5bd9-ba8e-5554dbea0800', 'Ness Glen, near Loch Doon', 'https://www.walkhighlands.co.uk/glasgow/ness-glen.shtml', 3.2, 81, 1.5, 'Below the Loch Doon dam the River Doon has carved a route through a beautiful wooded gorge. The Ness Glen was once a renowned showplace and still has a spectacular path that runs through it right down alongside the river. From the bottom of the gorge another path returns to the start through the woods at a higher level.', 55.2815, -4.4005),
('a78f5b73-d105-54d5-a78e-28761e4c667f', 'Strathclyde Loch, Motherwell', 'https://www.walkhighlands.co.uk/glasgow/strathclyde-loch.shtml', 6.0, 5, 2.0, 'This circuit around Strathclyde Loch - centrepiece of the Strathclyde Country Park - provides a popular walk within easy reach of many urban centres.', 55.7877, -4.0287),
('a807b0e3-407f-51b1-85f1-d263f97b4e66', 'The Sgùrr Ghiubhsachain round', 'https://www.walkhighlands.co.uk/fortwilliam/sgurr-ghiubhsachain.shtml', 21.75, 1454, 11.0, 'Sgùrr Ghiubhsachan is a magnificently rugged and rocky peak, well seen in the classic view down Glen Shiel from Glenfinnan. This route takes in the two additional Corbetts of Druim Tarsuinn and Sgùrr Croabh a'' Chaorain to make a strenuous but very fine challenging hillwalk.', 56.8579, -5.4068),
('a8492f3d-8e1d-599c-80f6-9ccbcf80124a', 'Isle of Muck coastal circuit', 'https://www.walkhighlands.co.uk/islands/muck-coast.shtml', 14.0, 260, 6.0, 'The circuit around the coastline of the Isle of Muck makes for a superb walk, with varied terrain, cliff-top scenery, beaches, wild moorland and farm fields - and entrancing views throughout.', 56.8324, -6.224),
('a87536e6-94c7-5ab6-99d4-5ab4b4ff6e12', 'Luskentyre Sands (Losgaintir)', 'https://www.walkhighlands.co.uk/outer-hebrides/luskentyre-sands.shtml', 4.25, 44, 1.0, 'Luskentyre Sands have been voted the finest beach in the UK. There are many other contenders but the setting is undeniably magnificent. This walk heads across the sands and then above the shoreline before returning through the village. Note that the route is impassable at high tide.', 57.8916, -6.9516),
('a8bcd164-d6ce-5dd2-a34c-dd529fa3c206', 'Stravanan Bay, from Kilchattan Bay', 'https://www.walkhighlands.co.uk/argyll/stravanan-bay.shtml', 5.75, 25, 2.0, 'Cross the narrowest part of Bute to visit Stravanan Bay with its fine views of the mountains of Arran. The return offers the opportunity to visit the remains of a prehistoric stone circle.', 55.7517, -5.0269),
('a8ca13bb-976c-5091-8127-b3645c6ef018', 'Mount Blair', 'https://www.walkhighlands.co.uk/angus/mount-blair.shtml', 4.5, 388, 2.0, 'Mount Blair is a prominent landmark around Glen Shee and Glen Isla, its gradual dome topped by a transmitter mast. It provides a short and straightfoward hillwalk, with superb summit views.', 56.7619, -3.38387),
('a8e9cd91-3264-5dde-9f9e-bebb069ceafa', 'Forfar Loch circuit, Forfar', 'https://www.walkhighlands.co.uk/angus/forfar-loch.shtml', 4.0, 10, 1.5, 'A straightforward and flat circuit of Forfar Loch, often busy with cyclists, runners, dog walkers, and offering the chance to look for birdlife or watch canoeists on the water. Visitor centre with toilets.', 56.6447, -2.8974),
('a90b0e5a-544b-5fb8-886a-4df6446c8d04', 'Aird a'' Mhorain, Grenitote', 'https://www.walkhighlands.co.uk/outer-hebrides/aird-a-mhorain.shtml', 9.25, 55, 3.0, 'Combine sandy beaches with a visit to a grassy headland, returning past an excavated roundhouse at Udal. A good walk to watch for seabirds, marine mammals and otters.', 57.6577, -7.3351),
('a926d79c-8945-5afe-b16a-798f3a2f966c', 'Sand River circuit, Big Sand', 'https://www.walkhighlands.co.uk/torridon/sand-river.shtml', 6.5, 125, 1.5, 'The seemingly bleak moorlands north of the Sand River, like many in the Highlands, harbour the remains of centuries of human activities. This constructed circular trail heads through these empty moors.', 57.7452, -5.7629),
('a947973e-8764-5363-ab87-af654e7804ad', 'Glen Devon Reservoirs, Glen Devon', 'https://www.walkhighlands.co.uk/perthshire/frandy-reservoirs.shtml', 8.5, 170, 2.5, 'This simple walk follows a private road into the empty glens of the Ochils, with good views over two reservoirs.', 56.2284, -3.69689),
('a9b62292-9cf2-51b2-921a-e6263d7b0d66', 'Strome Wood, Stromeferry', 'https://www.walkhighlands.co.uk/kintail/stromeferry.shtml', 2.0, 155, 1.0, 'A short but enjoyable woodland circuit that gives some fabulous views over Loch Carron and the mountains beyond. There are a number of picnic tables and benches on the route though the views are becoming impeded by trees. There are a few steep sections in the woodland with stone and wooden steps.', 57.3508, -5.5559),
('aa1ec2f1-3efe-58b5-b466-cb646f97ace6', 'Torr Alvie and the Duke of Gordon Monument', 'https://www.walkhighlands.co.uk/cairngorms/torr-alvie.shtml', 5.25, 150, 2.0, 'A delightful walk to a fine viewpoint over Strathspey - Tor Alvie. This beautiful wooded ridge high above the Spey and Kinara House. Pass the Waterloo Cairn before reaching the Duke of Gordon''s monument, a great landmark with a wondeful outlook. One of the best short walks in the area.', 57.1511, -3.889),
('aa4f7a09-4981-5684-b2cd-8b038191f7ca', 'Mount Battock from Glen Esk', 'https://www.walkhighlands.co.uk/angus/mount-battock.shtml', 15.0, 673, 5.0, 'Mount Battock is the most easterly of the Corbetts and the highest point of a wide area of rolling moors. It provides a straightforward ascent from Glen Esk.', 56.8995, -2.7562),
('aa71cddb-1cbe-54d0-bc7d-0400a5c95df4', 'Uamh an Tartair, Knockan, Elphin', 'https://www.walkhighlands.co.uk/ullapool/uamh-an-tartair.shtml', 3.75, 78, 1.5, 'Uamh an Tartair - the Cave of the Roaring - is a spectacular pot hole with a cave below, into which pour the waters of the Abhainn a'' Chnocain above Knockan. The cave should not be confused with another of the same name above Inchnadamph.', 58.0482, -5.0313),
('aa8505b6-95d7-5f53-bdbc-671121316976', 'Birnam Hill, Birnam', 'https://www.walkhighlands.co.uk/perthshire/birnam-hill.shtml', 6.25, 374, 3.0, 'This superb circular walk climbs up over the beautifully wooded Birnam Hill. It offers superb views over the surrounding countryside on the ascent and then over Dunkeld from a crag on the way down. The ascent up is reasonably well graded, but the descent is steep in parts.', 56.5465, -3.5612),
('aacd9486-280d-5a50-a987-5595242fdf3f', 'Ceann a'' Mhara and Balephuil Bay', 'https://www.walkhighlands.co.uk/islands/ceann-a-mhara.shtml', 5.0, 123, 2.5, 'Tiree is mostly flat and fertile apart from a few small rugged hills in the west - one of them being the Ceann a''Mhara headland, which has rugged and dramatic coastal scenery. With a contrasting approach across the sands of Balephuil Bay (Tràigh Bhi), this walk deserves to be regarded as a Tiree classic.', 56.4602, -6.9503),
('aadb3d38-80f6-53be-91de-c185288e61ae', 'Ormond Castle, Avoch', 'https://www.walkhighlands.co.uk/lochness/Ormondcastle.shtml', 4.75, 109, 1.5, 'A straightforward short circular walk from the old fishing village of Avoch. The walk visits Ormond Castle - once an important medieval stronghold but later completely destroyed by Oliver Cromwell. Today the green mound offers excellent views back to the village and across the bay.', 57.5595, -4.1767),
('ab697747-8232-5129-9991-7f19ed7d751b', 'Beinn Mhor, via Glen Massan', 'https://www.walkhighlands.co.uk/argyll/beinn-mhor.shtml', 13.0, 720, 5.5, 'Beinn Mhòr is the highest hill in the area west of Loch Eck, making it an extensive viewpoint. The walk is straightforward, although navigation skills are needed for the final climb.', 56.0358, -5.0259),
('ab71a674-c847-59e1-86ed-fd4bfb9a422a', 'Ben Nevis by the Mountain Path', 'https://www.walkhighlands.co.uk/fortwilliam/bennevis.shtml', 17.0, 1352, 9.0, 'Ben Nevis is the highest mountain in Britain. The route described here is the standard way up the mountain; it is straightforward, if strenuous, by hillwalking standards, but the less experienced should be sure to read all the precautions.', 56.8108, -5.0771),
('ab76b714-7650-5230-86a2-0067fd4f50f5', 'Ben Vorlich via Loch Sloy', 'https://www.walkhighlands.co.uk/lochlomond/ben-vorlich-lomond.shtml', 13.5, 945, 6.5, 'Ben Vorlich is a bulky and very rugged mountain, the most northerly of the Arrochar Alps. It is possible to walk a fine circuit taking in the Little Hills from Ardlui to the north, but the ascent here, from Inveruglas via the Loch Sloy dam road, is the quickest and most popular. The ascent is steep but the views are superb.', 56.2516, -4.70884),
('abf9b077-031c-53de-bc07-41fcdbb993b5', 'Meallach''s Grave, Dyemill Forest near Lamlash', 'https://www.walkhighlands.co.uk/arran/dyemill.shtml', 2.75, 110, 1.0, 'This attactive waymarked forest walk leads up to a neolithic tomb, as well as the ruins of the cleared township of Lagaville', 55.5211, -5.147),
('ac058eb7-8437-59c4-a34a-cb795abb9aed', 'Criffel by the Ardwall path', 'https://www.walkhighlands.co.uk/galloway/criffel.shtml', 5.5, 506, 3.0, 'Criffel may be only 569 metres high, but its modest altitude belies its prominence, rising as the highest hill for miles around and dominating the Solway coastline. The ascent is short but steep and rewarded with stunning views of the Solway, its estuaries and across to the English Lake District.', 54.9551, -3.6088),
('ac0ceaa3-9806-53e6-9a89-f20d4ba50a64', 'Balranald RSPB reserve', 'https://www.walkhighlands.co.uk/outer-hebrides/balranald.shtml', 5.75, 35, 1.5, 'The Balranald Nature Reserve includes the westernmost point of North Uist - the Aird an Runair peninsula. This waymarked route encircles the peninsula and offers great sea views as well as the chance to spot a wide variety of birds, including the elusive Corncrake.', 57.6057, -7.5181),
('ac3cedb1-3c72-5105-ac8d-0a538c6c54d1', 'The Old Man of Stoer and the point', 'https://www.walkhighlands.co.uk/ullapool/old-man-of-stoer.shtml', 7.0, 360, 3.5, 'A visit to the Old Man of Stoer, a spectacular sea-stack. The walking is rough but the coastal scenery impressive; the return is over a low hill with fantastic views in clear weather. This is the best walk in Assynt for whale and dolphin spotting.', 58.2382, -5.401),
('ac4d6991-02ec-5cd8-8303-2efbbf28cc48', 'Lewis West Side coastal walk', 'https://www.walkhighlands.co.uk/outer-hebrides/lewis-west-side.shtml', 18.75, 528, 7.0, 'This fine walk follows the clifftops, stacks and bays of the coastline between An Gearrannan and Bragar. Although linear the walk is served by buses and could be shortened by heading inland to reach the main road at a number of points.', 58.2964, -6.7908),
('ac76653c-b38e-5418-81eb-e80e3f84afdd', 'Almondell and Lin''s Mill Aqueduct, near Livingston', 'https://www.walkhighlands.co.uk/lothian/almondell.shtml', 10.5, 102, 3.5, 'Just a stone''s throw from Livingston, this beautiful circular walk takes in the Almondell Country Park en route to reach and cross a spectacular aqueduct on the Union Canal. Although in one of the more built up parts of the central belt, most of the walk has a real country feel.', 55.8946, -3.4777),
('ac91996a-a54e-5d06-b23e-206c5bdf797c', 'Ettrick Hills horseshoe', 'https://www.walkhighlands.co.uk/borders/ettrick-hills.shtml', 16.0, 863, 6.5, 'The uppermost reaches of the Ettrick valley are one of the most remote places in the Borders. Whilst the valley is marred by commercial forest plantations, the rounded green hills that surround it rise above the trees, offering a fine hill circuit in a very quiet area.', 55.3708, -3.2806),
('acefcf7f-c11c-580a-9391-0de8367dbd15', 'Mam na Gualainn circuit, Kinlochleven', 'https://www.walkhighlands.co.uk/fortwilliam/mam-na-gualainn.shtml', 19.5, 1084, 8.0, 'Mam na Gualainn is the western termination of a grand grassy ridgewalk high above Loch Leven with magnificent views. Although it can be more quickly reached from Callert, it would be a shame to miss the superb ridge via Beinn na Caillich on this excellent circuit.', 56.7167, -4.9629),
('acf9c29d-c9f7-50eb-b1b1-6c0810849b5a', 'Beinn Ghuilean circuit, Campbeltown', 'https://www.walkhighlands.co.uk/argyll/beinn-ghuilean.shtml', 6.5, 210, 2.5, 'This woodland circuit on the slopes of Beinn Ghuilean gives superb views over Campbeltown. The walk is described starting from the town centre but it is also possible to park nearer to the start. Parts of the route are popular with mountain bikers so care is needed.', 55.4235, -5.6065),
('acf9e93e-9aa1-582b-9c81-8e6d3cb1aa23', 'John Muir Link: Dunbar to Cockburnspath', 'https://www.walkhighlands.co.uk/lothian/dunbar-dunglass.shtml', 16.5, 179, 5.0, 'Part of the original John Muir Way which now terminates in Dunbar, this coastal walk continues along the most easterly section of the varied coastline of East Lothian to Cockburnspath - providing a link with the Southern Upland Way and Berwickshire Coastal Path routes.', 56.0053, -2.516),
('ad420704-ee4e-598b-8979-d6a70b843822', 'Cruach Àrdrain and Beinn Tulaichean', 'https://www.walkhighlands.co.uk/lochlomond/cruach-ardrain.shtml', 12.5, 1019, 7.0, 'Cruach Àrdrain has a distinctive outline which makes it a familiar sight from the Crianlarich and Tyndrum area. Its southern ridge rises to the satellite Munro peak of Beinn Tulaichean; to include both of these summits it is more convenient to start from the south to avoid reascending over the shoulder of Cruach Àrdrain. The slopes to and from the ridge are steep, rugged and pathless.', 56.333, -4.5157),
('ad893cd0-336a-51ab-856b-835ee8b35e9d', 'Ceapabhal, Taobh Tuath', 'https://www.walkhighlands.co.uk/outer-hebrides/ceapabhal.shtml', 6.75, 360, 3.0, 'A glance at any map will suggest that Ceapabhal would be an excellent viewpoint, and this short but very steep ascent rewards with stunning views along the beaches of Harris as well as out over a myriad of islands in the Sound.', 57.8, -7.0698),
('adc014b5-f888-53ab-a3a9-171e96f390a3', 'Rigg Bay and Cruggleton Castle, from Garlieston', 'https://www.walkhighlands.co.uk/galloway/cruggleton-castle.shtml', 10.25, 131, 3.0, 'This superb coastal walk heads around the back of beautiful Rigg Bay before continuing along the richly wooded coastline, with a final clifftop stretch to the ruins of Cruggleton Castle - an excellent viewpoint. The route is described here as an out-and-back walk from Garlieston, but if you can arrange transport then it''s possible to continue along the coastal path to Portyerrock and Isle of Whithorn.', 54.7881, -4.3684),
('adc1de92-26d7-5e2f-a36a-eb25edb66058', 'Dùn Fiadhairt, near Dunvegan', 'https://www.walkhighlands.co.uk/skye/dun-fiadhairt.shtml', 3.25, 87, 1.5, 'A short walk onto the little visited Fiadhairt peninsula, visiting the remains of an iron-age broch.', 57.4635, -6.6041),
('addcd4f1-b8f8-5746-abcd-696d4eb961e0', 'Twin Law cairns, from Watch Water', 'https://www.walkhighlands.co.uk/borders/twin-law.shtml', 11.0, 260, 3.5, 'This short hillwalk follows the route of the Southern Upland Way to visit the summit of Twin Law, which has perhaps the finest cairns of all Scotland''s hills. Situated towards the southern end of the Lammermuirs, it is a very fine viewpoint.', 55.8031, -2.5412),
('ae1d8c53-47dd-5d49-bccc-0d799e09cc7a', 'Bonchester Hill and fort, near Hawick', 'https://www.walkhighlands.co.uk/borders/bonchester.shtml', 8.25, 274, 3.0, 'Starting from the village of Bonchester Bridge, this circular route follows farm tracks and minor roads before ascending to the fine viewpoint of Bonchester Hill, site of an iron age fort.', 55.3987, -2.65534),
('ae56d315-64c4-5a1d-8903-00572160f839', 'Aonach Beag: Four Munros from Culra', 'https://www.walkhighlands.co.uk/cairngorms/aonach-beag.shtml', 18.5, 1110, 9.0, 'The high ridge running from Beinn Èibhinn over Aonach Beag to Geal Chàrn, and its eastern extension to Càrn Dearg, is one of the remotest mountain groups in Scotland. It can be approached from Luiblea in the north, or the western summits can be climbed from Corrour Station. The route described here is from Culra bothy which is closed but you can camp nearby; the setting is beautiful and accessed via a long walk-in from Dalwhinnie.', 56.8535, -4.4238),
('ae6ea329-7099-5dbe-a67d-5f725fc8d7e9', 'Carnan Mòr and Hynish', 'https://www.walkhighlands.co.uk/islands/carnan-mor.shtml', 8.25, 200, 3.0, 'This pathless and rough moorland walk ascends to the highest point on Tiree, by the ''golf ball'' radar station on Carnan Mòr, the summit of Ben Hynish. It then returns keeping closer to the coastline. The route starts and ends from Hynish - a fascinating complex of buildings which acted as the signal station for Skerryvore Lighthouse and which now includes an exhibition and cafe.', 56.4493, -6.8935),
('ae89a520-707a-51fa-aa9d-488d21f656e2', 'Seana Bhràigh', 'https://www.walkhighlands.co.uk/ullapool/seana-bhraigh.shtml', 27.0, 1095, 10.0, 'Seana Bhràigh is a remote Munro with dramatic northern cliffs and great wilderness views. A long walk, with sections which could be difficult to navigate in poor visibility. The forestry track can be cycled to save 5km of walking.', 57.8203, -5.0626),
('ae8e8413-bdca-546a-94e2-1e6ee3b054ec', 'Rubh an Eireannaich, Broadford', 'https://www.walkhighlands.co.uk/skye/irishmanspoint.shtml', 3.5, 20, 1.0, 'This picturesque walk follows a shoreside path to reach Broadford pier and then continues out to the low headland beyond. There are good opportunities for spotting wildlife and flowers. The optional alternate return is boggy.', 57.2416, -5.9098),
('aeaaaf56-a5ce-56fd-a81b-a985ec842a09', 'Harris Walkway 2: Tarbert to Seilebost', 'https://www.walkhighlands.co.uk/outer-hebrides/harris-walkway-2.shtml', 23.5, 494, 7.0, 'The southern section of the Harris walkway (now part of theHebridean Way) follows a variety of old paths and sections of minor roads past the tiny bays, wide seas and barren moors of the Bays district before following an old coffin route over a low bealach to reach the machair at Seilebost, overlooking Luskentyre sands.', 57.8981, -6.8049),
('aed0c390-c302-5ce4-af54-31fde2e68600', 'Castle O''Burrian and Bay of Tafts - Westray', 'https://www.walkhighlands.co.uk/orkney/bay-of-tafts.shtml', 5.5, 68, 2.0, 'The Castle o'' Burrian is a bulky sea stack off the Westray coast; it is renowned as the best place in all Orkney to see puffins at close range. The walk continues along dramatic clifftops before cutting across the island to visit the lovely sandy beach of the Bay of Tafts.', 59.2657, -2.8759),
('aedebb99-9006-506a-99e0-f5665abb7625', 'Ardmore Point, near Helensburgh', 'https://www.walkhighlands.co.uk/lochlomond/ardmore-point.shtml', 3.25, 2, 0.75, 'A short, easy walk around a small peninsula in the Firth of Clyde. Excellent views with seal and bird watching opportunities.', 55.9715, -4.68609),
('af06e941-388b-5d5b-b95f-62010bc5b21f', 'Craigieburn Forest, neat Moffat', 'https://www.walkhighlands.co.uk/galloway/craigieburn-forest.shtml', 4.5, 145, 1.5, 'This excellent waymarked circular walk through the Craigieburn Forest gives some fine views over Moffat Dale.', 55.34, -3.3836),
('af398bab-9287-5f7c-905b-1f79f4f2dc8e', 'Beinn Talaidh, via Glen Forsa', 'https://www.walkhighlands.co.uk/mull/beinn-talaidh.shtml', 18.0, 748, 6.0, 'Beinn Talaidh was once Mull''s second Corbett, before being demoted as it was found to be below 2500 feet. It is a steep-sided grassy peak, isolated from its neighbours by very low bealachs, and at the heart of the peaks of Mull it gives excellent views. This ascent via Glen Forsa to the north gives a longer approach but probably more enjoyable than the direct ascent from the A849 to the south.', 56.5141, -5.90979),
('af4ba0d2-0388-576c-b154-aef19fa79d7e', 'Glas Bheinn from Kinlochleven', 'https://www.walkhighlands.co.uk/fortwilliam/glas-bheinn.shtml', 20.75, 889, 8.0, 'Glas Bheinn is a shy and retiring Corbett, remaining hidden from most viewpoints as it rises shapelessly from the wild moors east of Kinlochleven. It provides an enjoyable walk, however, with unfamiliar perspectives on the surrounding higher peaks.', 56.7169, -4.96308),
('af5266a6-0537-51d4-ae8c-7ee560edc5aa', 'Fiacaill Ridge to Cairn Lochan and Cairn Gorm', 'https://www.walkhighlands.co.uk/cairngorms/fiacaill-ridge.shtml', 10.25, 775, 6.0, 'Fiacaill Coire an t-Sneachda - often known simply as the Fiacaill Ridge - offers the most interesting way up to the Cairn Gorm / Ben Macdui plateau for those who enjoy scrambling. The route is a Grade 1/2 scramble if the crest is taken, but any difficulties can be avoided on the right. The ridge can be used as the start of many different mountain days - including heading to Ben Macdui - but the route described here visits the nearby top of Cairn Lochan before returning over Cairn Gorm.', 57.134, -3.6712),
('afde02d5-d3a2-5432-b4dd-8a4bb1792490', 'Backaskaill Bay, Sanday', 'https://www.walkhighlands.co.uk/orkney/backaskaill-bay.shtml', 5.5, 44, 1.5, 'Explore the beautiful sandy beach of Backaskail Bay before heading inland, passing the ruins of a 16th century chapel before following country roads back to the start, with the chance of more bird watching on Bea Loch on the way.', 59.2395, -2.6242),
('afe21de0-9a96-5cf8-90d7-e300a1cceefc', 'Glen Sherup horseshoe, Glen Devon', 'https://www.walkhighlands.co.uk/fife-stirling/glen-sherup.shtml', 16.0, 600, 6.0, 'A circular tour of the hills either side of Glen Sherup, including the popular summit of Ben Shee, the Donalds Innerdownie and Tarmangie Hill, and the Glendevon Woodlands. Superb views from the high ground.', 56.2278, -3.6602),
('afe405cf-8c3e-590f-b20b-c72f97e13f2a', 'Cranstackie and Beinn Spionnaidh', 'https://www.walkhighlands.co.uk/sutherland/cranstackie.shtml', 12.0, 1030, 8.0, 'These two quartzite-topped Corbetts are the most northerly mountains in Britain. Together they give a rough but enjoyable hillwalk; the views are every bit as good as might be guessed from their position. Cranstackie is the most distinctive of the two peaks, whilst Beinn Spionnaidh has the most open outlook of the north coast.', 58.4892, -4.8623),
('b0182952-f24e-5293-8fd9-7310275cc10a', 'Banff and Whitehills circuit', 'https://www.walkhighlands.co.uk/aberdeenshire/banff-whitehills.shtml', 8.0, 44, 2.5, 'This almost level walk includes a lovely beach section followed by rocky shoreline renowned for its seabirds and seals and then a visit to Whitehills before looping back to rejoin the outward route.', 57.6712, -2.5245),
('b021ac5c-f691-581a-9ba0-dfa448d7ca2d', 'Dreggie & Glen Beg, Grantown on Spey', 'https://www.walkhighlands.co.uk/cairngorms/dreggie.shtml', 9.0, 173, 3.5, 'This varied circuit climbs above Grantown into the quiet, rolling hills, with fine distant views of the Cairngorms. The return visits a lovely stretch of the River Spey, and the town''s old curling and skating loch.', 57.3311, -3.608),
('b03ba6b0-6daa-5d9e-9604-59c8b55ee017', 'Douglas Estate lochs and Castle Dangerous, Douglas', 'https://www.walkhighlands.co.uk/glasgow/douglas.shtml', 6.5, 60, 1.5, 'Douglas, set just off the motorway on the northern flanks of the Lowther Hills, has a rich history. This walk explores both the village and the attractive lochs on the Douglas estate - as well as a visit to ''Castle Dangerous''.', 55.556, -3.847),
('b045e201-7a38-5b27-90aa-256cda0e2ec8', 'Twa'' brigs walk, Muirkirk', 'https://www.walkhighlands.co.uk/glasgow/twa-brigs-muirkirk.shtml', 5.25, 63, 2.0, 'This circular walk combines easy tracks and a rougher moorland burn, visiting two historic bridges and the original of tarmac.', 55.5146, -4.0658),
('b068524d-1ed5-5065-9310-4ce6cd7e5cb7', 'Linlithgow Loch and Palace', 'https://www.walkhighlands.co.uk/lothian/linlithgow.shtml', 3.5, 24, 1.0, 'This picturesque but straightforward walk around Linlithgow Loch has plenty of interest and wildlife - perfect for families. The route passes ancient Linlithgow Palace, and is stone''s throw from the town''s High Street with shops and cafes.', 55.977, -3.6073),
('b0792568-192f-5c49-99ef-8680c7b1bf10', 'Glas Tulaichean & Càrn an Rìgh, Glenshee', 'https://www.walkhighlands.co.uk/perthshire/glas-tulaichean.shtml', 27.0, 1085, 10.0, 'This pair of Munros lie out in the empty lands of the Mounth between Beinn a''Ghlò and Glen Shee. Glas Tulaichean has a track almost right to the summit but good views, whilst Càrn an Rìgh is a less shapely but much wilder and more remote.', 56.8141, -3.4672),
('b0cb3cc8-8793-559a-99ea-c010ed820a7e', 'The Isla Way: Dufftown to Keith', 'https://www.walkhighlands.co.uk/moray/isla-way.shtml', 20.5, 330, 5.0, 'The Isla Way links the distillery towns of Dufftown and Keith, taking a varied route of woodland, minor roads and field paths. This is a linear walk, but there is a heritage railway link between Dufftown and Keith on summer weekends, and a bus on weekdays; check timetables before setting off. The route can be shortened by ending at Drummuir.', 57.4448, -3.1284),
('b11e54fc-a5b2-5aac-8f87-e7d435743d34', 'Doune Castle and the River Teith', 'https://www.walkhighlands.co.uk/fife-stirling/doune.shtml', 2.75, 24, 1.0, 'This short walk around the fascinating small town of Doune takes in the mighty castle as well as a fine section of riverbank.', 56.1889, -4.0512),
('b13334c8-375a-5985-9e65-c4679b584e83', 'Dùn Morbhaidh, Cornaigbeag', 'https://www.walkhighlands.co.uk/islands/dun-morbhaidh.shtml', 1.0, 15, 0.5, 'A short stroll across the machair leads out to Dùn Morbhaidh, the site of an ancient fort with a great position looking up and down the coastline. There''s a sandy beach nearby too.', 56.6765, -6.5136),
('b1364d81-dea8-5f9f-be3a-3cb2d4d7f311', 'Beinn Achaladair and Beinn a''Chreachain', 'https://www.walkhighlands.co.uk/argyll/beinn-achaladair.shtml', 21.5, 1266, 9.0, 'This pair of Munros forms the northerly half of the Beinn Dòrain range and gives a grand ridgewalk. Beinn a''Chreachain, the highest Munro in the range, has a fine northern corrie, whilst Beinn Achaladair is a very shapely peak with much character. The views - especially looking out over the vast soggy table-land of Rannoch Moor - are magnificent.', 56.5556, -4.7461),
('b187a75a-97d7-53ab-a804-13099a856770', 'Fairy Pools and Coire na Creiche', 'https://www.walkhighlands.co.uk/skye/fairypools.shtml', 8.0, 360, 3.5, 'Social media exposure has led to first part of this walk - to the Fairy Pools - becoming extremely popular in recent years. It follows a beautiful crystal clear burn with many beautiful pools and waterfalls. The paid car park is busy in high season; it''s best to either arrive early, or consider a quieter alternative at the busiest times when the pools are overcrowded. On Walkhighlands, we describe a longer walk that leads away from the crowds to make a memorable circuit around this fine Cuillin coire.', 57.2506, -6.2725),
('b1984147-9b6c-57d1-8101-dbb747f69069', 'Burrow Head Coastal Circuit, Isle of Whithorn', 'https://www.walkhighlands.co.uk/galloway/burrow-head.shtml', 8.75, 147, 3.0, 'Explore Burrow Head, the southern most point on the Machars, on this coastal circuit. The clifftop here was used to film the final scenes from The Wickerman and provides dramatic scenery today.', 54.7009, -4.3647),
('b19b3c72-cc83-5c12-a561-18873fef6b88', 'Beinn Dòrain & Beinn an Dòthaidh, Bridge of Orchy', 'https://www.walkhighlands.co.uk/argyll/beinn-dorain.shtml', 14.3, 1228, 8.0, 'Beinn Dòrain is one of the most instantly recognisable Munros in the southern Highlands, a huge conical peak that dominates the A82 when driving north from Tyndrum. Its ascent can easily be combined with neighbouring Beinn an Dòthaidh which has a fine outlook over Rannoch Moor.', 56.5169, -4.7692),
('b1a231ee-4c54-54e5-b31e-b7ac68f28547', 'Càrn a''Chlamain', 'https://www.walkhighlands.co.uk/perthshire/carn-a-chlamain.shtml', 26.0, 930, 9.0, 'Càrn a'' Chlamain is the relatively minor stony summit rising above a spacious and very remote plateau. The approach is up scenic Glen Tilt, one of the Highlands'' most beautiful glens and it is this that makes the walk a minor classic.', 56.7745, -3.84325),
('b1b95c1e-41a0-5b0a-beb4-d838e62b54a9', 'Neist Point', 'https://www.walkhighlands.co.uk/skye/neistpoint.shtml', 3.0, 142, 2.0, 'Neist Point - the most westerly headland on Skye - is an iconic destination, with stunning cliff scenery, a fine lighthouse, an outlook to the Outer Hebrides, and the chance to watch for minke whales in the summer months.', 57.4296, -6.7791),
('b1df76a1-2d94-5334-95ef-199987ae1959', 'Beinn Mheadhoin & Derry Cairngorm, Deeside', 'https://www.walkhighlands.co.uk/cairngorms/mheadhoin-derry.shtml', 31.0, 1200, 10.0, 'This long hillwalk heads from the Linn of Dee heads up to Derry Lodge before climbing over the bald, stony summit of Derry Cairngorm. It then continues past the foot of Loch Etchachan to climb remote Beinn Mheadhoin with its majestic granite tours at the very heart of the wild Cairngorms. The return is down beautiful Glen Derry and through its pinewoods.', 56.99, -3.5443),
('b23675c3-c5fe-5e35-b89c-f49170e0c115', 'Torrisdale Bay and Broch, Invernaver', 'https://www.walkhighlands.co.uk/sutherland/torrisdale-bay.shtml', 8.0, 163, 2.5, 'This superb walk takes in a spectacular beach, dunes, riverside and moorland, as well as visiting an iron-age broch with stunning views. It passes an area of Special Scientific Interest due to the rare plants and archaeological remains. The walk section over the top can be hard to follow so some navigation skills are needed.', 58.5109, -4.2152),
('b2427560-24a1-53bf-8d4e-7a6ac859efa7', 'Dundee Law from Discovery Point', 'https://www.walkhighlands.co.uk/angus/dundee-law.shtml', 5.25, 168, 3.0, 'Explore Dundee - the City of Discovery - on this walk that takes in the major attractions of the city centre before crossing town to climb up Dundee Law for its sensational views.', 56.4572, -2.9686),
('b2c5254d-4793-5c1d-bbd0-afe242a7d22b', 'Cardrona Forest and Pikes Knowe', 'https://www.walkhighlands.co.uk/borders/cardrona-forest.shtml', 7.0, 230, 3.0, 'This route combines the longer forestry trails at Cardrona. After an initial zig-zag ascent there''s a stunning view up the Tweed Valley. The route then passes the remains of Cardrona Tower and an iron age fort site before a lengthy return through dense conifers on Pikes Knowe.', 55.6342, -3.125),
('b32deb63-d499-5206-86c9-0572ce98da42', 'Drumin Castle walk', 'https://www.walkhighlands.co.uk/cairngorms/drumin-castle.shtml', 4.0, 98, 1.0, 'This enjoyable ramble follows the waymarked Drumin Community Circuit and takes in a section of the River Livet as well as a visit to the ruins of Drumin Castle.', 57.353, -3.3405),
('b36e1d32-dcca-52eb-bba3-4ecbd903f861', 'Anagach Woods and the River Spey, Grantown', 'https://www.walkhighlands.co.uk/cairngorms/anagach-woods.shtml', 11.5, 250, 3.5, 'Anagach Woods are a beautiful native Scots pinewood, the haunt of the Capercaillie. There are several waymarked trails through the woods; this route is longer and takes in part of the River Spey as well as the woods themselves.', 57.3313, -3.6079),
('b394e0d5-62f9-5db7-9fd6-f7a67d8c6b19', 'Culloden Battlefield and Clava Cairns', 'https://www.walkhighlands.co.uk/lochness/culloden-clava.shtml', 13.25, 195, 3.5, 'This route combines a visit to the Culloden Battlefield - where the Jacobite Rising met its end - and the stunning prehistoric Clava Cairns. The remainder of the walk is through pleasant semi-rural countryside. The walk is partly signed as the Culloden Battlefield Trail.', 57.4827, -4.1397),
('b3ea7a83-78b6-534a-8065-818b104f1eaa', 'Gairbeinn and Corrieyairack Hill, Melgarve', 'https://www.walkhighlands.co.uk/cairngorms/gairbeinn.shtml', 15.5, 754, 6.5, 'Gairbheinn and Corrieyairack Hill were once regarded as Corbett twins, both having the same height on maps although the descent between them is insufficient for them to be separate Corbetts. Gairbheinn has since found to be marginally higher, but both hills together still make an enjoyable round, descending from the top of the Corrieyairack Pass.', 57.0289, -4.5264),
('b40f769a-48a9-5e0f-9e1c-1d74d0fa0cd0', 'Linn of Ruthrie, Aberlour', 'https://www.walkhighlands.co.uk/moray/aberlour.shtml', 3.0, 67, 1.0, 'Aberlour - or Charlestown of Aberlour to give it its full Sunday name - is a beautiful village near the Spey. This excellent short walk visits the fine Linn of Ruthrie (Linn Falls) on the Aberlour Burn.', 57.4702, -3.2298),
('b47b83ba-4ca9-55d8-bd85-30474d0a7f8a', 'Heoga Ness & Ladies Hole from Burravoe, Yell', 'https://www.walkhighlands.co.uk/shetland/burravoe.shtml', 5.25, 54, 2.0, 'A coastal walk right around the low lying Heoga Ness, a popular spot for otters, and a visit to Ladies Hole, a dramatic semi-circle of high cliffs home to puffins and numerous other nesting seabirds.', 60.4976, -1.0443),
('b499a95d-ffca-571e-af59-573adc7de2b3', 'Dalkeith Country Park circuit', 'https://www.walkhighlands.co.uk/lothian/dalkeith-park.shtml', 6.25, 90, 2.0, 'The grand stately pile of Dalkeith House is at the heart of a Country Park that makes for a fine walk, taking in the spectacular ruined conservatory, the banks of the Rivers North and South Esk, and an ancient oakwood.', 55.9026, -3.06096),
('b4e2f73c-45d4-5c09-8a32-2be448f50f25', 'Leacainn Walk, Furnace', 'https://www.walkhighlands.co.uk/argyll/leacainn.shtml', 8.5, 210, 4.0, 'This excellent circular walk links the Loch Fyne village of Furnace with the site of an ancient township at Auchindrain (museum now closed). It was waymarked to celebrate the millenium and features forests, waterfalls, rivers, pastures and loch views.', 56.1522, -5.1848),
('b4fc7d65-3ca3-5c66-be98-f3b9918ce879', 'Loch Morar to Tarbet, Bracorina, near Morar', 'https://www.walkhighlands.co.uk/fortwilliam/morar-tarbet.shtml', 9.0, 129, 3.0, 'A fantastic walk along Loch Morar with great mountain views then over a low pass to Tarbet on Loch Nevis. Western Isles Cruises ferry can be used to return to Mallaig (usually 3:40pm) but must be booked in advance (01687 462233) - checktimetable here. If using the ferry, a train or bus could be caught from Mallaig to Morar, and an additional road walk of 5km leads back to Bracorina unless transport has been arranged. Alternatively, you could make an 18km walk by simply returning from Tarbet on foot the same way.', 56.9697, -5.74349),
('b51733a9-8800-50d6-8770-5413316f857b', 'Heanish and Tràigh an Duin', 'https://www.walkhighlands.co.uk/islands/heanish.shtml', 3.85, 25, 2.0, 'This short walk explores Heanish, just west of Scarinish. It heads down from the houses across the machair to visit a dun and sandy bay.', 56.5011, -6.80776),
('b5185b98-7d94-5499-bd94-e952db90083d', 'Mealna Letter and Loch Beanie', 'https://www.walkhighlands.co.uk/angus/mealna-letter.shtml', 14.0, 469, 5.0, 'A great circuit climbing to the summit of Mealna Letter with good views before descending to Loch Beanie to return along the Cateran Trail in Glen Shee. Very boggy at the start and near Loch Beanie.', 56.7617, -3.3855),
('b51cef37-d074-5a83-8c28-d14f457daad1', 'Kilmichael archeology walk, Glecknabrae', 'https://www.walkhighlands.co.uk/argyll/kilmichael.shtml', 7.8, 175, 2.0, 'This walk follows a track along the west side of Bute with great views across the Kyles to Kames and Tighnabruaich in Cowal. The interest is in the various diversions from the track to visit the remains of several chambered cairns and the ruins of a chapel.', 55.8669, -5.1901),
('b542284a-59d8-5514-bde7-4d4690378f08', 'Allt na Calliche Trail, near Invergarry', 'https://www.walkhighlands.co.uk/fortwilliam/alltnacalliche.shtml', 4.5, 145, 2.0, 'Follow a delightful stream up through the forest, passing an attractive waterfall. The descent follows a track with more open views.', 57.0713, -4.83329),
('b54eb802-22ea-5dec-b1c0-63484a801eea', 'Birnam Oak and the River Tay, Dunkeld', 'https://www.walkhighlands.co.uk/perthshire/birnam.shtml', 6.0, 40, 2.0, 'This waymarked walk visits the ancient Birnam Oak together with other remarkable trees along a lovely stretch of the River Tay. The route returns through the village of Birnam with beautiful historic buildings and a Beatrix Potter garden.', 56.5647, -3.58413),
('b5546b19-61f7-5cee-805e-382392798ba6', 'Greshornish Point', 'https://www.walkhighlands.co.uk/skye/greshornish.shtml', 6.0, 141, 3.0, 'The Greshornish Peninsula is encircled by some beautiful coastal cliff scenery; the circuit around it is a short but challenging outing with lovely views.', 57.4991, -6.4403),
('b593144f-f591-5f51-817c-e8ac2f1f4d48', 'Dun Rig Horseshoe, Peebles', 'https://www.walkhighlands.co.uk/borders/dun-rig.shtml', 23.5, 941, 8.0, 'A fantastic hill walk from Peebles, taking in the four peaks surrounding Glensax with extensive views in all directions. Peat bogs in places.', 55.6408, -3.17736),
('b5aef027-b9a5-5841-8939-7b236693388a', 'Creag Dubh, near Newtonmore', 'https://www.walkhighlands.co.uk/cairngorms/creag-dubh.shtml', 5.0, 503, 4.0, 'Though not even a Corbett, Creag Dubh is a fine individual mountain, a wonderful viewpoint not far from Newtonmore. On its lower slopes is a celebrated rock-climber''s crag. Creag Dubh is the battle-cry of Clan MacPherson and the ascent is steep and rough enough to require a few battle cries of your own.', 57.0339, -4.1866),
('b5bab557-57d6-51b2-881f-ced39edc3eea', 'Balmerino and Thornton circuit', 'https://www.walkhighlands.co.uk/fife-stirling/balmerino.shtml', 5.25, 92, 1.5, 'The walk begins through attractive woodlands overlooking the Firth of Tay before returning along an old country lane. Leave time to visit the ruins of Balmerino Abbey.', 56.4098, -3.0427),
('b5e83596-1b87-51ce-8a9a-96f2762bbf74', 'Sgùrr an Airgid', 'https://www.walkhighlands.co.uk/kintail/Sgurranairgid.shtml', 10.5, 932, 6.0, 'Sgùrr an Airgid may seem like the lowly neighbour amongst the peaks of Kintail, but don''t be mistaken. Despite its lower height, it offers a relatively straightforward hillwalk revealing some of the area''s most magnificent views. An excellent introduction to the higher mountains of the area.', 57.2354, -5.4042),
('b5ecfbb7-33b6-5774-a591-6d070a61a9ee', 'The Brack and Cnoc Còinnich , Ardgartan', 'https://www.walkhighlands.co.uk/lochlomond/the-brack.shtml', 15.5, 1086, 7.5, 'The Brack gives a steep ascent with great character, conveniently climbed in combination with Cnoc Còinnich , a recent addition to the ranks of the Corbetts. Both hills have a fine position above Loch Long. There is some pathless, rugged ground particularly on the descent from the Brack. The route joins the Cowal Way for the return to Ardgartan.', 56.1946, -4.7913),
('b6600959-9fc6-5d09-b6e2-fed3760ea9c1', 'An Socach from Glen Clunie', 'https://www.walkhighlands.co.uk/cairngorms/an-socach.shtml', 15.75, 655, 6.0, 'An Socach is one of the lesser Munros of the area, a rounded whaleback hill which can either be climbed quickly by this short route from Baddoch Farm, or via an alternative approach from Inverey and Glen Ey.', 56.9313, -3.417),
('b66222f8-2bc3-5636-85a7-ac7df71b2e5b', 'Scolty Hill, near Banchory', 'https://www.walkhighlands.co.uk/aberdeenshire/scolty-hill.shtml', 3.25, 189, 1.5, 'A fantastic short walk with steep climb to the summit of Scolty Hill where you can climb the spiral staircase to the top of the tower for an even better view of the surrounding countryside. The walk can easily be extended by including the red-waymarked March Trail through the woods.', 57.0429, -2.5178),
('b6816f70-e6ac-5c38-b5a9-344449057b8c', 'Byne Hill, Girvan', 'https://www.walkhighlands.co.uk/glasgow/byne-hill.shtml', 6.5, 220, 2.5, 'Shapely Byne Hill is a familiar landmark when seen from Girvan. Its coastal position ensures that it offers some of the best views in Ayrshire. The descent route given is steep and rocky with minor scrambling, and it raises the route towards Grade 3 - it can be avoided by returning the same way.', 55.2281, -4.859),
('b6850a99-5ba0-5ab9-8d0d-c6b4386e0efe', 'Devil''s Trail, Barr', 'https://www.walkhighlands.co.uk/glasgow/devils-trail.shtml', 7.0, 169, 2.0, 'A straightforward wander through Changue Forest offering some panoramic views over the Stinchar Valley and Carrick hills.', 55.2119, -4.6945),
('b6ff1e5f-7229-57eb-992c-c1e8925fa080', 'Dùn Caan', 'https://www.walkhighlands.co.uk/skye/duncaan.shtml', 15.5, 540, 6.0, 'The distinctive flat-topped summit of Dùn Caan (Dùn Cana in Gaelic) is the highest hill on the Isle of Raasay and a sensational viewpoint. Standing at the top, surrounded by endless views of mountain and sea, one can sympathise with James Boswell who is said to have danced a jig when he visited the summit during his famous tour of the Highlands and Islands with Samuel Johnson.', 57.3505, -6.0818),
('b715e749-acff-54f1-a65b-79e3af42fe7b', 'Dun Ardtreck and Ardtreck Point, Fiskavaig', 'https://www.walkhighlands.co.uk/skye/dun-ardtreck.shtml', 4.75, 148, 2.0, 'Ardtreck Point is the northernmost part of Minginish, and an automated light guards the entrance to Loch Harport. The highlight of this enjoyable short moorland walk is the stunningly situated remains of Dun Ardtreck.', 57.3364, -6.4179),
('b72a48b5-a71e-5773-855f-acf64064d620', 'Tap o'' Noth, near Rhynie', 'https://www.walkhighlands.co.uk/aberdeenshire/tap-o-noth.shtml', 5.0, 294, 2.5, 'Climb up to the prominent peak of the Tap o'' Noth, site of the second highest hillfort in Scotland. The remains are impressive, and the views over rural Aberdeenshire are superb.', 57.3431, -2.8648),
('b72d72e5-10a7-5682-85a7-faf2efc3cdab', 'Culswick Broch and the Burga Stacks, Culswick', 'https://www.walkhighlands.co.uk/shetland/culswick-broch.shtml', 6.0, 140, 2.0, 'This superb and fairly short walk visits an iron age broch set on a spectacular section of Westside''s coastline, with fine cliffs and sea stacks.', 60.1883, -1.5107),
('b734f05f-33c4-55d0-92a5-5b0a02fae4f8', 'Kildalton Cross and Port Mòr', 'https://www.walkhighlands.co.uk/islay-jura/kildalton-cross.shtml', 2.5, 11, 1.0, 'The magnificent carved Celtic Cross at Kildalton dates from the late eighth century and merits a place on the itinerary of every visitor to Islay. This short walk heads down from the cross to visit the coastline.', 55.6842, -6.0452),
('b752e206-e371-5698-8c66-ac768d285e91', 'Gairich, Loch Cuaich', 'https://www.walkhighlands.co.uk/fortwilliam/gairich.shtml', 15.5, 850, 7.0, 'Gairich gives a fairly easy day out for Munro baggers; this isolated summit is a superb viewpoint.', 57.0719, -5.1877),
('b7868641-23a7-5936-8ca0-7774a9a1a37d', 'Croy Hill and the Antonine Wall, near Kilsyth', 'https://www.walkhighlands.co.uk/glasgow/croy-hill.shtml', 10.5, 206, 4.0, 'This interesting circular route takes in two Roman hill forts on the Antonine Wall, both good viewpoints, as well as the Forth and Clyde Canal. The route starts and finishes at Auchinstarry Marina on the canal where is parking and toilets.', 55.9664, -4.0503),
('b79b4989-8cf7-5f7b-a096-984bac92532a', 'Palacerigg Country Park, Cumbernauld', 'https://www.walkhighlands.co.uk/glasgow/palacerigg.shtml', 7.5, 93, 2.0, 'Palacerigg Country Park was created from a bleak upland farm in the early 1970s, on the hills above the new town of Cumbernauld. It provides a fine walk mostly through native woodland, a quiet stretch of countryside in one of the more built-up areas of the central belt.', 55.9368, -3.9436),
('b7edb291-273d-5672-96cc-0d82b86ef5e5', 'Sumburgh Head and Jarlshof circuit', 'https://www.walkhighlands.co.uk/shetland/sumburgh-head.shtml', 5.5, 197, 3.0, 'This is a real Shetland classic, combining two of the island''s most famous attractions into a great coastal circuit. It begins at Jarlshof - the most remarkable archaelogical site in Shetland. It then runs along the coastline before climbing up to Sumburgh Head and its lighthouse - the southernmost point of Shetland, and renowned for the chance it gives to see puffins at close quarters during the summer season. The return above the clifftops gives superb views.', 59.8692, -1.2875),
('b81c91dd-970f-5e79-8643-44db95b6a899', 'Inverinan Trail, Loch Awe', 'https://www.walkhighlands.co.uk/argyll/inverinan.shtml', 4.0, 117, 1.5, 'This unmarked forest walk climbs up through the broadleaved woods clothing the gorge of the Abhainn Fionn. The first part follows an old drove road along which cattle were driven from the north to markets in southern Scotland.The route then descends to a bridge deep in the glen before returning via old paths and tracks.', 56.308, -5.2381),
('b831ece2-5b36-507b-914b-e4bb3695e534', 'Fisherman''s walk circuit, Brodick', 'https://www.walkhighlands.co.uk/arran/brodick-bay.shtml', 5.5, 36, 2.0, 'This excellent walk runs from Brodick around the Bay to the fine sandy beach before reaching the entrance to Brodick Castle. It then returns via inland paths and country lanes, passing the Isle of Arran Cheese company and Arran Aromatics at Home Farm, and the Arran Heritage Museum. The walk can also be used as an approach to several other routes, including the usual route up Goat Fell and the circuit around the Brodick Castle Country Park.', 55.5777, -5.1505),
('b85059af-384f-536e-8aad-1bce9efd5d94', 'Hermaness National Nature Reserve, Unst', 'https://www.walkhighlands.co.uk/shetland/hermaness.shtml', 10.0, 372, 4.0, 'Hermaness is one of Shetland''s truly special places - a dramatic clifftop National Nature Reserve that is also a spectacular seabird city - home to more than 100,000 birds in the breeding season, including countless puffins, a huge gannetry and the world''s third largest colony of bonxies - great skuas. The awesome cliffs look out to the serrated rocks of Muckle Flugga and Out Stack - the most northerly place in Britain.', 60.8127, -0.8766),
('b8ae7c49-af24-5d68-a415-6caffa853565', 'Criffel circuit from New Abbey', 'https://www.walkhighlands.co.uk/galloway/criffel-new-abbey.shtml', 12.5, 607, 5.5, 'An approach from New Abbey enables the ascent of Criffel - the finest viewpoint in the area - to be made into a varied circular walk.', 54.9808, -3.6196),
('b8bd9115-483b-5b4e-9271-0743b691e2a2', 'Oswald''s Trail, Auchincruive', 'https://www.walkhighlands.co.uk/glasgow/oswald-auchincruive.shtml', 4.75, 35, 1.5, 'Located just outside Ayr, this walk combines a stretch of pleasant riverside walking with woodland trails in the grounds of the former Auchencruive estate.', 55.475, -4.55334),
('b8bfc091-f42a-54b7-953b-3219a7b38a38', 'Craigendarroch oakwoods, Ballater', 'https://www.walkhighlands.co.uk/cairngorms/craigendarroch.shtml', 4.0, 315, 2.0, 'Craigdendarroch may be a small hill, but it has a big place in the affections of Ballater folk. Its oakwood-clad flanks are steep making its ascent an enjoyable but arduous little walk. The views are superb.', 57.0499, -3.0407),
('b8cfaf46-8556-5239-84e4-98bbe849b875', 'Sutherland''s Grove forest walks, Barcaldine', 'https://www.walkhighlands.co.uk/argyll/glen-dubh.shtml', 2.7, 60, 1.0, 'This walk follows a waymarked trail through the forest, leading up through a fine gorge. The return route follows tracks and paths to complete a circuit through the forest.', 56.5273, -5.30906),
('b8ff0b1f-d5ec-54b6-9cb1-488373c5fdb0', 'Keil Caves, St Columba''s Steps and Dunaverty', 'https://www.walkhighlands.co.uk/argyll/southend.shtml', 5.5, 35, 2.0, 'Southend has a host of historical attractions as well as fine beaches; this walk attempts to link them all. The Keil Caves were long used as dwellings; St Columba''s footprints, chapel and well are a reminder that this is where he landed in Scotland in 563, and the rock of Dunaverty is a reminder of a bloody episode in history.', 55.3083, -5.6722),
('b9093e19-010d-598e-8709-ff34bb7a844c', 'Pierowall - Kirk, Castle and Beach, Westray', 'https://www.walkhighlands.co.uk/orkney/pierowall.shtml', 5.5, 30, 2.0, 'This straightforward circular walk explores the environs of Pierowall, the largest settlement on Westray. Beginning from the medieval kirk, it gives views over to the harbour before visiting a fine beach and the imposing Noltland Castle which dates back to the sixteenth century.', 59.3223, -2.9877),
('b951d87e-8d92-5c86-aded-3cced45eabb7', 'Bin of Cullen', 'https://www.walkhighlands.co.uk/moray/bin-of-cullen.shtml', 5.5, 180, 1.5, 'The Bin of Cullen is a dome-shaped 320m hill rising above the forestry with a bare summit, dominating the landward views from coastline from Cullen to Buckie.', 57.6565, -2.8531),
('b96b9558-5a79-5edf-91d4-bee1a11ff4ae', 'Ben More Assynt and Conival', 'https://www.walkhighlands.co.uk/ullapool/benmoreassynt.shtml', 17.25, 1077, 10.0, 'The only Munros in Assynt, these two rocky mountains are connected by a fine ridge. Together they give a very rough but rewarding ascent combined with the amazing views characteristic of all the Assynt peaks.', 58.1487, -4.9734),
('b976e980-94a0-5669-a95c-30472b6ded33', 'Glen Donich circuit, Lochgoilhead', 'https://www.walkhighlands.co.uk/argyll/glen-donich.shtml', 4.0, 230, 2.0, 'This waymarked forestry walk from Lochgoilhead gives an enjoyable circuit of the lower part of Glen Donich. It can be extended by including an alternative waymarked route higher on the north side of the glen.', 56.1703, -4.9012),
('b9b33833-184d-57a0-9f14-b777fc61ee92', 'Livingstone walk, Ulva', 'https://www.walkhighlands.co.uk/mull/livingstone-walk.shtml', 7.5, 185, 4.0, 'The explorer David Livingstone''s grandparents lived on a croft near the southern shores of beautiful Ulva and this excellent, varied circuit visits the ruins at the site as well as a cave and some basalt columns on the coastline. Make sure you leave plenty of time to get back before the last ferry. There is usually no ferry on Saturdays, and Sundays are only in high season.', 56.4808, -6.1532),
('b9d87c67-5eaf-5bc9-94cd-08e4e1425c8f', 'Ben Venue from Loch Achray', 'https://www.walkhighlands.co.uk/lochlomond/ben-venue.shtml', 14.0, 725, 6.0, 'Ben Venue may be small in stature but it is a mountain of real character, the finest in the Trossachs when seen across Loch Venachar, Loch Achray or Loch Katrine. The ascent is a great walk with both boggy and rocky ground higher up, and stunning views from the summit.', 56.2307, -4.4121),
('b9dff5b6-2300-559e-87ec-7161ea2ed2b4', 'Oak and Jubilee walk, Auchterarder', 'https://www.walkhighlands.co.uk/perthshire/auchterarder.shtml', 7.0, 110, 2.5, 'This circular walk explores the surroundings of Auchterarder, known as the Lang Toon due to the length of its high street. This walk begins in the centre of town and follows paths taking in the woods and fields around.', 56.296, -3.7067),
('b9f1619f-eb90-53f8-ab19-3308c63b11f2', 'Langamull Beach and Kildavie, near Dervaig', 'https://www.walkhighlands.co.uk/mull/langamull-beach.shtml', 6.25, 80, 2.0, 'This straightforward walk leads to a wild sandy beach with great views over to the Small Isles and Skye. The return walk visits the ruined settlement of Kildavie.', 56.5869, -6.2439),
('ba396ffe-de7e-51a6-ad6f-069c1e9dc896', 'Black Wood and Dùn da-Lamh fort', 'https://www.walkhighlands.co.uk/cairngorms/dundalamh.shtml', 8.5, 436, 4.0, 'This excellent circuit includes forestry, native pinewoods and an open hill ridge with superb views, all en route to the fascinating remains of a Pictish fort.', 56.982, -4.3594),
('ba53a23f-db3b-5eb9-9cf7-b156a398702f', 'Glen Tilt circuit, Blair Atholl', 'https://www.walkhighlands.co.uk/perthshire/glen-tilt.shtml', 14.75, 326, 5.0, 'This classic circular walk explores both sides of Glen Tilt, deservedly regarded as one of Scotland''s most beautiful glens. There are good views throughout. The route is waymarked and follows clear paths, tracks and minor roads. It is not affected by any stalking restrictions.', 56.7745, -3.84326),
('ba9e873b-0053-5670-841e-112a77cb8b1f', 'Morven, from near Logie Coldstone', 'https://www.walkhighlands.co.uk/aberdeenshire/morven.shtml', 8.75, 655, 4.5, 'On the eastern fringe of the Cairngorms, Morven dominates the Aberdeenshire farmland of Cromar lying to its east. It provides a popular ascent for Aberdonians, with extensive views.', 57.1267, -2.9761),
('baae35e9-0ceb-5480-bf06-cc4b32502814', 'Da Kame, Da Sneug & Da Noup: the complete Foula', 'https://www.walkhighlands.co.uk/shetland/complete-foula.shtml', 13.0, 864, 7.5, 'This magnificent walk takes in the main summits of the extremely remote island of Foula. From the airport it follows the coastline to the ferry pier before continuing to the northern part of the island before ascending to Soberlie. The spectacular western coastal cliffs - the highest in the UK outwith St Kilda - are then followed with an extremely steep climb to the top of Da Kame. From there a hill ridge links to Da Sneug - the highest summit on Foula - before dropping down and then climbing to Da Noup - the dramatic southern summit. From here the route returns to the airport; it can be shortened from Da Sneug if time or energy is running out.', 60.1232, -2.0545),
('bad63633-5f44-5bbc-a25c-747899bd2598', 'The Old Man of Hoy from Rackwick', 'https://www.walkhighlands.co.uk/orkney/old-man-of-hoy.shtml', 9.25, 220, 3.0, 'This is the essential, classic walk on Hoy, following the clear coastal path uphill from Rackwick to view the spectacular sea stack, the Old Man of Hoy, before returning by the same route.', 58.8735, -3.3861),
('bad7317a-d4ce-5446-83b8-797146b2a135', 'Leum Uilleim, from Corrour Station', 'https://www.walkhighlands.co.uk/fortwilliam/leum-uilleim.shtml', 9.75, 524, 4.5, 'Leum Uilleim would be a very remote hill were it not for Corrour Station - without arriving by train the ascent would be an epic. From the station, however, it gives a short and very rewarding hillwalk; the position north of Rannoch Moor making it a superb viewpoint.', 56.7602, -4.6906),
('bb2dae27-d4f5-59a7-8475-faa04b01af30', 'Meall nam Maigheach', 'https://www.walkhighlands.co.uk/perthshire/meall-nam-maigheach.shtml', 5.5, 270, 2.5, 'The ascent of this rather soggy Corbett can be quickly accomplished from the pass between Glen Lyon and Loch Tay. The uninspiring terrain is rewarded with a fine summit view, both along Glen Lyon and of the Tarmachan ridge.', 56.5458, -4.30649),
('bb5368cb-f1c6-564d-883b-8f290aabe95f', 'Culross - Heritage walk', 'https://www.walkhighlands.co.uk/fife-stirling/culross.shtml', 4.0, 70, 1.5, 'The Royal Burgh of Culross is the best preserved example of a 17th and 18th century Scottish town. This short walk explores the quaint streets with many historic buildings as well as the front onto the Firth of Forth and a climb up to the ruins of the West Kirk.', 56.0554, -3.6232)
INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('bb990669-d30c-5021-a2e9-8d03fe9107e7', 'Goatfell, from Corrie', 'https://www.walkhighlands.co.uk/arran/goatfell-corrie.shtml', 8.0, 836, 6.0, 'This circular route to the summit of Arran''s highest peak is quieter than the Brodick approach and suitable for more experienced hillwalkers. It explores the mountain''s magnificent north ridge as well as the adjacent, dramatic peak of North Goatfell.', 55.6318, -5.1455),
('bbac0b14-d24b-5c68-82d1-c3518c3a442b', 'Macdonald Monument and the Firth, Dingwall', 'https://www.walkhighlands.co.uk/lochness/macdonald-monument.shtml', 6.0, 95, 2.0, 'This exploration of the outskirts of the attractive market town of Dingwall includes a lovely coastal section, a climb with good views over the town and a visit to a large tower and a wander down the high street.', 57.5955, -4.4288),
('bbf01007-f124-5484-bc89-8bb19ae28985', 'Dumglow, Cleish Hills', 'https://www.walkhighlands.co.uk/fife-stirling/dumglow.shtml', 5.5, 215, 2.0, 'Dumglow is the highest of the Cleish Hills and the most popular of the minor ranges to the north of Dunfermline. The summit is the site of an ancient fort and is almost ringed by steep slopes, but forestry mars most of the approaches. This route also ascents Dummiefarline, the shapeliest of the range.', 56.1571, -3.4608),
('bbf31e09-788a-5156-9f82-c69d7e639df9', 'Littleferry and Loch Fleet', 'https://www.walkhighlands.co.uk/sutherland/littleferry.shtml', 7.0, 15, 2.0, 'This walk explores the eastern part of the Loch Fleet National Nature Reserve. It has fine views, a spacious sandy beach, Scots pine woodland and great opportunities for bird-watching.', 57.9353, -4.01647),
('bc44348f-1b02-5b36-beaf-1b4f80a570a9', 'Knockfarrel and the Peffery Way, Dingwall', 'https://www.walkhighlands.co.uk/lochness/knockfarrel-dingwall.shtml', 11.0, 184, 3.5, 'Climb through farmland to explore the iron age fort of Knockfarrel, a fantastic viewpoint overlooking Dingwall and the Cromarty Firth. The return walk makes use of part of the Peffery Way, a new cycle and footpath between Dingwall and Strathpeffer.', 57.5946, -4.4289),
('bc6e3367-a7ad-5d62-8262-f979a76236bd', 'Egilsay explorer, Egilsay', 'https://www.walkhighlands.co.uk/orkney/egilsay.shtml', 11.75, 86, 3.5, 'Explore the small island of Egilsay, visiting the ancient remains of St Magnus church with its unusual round tower, a beautiful sandy beach, then crossing farmland and the Onziebust RSPB Reserve where a freshwater loch on the coast is a haven for birds.', 59.1555, -2.9443),
('bce6ea41-09e5-52f7-bbab-ae1dffb62377', 'Barnluasgan Oakwood, Beaver trial site', 'https://www.walkhighlands.co.uk/argyll/barnluasgan.shtml', 2.5, 125, 1.5, 'This very attractive walk climbs to a low ridge, richly forested with ancient oaks and birches, looking out over the scattered lochs and great forests of Knapdale. The route lies within the Scottish Beaver reintroduction trial area.', 56.0606, -5.5512),
('bcf1e113-ad3d-57a0-8b5e-ccfd1207f895', 'Red Point to Craig', 'https://www.walkhighlands.co.uk/torridon/Redpointcraig.shtml', 14.0, 250, 5.0, 'This is part of the wild coastal walk between Diabaig in Torridon and Red Point. Times given are for the return walk from Red Point to Craig.', 57.6508, -5.80342),
('bcf903ef-127b-5c15-8820-5ace4c41ec16', 'Loch Freuchie circuit, Amulree', 'https://www.walkhighlands.co.uk/perthshire/loch-freuchie.shtml', 12.25, 140, 3.0, 'This pleasant circuit leads through a little visited part of Perthshire, looping around an attractive loch surrounded by open moorland. The return leg is on a minor road but there is little traffic.', 56.5096, -3.7879),
('bd262ebc-a7d9-505c-9cd5-470a486fc194', 'Corran sands and river circuit', 'https://www.walkhighlands.co.uk/islay-jura/corran-sands.shtml', 4.0, 13, 1.5, 'Corran Sands is a beautiful sweep of shell sand around a lovely bay - probably the finest beach on Jura. This circular walk explores the beach before returning on a muddier path by the Corran river.', 55.8686, -5.9357),
('bd309c1a-5b6b-544a-8a6d-3ae5ef102dc2', 'Sgùrr nan Eugallt, near Kinloch Hourn', 'https://www.walkhighlands.co.uk/fortwilliam/sgurr-nan-eugallt.shtml', 9.5, 786, 5.0, 'Sgùrr nan Eugallt is a very fine mountain - a superb viewpoint on the edge of Knoydart. The short distance and the use of a stalkers path for the initial ascent makes for an easier day than its neighbours in this very rugged area.', 57.0953, -5.3714),
('bd30f102-6885-5387-80fd-5f06de869770', 'Orphir Bay, near Houton', 'https://www.walkhighlands.co.uk/orkney/orphir.shtml', 3.25, 32, 1.0, 'This short walk leads from the small Orkneyinga Saga heritage centre to the remains of the Earl''s Bu where a great feast was held (according to the saga). The route then runs along low coastal cliffs with views across Scapa Flow before returning along minor roads.', 58.9225, -3.1576),
('bdb62b84-98d6-55ee-aede-a25d13bd0534', 'Scurdie Ness and Elephant Rock, Ferryden', 'https://www.walkhighlands.co.uk/angus/ferryden.shtml', 11.5, 210, 3.5, 'A great coastal circuit from pretty Ferryden, taking in the lighthouse at Scurdie Ness and the elephant-shaped rock near Boddin Point before returning inland on minor road.', 56.7014, -2.4629),
('bdde1282-c630-57fa-9cf1-4d19df3ef88e', 'Huiseabhal Mòr ridge, Hùisinis', 'https://www.walkhighlands.co.uk/outer-hebrides/huiseabhal-mor.shtml', 13.0, 742, 6.0, 'Starting from the stunning sand of Hùisinis the route follows the coast to start with and visits another spectacular beach before heading inland to climb to a broad ridge walk with superb views - St Kilda and many nearer islands are often visible.', 57.9957, -7.092),
('be56fe48-da26-558d-8dfa-b818ddf9c80f', 'Oban Explorer - a town walk', 'https://www.walkhighlands.co.uk/argyll/oban-explorer.shtml', 5.75, 150, 2.5, 'Oban is renowned as the Gateway to the Isles, but this bustling town is well worth exploring in its own right. This route explores the centre of the town, taking in the promenade and seafront villas. It also climbs up to two superb viewpoints, taking in the dramatic landmark of MacCaig''s Tower, and the magnificent panorama from Pulpit Hill.', 56.4147, -5.4744),
('be7a8f3f-09f8-54af-9469-d067baf4f703', 'Stac Pollaidh ridge and circuit', 'https://www.walkhighlands.co.uk/ullapool/stacpollaidh.shtml', 4.5, 510, 4.0, 'This circuit heads around spectacular Stac Pollaidh (often anglicised to Stac Polly) with an optional ascent up to the ridge. The whole walk has great views over Assynt to the north and the Summer Isles and Achiltibuie to the south and west. Reaching the true summit of Stac Pollaidh involves a tricky scramble.', 58.0348, -5.2074),
('bea6c99e-f05d-56e5-83b7-b9c6d1e8b2fa', 'Tall Trees Trail, near Dalavich', 'https://www.walkhighlands.co.uk/argyll/timber-walk.shtml', 3.5, 120, 1.5, 'This waymarked walk heads down to the shores of Loch Awe, passing the remains of a crannog, before climbing up past a waterfall through MacKenzie''s Grove with its giant Douglas Fir trees.', 56.2416, -5.3004),
('bec00d40-7b3c-5e69-98ee-112902426706', 'Carsethorn and Powillimount Shore walk', 'https://www.walkhighlands.co.uk/galloway/carsethorn.shtml', 9.0, 60, 3.5, 'This tidal walk heads out along the shores of the Solway Firth from Carsethorn, continuing across the sands and mud until Powillimount Beach. The return is along quiet country roads, passing John Paul Jones cottage museum - the birthplace of the father of the US Navy.', 54.9228, -3.57233),
('bf4c7427-fe29-558a-b1f3-e8a5f6873faf', 'Beinn Mhic Mhonaidh, from Glen Orchy', 'https://www.walkhighlands.co.uk/argyll/beinn-mhic-mhonaidh.shtml', 13.5, 752, 5.0, 'Climb up from Eas Urchaidh falls on the beautiful River Orchy, passing alongside an ancient Caledonian pinewood, to gain the open slopes of this rather forgotten Corbett. The summit offers superb views of the higher mountains all around in this part of the Highlands.', 56.4479, -4.852),
('bf6bef0a-c3a2-54e6-bcb1-a973d4a3f479', 'The Rock and Spindle, from St Andrews', 'https://www.walkhighlands.co.uk/fife-stirling/rock-and-spindle.shtml', 4.75, 132, 2.0, 'An undulating section of coast passes interesting cliffs and rock stacks before reaching the large formation known as the Rock and Spindle. There are good views back to St Andrews and along the coast. The return is by the same route and the time given includes there and back.', 56.3333, -2.7796),
('bfb1ad9f-46bb-5cf2-96ac-b925dfc1d2ea', 'Baron''s Haugh and Dalzell Estate, near Motherwell', 'https://www.walkhighlands.co.uk/glasgow/dalzell-estate.shtml', 6.0, 104, 2.0, 'Baron''s Haugh is a stunning wetland nature reserve managed by the RPSB. This circular walk loops through both the reserve and the Dalzell Estate, on the edge of Motherwell.', 55.7745, -3.986),
('bfcea261-962c-5308-987d-c4f4df6c5277', 'Ardintoul Circuit, near Glenelg', 'https://www.walkhighlands.co.uk/kintail/Ardintoul.shtml', 14.25, 451, 5.5, 'This stunning circular walk from the Glenelg Ferry gives superb views along a little visited section of the shores of Loch Alsh, before returning via forestry tracks over the hill.', 57.2297, -5.6544),
('bfd20232-6164-5d25-8b63-e9122adc2ae7', 'Evans'' walk and Glenbatrick Bay', 'https://www.walkhighlands.co.uk/islay-jura/evans-walk.shtml', 17.5, 443, 7.0, 'Evans'' walk heads through the wild landscapes of central Jura, in the shadow of the Paps. This out-and-back walk leads to beautiful Glenbatrick Bay on the remote west coast before returning the same way.', 55.8888, -5.9198),
('bfe3b537-2958-5d02-bc03-60e2c3263a2a', 'Lendrick Hill, near Brig o'' Turk.', 'https://www.walkhighlands.co.uk/lochlomond/lendrick-hill.shtml', 7.25, 281, 3.0, 'This circular walk climbs up through the beautiful regenerating woodlands of the Great Trossachs Forest, before joining a high terrace path with superb views. It returns with a chance to visit the setting of a celebrated painting.', 56.2291, -4.3466),
('bfecf79f-1128-59cb-93d8-47d79e78f81e', 'Holland Farm and Tor Ness, Stronsay', 'https://www.walkhighlands.co.uk/orkney/holland-farm.shtml', 5.5, 11, 2.0, 'Tor Ness is the southernmost point of Stronsay; the walk out to it also gives the opportunity to watch birds on Lea Shun, spot seals, or continue to the beach at Sand of the Crook.', 59.0851, -2.5938),
('c01ce83b-03cb-553c-8a8b-7279c43eb75b', 'Beinn a'' Chaorainn & Beinn Teallach', 'https://www.walkhighlands.co.uk/fortwilliam/beinnachaorainn.shtml', 16.0, 1172, 8.0, 'This pair of Munros are much less visited than their better known neighbour Creag Meagaidh to the east. Their lower slopes may be boggy, but the walk along the summit ridge of Beinn a''Chaorainn is a delight.', 56.8951, -4.6656),
('c0ec8e78-29d7-53c1-811e-f038601a8f46', 'Broadford Marble Line', 'https://www.walkhighlands.co.uk/skye/marble-line.shtml', 13.0, 230, 3.0, 'An easy-going walk tracing the line of the railway line for the marble quarries at Kilchrist. Good views of Blaven and the surrounding hills.', 57.2417, -5.9105),
('c1268bc2-2a93-575e-a6cb-69368e9cc2b9', 'Cubbie Roo''s Castle and The Taing, Wyre', 'https://www.walkhighlands.co.uk/orkney/wyre.shtml', 7.5, 46, 3.0, 'Wyre is a small island just a short ferry hop over from Rousay; this walk visits one of the oldest castles in Scotland before heading for the coast which is popular with seals at low tide.', 59.1243, -2.9725),
('c1979d50-42d1-50a6-b6a4-62c7d4c075a3', 'Tirefour Broch and Castle Coeffin from Achnacroish', 'https://www.walkhighlands.co.uk/argyll/tirefour-broch.shtml', 11.0, 165, 4.5, 'This walk takes in Lismore''s two best-known historical features on a circular route from Achnacroish. There''s a cafe at half-way.', 56.5113, -5.4926),
('c1ef671f-c100-59f2-b06d-088658f744ab', 'Dunbeath Strath', 'https://www.walkhighlands.co.uk/sutherland/dunbeath-strath.shtml', 10.5, 140, 3.5, 'Dunbeath Strath provides a walk with a fine variety of interest. Beautiful silver-birch woodland borders the stream and the rocky gorge whilst the open moors above provide expansive views. There is a wealth of archeological remains along the way. Those looking for an easier walk can simply follow the route as far as the Prisoner''s Leap.', 58.2499, -3.4332),
('c201dc3e-1bfe-565d-9d88-b61d5f31f03f', 'Loch Venachar circuit, near Brig o''Turk', 'https://www.walkhighlands.co.uk/lochlomond/venachar-circuit.shtml', 19.0, 315, 5.0, 'Spend a leisurely day circumnavigating Loch Venachar by a mixture of cycle paths and minor roads with good views of the water most of the way. Refreshments available at the Byre Inn near Brig o'' Turk, the Brig o'' Turk Tearoom and Venachar Lochside cafe.', 56.2291, -4.3467),
('c220e559-60db-597a-88d7-e4ca203d9727', 'Ward of Clett, Whalsay', 'https://www.walkhighlands.co.uk/shetland/ward-of-clett.shtml', 6.25, 165, 2.5, 'Whalsay is one of the more prosperous of Shetland''s smaller islands and is at heart of its fishing industry. This short walk heads through the main settlement then takes in a stretch of the coastline before ascending to the island''s highest summit, the Ward of Clett.', 60.3419, -1.0289),
('c2344b94-12a4-587c-9ad0-eb3190ab3468', 'St John''s Point', 'https://www.walkhighlands.co.uk/sutherland/st-johns-point.shtml', 2.75, 55, 1.0, 'This lovely headland has excellent views across to Orkney and numerous stacks and geos on its coastline which also has the remains of a defensive fort. The second part of this walk visits Scotland''s Haven, a natural harbour which is cut off from the rest of the sea at very low tide.', 58.6525, -3.1885),
('c24ab045-e5b1-5920-90dd-a421e60c9d2b', 'Haughton Country Park, Alford', 'https://www.walkhighlands.co.uk/aberdeenshire/haughton-country-park.shtml', 5.0, 19, 2.0, 'This circular route explores the woods of Haughton Country Park and the banks of the River Don from the country town of Alford.', 57.2323, -2.7012),
('c24f5273-c4b1-5aff-aa62-51ed81ab0535', 'Aberdeen centre - Granite City', 'https://www.walkhighlands.co.uk/aberdeenshire/aberdeen-granite-city.shtml', 3.25, 21, 1.0, 'Explore the granite buildings and sculptures of Aberdeen''s city centre on this circuit which also takes in the Art Gallery and Provost Skene''s House.', 57.1482, -2.0925),
('c2638966-8ec1-5455-b98c-045dc65cbb13', 'Sheep walk, Auchtertyre Farm, near Tyndrum', 'https://www.walkhighlands.co.uk/argyll/sheep-walk.shtml', 4.75, 192, 2.5, 'Leaving Auchtertyre Farm, the sheep route climbs past a fine waterfall and beneath the West Highland Railway before continuing over open moorland. The route then becomes very overgrown (especially in summer) and hard to follow in places before it crosses a footbridge and returns down a farm track.', 56.4244, -4.6722),
('c281b0d9-95dc-5335-a7c8-7ed37686b392', 'Benarty Hill, near Ballingry', 'https://www.walkhighlands.co.uk/fife-stirling/benarty-hill.shtml', 3.5, 188, 1.5, 'This short and straightforward hill walk gives rewards out of all proportion to the effort involved, with stunning views over Loch Leven and beyond.', 56.1579, -3.35548),
('c2a3c656-803e-52fe-a107-9e153098b9a3', 'Fife Coastal Path 6:  St Monans to Anstruther', 'https://www.walkhighlands.co.uk/fife-stirling/st-monans-anstruther.shtml', 5.75, 55, 2.0, 'This easy-going section of the Fife Coastal path links three of the celebrated East Neuk fishing villages: St Monans, Pittenweem and Anstruther. There is plenty to see along the way and the return to the start can be made by bus.', 56.2036, -2.7718),
('c2a777b8-a446-5fc0-9472-17730246bcfa', 'Saddell Bay and sculptures, Saddell', 'https://www.walkhighlands.co.uk/argyll/saddell-bay.shtml', 3.5, 35, 1.0, 'This easy and level walk visits a beautiful sandy bay and a fine castle. The walk takes in both the medieval sculptures of the Saddell Stones and a striking modern one by Antony Gormley.', 55.532, -5.5102),
('c2acc29b-41bb-54b8-8d9f-31a5e9847fbf', 'Stuchd an Lochain', 'https://www.walkhighlands.co.uk/perthshire/stuchd-an-lochain.shtml', 8.5, 726, 4.5, 'With a start at over 400 metres, Stuchd an Lochain gives a short ascent for a Munro. The initial climb is steep and boggy but the ridge traverse that follows around above the corrie cradling little Lochan nan Cat, is a delight, and the summit views are superb.', 56.5856, -4.42609),
('c31cc1ef-66ca-5bf9-a05c-8a2c2d11a311', 'Coire Fhionn Lochan', 'https://www.walkhighlands.co.uk/arran/coire-fhionn-lochan.shtml', 5.25, 326, 2.0, 'A straightforward moorland walk to a beautiful mountain lochan with white gravel beach.', 55.6667, -5.37306),
('c355a7c4-a346-531f-a789-32d3e059c174', 'Cairn Cattoch, Archiestown', 'https://www.walkhighlands.co.uk/moray/archiestown.shtml', 9.5, 163, 3.5, 'This forest walk from the attractive village of Archiestown climbs gradually through the trees to reach the summit of Càrn Cattoch, a fine viewpoint.', 57.481, -3.2865),
('c3712505-c6eb-5f0f-b6fa-af52be8642c0', 'Traprain Law, near Haddington', 'https://www.walkhighlands.co.uk/lothian/traprain-law.shtml', 3.2, 145, 1.5, 'A familiar landmark from much of East Lothian, Traprain Law is a small but steep-sided and distinctive volcanic hill rising from the farmland. The climb to the summit is short but steep; the top was the site of an extensive hill fort with panoramic views over the local area and beyond. The walk continues by encircling the base of the hill.', 55.9658, -2.6716),
('c38396a7-c1ae-58c1-81b2-78f2c4d8e700', 'The Deil''s Cauldron & Melville Monument, Comrie', 'https://www.walkhighlands.co.uk/perthshire/deils-cauldron.shtml', 7.5, 270, 3.0, 'The River Lednock cascades out from a rocky gorge in the atmospheric tree-clad amphitheatre known as the Deil''s Cauldron. This excellent and varied circular walk from the attractive village of Comrie visits the Cauldron itself. It also includes the ascent to the Melville Monument, the obelisk atop Dun More - a wonderful viewpoint.', 56.3748, -3.99),
('c3952623-2b22-5ca8-829d-d876c43183ac', 'South Glen Shiel Ridge: 7 Munros', 'https://www.walkhighlands.co.uk/kintail/Glenshielridge.shtml', 26.75, 1818, 11.0, 'This marvellous but long and arduous ridge walk is a Munro-baggers delight. Nowhere else in the Highlands can so many peaks be climbed in a day, with minimal descent between the summits, and the views are excellent all the way. However, this is a long day with steep ground on either side of the ridge - route finding skills and a fast pace are required. If in any doubt about fitness, the route can be split into two days by using the Druim na Coire nan Eirecheanach ridge to descend from the ridge at the end of the first day, and use the Druim Thollaidh ridge to regain the ridge to begin the second day.', 57.156, -5.17815),
('c399e4b4-04a8-5909-8a6a-2154cfc179a4', 'Meall Corranaich and Meall a''Choire Lèith', 'https://www.walkhighlands.co.uk/perthshire/meall-corranaich.shtml', 9.5, 740, 6.0, 'These two Munros form the westward end of the great Ben Lawers ridge. The start at almost 550 metres makes this a short round for baggers but the terrain is very rough - and peat bogs unavoidable.', 56.5453, -4.28936),
('c3a68cec-3005-5de0-8504-721449a0acad', 'Loch of Lowes circuit, Dunkeld', 'https://www.walkhighlands.co.uk/perthshire/loch-of-lowes.shtml', 7.8, 85, 2.5, 'This walk explores the rolling countryside on the north side of Dunkeld. It can be started in Dunkeld itself, but we describe it here from the Cally Woods car park where parking is free. The walk gives the chance to visit the Scottish Wildlife Trust Reserve at the Loch of Lowes, with its hides (admission charge) overlooking the famed osprey eyrie.', 56.5754, -3.5917),
('c3d5ae8e-b8df-52ae-974b-f09c04c7a129', 'Calum''s Path and Fladda, from Arnish', 'https://www.walkhighlands.co.uk/skye/torran.shtml', 5.5, 280, 2.5, 'This superb and varied circular walk starts from the end of ''Calum''s Road'' at the northern end of Raasay. It leads through some beautiful native birchwoods, following a path built by Calum MacLeod with his brother, before he started on his more famous road. It leads to a slimy tidal causeway connecting with Eilean Fladday (or Fladda) - which you can cross with care at low tide. The return follows another fine path back to Torran.', 57.4583, -6.0132),
('c3fdfa33-9ce8-5240-8a2a-9c4031da8816', 'Peanmeanach village and beach', 'https://www.walkhighlands.co.uk/fortwilliam/peanmeanach.shtml', 11.5, 396, 5.0, 'This stunning walk leads to a deserted village set behind a lovely secluded beach. There are superb views of the coast and islands on the walk out; on a sunny summer''s day you wouldn''t trade it for the world.', 56.8873, -5.70779),
('c40f8661-2fe8-5907-a1ce-8a461238b078', 'Beinn Resipol from Resipole campsite', 'https://www.walkhighlands.co.uk/fortwilliam/benresipol.shtml', 11.5, 827, 6.0, 'Ben Resipol is the westernmost of the big Highland peaks; it''s position between Loch Shiel and Loch Sunart, looking out over Ardnamurchan and a wide sweep of sea and islands, makes it a classic viewpoint.', 56.7109, -5.7202),
('c48dff63-43f3-5478-b4f5-554df5d4eb60', 'Black Spout and Edradour, Pitlochry', 'https://www.walkhighlands.co.uk/perthshire/edradour.shtml', 5.0, 145, 2.0, 'This varied walk begins in Pitlochry town centre, passing Athol Distillery then through woodland to visit the fine Black Spout waterfall before continuing up to Edradour Distillery (not currently open to public). There are good views of the surrounding hills before the route returns to Pitlochry through the trees.', 56.702, -3.73064),
('c495a9a2-db43-5bdf-9245-7e29daf8302c', 'Ben Aden, by Loch Cuaich', 'https://www.walkhighlands.co.uk/fortwilliam/ben-aden.shtml', 26.75, 950, 13.0, 'Ben Aden - or Beinn an Aodain to give its correct Gaelic name - is one of the remotest Corbetts. Although surrounded by higher Munros this is a hill of real character; rocky, steep and rugged, the ascent provides a real challenge for many. The approach along the shores of Loch Quoich makes it possible to ascend in a day, but requires a decent spell of dry weather before attempting, as the crossing of the Abhainn Chosaidh is impossible in spate conditions and the start of the walk also requires a long detour if water levels are high.', 57.0786, -5.312),
('c4d3d114-93ff-572b-8599-e3f36decfdb7', 'Kenmore Hill', 'https://www.walkhighlands.co.uk/perthshire/kenmore-hill.shtml', 5.0, 224, 2.0, 'An excellent waymarked circuit on and around Kenmore Hill. The hill has been planted with Scots pines and other native trees and offers superb views of Loch Tay and the mountains beyond.', 56.5776, -3.9776),
('c50542a5-3f11-5de1-87f3-817074341559', 'Drummore and Castle Clanyard, Drummore', 'https://www.walkhighlands.co.uk/galloway/drummore.shtml', 9.0, 179, 3.0, 'This walk explores the rural highways and byways in the rolling farmland hills above Drummore, the most southerly village in Scotland.', 54.6896, -4.8949),
('c511ae15-7b7f-519b-b750-9767f8b142ad', 'White Mounth Munros, Glen Muick', 'https://www.walkhighlands.co.uk/cairngorms/white-mounth.shtml', 29.0, 1228, 11.0, 'A long hillwalk taking in the five Munros on the extensive White Mounth plateau. Lochnagar is by far the finest of the summits, but in good weather this is all a hugely enjoyable round with a great feeling of space.', 56.9525, -3.1364),
('c5511ea5-61a3-5c7b-afad-4177afc3bf0a', 'Meall Greigh, Meall Garbh and An Stùc', 'https://www.walkhighlands.co.uk/perthshire/meall-garbh.shtml', 16.5, 1230, 8.0, 'The eastern three Munros of the Lawers range give an excellent circuit of the corrie holding Lochan nan Cat, the finest feature of the range. The recently-promoted Munro of An Stùc involves a steep scramble and this route is much more challenging than the usual trade route to Ben Lawers itself. The walk can easily be extended to take in the higher summit.', 56.5295, -4.15186),
('c5abe263-1119-528f-9826-5393fa8f34dc', 'Sandwood Bay', 'https://www.walkhighlands.co.uk/sutherland/sandwood-bay.shtml', 13.0, 150, 5.0, 'A walk in along a bleak moorland track is amply rewarded when the fabulous views of Sandwood Bay come into view, perhaps the most beautiful beach in Britain. Spend time exploring the mile of golden sand and dunes, with rocky cliffs and a giant sea stack to complete the scene. Despite its popularity, Sandwood Bay never seems busy as the beach is big enough to absorb the visitors.', 58.4939, -5.0952),
('c5aec948-e5e3-5960-93b5-5ee002659696', 'Fair Isle North Lighthouse & Observatory', 'https://www.walkhighlands.co.uk/shetland/fair-isle-north-end.shtml', 6.0, 130, 2.0, 'This short, easy ramble follows the road from the ferry jetty at North Haven, exploring the coastal features to reach the North Lighthouse with spectacular cliffs nearby before returning via a blow hole and the bird observatory.', 59.5377, -1.6037),
('c5cad650-8e61-5af0-8c7a-2aa6382bedea', 'New Town, Edinburgh', 'https://www.walkhighlands.co.uk/lothian/new-town.shtml', 3.5, 15, 1.5, 'Edinburgh New Town is considered one of the masterpieces of Town Planning. Today Princes Street is the capital''s main shopping thoroughfare, with superb views across to the Castle. Further from this busy hub, the original Georgian architecture of the fine crescents and circusses to the north can be appreciated in full.', 55.953, -3.1901),
('c5fb821a-a8cc-5ad3-bc36-788f995c98a6', 'Salmon Leap Walk, Selkirk', 'https://www.walkhighlands.co.uk/borders/salmon-leap-selkirk.shtml', 6.0, 28, 2.0, 'A lovely walk exploring the Ettrick Water to a weir with salmon ladder, returning past an old watermill with a short detour to a cafe possible before following the mill lade back to the houses of Selkirk.', 55.5506, -2.84962),
('c6048ac8-3040-5970-ab5d-ac85ec18d97b', 'Mu Ness and the Castle from Uyeasound, Unst', 'https://www.walkhighlands.co.uk/shetland/muness-castle.shtml', 12.0, 154, 5.0, 'This circular walk explores the low lying southern coastline of Unst, running from the settlement at Uyeasound to visit Scotland''s most northerly castle - Muness, a sixteenth century tower house. Watch out for otters along the coastline; the return walk is then along quiet minor roads.', 60.6866, -0.9046),
('c6075eae-6f9d-5c22-bdfe-beb3bb9d89f9', 'The Prop of Ythsie, near Tarves', 'https://www.walkhighlands.co.uk/aberdeenshire/prop-of-ythsie.shtml', 2.5, 63, 0.75, 'This short rural walk visits a stone memorial tower that is a prominent landmark and offers very extensive views over the surrounding countryside near Tarves, which itself is worth a visit.', 57.3669, -2.1982),
('c61d54e1-e64d-5b04-8f43-c090222b15a2', 'Sròn  na Muic, Invermoriston', 'https://www.walkhighlands.co.uk/lochness/sron-na-muic.shtml', 23.75, 503, 6.0, 'Climb forestry tracks to eventually reach open views with a wonderful outlook over Loch Ness and down the Great Glen. The route would also make a good though strenuous mountain bike route, speeding through long forestry sections where the views are more limited.', 57.2136, -4.6173),
('c61dcebc-4b94-5204-8f5d-2d3f973681f8', 'Calfield Rig and Mid Hill, Langholm', 'https://www.walkhighlands.co.uk/galloway/mid-hill.shtml', 11.5, 298, 4.0, 'After leaving Langholm through parkland, climb pleasant farmland to reach the open moorland ridge of Calfield Rig, Black Knowe and Mid Hill with good open views. Waymarked at walk 9.', 55.154, -3.0004),
('c63efd71-8ca6-5085-b173-301c93ca48e6', 'Hill of Fare: northern approach', 'https://www.walkhighlands.co.uk/aberdeenshire/hill-of-fare-north.shtml', 6.5, 200, 1.5, 'The Hill of Fare is an area of rough moorland rising above forest plantations a few kilometres north of Banchory. This route from the north gives the shortest and quickest ascent route - an out-and-back trip that is well worthwhile for the fine views.', 57.1321, -2.57948),
('c63fa669-539a-5041-90fc-ca9fde1712c2', 'Beinn Pharlagain, near Rannoch Station', 'https://www.walkhighlands.co.uk/perthshire/beinn-pharlagain.shtml', 18.25, 640, 6.0, 'Beinn Pharalagain is a rounded, knobbly ridge of heather and grasses running south from the Munro Sgòr Gaibhre. It''s highest summit - Meall na Meoig - acheives Corbett status. The walk can be extended to take in the two Munros of Sgòr Gaibhre and Càrn Dearg.', 56.6863, -4.538),
('c646a8a5-3f5f-5cdf-a1b6-eaf9d5ed62f5', 'Dunecht Estate and Barmekin Hill', 'https://www.walkhighlands.co.uk/aberdeenshire/barmekin-hill.shtml', 11.5, 205, 4.0, 'This circular walk begins by following tarmac lanes and tracks through the Dunecht Estate, giving views of the great country house as well as over the Policy Loch. The walk then continues with a moorland climb up to the remains of the iron-age hillfort on the summit of Barmekin Hill, with good views over the Aberdeenshire countryside.', 57.1717, -2.4077),
('c660c5ed-56c3-52c6-8d80-50663a2edd56', 'Bealach Route and Killiecrankie, Pitlochry', 'https://www.walkhighlands.co.uk/perthshire/bealach-route.shtml', 16.0, 625, 5.0, 'This varied waymarked walk climbs the open moorland above Pitlochry to cross the Bealach na Searmoin, offering great views, to reach Killecrankie. The return walk is down into the gorge, past the Soldier''s Leap and along a delightful stretch of the River Garry and Loch Faskally. Killiecrankie Visitor Centre has toilets and seasonal cafe.', 56.7033, -3.7371),
('c728a9a1-b6d9-5337-b824-6f63cdb96092', 'Sgùrr na h-Eachainne & Druim na Sgriodain', 'https://www.walkhighlands.co.uk/fortwilliam/sgurr-na-h-eachainne.shtml', 11.75, 838, 6.5, 'The fine peak of Sgùrr na h-Eachainne rises dramatically on the north side of the Corran narrows, and is a familiar sight for travellers along the A82 to Fort William. Further along the ridge is the less impressive main summit of Druim na Sgriodain. The ascent of both gives a steep and rugged hillwalk with spectacular views.', 56.727, -5.2529),
('c736f951-31e1-5ca8-841e-917f86c5a6d9', 'Ben Venue from Ledard Farm', 'https://www.walkhighlands.co.uk/lochlomond/ledard.shtml', 11.5, 812, 6.0, 'Ben Venue - one of the rockiest hills in the Trossachs - is not in view from Loch Àrd, which results in this approach being quieter than that from Loch Achray. Nonetheless the beautiful broadleaved woodland of the lower Ledard Glen provides a picturesque approach, though the upper glen is boggy. Once on the ridge, the views are magnificent.', 56.1879, -4.4839),
('c75020c4-b06e-52b4-b43a-1eb763d234a0', 'Primrose Hill, Loch Katrine', 'https://www.walkhighlands.co.uk/lochlomond/primrose-hill.shtml', 11.0, 289, 4.0, 'This superb waymarked trail runs high through the woods on the north side of Loch Katrine, offering stunning views over this beautiful stretch of water and passing a filming location for the TV drama Outlander.', 56.2333, -4.4286),
('c79cc658-efa2-567e-8115-a506449eb620', 'Sròn  a''Chlachain and Creag Buidhe, Killin', 'https://www.walkhighlands.co.uk/perthshire/sron-a-chlachain.shtml', 4.0, 408, 2.5, 'This short but steep hillwalk from Killin reveals a truly classic view down the length of Loch Tay. The climb from the village may be strenuous, but it leads through lovely oak woods and then along an enjoyable ridge with great views throughout.', 56.4692, -4.31772),
('c7c17813-a2f8-5bec-af7e-a3722c80a924', 'Loch Morlich circuit', 'https://www.walkhighlands.co.uk/cairngorms/loch-morlich.shtml', 5.75, 50, 2.0, 'Loch Morlich enjoys one of the finest settings of any loch in the country. It is surrounded by forests and fringed by beaches, with the stunning backdrop of the often snow-clad peaks of the northern Cairngorms. The circuit of the loch is a very popular walk.', 57.168, -3.7004),
('c7f51e34-e33b-54eb-b322-7466fa1e76f3', 'Loch Ness and Torr Woods circular, Dores', 'https://www.walkhighlands.co.uk/lochness/Aldourie.shtml', 7.0, 65, 2.0, 'This lovely woodland walk offers great views from the shores of Loch Ness, a chance to look for red squirrels and roe deer in the woods, and views of Aldourie Castle.', 57.3844, -4.329),
('c802adee-dec9-56f6-9cc4-c91dbb34deee', 'Rubha Hunish', 'https://www.walkhighlands.co.uk/skye/rubhahunish.shtml', 8.5, 340, 5.0, 'Beautiful Rubha Hunish, the northernmost point of the island, is a magical place; this is the best walk on Skye for seabird and marine mammal watching.', 57.6839, -6.3259),
('c80e5a99-e7f8-5f45-9a24-1ab3355821a4', 'Fearnoch Forest Ant Hill Trail, near Taynuilt', 'https://www.walkhighlands.co.uk/argyll/fearnoch.shtml', 3.6, 74, 1.0, 'This waymarked walk in the plantations of Fearnoch Forest provides a gentle leg stretcher passing through both coniferous plantations and deciduous woodland.', 56.4378, -5.2964),
('c830ed60-27dd-5e9e-8360-67922bd970a4', 'Flanders Moss National Nature Reserve, near Kippen', 'https://www.walkhighlands.co.uk/lochlomond/flanders-moss.shtml', 0.9, 1, 0.5, 'A short exploration of this fascinating peat bog, complete with viewing tower to climb, good hill views as backdrop to the cotton grass, birches and heather of the reserve.', 56.1536, -4.17845),
('c8467226-6c43-52cb-9367-aad5dbdba4bd', 'Hoddom Castle and the Repentance Tower', 'https://www.walkhighlands.co.uk/galloway/hoddom-castle.shtml', 6.5, 87, 2.5, 'This pleasant ramble explores part of the River Annan, farmland and woodland, passing a series of sculptures about salmon, Hoddom Castle (cafe) and climbs to the Repentance Tower with good views.', 55.0406, -3.3109),
('c861d681-6e5d-5afb-beeb-882cc3a0f034', 'Wamphray Glen circuit, near Moffat', 'https://www.walkhighlands.co.uk/galloway/wamphray-glen.shtml', 5.0, 110, 2.0, 'This waymarked circuit set up by the Crown Estate explores a wooded glen, the site of an old motte and bailey, an old mill and a fine old church, all set in farmland on the east side of Annandale.', 55.251, -3.3848),
('c8fc0601-2765-5eff-b367-f79f93c52207', 'Speinne Mòr , near Loch Frisa', 'https://www.walkhighlands.co.uk/mull/speinne-mor.shtml', 9.0, 370, 3.0, 'A fairly straightforward hill walk with panoramic views. Wet underfoot, the out and back route is easy to navigate and looks down on Loch Frisa.', 56.5944, -6.1301),
('c932bb9c-93b1-58d5-905c-2f014d713ed6', 'Smirisary village and beach from Glen Uig', 'https://www.walkhighlands.co.uk/fortwilliam/smirisary.shtml', 4.5, 242, 3.5, 'A varied walk with good coastal views and the opportunity to explore the part-restored and roadless village of Smirisary and on to the beautiful white beach opposite Eilean Coille and other small islands.', 56.8283, -5.84702),
('c935431d-9cc8-552e-b740-acaab0a9b152', 'Clashnessie Bay and Falls', 'https://www.walkhighlands.co.uk/ullapool/clashnessie-beach.shtml', 2.25, 45, 0.75, 'Clashnessie Bay has a very fine sandy beach, one of few in Assynt to face north. Its name comes from the GaelicClais an Easaidh- the Channel of the Waterfall - and the falls which give the name make for a short if boggy hike. The Clashnessie Falls are 15m high and are most impressive when in spate.', 58.2236, -5.30918),
('c96c45e6-9f59-5393-bebf-938576ec4a97', 'Creag Uchdag from Glen Lednock', 'https://www.walkhighlands.co.uk/perthshire/creag-uchdag.shtml', 15.0, 667, 6.5, 'Creag Uchdag is a little known summit rising above the boggy plateaux and broken crags between Loch Tay and Glen Lednock. This circular route makes a high level but wet approach before making a steeper and rougher return via Loch Lednock.', 56.4209, -4.0395),
('c989eed3-f29e-5a5f-b000-b0c84b4eabe2', 'Glasdrum Wood, Loch Creran', 'https://www.walkhighlands.co.uk/argyll/glasdrum.shtml', 1.0, 113, 1.0, 'A short, but steep, walk up through part of the Glasdrum Wood National Nature Reserve, renowned for its rich variety of plants, birds and butterflies. The walk has good views over the head of Loch Creran.', 56.5583, -5.25392),
('c9924aba-b3ed-5dcd-82d3-e4feda627f15', 'Kyle of Durness circuit', 'https://www.walkhighlands.co.uk/sutherland/kyle-of-durness.shtml', 8.6, 160, 3.5, 'This unspoilt and idyllic route follows the coastline around the Kyle of Durness with lovely beaches and excellent views.', 58.5761, -4.7681),
('c9c7a0e7-3b07-5044-85c7-078f41ee7fbe', 'Salt Pans Bay from Galdenoch Castle, near Leswalt', 'https://www.walkhighlands.co.uk/galloway/salt-pans-bay.shtml', 4.6, 88, 1.5, 'Head from the crumbling ruins of a 16th century castle across the fields to reach a secluded bay, once used for panning salt from the sea.', 54.9224, -5.1638),
('ca40362a-a340-5696-8c66-2100a4183270', 'Rueval (Ruabhal), Benbecula', 'https://www.walkhighlands.co.uk/outer-hebrides/ruabhal.shtml', 3.5, 127, 1.5, 'Climb to the highest point on Benbecula for a fantastic 360 degree view of water, islands, beaches and mountains. A steep pull but a straightforward and fairly short walk.', 57.4588, -7.3183),
('ca4d76ed-b840-543a-a98d-ee0f7a9ab8a1', 'Burn Anne walk, Galston', 'https://www.walkhighlands.co.uk/glasgow/burn-anne-galston.shtml', 8.5, 176, 2.5, 'An easy circuit of the woods and meadows of the Irvine Valley.', 55.5985, -4.3801),
('ca9316aa-5ea6-5230-9c05-1e0f5af2fc53', 'Acairseid Mhòr shore walk, Eriskay', 'https://www.walkhighlands.co.uk/outer-hebrides/acarseid.shtml', 5.75, 121, 2.0, 'Explore a hidden bay on Eriskay to look for seals and otters, passing a moorland lochan on this very pleasant and straightforward walk from the ferry terminal.', 57.0701, -7.3079),
('caaf480f-1324-550b-9f0e-e3ca577c1581', 'Eskrigg Nature Reserve circuit from Lockerbie', 'https://www.walkhighlands.co.uk/galloway/lockerbie.shtml', 7.0, 21, 3.0, 'Eskrigg Nature Reserve is maintained by a local charity on the site of an old curling pond. This walk begins from the town centre of Lockerbie, heading out to the reserve and returning via the Garden of Remembrance for victims of the Lockerbie bombing.', 55.1217, -3.3563),
('cabe90b2-2816-5df3-b585-dbb82b1649dd', 'Lerwick Explorer', 'https://www.walkhighlands.co.uk/shetland/lerwick-explorer.shtml', 6.0, 80, 2.0, 'Lerwick is the capital of Shetland and by far the largest settlement. This route explores the older part of the town and harbour and passes round the headland of the Knab with some fine coastal scenery and views. There is also the chance to see a well-preserved and restored broch.', 60.1538, -1.1422),
('cadd6b87-e7ff-5964-aa0c-79ce27ea2ec3', 'Hazlehead Park, Aberdeen', 'https://www.walkhighlands.co.uk/aberdeenshire/hazlehead-park.shtml', 4.5, 50, 1.5, 'A varied exploration of Hazlehead Park in west Aberdeen, taking in woods, formal gardens and golf course. A great family park with giant maze, pets corner, play park and cafe.', 57.1396, -2.1795),
('cb98a873-e2cd-5333-a9b2-96cbf5534400', 'Dalmeny Estate: Queensferry to Cramond Brig', 'https://www.walkhighlands.co.uk/lothian/dalmeny-estate.shtml', 10.5, 98, 3.0, 'This linear walk - following a section of the John Muir Way - starts in the historic town of Queensferry, taking quiet lanes and tracks through the wooded Dalmeny Estate close by the shores of the Forth. The route passes Dalmeny House and Barnbougle Castle; both ends of the route are accessible by public transport.', 55.9866, -3.38216),
('cb9e9f70-6643-5973-8502-7f7ac519b19b', 'Lairig Ghru', 'https://www.walkhighlands.co.uk/cairngorms/lairig-ghru.shtml', 30.5, 810, 10.0, 'The Lairig Ghru is the best known hill-pass in Scotland. It climbs to an altitude of 835 metres and crosses through the central Cairngorms, one of the wildest areas in the country, and is a true classic walk. It is described from Speyside to Deeside.', 57.1741, -3.797),
('cbabbb39-d5b8-5365-b034-2712cdb5ad8f', 'Dùn Uragaig & Loch an Sgoltaire, Kiloran Bay', 'https://www.walkhighlands.co.uk/islay-jura/uragaig.shtml', 8.5, 132, 4.0, 'Climb up from the picture-perfect Kiloran Bay through the crofting settlement of Uragaig before exploring a clifftop fort and pebble beach. The return crosses rough moorland alongside Loch an Sgoltaire whcih can be boggy and overgrown followed by a final quiet road section.', 56.1009, -6.1869),
('cbadf91e-a909-595d-be2d-adda9dbbf724', 'Fiskavaig coast, from Talisker', 'https://www.walkhighlands.co.uk/skye/fiskavaig.shtml', 12.25, 445, 6.0, 'The northern section of the spectacular Minginish coastline gives a very rough walk across boggy moorland terrain, with impressive cliff scenery.', 57.2876, -6.4389),
('cc47a75d-8e11-5613-9013-d019beb59ce2', 'Westray west coast walk', 'https://www.walkhighlands.co.uk/orkney/westray-coast.shtml', 9.5, 230, 5.0, 'Offering the finest walk on Westray, this wild coastal walk brims with arches, stunning cliff scenery and seabird cities. This linear walk from Kirbest to Noup Head would need transport arranged to return to the start (and note that the drive to Noup Head is very rough); or it could be done as a there and back day walk - doubling the distance and time given here.', 59.2764, -3.0055),
('cc53d11c-7bc1-5ebb-bd1d-440d97797070', 'Ben Cleuch circular', 'https://www.walkhighlands.co.uk/fife-stirling/ben-cleuch.shtml', 9.5, 731, 6.0, 'Ben Cleuch is the highest of the Ochils and one of the most popular hillwalks in Central Scotland. There are many possible routes of ascent; the circuit described ascends via the popular path up The Law before descending over Ben Ever and then steeply back down into the dramatic Mill Glen.', 56.1571, -3.7492),
('cc5b51e9-2c09-5e63-9d00-573a69e13870', 'Càrn Ban via Strath Vaich', 'https://www.walkhighlands.co.uk/ullapool/carn-ban-vaich.shtml', 43.0, 1092, 13.0, 'Càrn Ban is one of the most remote Corbetts, though the approach can be greatly eased by use of a mountain bike. For those completing the whole distance on foot, there are a few spots suitable for wild-camping in Gleann Beag. Stalkers'' paths aid the ascent and descent whilst the summits are grassy and spacious with stunning views.', 57.6978, -4.7307),
('cc7a39f2-dba4-5bf3-af85-88a1e9c93c42', 'Allean Forest trail, near Queen''s View', 'https://www.walkhighlands.co.uk/perthshire/queens-view.shtml', 4.0, 182, 1.5, 'This enjoyable waymarked forest walk has plenty of interest, including a restored black house at the site of an old clachan, and an ancient ring fort. The route begins from near the Queen''s View, famed for its outlook over Loch Tummel.', 56.7177, -3.8665),
('ccc6acf0-e79c-5ee0-a5a7-9dd2fac98ba0', 'Bay of Newark from Heritage Centre, Eday', 'https://www.walkhighlands.co.uk/orkney/bay-of-newark-eday.shtml', 3.75, 20, 2.0, 'This short walk explores part of the west coast of Eday with a chance to visit the sandy Bay of Doomy and the Bay of Newark.', 59.2001, -2.7647),
('cd118c23-14f9-58ff-867c-dac2bb16b2e4', 'Phoineas Hill, near Beauly', 'https://www.walkhighlands.co.uk/lochness/Phoineashill.shtml', 4.85, 148, 2.0, 'This pleasant and straightforward forestry walk visits a hilltop mast to gain some wide views over the Beauly area.', 57.4461, -4.4617),
('cd32e117-9458-5826-b0db-fe5665073edf', 'Loch Drunkie', 'https://www.walkhighlands.co.uk/lochlomond/loch-drunkie.shtml', 3.25, 100, 1.0, 'Accessible only by the Three Lochs Forest Drive (small charge - open only from Easter to October), this pair of short loops from the Loch Drunkie car park make up an enjoyable figure of eight.', 56.2113, -4.36318),
('cd598522-2f4e-5926-bdf5-42d960532db3', 'Tormore pier and quarry circuit, Fionnphort', 'https://www.walkhighlands.co.uk/mull/fionnphort.shtml', 2.5, 72, 1.5, 'This is a great walk across a coastal headland to the hidden anchorage at Tormore where there is a white sandy beach. From here climb up through the pink granite quarry that supplied much of the stone for the abbey on Iona. Return across fields which can be very muddy at times.', 56.3241, -6.3654),
('cd666c84-aaaf-509e-8e24-c9fa64e3dc7a', 'Falls of Foyers', 'https://www.walkhighlands.co.uk/lochness/Fallsoffoyers.shtml', 4.5, 152, 2.0, 'This short but spectacular walk takes in the must see sight of South Loch Ness - the Falls of Foyers, set in a dramatic gorge. The walk then continues down to the shores of Loch Ness for a short, quiet loop before returning to the cafe.', 57.2504, -4.4905),
('cd6c764d-9138-5b48-8102-cc0fe52f9c70', 'Duthie Park and the River Dee', 'https://www.walkhighlands.co.uk/aberdeenshire/duthie-park.shtml', 11.5, 63, 4.0, 'Explore Duthie Park and then head out of Aberdeen along the banks of the mighty River Dee. Rough fishermen''s paths lead out to Cults from where the much more straightforward return walk heads back to the Park along the line of the old Deeside railway.', 57.1301, -2.0986),
('cd898a5f-0561-5558-9422-a0342674db11', 'Schiehallion', 'https://www.walkhighlands.co.uk/perthshire/schiehallion.shtml', 10.0, 731, 6.0, 'One of Scotland''s best known hills, Schiehallion is one of the easiest Munros to climb on a fine summer''s day. It takes the form of a broad ridge, with the famous conical appearance only apparent from across Loch Rannoch.', 56.6758, -4.03603),
('cdd29817-d986-5607-aec4-989c118efb7d', 'Carrifran Wildwood, Moffat Dale', 'https://www.walkhighlands.co.uk/galloway/carrifran-wildwood.shtml', 4.0, 99, 1.5, 'Since 2000 this spectacular ice-gouged valley has been the site of the Carrifran Wildwood. The aim of the land management here - carried out by a voluntary group - is to restore the valley to ecological health. Before the coming of sheep, much of the Southern Uplands was a wooded landscape. The Carrifran Wildwood group''s work on re-establishing native trees here - intervening just enough to allow nature to take a hold once more - enables visitors and others to better understand what much of the Border country would once have looked like.', 55.3908, -3.328),
('cde12fcb-19d2-5bd1-89cd-2b9e99d2f8d9', 'Beinn Bhreac, from Calvine', 'https://www.walkhighlands.co.uk/perthshire/beinn-bhreac.shtml', 41.25, 1054, 12.0, 'Beinn Bhreac is a rolling, heather-covered hill guarded by peat bogs and featureless moorland, hidden away in the remotest corner of the Atholl hills. Reaching it from any direction is something of an epic; the easiest route is that described here - the long approach up Glen Bruar can be greatly aided by the use of a mountain bike.', 56.7681, -3.9573),
('cde4b61f-238b-514b-9ad0-ed4b2b268b9a', 'Duncolm and the Slacks, Old Kilpatrick', 'https://www.walkhighlands.co.uk/glasgow/duncolm.shtml', 15.0, 490, 4.5, 'The steep grassy dome of Duncolm rises above the moors as the highest point of the Kilpatrick Hills. Although close to Glasgow it feels like a wild place and is a popular objective. This route from Old Kilpatrick is easily reached by public transport; the return given is via the Slacks which has superb views over the city.', 55.9247, -4.4515),
('ce14dd3e-6157-5e58-97a7-afb95cbe9d95', 'Ben Vorlich and Stùc a'' Chròin', 'https://www.walkhighlands.co.uk/perthshire/ben-vorlich.shtml', 14.5, 1145, 7.0, 'These two Munros on the southern fringe of the Highlands appear as an identical pair in many distant views. Closer up, they are more different. Ben Vorlich is a very popular hillwalk from Loch Earn and a fine viewpoint, whilst the continuation to Stùc a'' Chròin is a more serious walk with steep, rocky ground.', 56.3813, -4.2158),
('ce188543-65a0-5605-8483-e2eb4eb2e216', 'Striding Arches, near Moniaive', 'https://www.walkhighlands.co.uk/galloway/striding-arches.shtml', 9.5, 334, 3.5, 'The Striding Arches are a series of three massive stone sandstone arches built on the hilltops around Cairnhead, near Moniaive. Built by renowned sculptor Andy Goldsworthy, the arches are complemented by another springing from an old byre at the foot of the valley. This walk starts from the byre and climbs up through the forest to visit one of the hilltop arches; it is possible to extend the route to visit a second arch along the hill ridge.', 55.251, -4.0429),
('ce8d5203-31e2-50d8-9dcc-fb7d60fb56c4', 'Glas Bheinn from Inchnadamph', 'https://www.walkhighlands.co.uk/ullapool/glas-bheinn.shtml', 15.75, 770, 6.5, 'The northernmost summit of the great range which borders the eastern side of Assynt and runs over Conival to Breabag, Glas Bheinn receives comparatively little attention. It''s ascent still provides a good walk in stunning surroundings.', 58.1485, -4.9734),
('ce915578-750e-5960-9e09-5b3fcad67b58', 'Bidein a'' Choire Sheasgaich and Lurg Mhòr', 'https://www.walkhighlands.co.uk/torridon/bideinachoiresheasgaich.shtml', 38.0, 1530, 64.0, 'A challenging expedition to climb two of the remotest Munros. The fine, pointed summit of Bidein a''Choire Sheasgaich would be more celebrated were it not hidden deep in the wilds of Monar, whilst neighbouring Lurg Mhòr is even more inaccessible. The walk can be broken up by an overnight stay in the bothy or wild camping.', 57.3915, -5.45534),
('ceb86d7a-68a5-5bf0-b252-cc60b025b0e4', 'Ben Vrackie, near Pitlochry', 'https://www.walkhighlands.co.uk/perthshire/ben-vrackie.shtml', 10.0, 787, 4.0, 'Ben Vrackie is indelibly associated with the town of Pitlochry at its foot, and has for long been an extremely popular ascent for those visiting the town. The summit is a great viewpoint and the ascent follows good paths through woodland, open moorland and past picturesque Loch a'' Choire. The route description includes two optional extensions to make longer walks.', 56.7155, -3.7277),
('cee5d3aa-64c0-5f92-a7ba-4b9ba11b66c8', 'Sgòr Gaoith, from Glen Feshie', 'https://www.walkhighlands.co.uk/cairngorms/sgor-gaoith.shtml', 14.0, 913, 7.0, 'Sgòr Gaoith gives a superb, fairly short hillwalk when approached from Glen Feshie. The ascent passes through some magnificent pinewoods before climbing the bare upper slopes to reach a vast plateau. The summit is extremely dramatic perched on the very edge of the vast broken crags that plunge down to Loch Einich; the views are superb.', 57.0879, -3.8951),
('cf2527b0-e074-5315-be6d-f33f8e46784f', 'Duncryne hill, by Gartocharn', 'https://www.walkhighlands.co.uk/lochlomond/duncryne.shtml', 1.25, 88, 0.6666666666666666, 'Duncryne, known locally as the Dumpling, is a tiny hill of only 465 feet above sea level. However the very short ascent gives a reward out of all proportion to the effort, revealing a fantastic view of Loch Lomond, dotted with its many islands and backed by the great mountains of the Southern Highlands.', 56.0377, -4.5174),
('cf7f67ca-61a8-58a6-b282-738154575f41', 'Tarbat Ness circuit, Portmahomack', 'https://www.walkhighlands.co.uk/ullapool/tarbat-ness.shtml', 14.0, 132, 5.0, 'This excellent coastal circuit heads around the Tarbat Ness headland, passing a majestic lighthouse and linking two former fishing villages. There are good views throughout and the opportunity to spot seabirds, dolphins and seals.', 57.8347, -3.8292),
('cfde4c90-2e98-5236-a89e-d9dfbaa05f24', 'Càrn Ban via Alladale', 'https://www.walkhighlands.co.uk/sutherland/carn-ban-alladale.shtml', 38.5, 935, 12.0, 'Càrn Ban is one of the most remote Corbetts, though the approach can be greatly eased by use of a mountain bike for the first (and last) 11.5km or more. For those completing the whole distance on foot, there are plenty of possible wild-camping spots. The approach through Gleann Mòr passes through stunning regenerating pine and birch woods. Stalkers'' paths aid the ascent and descent whilst the summits are grassy and spacious with stunning views.', 57.8653, -4.5902),
('cff039fb-efa4-5dd8-9e7f-0a0ba1ba38e6', 'Ward of Bressay and Kirkabister Ness, Bressay', 'https://www.walkhighlands.co.uk/shetland/ward-of-bressay.shtml', 12.5, 303, 5.0, 'Just a short ferry hop away from busy Lerwick, the Isle of Bressay is a world apart. This circular walk follows tracks up to the island''s summit - the Ward of Bressay - for its superb views. The circuit continues with a rough and boggy moorland traverse before descending with views to the spectacular arch below the lighthouse at Kirkabister Ness.', 60.1564, -1.1215),
('cffb6cc3-cd74-5364-a4cf-4fee172b292c', 'Beinn a'' Bheithir via Schoolhouse Ridge', 'https://www.walkhighlands.co.uk/fortwilliam/beinnabheithir.shtml', 15.5, 1387, 9.0, 'This magnificent mountain ridgewalk takes in two Munros with truly outstanding views of mountain, sea and loch; a real Scottish classic. The ascent involves some easy scrambling up Schoolhouse Ridge, with an alternative suggested for those not wishing to put hand to rock.', 56.6783, -5.12981),
('d01b09bb-0340-546e-bffe-e3a369a14a27', 'Beinn Ghobhlach', 'https://www.walkhighlands.co.uk/ullapool/beinnghobhlach.shtml', 11.0, 760, 6.0, 'Beinn Ghobhlach may be only 635m high but its distinctive outline and rugged character exceed those of many a higher peak. Its position on the Scoraig peninsula between the two Loch Brooms makes it a truly stunning viewpoint.', 57.874, -5.2804),
('d01d94d6-d14c-503a-9aec-d95e4fea7e6f', 'Dallas Dhu and the River Findhorn circuit, Forres', 'https://www.walkhighlands.co.uk/moray/dallas-dhu.shtml', 14.0, 94, 4.5, 'Beginning from the centre of the fine country town of Forres, this circuit explores some of the town''s attractive woodlands en route to the historic distillery of Dallas Dhu. Country lanes then provide a link to reach the banks of the Findhorn River before the route returns to Forres.', 57.6127, -3.6041),
('d02c251e-b41e-5f6a-9517-dc66882f2049', 'Riverside Walk, Newton Stewart', 'https://www.walkhighlands.co.uk/galloway/newton-stewart-riverside.shtml', 2.6, 8, 1.0, 'This pleasant stroll from Newton Stewart heads along the banks of the lovely River Cree.', 54.9568, -4.481),
('d0308a21-9099-545a-9d31-561dd4a00752', 'Dornie, River Glennan and Carr Brae circuit', 'https://www.walkhighlands.co.uk/kintail/Dornie.shtml', 18.5, 778, 7.0, 'Linking up a series of neglected historical paths, this circuit from Dornie offers solitude even at the busiest times, wild landscapes and some superb views.', 57.2796, -5.5157),
('d066267e-1454-5b4f-a34b-fb353ea40e4a', 'Dunearn Burn & the Findhorn, Darnaway Forest', 'https://www.walkhighlands.co.uk/moray/darnaway-forest.shtml', 3.5, 130, 1.5, 'This excellent forest walk explores the western side of the dramatic gorge carved by the River Findhorn. The narrow path passes close to the edge of vertical drops down to the swirling waters.', 57.541, -3.6786),
('d0d4ff04-c651-5954-9bf0-cdb2256bb1d4', 'Monadh Liath Munros: Càrn Dearg, Càrn Sgulain & A'' Chailleach', 'https://www.walkhighlands.co.uk/cairngorms/monadhliath.shtml', 24.5, 946, 10.0, 'This long hillwalk includes ascents of three of the four Monadh Liath Munros. The hills themselves are undistinguished (particularly Càrn Sgulain), but Càrn Dearg has a feeling of remoteness and the long trek across the plateau from this peak to the others gives a feeling of great space, given favourable weather.', 57.0705, -4.1576),
('d0f60a2b-a160-5dfd-b03e-730c81e0d8c6', 'Eabhal (Eaval), North Uist', 'https://www.walkhighlands.co.uk/outer-hebrides/eaval.shtml', 10.5, 375, 5.5, 'Eaval is the highest hill on North Uist. Though only 347m in height its steep cone dominates the low-lying island and provides unique, stunning views of the amazing land-and-waterscape around it.', 57.5509, -7.2004),
('d108b801-baa9-5b0d-bea4-d2e27c2eca9a', 'Achnabreac Cup and Ring carvings, Cairnbaan', 'https://www.walkhighlands.co.uk/argyll/achnabreck.shtml', 1.75, 65, 1.0, 'This short forest walk visits the most extensive prehistoric rock carvings in the UK: the Achnabreac Cup and Ring rocks. The easy circular also gives good views over Lochgilphead towards the Isle of Arran.', 56.0622, -5.4528),
('d128579a-2a5c-5cea-ba17-0139459b9a52', 'Falkirk Wheel and Antonine Wall, near Falkirk', 'https://www.walkhighlands.co.uk/fife-stirling/antonine-wall.shtml', 7.0, 52, 2.0, 'An almost level walk following the Forth & Clyde Canal towpath to Bonnybridge and then exploring the Antonine Wall and Roman Fort before a woodland walk reaches the top of the Falkirk Wheel, a marvel of modern engineering.', 56.003, -3.8408),
('d13a28c2-2771-541e-9b9e-510638fc68a4', 'Taybank circuit, Errol', 'https://www.walkhighlands.co.uk/perthshire/errol.shtml', 7.0, 44, 2.5, 'This straightforward circular walk leads from Errol down to a wooded bank at the edge of the Tay, at first above reed beds and later above the watery tidal flats. It gives an interesting perspective on the river and is a good walk for birdlife. Errol is a large village set on the Carse of Gowrie, the flat lands on the north side of the Tay, renowned for its fertile soils.', 56.3931, -3.21256),
('d14a7029-f479-5ea2-995d-70bf9df69e5b', 'Aonach Beag and Aonach Mòr from Glen Nevis', 'https://www.walkhighlands.co.uk/fortwilliam/aonachmor.shtml', 16.5, 1376, 10.0, 'These are two of the highest mountains in Britain. This route avoids the ski developments on the northern flanks of Aonach Mòr which remain out of sight. It gives a fairly long, rugged and remote hillwalk with superb views.', 56.7777, -5.00031),
('d1778877-df27-5ac6-b2a2-ecf5b8336fe0', 'Pollok Park, Glasgow', 'https://www.walkhighlands.co.uk/glasgow/pollok-park.shtml', 5.25, 10, 1.5, 'Explore Pollok Park on the south side of Glasgow; the route offers the chance to visit stately Pollok House, or the fascinating (and free) Burrell Collection. Cafe, toilets, parking and excellent children''s play area.', 55.8239, -4.30128),
('d1cdcbde-bf79-5ef7-ac11-3bb39b018f66', 'Vallay (Bhalaigh) island, near Sollas', 'https://www.walkhighlands.co.uk/outer-hebrides/vallay.shtml', 8.0, 22, 2.5, 'This exciting tidal walk heads across wet sands and mud flats to reach the now uninhabited island of Vallay. Pass the ruins of impressive Vallay House and the farm to cross the island to a sandy bay and the ruins of an ancient chapel.', 57.6375, -7.3966),
('d1d895bd-b13b-558f-8dd2-595f27865329', 'Ravensheugh Sands', 'https://www.walkhighlands.co.uk/lothian/baldreds-cradle.shtml', 5.25, 36, 2.0, 'This fine coastal walk heads out onto the grassy headland at St Baldred''s Cradle - the site of an ancient cairn with great views out to the Bass Rock. The walk then heads for the beautiful Ravensheugh Sands before returning to the start.', 56.0194, -2.6012),
('d20030d6-6623-56ec-883c-1c9c959620f1', 'Ardblair Trail & Bluebell Woods, Blairgowrie', 'https://www.walkhighlands.co.uk/perthshire/ardblair-trail.shtml', 9.5, 80, 2.5, 'This fine circular walk from Blairgowrie takes in fertile countryside, a couple of attractive lochs and a wood which is carpeted with bluebells in early summer. The last part of the walk heads through housing to return to the centre of Blairgowrie.', 56.5923, -3.3361),
('d2250454-6729-5633-abcb-045430119331', 'Curleywee and Lamachan Hill, Glen Trool', 'https://www.walkhighlands.co.uk/galloway/lamachan-hill.shtml', 17.0, 949, 7.5, 'The Galloway Hills have some challenging pathless and tussocky terrain - nowhere more so than on the lower slopes of Curleywee and Lamachan Hill, as visited on this route. Above the hard going, Curleywee is a fine conical peak and a superlative viewpoint, whilst Lamachan has a more extensive, plateau-like summit.', 55.093, -4.48392),
('d25f930e-1246-5d5e-a7bd-47f91daa0d48', 'The Birks of Aberfeldy, Aberfeldy', 'https://www.walkhighlands.co.uk/perthshire/birks-of-aberfeldy.shtml', 3.5, 195, 2.0, 'This beautiful short walk is deservedly popular. Celebrated in a poem by Robert Burns, the fine walk up the steep gorge of the Moness burn reveals several waterfalls.', 56.6157, -3.86656),
('d27c42ca-1c41-51ac-90eb-078ebe5ed479', 'The Great Map of Scotland circuit, Eddleston', 'https://www.walkhighlands.co.uk/borders/barony.shtml', 5.0, 101, 1.5, 'This waymarked circuit from the old village of Eddleston visits the impressive Barony Castle - a hotel - and the Great Polish Map of Scotland before looping through the woods and fields with views across to the Moorfoot Hills.', 55.7122, -3.2072),
('d27fe8e1-30a2-5a3c-9b00-411b68b0e5b6', 'Ben More via A'' Chioch and Beinn Fhada', 'https://www.walkhighlands.co.uk/mull/ben-more-a-chioch.shtml', 14.5, 1255, 9.0, 'The A'' Chioch ridge provides the classic approach to Ben More for scramblers, revealing the finest features of the mountain. Adding Beinn Fhada as well makes for a full mountain day. The final slope up Ben More is unpleasantly loose and steep with tricky route finding.', 56.461, -6.043),
('d2f3f993-d164-5545-94cb-82ecac1c6c7e', 'Shenavall circuit', 'https://www.walkhighlands.co.uk/ullapool/shenavall.shtml', 18.5, 740, 6.0, 'This fine circuit visits the edge of the Fisherfield Forest, an area known to keen hillwalkers as the ''Great Wilderness''. It passes through scenery including attractive woodland, a fine river and bleak, boggy moorland, has fine views of the surrounding mountains and visits a well-known bothy.', 57.8149, -5.176),
('d373b7ef-64d1-5f8a-9fe4-80cba9fd9f98', 'Ullapool and Loch Achall, Ullapool', 'https://www.walkhighlands.co.uk/ullapool/lochachall.shtml', 12.0, 381, 3.5, 'The walk begins up the Ullapool Hill Path to take in great views of the town and Loch Broom, before visiting to the lonely shores of Loch Achall and the Ullapool River.', 57.8974, -5.1641),
('d3b28274-e7f6-532a-9e5a-454379af77b1', 'Monega Hill and Glas Maol round from Glen Isla', 'https://www.walkhighlands.co.uk/angus/monega-glas-maol.shtml', 20.75, 1135, 7.5, 'A fantastic horseshoe with great views from Monega Hill and a much better route for the two Munros than the usual approach from the Cairnwell with a finish over the Corbett, Monamenach', 56.8128, -3.32404),
('d3c6ce1d-6eea-586c-a6a9-27698f895462', 'Sgùrr a'' Bhac Chaolais', 'https://www.walkhighlands.co.uk/kintail/sgurr-a-bhac-chaolais.shtml', 10.0, 858, 6.0, 'Sgùrr a'' Bhac Chaolais is thirty metres short of Munro status and is very much the forgotten peak on the great range along the south side of Glen Shiel. Nonetheless it gives a good hillwalk with views over its more famous neighbours. Until 2012 the summit was regarded as a Corbett jointly withBuidhe Bheinn, but a resurvey revealed that the latter was the higher summit and thus the Corbett.', 57.17, -5.3538),
('d3caf8ba-69a9-5f0b-85e1-74257db0ecba', 'Dunglass Island and the Conon, Maryburgh', 'https://www.walkhighlands.co.uk/lochness/dunglass-island.shtml', 12.0, 90, 3.5, 'This attractive walk combines sections alongside the broad River Conon and a circuit around Dunglass Island - once the site of a fort. The return is along a fine avenue of trees with views over the Cromarty Firth.', 57.5779, -4.4394),
('d4314f94-4064-578e-a28b-49fedbfb3efc', 'Ardgartan shore and woodlands', 'https://www.walkhighlands.co.uk/lochlomond/ardgarten.shtml', 3.5, 60, 1.0, 'This beautiful and varied circuit from Ardgartan begins with a road stretch, but soon leads along the shores of Loch Long and then follows the wooded banks of the Croe Water.', 56.1944, -4.7912),
('d46e0fee-6434-5e92-aaf1-db6ea30187e3', 'Hill of Dunnideer, near Insch', 'https://www.walkhighlands.co.uk/aberdeenshire/dunnideer.shtml', 5.25, 118, 2.0, 'The Hill of Dunnideer is a prominent local landmark, crowned by an ancient hillfort, the ruins of a medieval castle - and last but not least - superb views out of proportion to the effort involved. This circular walk continues from the summit, passing some standing stones to return through a belt of woodland planted for wildlife.', 57.3429, -2.638),
('d4a22167-1ace-5b6d-8c88-5cd3ed3fd6b3', 'Tinto from the north', 'https://www.walkhighlands.co.uk/glasgow/tinto.shtml', 7.0, 486, 2.5, 'A great little hill with commanding views of the Clyde Valley and a massive summit cairn. A very popular landmark, the route is easy to follow and reasonably gentle.', 55.6197, -3.6455),
('d4a90384-c7bc-5a7e-9f65-02b0f227ff1b', 'Allt Mhoraich circuit', 'https://www.walkhighlands.co.uk/cairngorms/alltmhoraich.shtml', 5.5, 238, 2.5, 'This is mostly a quiet moorland walk, making a circuit around Creag Sanais; there are fine views around the upper Spey and Badenoch. There are often livestock on the first section and the farmer requests walkers to leave their dogs behind.', 57.0129, -4.21),
('d4d56ad7-c61e-5154-bce8-2e11a148dc90', 'Stob Coire a'' Chearcaill, from Loch Eil', 'https://www.walkhighlands.co.uk/fortwilliam/stob-coire-chearcaill.shtml', 14.0, 789, 6.0, 'Stob Coire a'' Chearcaill is a familiar sight across Loch Linnhe from Fort William, but far fewer people actually climb it. This is the easiest route, making use of a track to avoid the boggiest terrain lower down. The views - as might be expected - are excellent.', 56.8449, -5.203),
('d4db1863-08a8-5d87-8b2b-149bfe0384fa', 'Ellenabeich hillwalk, Isle of Seil', 'https://www.walkhighlands.co.uk/argyll/ellenabeich.shtml', 2.25, 62, 1.0, 'Climb the steep hillside behind Ellenabeich to reveal fantastic views over dramatic cliff scenery towards the Isle of Mull, as well as over the village to Easdale. The route explores the picturesque rows of old cottages on the return.', 56.2955, -5.6513),
('d504415c-6897-578a-9d6c-214dabf87683', 'Glen Aros forest, near Salen', 'https://www.walkhighlands.co.uk/mull/glen-aros.shtml', 1.5, 35, 0.5, 'This is a very short but pleasant circular forestry walk, and is well waymarked. The main point of interest is the site of the old chapel and graveyard of Cill an Alein - an attractive spot with an outlook towards Ben More.', 56.5368, -5.98529),
('d51dd509-0d37-5fac-b641-b4416f1948d9', 'Dingieshowe circuit, Deerness', 'https://www.walkhighlands.co.uk/orkney/dingieshowe.shtml', 3.75, 57, 1.0, 'This short circuit takes in the sand and pebble beach of Dingieshowe, a short section of low coastal cliffs, and a return along the tarmac. The walk starts at the narrow isthmus that connects Deerness to the rest of Mainland Orkney.', 58.9158, -2.7838),
('d520b246-3a54-57c9-af1d-0ee6f6506b8e', 'King''s Cave circuit, near Blackwaterfoot', 'https://www.walkhighlands.co.uk/arran/kings-cave.shtml', 4.5, 140, 2.0, 'Historic King''s Cave is one of several locations in which Robert the Bruce is said to have had his famed encounter with a spider.  This circular heads down to explore a dramatic section of coastline with a series of caves.', 55.5317, -5.333),
('d54444c0-d0f1-59f4-acc1-419afb399c30', 'Scorrybreac circuit, Portree', 'https://www.walkhighlands.co.uk/skye/scorrybreac.shtml', 3.0, 164, 2.0, 'A beautiful circuit on the north side of Portree bay, popular with both visitors and local dog walkers.', 57.4151, -6.1828),
('d555aa3c-b4b9-58b2-8327-dfa0fbe80646', 'Buachaille Etive Beag', 'https://www.walkhighlands.co.uk/fortwilliam/buachailleetivebeag.shtml', 8.0, 900, 6.0, 'Buachaille Etive Beag is often overlooked in favour of its more illustrious neighbour. It is, however, a magnificent ridge in its own right, offering superlative views down Loch Etive and of the surrounding peaks of Glencoe. It also has the benefit of an excellent path easing the ascent and descent from the Lairig Èilde.', 56.6627, -4.9582),
('d56d077d-010c-530c-a1d9-056d396f69ef', 'Helmsdale Explorer', 'https://www.walkhighlands.co.uk/sutherland/helmsdale.shtml', 6.0, 130, 2.5, 'This circuit makes a very varied exploration of the environs of Helmsdale, taking in the harbour, a short coastal walk, a climb across the hillside overlooking the village, and finally a riverside stroll.', 58.1171, -3.654),
('d5c4ad1d-e24d-531a-b251-ea352dd6b89c', 'Port Charlotte circular', 'https://www.walkhighlands.co.uk/islay-jura/port-charlotte.shtml', 4.6, 82, 2.0, 'A pleasant coastal and farmland circuit which climbs above Port Charlotte to give good views before returning to explore the picturesque village.', 55.74, -6.3784),
('d5d6e919-9fc6-5235-b933-97183b623003', 'Scapa Flow and Loch of Ayre, St Mary''s', 'https://www.walkhighlands.co.uk/orkney/st-marys.shtml', 3.25, 13, 1.0, 'A circular walk along the shores of Scapa Flow, passing Howequoy Head near where HMS Royal Oak was sunk in 1939, and continuing inland to return to St Mary''s past the Loch Of Ayre.', 58.8948, -2.9188),
('d61ae5ff-7d3c-5d0b-b01e-b92568ffe1c4', 'Ness of Hillswick circuit, Northmavine', 'https://www.walkhighlands.co.uk/shetland/ness-of-hillswick.shtml', 7.75, 240, 3.5, 'This excellent walk makes a coastal circuit around the Ness of Hillswick peninsula. There are some spectacular sea stacks and fine clifftop scenery, as well as a tiny lighthouse at the far end.', 60.4759, -1.4886),
('d6265ca7-967f-5926-8c55-20b99e57b0af', 'Meikle Balloch, near Keith', 'https://www.walkhighlands.co.uk/moray/meikle-balloch.shtml', 5.2, 169, 2.5, 'Meikle Balloch is a largely forested hill to the east of the town of Keith. The moorland summit rises clear of the conifers and gives extensive views over Moray and Aberdeenshire.', 57.5313, -2.9056),
('d6580b16-245e-51cb-9d2c-671392820bdc', 'Peterhead Town Trail', 'https://www.walkhighlands.co.uk/aberdeenshire/peterhead-trail.shtml', 5.5, 44, 2.0, 'This urban route takes in the streets and waterfront of the town of Peterhead, uncovering many fascinating tales from its history. There''s a chance to visit a fine beach and great views out to see, as well as the town''s monuments and buildings.', 57.5057, -1.78539),
('d66b66a8-0d65-5401-a972-669e82a48da0', 'Dumyat from Blairlogie', 'https://www.walkhighlands.co.uk/fife-stirling/dumyat-blairlogie.shtml', 6.0, 415, 4.0, 'A rougher approach to the lovely summit of Dumyat than the more popular route, however it has good views and although steep and indistinct in places makes a rewarding climb.', 56.1498, -3.883),
('d6b0cfb9-3f66-5330-9b2c-a78e83feb234', 'Cambus o'' May Pinewood trail', 'https://www.walkhighlands.co.uk/cairngorms/pinewood-trail.shtml', 4.25, 50, 2.0, 'This is the longest of three circular waymarked trails through the pinewoods at Cambus o'' May. The walk offers views up Deeside, passes two attractive forest lochans and offers the chance to spot woodland wildlife.', 57.0698, -2.9847),
('d6b377c8-11ec-5d00-aa8a-6a8a44e0360c', 'The Saddle, Forcan Ridge and Sgùrr na Sgìne', 'https://www.walkhighlands.co.uk/kintail/Thesaddle.shtml', 13.0, 1350, 9.0, 'The Saddle is the finest of the Kintail peaks and one of the most magnificent mountains in the Highlands. Its ascent via the Forcan Ridge is a difficult but classic scramble; the scrambling can be avoided if needed and the walk still has fantastic views.', 57.1762, -5.36459),
('d6b4600b-a62a-5c1e-b742-aff7fbee127a', 'Bridgend Woods and the Woollen Mill', 'https://www.walkhighlands.co.uk/islay-jura/bridgend-woods.shtml', 6.6, 23, 2.0, 'Explore the mixed woodland, once part of the grounds of Islay House, and visit Islay Woollen Mill part way round. Can be combined with a visit to Islay House Square with galleries, brewery and community garden.', 55.7841, -6.2463),
('d6cd022e-0a46-58eb-ab11-c6090e3ad025', 'Uisgneabhal Mòr , Teileasbhal and Stuabhal', 'https://www.walkhighlands.co.uk/outer-hebrides/uisgneabhal-mor.shtml', 20.25, 1100, 8.0, 'Uisgneabhal Mòr is the second highest mountain in the Outer Hebrides, and with its close neighbour Teileasbhal looks impressive from the A859 west of Tarbert. Combined with remote Stuabhal the hills make for a grand and rugged hillwalk, with a long initial approach up Gleann Miabhaig enlivened by the rock architecture of Sròn  Scourst.', 57.9509, -6.903),
('d6d4ff1e-1e9e-57e9-ab84-601286e37c27', 'Plock of Kyle, Kyle of Lochalsh', 'https://www.walkhighlands.co.uk/kintail/Plockofkyle.shtml', 2.5, 55, 1.5, 'The Plock of Kyle (Am Ploc in Gaelic) is the beautiful promontory west of Kyle of Lochalsh. The road to the Skye Bridge crosses its southern shores, but away from the road the Plock is a wonderful place to explore, with wild flower meadows, native woodland, a series of hidden rocky coves and a fine viewpoint. It''s rich in wildlife; this is an excellent place to look for otters. Whilst the directions may seem complex due to the many paths, the exact route taken matters little - the Plock is a great place to explore. It is owned by the Kyle and Lochalsh Community Trust who have developed access for the benefit of locals and visitors alike.', 57.2818, -5.7264),
('d710fba9-f03a-5b73-a413-bd5fd8528ac9', 'North Ronaldsay circuit', 'https://www.walkhighlands.co.uk/orkney/north-ronaldsay.shtml', 19.25, 85, 7.5, 'North Ronaldsay is the most northerly - and remote - of the Orkney islands. It is almost completely enclosed by a stone wall that keeps the ancient Ronaldsay sheep on the rocky shore; for the most part this unique walk heads round the shore outside the wall. The going can be tiresome in places, but there are fine sandy stretches too, and the island has a flavour all its own.', 59.3617, -2.4435),
('d792b193-d85f-5092-8d55-6447d7949f85', 'Fionn Bheinn, Achnasheen', 'https://www.walkhighlands.co.uk/torridon/Fionnbheinn.shtml', 12.0, 807, 6.0, 'Fionn Bheinn is the forgotten hill of the area, its wide grassy (and wet) slopes contributing to its neglect. This isn''t a hill to leave for a claggy day however, as the summit is a superb viewpoint.', 57.5793, -5.0734),
('d7a28116-211d-5058-889d-d9276635dd9e', 'River Teviot and Roxburgh circuit, Kelso', 'https://www.walkhighlands.co.uk/borders/kelso.shtml', 11.75, 120, 3.5, 'Starting from the characterful town of Kelso, this beautiful low-level circular walk heads out along the banks of the River Teviot to a grand viaduct, before returning along the route of an old railway line.', 55.5974, -2.43091),
('d7a9ccb1-90fb-53a2-a18e-550f033b57c1', 'The White Wife of Otterswick, Yell', 'https://www.walkhighlands.co.uk/shetland/white-wife.shtml', 6.75, 128, 2.5, 'The White Wife of Otterswick is one of Shetland''s more unusual and moving memorials - the figurehead of the German ship Bohus which sank in a storm off the coastline here, and which now commemorates the lives of four of the crew who were lost. The straightforward coast walk continues around the Ness of Queyron before returning to the start along a minor road - watch out for the otters for which this is prime habitat, and for porpoises swimming offshore.', 60.5561, -1.0542),
('d7ca3243-1ed6-52b9-b40b-55f7161d4991', 'Eynort Forest walk', 'https://www.walkhighlands.co.uk/skye/eynort-forest.shtml', 9.5, 241, 3.5, 'This straightforward, waymarked walk through forestry plantations offers some fine views over Loch Eynort, with picnic benches. The climbs involved are fairly gradual.', 57.2571, -6.3377),
('d7f8957b-b51c-5b82-a85e-3699f3a76b90', 'Beinn Bheula, near Lochgoilhead', 'https://www.walkhighlands.co.uk/argyll/beinn-bheula.shtml', 12.0, 798, 6.0, 'Beinn Bheula enjoys a superb location rising above remote Lochgoilhead and almost surrounded by the many sea lochs that penetrate for miles in this part of Argyll. Although only a fairly lowly Corbett, it is a steep and very rugged mountain of grand character. Although fairly short this hillwalk gives very rough going in places.', 56.1589, -4.921),
('d8221c8b-1754-54d5-bcc4-8056df191c52', 'Sgùrr nan Conbhairean round', 'https://www.walkhighlands.co.uk/kintail/sgurrnanconbhairean.shtml', 17.5, 1260, 8.0, 'This enjoyable walk takes in three Munros on the north side of Loch Cluanie. Though less steep and shapely than their Glen Shiel counterparts, these mountains give an excellent outing with grand views into their fine eastern corries.', 57.1461, -5.0682),
('d8326c9f-8373-55a4-bc80-476b14833028', 'Sgùrr a'' Choire-bheithe, from Barrisdale Bay', 'https://www.walkhighlands.co.uk/fortwilliam/sgurr-a-choire-bheithe.shtml', 9.75, 932, 5.5, 'Sgùrr a'' Choire-bheithe is one of the highest and most remote of the Corbetts. The route described here is the most straightforward, up an easy-angled grassy ridge from Barrisdale Bay on the Knoydart peninsula. There is no road access to Barrisdale - which is a4 hour walk-in from Kinloch Hourn.', 57.0796, -5.5134),
('d84d1d23-bc3a-5a99-b8e2-a654be470401', 'Beinn Leoid and Meallan a'' Chuail from the A838', 'https://www.walkhighlands.co.uk/sutherland/beinn-leoid.shtml', 15.5, 941, 7.0, 'Beinn Leoid is a rather neglected Corbett, being remote and hidden from roads. This route combines it with its fine neighbour Meallan a'' Chuail using an excellent stalkers'' path for the approach. Baggers could easily extend the route to take in the additional but undistinguished Fiona of Meall an Fheur Loch.', 58.2578, -4.7997),
('d8522dee-64fc-55ee-a77b-00d4a695bc1a', 'Ui Church and Broad Bay Beach, near Stornoway', 'https://www.walkhighlands.co.uk/outer-hebrides/ui-church.shtml', 2.0, 25, 1.0, 'This short walk visits the important ruins of the medieval Eaglais na h-Aoidhe (Ui Church) and its beautiful carved gravestones before exploring the sandy beach on the north side of the tombolo that links Point to the rest of Lewis. The return is on a dune path, visiting the striking memorial to a group of 19th century land raiders.', 58.2052, -6.2853),
('d8808bb2-7024-5a88-bcc1-216616f5f092', 'Cambuskenneth Abbey  from Stirling', 'https://www.walkhighlands.co.uk/fife-stirling/cambuskenneth.shtml', 5.25, 13, 1.5, 'Explore a different part of Stirling, heading past the old harbour to visit the ancient abbey at Camuskenneth before returning along the River Forth to Old Stirling Bridge.', 56.1195, -3.9353),
('d890e398-120e-523c-ac84-b0f7375edd59', 'River Lochy Falls & Strone Woods, Glen Lochy', 'https://www.walkhighlands.co.uk/argyll/strone-woods.shtml', 2.0, 60, 0.75, 'Strone Hill woods are a very beautiful remnant of ancient oakwood almost hidden by the surrounding forestry of Glen Lochy. There is a short waymarked trail - a delightful and very easy walk - that also visits the falls on the river.', 56.4029, -4.9025),
('d8952e63-bd83-5fe4-8720-8221dc028d35', 'Loch Lochy Munros from Kilfinnan', 'https://www.walkhighlands.co.uk/fortwilliam/lochlochymunros.shtml', 19.0, 1258, 9.0, 'Sròn a'' Choire Ghairbh and Meall na Teanga rise steeply above Lochy Lochy opposite the busy A82, and are commonly known as the Loch Lochy Munros. Their ascent from Kilfinnan begins with an approach through dense plantations, but once on the hills the views are superb.', 57.0213, -4.83917),
('d8a4407f-7f41-5a5d-934f-b0a841a84212', 'Stob Coire Easain and Stob a''Choire Mheadhoin', 'https://www.walkhighlands.co.uk/fortwilliam/easains.shtml', 16.5, 1172, 8.0, 'This fine pair of Munros - commonly known as the Easains - give a fairly long ridgewalk high above the glacial trough of Loch Treig. Stob Coire Easain in particular is a fine peak and offers superb views; it is quite hidden away behind other summits from most roads which perhaps explains why it isn''t better known.', 56.8654, -4.7084),
('d8c66be1-1bf1-598a-9c23-11d7e193ed48', 'Hart Fell ridges horseshoe, near Moffat', 'https://www.walkhighlands.co.uk/galloway/hart-fell.shtml', 13.0, 886, 6.0, 'This superb horseshoe of escarpments and ridges - including the very fine Saddle Yoke - encircles the skyline around the Blackhope Burn. It makes for the classic route to the Corbett of Hart Fell.', 55.3751, -3.3476),
('d9204685-673f-5efd-9b71-89c55e662a0b', 'Ben More and Stob Binnein', 'https://www.walkhighlands.co.uk/lochlomond/ben-more.shtml', 12.0, 1335, 8.0, 'Ben More dominates Crianlarich and the road east, an enormous green pyramid offering no obvious easy approaches; the ascent is unrelenting. Its near neighbour Stob Binnein is often regarded as its twin, but this more retiring summit is actually the finer of the two peaks, a graceful cone above its supporting ridges.', 56.4028, -4.5612),
('d96de24a-3723-52db-b7b6-1cd8efc4cd01', 'Kiloran Bay and Carnan Eoin', 'https://www.walkhighlands.co.uk/islay-jura/kiloran-bay.shtml', 4.25, 171, 2.0, 'Kiloran Bay is Colonsay''s most celebrated beach - and within easy reach of the road. This walk heads across the spectacularly yellowish sands - with the opportunity to explore caves unless the tide is high - before making a rougher climb up to the highest point on the island - a superb viewpoint.', 56.1008, -6.1866),
('d9a6d72d-78fd-58c7-9d54-2bc151071c90', 'Lee Pen, Innerleithen', 'https://www.walkhighlands.co.uk/borders/lee-pen.shtml', 5.25, 343, 2.5, 'A steep but short climb is rewarded with great views over the Tweed Valley and beyond on this pleasant route from Innerleithen.', 55.6193, -3.0672),
('d9cd49c7-c082-5cde-afc1-2e15f1dd8f05', 'Ness of Burgi Iron Age fort, from Scatness', 'https://www.walkhighlands.co.uk/shetland/ness-of-burgi.shtml', 3.25, 35, 1.0, 'This short and straightforward walk - with one trickier rocky section - leads out on a beautiful headland with superb views to both Sumburgh and Fitful Head. The walk visits a well-preserved Iron Age Block House or fort that is 2,000 years old.', 59.8718, -1.3079),
('d9e9ee34-0733-57ca-a9bf-373e494373a2', 'Leithen Water circuit, Innerleithen', 'https://www.walkhighlands.co.uk/borders/leithen-water.shtml', 4.5, 66, 2.0, 'A pleasant woodland and riverside walk following the Leithen Water to the golf course just outside town.', 55.6211, -3.0613),
('da3215da-7efc-5de0-a761-368d8d5b9b3c', 'Hailes Castle from East Linton', 'https://www.walkhighlands.co.uk/lothian/hailes-castle.shtml', 5.5, 34, 1.5, 'A visit to the extensive ruins of Hailes Castle is the objective on this straightforward riverside walk from the attractive village of East Linton. The alternative return route is along a quiet minor road.', 55.9867, -2.6563),
('da5ea257-4192-51a1-ba8d-28911ee83d32', 'Loch Vaa, near Aviemore', 'https://www.walkhighlands.co.uk/cairngorms/loch-vaa.shtml', 3.5, 28, 1.0, 'Hidden away in the pinewoods just off the A95 between Aviemore and Boat of Garten, Loch Vaa is a secluded gem. This short walk makes a straightforward circuit around the loch.', 57.2345, -3.8067),
('da8a1b2a-1421-5cbf-98a9-3bf176c429fe', 'Balnahard and Tràigh Ban', 'https://www.walkhighlands.co.uk/islay-jura/balnahard.shtml', 11.5, 202, 3.5, 'Whilst Kiloran Bay is Colonsay''s best known beach, a longer walk from the road leads to Balnahard and Tràigh Ban - for many people, an even more beautiful spot. The white sands here face eastwards and the beach is usually more sheltered than its counterpart.', 56.0983, -6.1828),
('db87acb8-9678-590c-8bb2-a66c10e5f6f1', 'Screel Hill, near Palnackie', 'https://www.walkhighlands.co.uk/galloway/screel-hill.shtml', 5.0, 331, 2.0, 'Screel Hill may rise only to a modest 344m but this rocky eminence provides a very rough walk. The reward is the stunning views over the Rough Firth and Auchencairn Bay.', 54.8774, -3.8986),
('dba0d46e-7049-5d1c-97c8-84732c75e14c', 'Hunda island from Burray village', 'https://www.walkhighlands.co.uk/orkney/hunda-reef.shtml', 12.75, 46, 4.0, 'The small, uninhabited island of Hunda makes for a fine walk; it is linked to Burray by a causeway. The walk is described from Burray village to avoid access problems at Littlequoy.', 58.8463, -2.9145),
('dbe00a15-02b6-5e6b-92d2-4d24b2bd71cd', 'Hogh Bay and Totronald RSPB reserve', 'https://www.walkhighlands.co.uk/islands/hogh-bay.shtml', 4.0, 7, 1.0, 'This easy shorter walk starts from the RSPB visitor centre at Totronald, and heads through corncrake country down to explore Hogh Bay - a truly magnificent sandy beach.', 56.6122, -6.6168),
('dc1969ea-c02e-5500-83c5-96cefbbf5bba', 'Heaval, from Castlebay', 'https://www.walkhighlands.co.uk/outer-hebrides/heaval.shtml', 5.25, 384, 3.0, 'Heaval is the highest summit on the Isle of Barra, and forms a dramatic backdrop to Castlebay. The ascent is short but very steep and rewards with stunning views on a clear day.', 56.9543, -7.4878),
('dc1f6af3-f204-5d06-80df-ffa169b18052', 'Auchmore Circuit, Killin', 'https://www.walkhighlands.co.uk/perthshire/auchmore-circuit.shtml', 4.5, 68, 1.5, 'This easy going circuit follows tracks and minor roads to the southeast of Killin, passing above Auchmore House and with views towards the Lawers range.', 56.4615, -4.32103),
('dc424daf-fdf3-512f-85dc-fb2604a75499', 'Prince''s Walk, Kinlochmoidart', 'https://www.walkhighlands.co.uk/fortwilliam/princeswalk.shtml', 3.0, 46, 1.0, 'This short circular walk gives views over the very impressive Kinlochmoidart House, before returning along a riverbank to visit the beautiful old stone bridge.', 56.7896, -5.7511),
('dc6560cb-9ff4-548d-b1e1-45deeef91aa6', 'Lews Castle Grounds, Stornoway', 'https://www.walkhighlands.co.uk/outer-hebrides/lews-castle.shtml', 6.5, 193, 2.0, 'An easy but delightful walk from the centre of Stornoway exploring the coastal grounds of Lews Castle. Refreshments are available at the Woodlands Centre in the Castle grounds.', 58.2086, -6.3901),
('dc780a5d-3cfe-504d-8c6b-87be4b01f8ff', 'Ben Vuirich', 'https://www.walkhighlands.co.uk/perthshire/ben-vuirich.shtml', 22.75, 673, 8.0, 'Ben Vuirich is a rather shy Corbett, hidden away in quiet country behind the much better known Ben Vrackie. This circular route includes some sections of rougher going but also offers solitude, overshadowed by the great bulk of nearby Beinn a''Ghlo.', 56.7826, -3.7926),
('dcbb5bfb-a98e-5270-a686-e8911cc83909', 'Blà Bheinn (Blaven)', 'https://www.walkhighlands.co.uk/skye/blabheinn.shtml', 8.0, 990, 6.0, 'Blà Bheinn is one of the most magnificent mountains in Britain; a great isolated citadel of rock with fabulous views and all the character of the main Cuillin Ridge. Its ascent is straightforward by Cuillin standards but very rocky.', 57.2203, -6.0429)
INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('dcf1f26e-b2ce-5325-aec3-36ab6aafc92b', 'Howmore (Tobha Mòr) beach circuit', 'https://www.walkhighlands.co.uk/outer-hebrides/howmore.shtml', 3.75, 10, 1.0, 'A short walk taking in the beach, machair, and thatched cottages and hostel at Howmore with time to explore the ancient chapel ruins.', 57.3026, -7.3871),
('dcf960d6-fa08-592e-bcac-c347e2a516cc', 'Castle Roy circuit, Nethy Bridge', 'https://www.walkhighlands.co.uk/cairngorms/castle-roy.shtml', 5.5, 95, 1.5, 'This figure-of-eight walk from Nethy Bridge follows a variety of paths and passes the ruins of Castle Roy, a thirteenth century fortress.', 57.2664, -3.6435),
('dd113829-260f-59be-aa92-900484639607', 'Dyke walk, Darvel', 'https://www.walkhighlands.co.uk/glasgow/dyke-darvel.shtml', 6.5, 171, 1.5, 'This enjoyable country circular walk climbs from Darvel to give good views over the Irvine Valley. The return is through the verdant Lanfine Estate - where wild boars help to manage the woodlands.', 55.6087, -4.2816),
('dd22db4d-3935-563c-8378-5cf07a29b451', 'Lochan a'' Mhill, Catacol', 'https://www.walkhighlands.co.uk/arran/lochan-a-mhill.shtml', 3.75, 268, 3.0, 'A short but tough little walk climbing over rough, often pathless, moorland. The initial ascent can be severely hampered by bracken, so the walk is best attempted once it has died down. Despite the effort involved the rewards are substantial with amazing views from this remote hill lochan.', 55.6886, -5.32666),
('dd2315cf-adab-5ef9-8770-3abba8be2695', 'Brodick and Lamlash circuit, Brodick', 'https://www.walkhighlands.co.uk/arran/lamlash-brodick.shtml', 14.0, 242, 5.0, 'This enjoyable circuit links Arran''s two largest villages - the capital, Brodick, and beautiful Lamlash. The route heads out around the coastline before returning via a cycle path next to the road and then an old track through the wooded Fairy Glen.', 55.5764, -5.1384),
('dd9fa985-0d84-5e39-b741-ab03a8d880e9', 'Beinn Bheigier and Glas Bheinn', 'https://www.walkhighlands.co.uk/islay-jura/beinn-bheigier.shtml', 16.5, 775, 8.0, 'The hills of Islay may not reach any great height, but they offer a solitude that can match almost any in Scotland. Their rocky upper slopes give superb views, though these must be earned by struggling through some extremely tussocky and tiring terrain lower down.', 55.711, -6.04069),
('dda1609f-02a6-5cce-9db5-b5058029ec67', 'Windlestraw Law circuit, Innerleithen', 'https://www.walkhighlands.co.uk/borders/windlestraw-law.shtml', 18.75, 794, 6.5, 'Windlestraw Law is the highest summit of the Moorfoots. Although a boggy plod when climbed by the baggers'' trade route from the west, it provides the high point of an excellent circular when climbed from Innerleithen, following two ridges with some grand views.', 55.621, -3.06148),
('dda50ce2-fbae-5876-a591-a574d76bc2f5', 'Mellon Udrigle beach circuit', 'https://www.walkhighlands.co.uk/torridon/mellonudrigle.shtml', 4.0, 107, 2.0, 'The spectacular beach of Camas a'' Charraig at Mellon Udrigle is the start point for this short but rough exploration of the wild moorland coastline to the north. There are great views across the sea to Assynt, Coigach and the Summer Isles.', 57.9027, -5.56228),
('de355c47-65f5-58e8-9d3f-1e4a1d331c54', 'Storr to Portree coast', 'https://www.walkhighlands.co.uk/skye/portreecoast.shtml', 11.0, 465, 6.0, 'An unpromising start across rough moorland soon leads to a fabulous parade along the top of dramatic coastal cliffs. Superb views.', 57.4939, -6.1457),
('de38f3f9-de78-5a80-aba9-2e47cb90cd88', 'Beinn Liath Mhor, Achnashellach', 'https://www.walkhighlands.co.uk/torridon/Beinnliathmhor.shtml', 15.25, 1054, 8.0, 'Beinn Liath Mhòr takes the form of a long ridge sprinkled with white quartzite screes. It gives a fine, steep hillwalk of much character.', 57.4817, -5.32935),
('de493e35-62cb-5680-a090-26725e442608', 'Craigellachie, Aviemore', 'https://www.walkhighlands.co.uk/cairngorms/craigellachie.shtml', 5.0, 302, 3.0, 'Accessed right from the heart of Aviemore, Craigellachie is a nature reserve with several lochans, beautiful birchwoods, steep crags and excellent views of the Cairngorms. The uppermost section can be omitted to reduce the grade to 1 and the time to an hour; the walk gives a chance to get away from the hustle and bustle of the town and to experience a glimpse of the wild Cairngorms. The crags are home to peregrine falcons.', 57.1846, -3.8327),
('de62cb6a-112a-593c-b2e5-f890b4063929', 'Blackwater Reservoir, Kinlochleven', 'https://www.walkhighlands.co.uk/fortwilliam/blackwater.shtml', 17.5, 550, 6.0, 'This daywalk explores the once industrially exploited but today very beautiful and peaceful Glen Leven, including a visit to the bleak and impressive Blackwater Dam.', 56.7127, -4.96299),
('de983bb3-7487-51e9-bc89-eb2555df624a', 'Beinn Eighe (western summits)', 'https://www.walkhighlands.co.uk/torridon/Beinneighe.shtml', 18.0, 1116, 9.0, 'Beinn Eighe is the bulkiest of the trinity of great Torridon peaks. The western half of its ridge contains both of its two Munros. This section of the ridge makes a fine traverse with magnificent views; it may involve less scrambling than Beinn Alligin or Liathach, but compensation comes when Coire Mhic Fhearchair is reached during the descent; this is the most spectacular of all Torridon''s corries.', 57.5556, -5.4137),
('dec7bb1d-0766-5d12-a89b-296035ebd7f3', 'Bogton Braes circuit, Comrie', 'https://www.walkhighlands.co.uk/perthshire/bogton-braes.shtml', 9.5, 95, 3.0, 'This circular walk leads through the attractive pastoral countryside of lowland Perthshire. The section alongside the River Earn is very attractive but includes an awkward stretch in Stage 3. Much of the route is waymarked but some of the markers are missing, particularly on the difficult riverside section.', 56.3732, -3.9875),
('dedf9026-09f5-56f1-96fe-723c819141fe', 'Wick Old Castle circuit', 'https://www.walkhighlands.co.uk/sutherland/wick-castle.shtml', 7.5, 80, 2.0, 'The ideal introduction to Wick, this walk gives grand views over the working harbour before following the open coast to visit the Trinkie Pool, a fine natural arch, and the dramatically situated Old Castle of Wick.', 58.4429, -3.0948),
('df07f691-ee90-51ea-bfd2-cf466b0109ee', 'Doon Hill and Fairy Knowe, Aberfoyle', 'https://www.walkhighlands.co.uk/lochlomond/doon-hill.shtml', 6.5, 124, 2.0, 'This straightforward circular walk from Aberfoyle climbs mystical Doon Hill, reputed home of the faerie folk. It passes through beautiful native woodland, open countryside and riverside.', 56.1781, -4.3832),
('df104855-837f-55ee-93b0-c2cb483aed1d', 'Caterthun Forts, near Edzell', 'https://www.walkhighlands.co.uk/angus/caterthun-forts.shtml', 3.0, 96, 1.0, 'The White and Brown Caterthuns are two massive iron age hill-forts on two neighbouring low hilltops on the fringe of the Angus glens. They can both be visited by short walks from a layby on a road between the two, offering fine views both towards the glens and over Strathmore.', 56.784, -2.7343),
('df3890be-7a1c-50fa-9aeb-c37b6cc8209f', 'Burn O'' Vat and the Culblean circuit', 'https://www.walkhighlands.co.uk/cairngorms/burn-o-vat.shtml', 6.5, 200, 2.0, 'This circular walk takes in the impressive geological feature known as the Vat, a deep, water gouged bowl that you can enter, and then rises through pleasant pinewoods and more open countryside to make a good circuit through the Muir of Dinnet National Nature Reserve.', 57.085, -2.943),
('df5acb19-77de-59f1-8442-c21537e1bc29', 'Beinn Each from Loch Lubnaig', 'https://www.walkhighlands.co.uk/lochlomond/beinn-each.shtml', 7.0, 693, 4.5, 'Beinn Each is a popular Corbett rises steeply above Loch Lubnaig (although hidden). The ascent is via a steep hill path and can be accomplished quickly; the walk can be extended by a much rougher and trickier continuation to Stùc a'' Chròin.', 56.2947, -4.29129),
('df712fa6-7aed-5ecd-ab0e-d6261d06fc3a', 'Meall Dubh, from Glen Moriston', 'https://www.walkhighlands.co.uk/lochness/meall-dubh.shtml', 11.0, 670, 5.0, 'Meall Dubh is an unassuming Corbett at the heart of the Highlands, many of its slopes now decorated with windfarm turbines. However, its position ensures that the view west from the massive summit cairn is magnificent on a good day - a slice of West Highland mountain grandeur.', 57.1622, -4.8882),
('df8a7520-6ce4-5a29-ad05-65c35735db23', 'The Kelpies and the Helix, Falkirk', 'https://www.walkhighlands.co.uk/fife-stirling/kelpies.shtml', 6.25, 4, 2.0, 'The Kelpies are two huge equine sculptures by Andy Scott, and have rapidly become an icon of Scotland. They are the centrepiece of the Helix, a community project regenerating a large old industrial area between Falkirk and Grangemouth into parkland and space for recreation.', 56.0132, -3.7594),
('df97322b-cd0d-589a-b5b6-10f8ad967877', 'Ben Rinnes ascent', 'https://www.walkhighlands.co.uk/moray/ben-rinnes.shtml', 7.5, 541, 4.0, 'Ben Rinnes is the dominating summit of Moray and is a very popular hillwalk. The views, as might be expected, are extremely extensive, taking in much of northeast Scotland.', 57.4082, -3.19207),
('dfb7ae2b-1f18-5bef-bbee-a1a92feaf883', 'Bruach na Frithe', 'https://www.walkhighlands.co.uk/skye/bruachnafrithe.shtml', 13.75, 947, 7.0, 'Bruach na Frithe is one of the easiest of the Cuillin summits to reach as well as one of the finest viewpoints, but the walk still crosses much extremely rocky and rough terrain. Navigation is very difficult in mist, especially as compasses do not function correctly on the ridge.', 57.2888, -6.1842),
('dfd6520c-7f98-5552-93d8-3037e927858c', 'Feshiebridge, Uath Lochans and Loch Insh', 'https://www.walkhighlands.co.uk/cairngorms/feshiebridge.shtml', 12.25, 240, 4.0, 'This stunning walk packs great variety into an entertaining circuit, taking in the beautiful lower reaches of Glen Feshie, the stunning Uath Lochans and  lovely Loch Insh.', 57.1182, -3.9019),
('e0008494-f357-5151-95e1-37864a37e254', 'Black Lochs circuit, Connel', 'https://www.walkhighlands.co.uk/argyll/black-lochs.shtml', 10.5, 140, 2.5, 'This pleasant circuit visits the Black Lochs, a series of small and attractive lochs fringed by native woodland, with distant views of Ben Cruachan. There are usually many cattle grazing along the route.', 56.4547, -5.39419),
('e0260573-5071-5955-83fd-226831ddb4ac', 'Beauly Priory and river', 'https://www.walkhighlands.co.uk/lochness/beauly-priory.shtml', 2.75, 5, 1.0, 'This short walk from Beauly visits the ruins of the Priory before heading around the meander in the river.', 57.4835, -4.45989),
('e0299ad6-38c3-524e-9eaa-cca91e60e24c', 'Keils and Kilearnadil cemetery, Craighouse', 'https://www.walkhighlands.co.uk/islay-jura/keils.shtml', 4.75, 39, 1.5, 'This easy walk from Craighouse visits the old settlement of Keils and Kilearnadil graveyard with its medieval graves - it has been the island''s cemetery for many centuries.', 55.8338, -5.9508),
('e05fa1a2-a074-52ec-a58c-c6d8334612aa', 'Glenmulliach Forest, near Tomintoul', 'https://www.walkhighlands.co.uk/cairngorms/glenmulliach.shtml', 6.0, 180, 2.0, 'This combination of two waymarked walks climbs through Glenmulliach forest and on upwards to a moorland viewpoint overlooking Tomintoul and the surrounding hills. The return leg heads deeper into mixed woodland and passes a wildlife hide.', 57.235, -3.3371),
('e09d71d6-0542-5e81-841d-1a5ec0cc57ec', 'Ben A''an', 'https://www.walkhighlands.co.uk/lochlomond/ben-aan.shtml', 3.7, 340, 4.0, 'Ben A''an is one of the most popular amongst Scotland''s smaller hills. Often known as the mountain in miniature, its position at the heart of the Trossachs makes it a truly wonderful viewpoint. The car park quickly becomes full on sunny weekends in summer, nearest alternative Ben Venue carpark 450m along A821 towards Aberfoyle.', 56.2327, -4.4065),
('e0d10a18-29f1-59c0-81e6-8011ccef930c', 'Ben Wyvis, near Garve', 'https://www.walkhighlands.co.uk/lochness/Benwyvis.shtml', 14.0, 935, 5.5, 'Ben Wyvis is a vast and sprawling mountain whose isolated position makes it the dominating feature of a wide area of the Highlands. The ascent to its spacious plateau is a reasonably straightforward ascent in good summer conditions by Munro standards and there are very extensive views from the summit.', 57.6658, -4.6668),
('e0fe2036-4410-5471-9b65-ac6bfc6cd77c', 'Kilchurn Castle, Loch Awe', 'https://www.walkhighlands.co.uk/argyll/kilchurn-castle.shtml', 2.0, 10, 0.6666666666666666, 'Kilchurn Castle is a marvellously evocative ruin with a stunning setting on Loch Awe. Unsigned from road this short walk is a delight and ideal for a picnic on a fine summer''s day.', 56.4072, -5.0173),
('e1085e6d-c262-59e4-9663-3b84260cc6ef', 'Cuilags, St John''s Head and the Old Man of Hoy', 'https://www.walkhighlands.co.uk/orkney/st-johns-head.shtml', 20.0, 677, 7.0, 'This challenging hill and cliff walk climbs steeply over Cuilags before descending rough ground to the impressive cliffs of St John''s Head before reaching the Old Man of Hoy and returning via Rackwick village and the Glen.', 58.9163, -3.3136),
('e12e147c-59d6-5a2c-8425-a46d48d9b349', 'Charles Rennie Mackintosh''s Glasgow', 'https://www.walkhighlands.co.uk/glasgow/mackintosh-glasgow.shtml', 13.0, 90, 4.0, 'A fascinating city centre walk taking in the major works of architect Charles Rennie Mackintosh. Leave plenty of time to visit the attractions on the way including the Glasgow School of Art, Kelvingrove Art Gallery and Museum, and Scotland Street School. Note: The Mackintosh building at the School of Art currently closed due to a devasting fire in June 2018 - likely to remain closed until 2030.', 55.8606, -4.2585),
('e1ae1afb-efef-50db-aa63-e18ec12ca528', 'Fiddler''s Path, Dunkeld', 'https://www.walkhighlands.co.uk/perthshire/larches.shtml', 10.5, 150, 3.0, 'This lovely circuit follows the banks of the mighty River Tay upstream from Dunkeld, before returning down the opposite site. It takes in the magnificent ruined Cathedral as well as some remarkable trees - including the Mother Larch and Niel Gow''s Oak.', 56.5675, -3.58681),
('e1de3a47-dc36-500d-bdb6-017c60255262', 'Fife Coastal Path 5: Lower Largo to St Monans', 'https://www.walkhighlands.co.uk/fife-stirling/largo-st-monans.shtml', 14.0, 140, 4.0, 'This section of the Fife Coast Path starts with a long beach covered in shells, and then passes a nature reserve popular with birdwatchers, before rounding Kincraig Head on high cliffs.  Elie provides a pretty stopping point and from there the coast is attractive, passing the ruins of a clifftop castle before reaching St. Monans.', 56.2127, -2.9324),
('e1e2855e-29bf-521a-aea1-2b3ab91ea659', 'Glenbuchat and Creag an Sgòr, near Strathdon', 'https://www.walkhighlands.co.uk/cairngorms/glenbuchat.shtml', 16.75, 494, 5.0, 'The atmospheric ruins of Glenbuchat Castle provide the starting point for a walk along the ridge above the glen, right on the boundary of the Cairngorms National Park. There are good views across this quiet landscape.', 57.2208, -2.9981),
('e2117d60-e7c5-5536-af34-2750aa780076', 'Montrose Beach circular', 'https://www.walkhighlands.co.uk/angus/montrose-beach.shtml', 11.5, 18, 3.0, 'Montrose is blessed with a quite magnificent and vast sandy beach. This circular walk heads along the length of the beach before returning via an inland route, visiting the fine North Water viaduct - now part of a cycle path.', 56.7125, -2.4478),
('e2856368-afea-55bb-8875-ccbb04ad1a6b', 'Well Path circuit, Durisdeer', 'https://www.walkhighlands.co.uk/galloway/well-path.shtml', 6.5, 221, 3.0, 'This circuit heads follows a narrow glen which snakes between the shapely grassy hills behind the picturesque village of Durisdeer. The route is a delight - apart from one boggy section - with plenty of interest. The route is sometimes known as the Wald Path, or as the Roman Road.', 55.3153, -3.74417),
('e2cc1eda-678b-5207-bf86-b85cddfd7b2f', 'Isle Martin explorer', 'https://www.walkhighlands.co.uk/ullapool/isle-martin.shtml', 5.5, 220, 3.0, 'Isle Martin is a community owned island, a memorable place to visit. This walk is a circular hill and coastal route with some rough hill ground and some rocky coastal walking, but with superb views over Loch Broom and the surrounding hills in a unique setting.', 57.9404, -5.21548),
('e2e85514-e3ac-53fb-865c-795832dec795', 'White Shores (Port Ban), Tarbert', 'https://www.walkhighlands.co.uk/argyll/port-ban.shtml', 3.0, 15, 1.0, 'This short walk to the White Shores (also known as Port Ban) skirts the northern side of Tarbert harbour with lovely views back over the boats and then reaches the small secluded pebble beach, from where you can watch the ferries heading across to Cowal.', 55.8635, -5.4153),
('e2ec68fc-3e09-5e2f-b1a0-9faf7d7f4cbe', 'Ben Gulabin, Glen Shee', 'https://www.walkhighlands.co.uk/perthshire/ben-gulabin.shtml', 6.25, 453, 3.0, 'Ben Gulabin rises steeply above the Spittal of Glenshee; it provides a short and straightforward hillwalk with a grand view back down the glen.', 56.8257, -3.4526),
('e3084247-06cd-5c73-9113-7b50875850f1', 'Balintore to Rockfield', 'https://www.walkhighlands.co.uk/ullapool/rockfield.shtml', 10.25, 120, 2.5, 'A good linear walk along the coast between the pretty seaboard villages to Rockfield. Along the way there are impressively sculpted rocks along the shore, the remains of salmon fishing stations and cliffs used by nesting seabirds. The walk can easily be extended by 1.5 km to end in Portmahomack from where a bus can be caught to return to the start (check the timetable before starting out).', 57.7541, -3.9139),
('e31a58f7-f437-589f-807e-f23b31f88c9e', 'Steall Falls and the Nevis Gorge', 'https://www.walkhighlands.co.uk/fortwilliam/steallfalls.shtml', 3.5, 220, 2.0, 'One of the best short walks in Scotland, this route heads through the dramatic and beautiful Nevis Gorge and leads to the awesome Steall Falls.', 56.7776, -5.0003),
('e31fdea7-f452-59c5-b123-e8741a5716b7', 'Arthur''s Seat and Holyrood Park, Edinburgh', 'https://www.walkhighlands.co.uk/lothian/arthurs-seat.shtml', 4.75, 279, 2.5, 'Experience a proper hill walk in the heart of the city. Arthur''s Seat''s rocky summit towers over Edinburgh, with fabulous views in all directions, and the extensive parkland surrounding it is an oasis of calm as a retreat from the busy city.', 55.9513, -3.1705),
('e32c73e3-93fa-5e43-8b0f-decec7918772', 'Loch Arkaig and Invermallie', 'https://www.walkhighlands.co.uk/fortwilliam/locharkaig.shtml', 9.0, 184, 3.0, 'This straightforward walk follows a track through the attractive woodland beside the lower reaches of Loch Arkaig. The objective is the open bothy of Invermallie; the return is made the same way.', 56.9548, -4.99989),
('e340b525-707c-5759-9fbf-ae5132b3a094', 'Eathie coast, near Rosemarkie', 'https://www.walkhighlands.co.uk/lochness/Eathie.shtml', 4.5, 190, 2.0, 'This is a short walk providing historical, geological and wildlife interest. In good weather the mid point of the walk is a great place to picnic and gaze over the clear water in search of dolphins. In bad weather the bothy, now a small interpretative centre about the salmon station and Hugh Miller, provides good shelter.', 57.6447, -4.0641),
('e38eaca0-8d72-5289-b97e-b109149899fe', 'Portchullin circuit from Achmore', 'https://www.walkhighlands.co.uk/kintail/portchullin.shtml', 4.0, 105, 1.5, 'This short circular walk from Achmore village leads down the beautiful shores of Loch Carron. The outward leg crosses wet pastures below the steep crags of Creag Mhaol to reach the hamlet of Portchullin with its fine views across the water, before returning to Achmore along a beech-lined lane.', 57.3418, -5.5647),
('e3be0ba6-fa76-5c3c-a428-1ca976413098', 'Clachtoll Beach and the Broch', 'https://www.walkhighlands.co.uk/ullapool/clachtoll-beach.shtml', 3.0, 40, 1.5, 'This lovely short walk includes a visit to beautiful Clachtoll beach with its perfect sand and the crumbling iron-age broch of An Dùn.', 58.1909, -5.337),
('e3e7e3af-612f-5aae-a08d-dbd9fa29dafa', 'Ardessie Falls', 'https://www.walkhighlands.co.uk/ullapool/ardessie.shtml', 2.5, 228, 0.5, 'A short, steep walk alongside the Allt Airdeasaidh to view the impressive Ardessie waterfalls. The path is eroded and wet in places, but there are beautiful views across Loch Broom on a fine day.', 57.8537, -5.2857),
('e4040ab6-3bff-585c-b7cc-37bee42d4999', 'Trotternish Ridge', 'https://www.walkhighlands.co.uk/skye/trotternishridge.shtml', 36.5, 2417, 66.0, 'One of the finest ridge traverses in Britain. Spectacular views throughout.', 57.6574, -6.2537),
('e405dce1-79cd-5cba-9eb6-55ef5ba109f4', 'John Buchan Way, Peebles to Broughton', 'https://www.walkhighlands.co.uk/borders/john-buchan-way.shtml', 22.0, 590, 6.5, 'Explore a delightful cross section of Borders farmland and open moor on this linear route from Peebles to Broughton named after the famous author who had associations with the area.', 55.6496, -3.1914),
('e40956f7-d78f-5a09-ab5b-2b832031d1b2', 'Beinn a'' Chuallaich', 'https://www.walkhighlands.co.uk/perthshire/beinn-a-chuallaich.shtml', 10.5, 678, 5.0, 'Beinn a''Chuallaich''s position ensures it is a grand viewpoint, look out along Lochs Rannoch and Tummel. There are good stalkers paths up from the south - but no convenient place to park - so this circuit ascends from the hill road to the east.', 56.727, -4.1142),
('e42bf96e-9062-5aa6-8a49-fd29614ec660', 'Davaar Island and the Crucifixion Cave', 'https://www.walkhighlands.co.uk/argyll/davaar-island.shtml', 6.5, 35, 3.0, 'Cross the long causeway that links Davaar Island to the mainland at low tides and explore a number of sea caves including one with a famous crucifixion painting, and then follow a track to the lighthouse at the northern most point. NOTE: This walk is only possible at low tide - you must check tide times before you plan your day and allow plenty of time to return as the tide comes in fast and completely submerges the causeway.', 55.4168, -5.5643),
('e43a0134-dea3-5c3c-ada3-6a36371010d3', 'Sgòr Mòr circular, from the Linn of Dee', 'https://www.walkhighlands.co.uk/cairngorms/sgor-mor.shtml', 20.75, 544, 7.0, 'Viewed in isolation, Sgòr Mòr would be an unassuming hill - a rounded heather moorland crowned by several summits. However, its position on the southern fringe of the Cairngorms makes it one of the finest viewpoints for looking in towards this great range, and combined with the always magnificent pinewoods it makes for a grand days walking.', 56.9895, -3.5439),
('e4770964-0df6-534f-8b4d-d51c2bebb936', 'Poca Buidhe and Loch na h-Oidhche', 'https://www.walkhighlands.co.uk/torridon/pocabuidhe.shtml', 20.0, 565, 7.0, 'This walk follows a stony track to a large, quiet loch surrounded by magnificent mountains.', 57.6873, -5.5973),
('e4bc59a4-1f9c-5f3e-aad0-090b98651802', 'The Eachach Càrn Deargs, Glen Roy', 'https://www.walkhighlands.co.uk/fortwilliam/carn-deargs-eachach.shtml', 14.0, 767, 6.0, 'This pair of very rounded Corbetts have a lonely position above Glen Turret near the head of Glen Roy; the descent route here crosses the famous Parallel Roads.', 56.9812, -4.7431),
('e4cea7d5-500b-5051-882a-14cb39ccfbb4', 'Five Sisters of Kintail', 'https://www.walkhighlands.co.uk/kintail/Fivesisters.shtml', 15.0, 1385, 10.0, 'A classic ridgewalk taking in three Munros, the Five Sisters give a wonderful days excursion with magnificent views.', 57.1694, -5.2945),
('e4dc7c27-549d-5155-ad55-b1f59c26648c', 'Wideford Hill and Chambered Cairn, Kirkwall', 'https://www.walkhighlands.co.uk/orkney/wideford-hill.shtml', 9.75, 308, 3.0, 'A great ''there and back'' to climb to the top of Wideford Hill which is a great viewpoint above Kirkwall and visit the impressive chambered cairn on the far side of the hill before returning to Kirkwall.', 58.9821, -2.9723),
('e503a58c-d1ef-5bb8-a212-f5c3b0ee7d99', 'Shieldaig peninsula', 'https://www.walkhighlands.co.uk/torridon/Shieldaig.shtml', 4.5, 165, 1.5, 'This beautiful short walk onto the An Aird peninsula which projects out into Loch Torridon from Shieldaig, one of the most picturesque villages in the Highlands. There are many lovely spots to admire the shoreline and look for otters and herons.', 57.5256, -5.64928),
('e510bca1-7913-5caf-8a7d-5fa8730cc0c7', 'Quiraing, hill circuit', 'https://www.walkhighlands.co.uk/skye/quiraing.shtml', 6.5, 374, 4.0, 'The truly spectacular Quiraing is an icon of Scotland. Many people visit only the first short section of path, but this complete hill circuit goes further, passing the Prison, Needle and other features before climbing back to return above the escarpment; the views are simply sensational throughout.', 57.6282, -6.2904),
('e5560bd2-5a58-5ae1-9e0e-482a8a117090', 'Monikie Country Park, near Carnoustie', 'https://www.walkhighlands.co.uk/angus/monikie.shtml', 3.25, 7, 1.0, 'A level circuit around two former reservoirs, now used for angling, watersports and bird watching. Ranger information service, adventure play area, toilets and cafe. Parking charge April - September. The pools are prone to blue-green algae which can be toxic to children and dogs.', 56.5345, -2.8114),
('e5769954-edc5-533a-aee2-fddb0f9ccc05', 'West Lomond via the Bunnet Stane', 'https://www.walkhighlands.co.uk/fife-stirling/west-lomond-bunnet.shtml', 9.25, 421, 4.0, 'Longer and more strenuous than the usual ascent from Craigmead, this is the finest route up West Lomond. The route leads past the fascinating rock formations at the Bunnet Stane.', 56.2591, -3.3174),
('e5ad8107-f0e6-567d-933c-984b779665f2', 'Wood of Cree, near Newton Stewart', 'https://www.walkhighlands.co.uk/galloway/wood-of-cree.shtml', 3.75, 111, 1.5, 'The Wood of Cree is a magical place; the largest area of ancient woodland in Southern Scotland, and is an RSPB nature reserve. This walk - combining the Woodland and Scrubland trails - climbs up beside a delightful cascading burn, running through natural woodland with some mighty oaks, and a carpet of bluebells in the spring. At the end of the walk you can visit an otter pool on the River Cree.', 55.0056, -4.5328),
('e6048fa6-42ed-5aa7-893d-137c3acd4c2d', 'Beinn nan Aighenan, Glen Etive', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-nan-aighenan.shtml', 15.75, 1320, 9.0, 'Beinn nan Aighenan is the forgotten Munro of the Starav range, being hidden away from Glen Etive by an intervening ridge. The usual route of ascent to this rocky summit is over the ridge, however, as any alternatives involve a very long approach.', 56.5765, -5.0352),
('e63bcad1-1535-5b41-9cee-c168b9eee5b3', 'Buzzard Path, Beinn Eighe visitor centre', 'https://www.walkhighlands.co.uk/torridon/Talkingtrail.shtml', 1.5, 50, 1.0, 'This short, attractive walk in the Beinn Eighe National Nature Reserve begins from the visitor centre - a great source of information. The walk has a good path through the pinewoods leading past several excellent sculptures but perhaps the greatest attraction is the superb views of Beinn Eighe and Slioch.', 57.6134, -5.31679),
('e646204e-fb37-59a6-af1c-b9ef94fb2a3d', 'Cairn Toul - Braeriach traverse', 'https://www.walkhighlands.co.uk/cairngorms/cairn-toul.shtml', 36.0, 1820, 61.0, 'The magnificent walk from Cairn Toul to Braeriach follows the edge of a vast plateau around the Cairngorms'' most spectacular corries. It is also exceptionally remote and arduous; many will break the route with an overnight stay at Corrour bothy. This can be approached either from the Linn of Dee to the south leaving a very long return, or via the Chalamain Gap from the Sugar Bowl car park on Speyside - the latter route making the traverse possible in a single epic day for the extremely fit.', 57.1462, -3.6793),
('e690672b-0d0b-5194-b359-c7214f2b2a8c', 'Kinlochard and the Crannog', 'https://www.walkhighlands.co.uk/lochlomond/kinlochard.shtml', 12.0, 221, 4.0, 'This easy-going circuit on forest tracks has excellent views over Loch Àrd including the remains of a small crannog. The return leg has superb views over the loch to Ben Lomond, especially good in the autumn colours.', 56.1855, -4.5037),
('e6a306ae-c027-548b-8e23-4a653334c7c3', 'Teampull na Trianaid, Carinish', 'https://www.walkhighlands.co.uk/outer-hebrides/teampull-na-trianaid.shtml', 1.0, 6, 0.3333333333333333, 'A very short walk to visit the site of the Battle of Carinish (1601) and then the ruins of Teampull na Trianaid (Trinity Temple), a 12th century church.', 57.5214, -7.3132),
('e6e74415-6be7-5010-884a-8d56ea1c2e3d', 'The Pap of Glencoe', 'https://www.walkhighlands.co.uk/fortwilliam/papofglencoe.shtml', 7.0, 716, 5.0, 'Known in Gaelic as Sgòrr na Cìche, the Pap of Glencoe is a familiar landmark around the lower end of the glen and Loch Leven. Despite its modest height, it is a sensational viewpoint and gives a short but steep andvery roughhillwalk.', 56.6822, -5.09182),
('e715f056-3551-5c1a-b788-ab88d9f3bb0f', 'St Ninian''s Isle, near Bigton', 'https://www.walkhighlands.co.uk/shetland/st-ninians-isle.shtml', 5.75, 110, 2.5, 'Head across Shetland''s most celebrated beach - the spectacular sand tombolo that links Mainland Shetland to St Ninian''s Isle - before embarking on a coastal round of this beautiful island. There is some fine cliff scenery, and the remains of St Ninian''s chapel - where Shetland''s most precious archaeological find was made.', 59.9711, -1.3306),
('e7512072-ff5c-59fc-ab1d-bef7b1bdc1af', 'Stairhaven Coastal Circuit, Stairhaven', 'https://www.walkhighlands.co.uk/galloway/stairhaven.shtml', 8.5, 175, 3.0, 'Fine coastal scenery is the main draw of this clifftop walk with the return along minor country lanes. A short detour allows a stop at the Cock Inn at Auchemalg Bay at the half way point.', 54.8462, -4.7917),
('e79b0bbb-6dd0-5776-b6ed-efbe2a02d21f', 'Strone Hill, Kilmun', 'https://www.walkhighlands.co.uk/argyll/strone-hill.shtml', 7.75, 395, 3.5, 'This steep ascent from Kilmun on the Holy Loch follows increasingly steep and rough paths uphill through the forest. The reward is the superb view from the summit, whether looking over Dunoon to Arran or up Loch Long.', 55.9897, -4.92807),
('e7a07e46-7571-54f2-9ff0-c7ce63acebcb', 'Conachcraig and Gelder Shiel, from Balmoral', 'https://www.walkhighlands.co.uk/cairngorms/conachcraig.shtml', 22.25, 679, 7.0, 'Conachcraig can be easily climbed as a detour from the normal route up Lochnagar. This longer approach from the north, however, enables a better appreciation of this Corbett in its own right; the bothy at Gelder Shiel can be visited en route and there are superb views of Lochnagar throughout.', 57.0396, -3.2166),
('e7ec424b-6588-5942-9da7-b046839ce555', 'Kirroughtree Forest walks, near Newton Stewart', 'https://www.walkhighlands.co.uk/galloway/kirroughtree-forest.shtml', 5.25, 148, 2.0, 'Kirroughtree Forest is one of the popular 7stanes Mountain Biking centres, but also has 3 waymarked routes for walkers. This route combines the Millenium Cairn (waymarked in orange) and then Little Bruntis (yellow) routes to make for the best short outing in the forest.', 54.9555, -4.42097),
('e7f0baca-9a96-58ca-8b9d-09065317c9d2', 'Càrn Daimh circuit from Tomnavoulin', 'https://www.walkhighlands.co.uk/cairngorms/carn-daimh-tomnavoulin.shtml', 10.25, 360, 4.0, 'This superb circular walk begins from Clash Wood near Tomnavoulin. It climbs up past Craighead to traverse the moorland summit ridge of Càrn Daimh before descending back to the start; there are superb views for much of the route.', 57.3222, -3.3162),
('e800bff4-013d-52b1-b5d2-66523cfcec70', 'Fairy Knowe, near Barr', 'https://www.walkhighlands.co.uk/glasgow/fairy-knowe.shtml', 4.75, 114, 1.5, 'This waymarked circular walk heads up a forested glen from above the picturesque village of Barr. The route visits the beautiful Fairy Knowe then climbs a long flight of steps up a narrow grassy ridge before returning through the forest.', 55.2106, -4.6912),
('e850f7f6-0093-537e-ae43-b09aef1819cf', 'Sgùrr Mhurlagain and Fraoch Bheinn, Loch Arkaig', 'https://www.walkhighlands.co.uk/fortwilliam/sgurr-mhurlagain.shtml', 15.0, 1243, 8.0, 'This fine pair of Corbetts lies above the end of the tortuous road up Loch Arkaig. Sgùrr Mhurlagain is approached along a grassy ridge to a dramatic summit; Fraoch Bheinn gives steeper going. Both mountains offer superb views over both the loch and the surrounding hills.', 56.9716, -5.3122),
('e8ba0c2c-c64e-5dd1-bf83-bf2c0ed7f00b', 'Craiglich, near Tarland', 'https://www.walkhighlands.co.uk/aberdeenshire/craiglich.shtml', 4.5, 191, 1.5, 'Craiglich is a rounded hill that borders the eastern edge of the bowl of farmland that is the Howe of Cromar. It provides a straightforward ascent and is a fine viewpoint.', 57.1457, -2.7834),
('e8c39c62-443e-5735-8948-368769f2c8a2', 'The Fairy Glen, near Uig', 'https://www.walkhighlands.co.uk/skye/fairyglen.shtml', 1.5, 45, 1.0, 'A bizarre and delightful miniature landscape of grassy, cone-shaped hills, the Fairy Glen (sometimes spelt Faerie Glen) is a fascinating and otherworldly place to visit.', 57.585, -6.3338),
('e8dc5bec-31f4-5953-8d66-2c01262f634b', 'Corran Narrows and Clovullin', 'https://www.walkhighlands.co.uk/fortwilliam/corran-narrows.shtml', 3.6, 10, 1.0, 'The Corran ferry links two different worlds - the busy A82 and Fort William area with the peaceful retreat of Ardgour. This short circular walk makes for an enjoyable stroll through wonderfully scenic surroundings - though the latter part is along the verge of a busy road.', 56.7226, -5.2436),
('e96bc7e1-1f4e-51fe-9c52-4778d8088b72', 'Loch Ruthven, near Farr', 'https://www.walkhighlands.co.uk/lochness/loch-ruthven.shtml', 1.0, 5, 0.5, 'More of a place to visit than a walk, Loch Ruthven RSPB Reserve is a nesting site for the dramatic-looking Slavonian Grebe and a great place to spot other birds and wildlife. This very short walk follows the shores of the loch to a bird hide - bring your binoculars!', 57.3227, -4.2633),
('e98b84b4-923d-52b1-b3a8-62997febab96', 'Rubha na Cille and Keills Chapel', 'https://www.walkhighlands.co.uk/argyll/rubha-na-cille.shtml', 4.75, 65, 2.0, 'The slender Rubha na Cille peninsula offers an unusual landscape of contorted rocks, and superb views to the islands. Combined with a visit to the little known but superb carved stones at Keills Chapel, it makes for a fine outing.', 55.962, -5.6987),
('e99913f5-83b9-5514-91ab-92263c7e3d9f', 'Jura coast-to-coast - Tarbert', 'https://www.walkhighlands.co.uk/islay-jura/jura-tarbert.shtml', 4.0, 37, 1.5, 'Walking from coast to coast across Jura sounds like a very demanding excursion - but not on this straightforward walk that crosses the island at the narrows of Tarbert. A good track leads to the lovely shores of Loch Tarbert on the west coast, whilst the route is completed with a visit to Tarbert Bay on the east. The route was once used to haul boats across, avoiding the need to take on the fearsome Gulf of Corryvreckan.', 55.9726, -5.8392),
('e9a69f81-beeb-5811-87f6-be6f8571fd53', 'Machir Bay, Kilchoman', 'https://www.walkhighlands.co.uk/islay-jura/machir-bay.shtml', 3.0, 12, 1.0, 'A 2km sweep of the finest sand, Machir Bay must rank amongst Islay''s most beautiful beaches. This straightforward walk explores the length of the bay.', 55.7832, -6.4537),
('e9a99291-078d-579c-bd6e-f50ec5b2c1a5', 'Sgùrr a Mhadaidh and Sgùrr a Ghreadaidh', 'https://www.walkhighlands.co.uk/skye/sgurraghreadaidh.shtml', 9.5, 997, 8.0, 'Twin-topped Sgùrr a Ghreadaidh is the highest peak on the northern half of the Cuillin Ridge; it can be climbed either with its neighbour Sgùrr a Mhadaidh or on separate excursions; both peaks involve tough scrambling but have fantastic views.', 57.2198, -6.2929),
('e9ace769-09a8-5528-b059-916a0195e021', 'Roseisle Forest and Dunes', 'https://www.walkhighlands.co.uk/moray/roseisle.shtml', 3.5, 12, 1.5, 'This exploration of the pine-clad dunes at Roseisle takes in the best bits of the woods, visits a bird hide, and takes in views of the sea, but also leaves plenty of time to enjoy the beach.', 57.672, -3.5038),
('e9af3b16-fdf9-5a5a-82c7-30bb480b3893', 'Big Burn, Golspie', 'https://www.walkhighlands.co.uk/sutherland/big-burn.shtml', 3.0, 84, 1.0, 'This is Golspie''s hidden gem: a spectacular short walk up a gorge criss-crossed by footbridges and ending in a waterfall. A really excellent circuit.', 57.9792, -3.9627),
('e9f9d26a-aa1f-5bac-bc30-4435126d0cbd', 'Blackchester Fort circuit, Lauder', 'https://www.walkhighlands.co.uk/borders/blackchester.shtml', 12.0, 168, 3.5, 'This pleasant, easy-going circuit climbs rolling countryside to the remains of Blackchester hillfort and then across farmland with good views before descending and following the Harry Burn back to Lauder.', 55.7194, -2.7486),
('e9fb8760-69dd-5d93-9cd7-4f5d8f89079c', 'Fyrish Monument, near Alness', 'https://www.walkhighlands.co.uk/ullapool/fyrish-monument.shtml', 6.0, 292, 2.5, 'All walkers travelling along the A9 in this region will be keen to visit the prominent, strange monument atop the hills north of the road. They will be rewarded with extremely fine views on this straightforward climb through woodland.', 57.7122, -4.3052),
('ea0aab3e-1b72-580f-89d4-7c3849c64c34', 'Meall Horn', 'https://www.walkhighlands.co.uk/sutherland/meall-horn.shtml', 18.0, 836, 7.0, 'Meall Horn may attract little attention, its rounded dome rather overshadowed by the more distinctive mountains around it, but it offers a grand circuit with some superb views of those illustrious neighbours.', 58.3175, -4.9098),
('ea96f3f1-ca63-500e-9a37-4cbf356c5750', 'Sgùrr Mòr and the eastern Fannichs', 'https://www.walkhighlands.co.uk/ullapool/fannichs.shtml', 24.75, 1435, 11.0, 'The main eastern range of the Fannichs is a magnificent ridge-walk taking in four Munros, including the highest, shapely Sgùrr Mòr. The price to be paid however is the rugged and boggy approach across the moors - and, more especially, the long return walk from An Coileachan.', 57.7248, -4.8943),
('eaa970c2-b4e4-5af2-b556-2e1f53add9f0', 'Loch Affric Circuit', 'https://www.walkhighlands.co.uk/lochness/Lochaffric.shtml', 18.0, 330, 6.5, 'A magnificent circuit of Loch Affric. The walk keeps mostly well above the loch and passes through both fine pinewood and moorland scenery, with views of the mountains high above.', 57.2652, -4.9846),
('eab1d517-e7d1-59bd-afdd-27f28f5c8cf5', 'Craiglea Trail and Loch Doon Castle', 'https://www.walkhighlands.co.uk/glasgow/craiglea-trail.shtml', 3.5, 97, 1.5, 'The Craiglea Trail begins from the ruins of Loch Doon castle on the shores of the loch, climbing above the north side to give some excellent views over the water.', 55.2258, -4.3851),
('eac2cd1a-1851-55d1-89b4-9182ae4e8d92', 'Beinn Iutharn Mhòr and Càrn Bhac, Inverey', 'https://www.walkhighlands.co.uk/cairngorms/beinn-iutharn-mhor.shtml', 32.0, 983, 10.0, 'The long approach up Glen Ey deters many from the round of these two remote Munros. On a busy weekend they give a quieter escape from the busier hills of the area.', 56.9851, -3.5003),
('eae5bfd0-30e7-5325-aef0-6828759aaee0', 'Innerwick and Bridge of Balgie, Glen Lyon', 'https://www.walkhighlands.co.uk/perthshire/bridge-of-balgie.shtml', 4.5, 165, 1.5, 'Glen Lyon is renowned for its great beauty; this walk gives a chance to explore its middle reaches, climbing through the Ben Meggernie birchwoods to give fine views. Equally important is the opportunity to visit the excellent cafe on the route.', 56.598, -4.30344),
('eb496af2-cb96-55c6-a6bb-679385e6157b', 'Cullykhan Bay and Fort Fiddes', 'https://www.walkhighlands.co.uk/aberdeenshire/cullykhan-bay.shtml', 1.3, 72, 0.6666666666666666, 'More a place to visit than a walk, Cullykhan Bay is a delightful sandy cove. Overlooking it is Castle Point, the site of ancient Fort Fiddes and an excellent viewpoint for Pennan and the remarkable Hell''s Lum.', 57.6842, -2.2775),
('eb5d2253-63b6-56b4-b0cd-4020026085a1', 'Meallan Liath Coire Mhic Dhughaill', 'https://www.walkhighlands.co.uk/sutherland/meallan-liath-coire-mhic-dhughaill.shtml', 16.0, 900, 6.5, 'The hill with the longest name in Scotland makes for an enjoyable circuit with - as is usual in the far northwest - stunning summit views.', 58.2664, -4.8178),
('eb695726-8de9-5013-a103-286d25f47702', 'The Whangie, Kilpatrick Hills', 'https://www.walkhighlands.co.uk/glasgow/the-whangie.shtml', 4.5, 180, 2.0, 'The Whangie is a bizarre rock-feature in the Kilpatrick Hills, and has wonderful views towards Loch Lomond, the Highlands and the Campsies.', 55.9975, -4.389),
('eb69a40a-0386-51e2-966c-c918558d6c2a', 'Point of Sleat', 'https://www.walkhighlands.co.uk/skye/pointofsleat.shtml', 8.5, 400, 4.0, 'A walk to the lighthouse at the southernmost point of Skye. Good spot for seeing marine mammals and views to the islands of Eigg and Rum. A delightful detour to a lovely sandy beach at Camas Daraich is recommended.', 57.0347, -5.9754),
('eb734b32-1143-53ea-a1fa-1a9122cb9527', 'Lumphanan circular', 'https://www.walkhighlands.co.uk/aberdeenshire/lumphanan.shtml', 3.6, 93, 1.0, 'This delightful short walk from Lumphanan village follows the line of an Old Military Road through mixed woodland, giving distant views out to the mountains of the Mounth.', 57.1291, -2.687),
('eb98ac2f-c8a1-505b-b6a1-1f8f7197c428', 'Three Brethren, from near Selkirk', 'https://www.walkhighlands.co.uk/borders/three-brethren.shtml', 9.25, 408, 4.0, 'The Three Brethren are a trio of massive, solidly built cairns dating back to the sixteenth century; their position ensures they are a popular objective and a splendid viewpoint. This circular route reaches them from the southern side, near Selkirk.', 55.5502, -2.86647),
('ebbb03ba-fc50-5a5c-b20b-8341ea36cfd4', 'Carlingwark Loch, Castle Douglas', 'https://www.walkhighlands.co.uk/galloway/carlingwark-loch.shtml', 5.75, 31, 1.5, 'Carlingwark Loch is a very attractive sheet of water on the fringes of the town of Castle Douglas. This enjoyable walk makes a circuit around the loch and beyond using paths and minor roads.', 54.9352, -3.9253),
('ebfcaf72-eae9-5121-a42b-5f9321c8c648', 'Achnahaird Bay and Garvie Bay circular', 'https://www.walkhighlands.co.uk/ullapool/achnahaird-bay.shtml', 8.5, 168, 4.0, 'Achnahaird Bay is deservedly one of the most celebrated beaches of the Northwest Highlands. This rough coastal circuit follows the shoreline eastwards with fine views of the Coigach mountains to visit the much quieter Garvie Bay. The return is on a minor road.', 58.0566, -5.3562),
('ec10d574-1124-5aa7-9d47-4df63903dece', 'Meal Beach and Hamnavoe', 'https://www.walkhighlands.co.uk/shetland/meal-beach.shtml', 4.5, 110, 2.0, 'Explore a stunning sandy beach before following the coastline to Fugla Ness lighthouse and returning through the settlement of Hamnavoe.', 60.1022, -1.323),
('ec502cc5-0c57-53f4-b1ef-ca24014d0d93', 'An Teallach, Dundonnell', 'https://www.walkhighlands.co.uk/ullapool/anteallach.shtml', 20.0, 1415, 10.0, 'This fabled mountain is perhaps the most impressive in Britain, and gives a day of drama and views that will live in the memory forever. The full traverse is a magnificent scramble, whilst the two Munros can be reached by an easier there-and-back route.', 57.84, -5.215),
('ec9408ec-858e-562a-bfd4-b02e3e8470d6', 'Lochgoin Circuit, Whitelee Windfarm', 'https://www.walkhighlands.co.uk/glasgow/whitelee-windfarm.shtml', 13.5, 117, 3.0, 'A visitor centre and good car parking makes this an easy circular route around Europe''s largest onshore windfarm.', 55.7133, -4.3401),
('ecab70ce-f15d-5c51-b778-24878f351725', 'Chalamain Gap circuit, Glenmore', 'https://www.walkhighlands.co.uk/cairngorms/chalamain-gap.shtml', 18.0, 541, 7.0, 'The Chalamain Gap is a bouldery defile on the path that links the Cairn Gorm ski road with the Lairig Ghru. It forms the centerpiece of this grand circular walk that combines many of the finest aspects of the Cairngorms - rocky, bare mountainsides, beautiful pinewoods, and forest lochs.', 57.1463, -3.6793),
('ecc34864-0983-5f15-9095-490c1c2cff31', 'St Ninians and Loch Fitty from Kingseat', 'https://www.walkhighlands.co.uk/fife-stirling/st-ninians-loch-fitty.shtml', 7.0, 180, 2.0, 'One of the more unusual walking routes in the region, this one starts from the village of Kingseat and crosses a causeway over beautiful Loch Fitty. The destination is St Ninians; originally a deep coal mine, then a vast opencast mine until closure in 2013. There were plans to transform the site into a massive artwork by renowned landform artist Charles Jencks; partly realised but abandoned before completion. Today there are further development plans as a ''wellness'' centre, but the site is already interesting for walkers, with man-made grassy hills (former mining spoil bings) now bedecked by wildflowers.', 56.1002, -3.4066),
('ecd50bdb-6d7f-518a-a6d9-3b0c5bf6996d', 'Beinn a'' Chearcaill, from Loch Maree', 'https://www.walkhighlands.co.uk/torridon/beinn-a-chearcaill.shtml', 12.5, 700, 6.0, 'This rounded hill on the northern fringe of Torridon offers an unforgettable vantage point for the far grander peaks all around. The summit is a flat slab of sandstone littered with boulders, making it the perfect foreground for keen photographers.', 57.6554, -5.4165),
('ecd9190b-380b-551c-aa8f-ccfe7deb3b99', 'Burns'' Trail, Alloway', 'https://www.walkhighlands.co.uk/glasgow/burns-alloway.shtml', 6.0, 11, 2.0, 'A circular route exploring Alloway, birthplace of Robert Burns, and the surrounding woodland and parks. Allow extra time to investigate all the Burns connections along the route.', 55.4324, -4.6347),
('ecda8c72-e541-5acf-a0a1-eb7100c48f63', 'Brighouse Bay circuit', 'https://www.walkhighlands.co.uk/galloway/brighouse-bay.shtml', 7.25, 108, 3.0, 'The sandy beach at Brighhouse Bay is the start point of this enjoyable circuit. Follow the coastline atop the cliffs before turning inland for a ramble through some of Galloway''s rich dairy country.', 54.7883, -4.1252),
('ed290159-d261-507e-9d0b-1d968b4001a2', 'Bishop''s Glen, Dunoon', 'https://www.walkhighlands.co.uk/argyll/bishops-glen.shtml', 3.0, 98, 1.0, 'This pleasant and easy circuit explores the reservoirs of Bishop''s Glen and the tumbling Balgaigh Burn. It can also be walked from the centre of Dunoon by following signs west for Bishop''s Glen.', 55.948, -4.9399),
('edeac8f8-5759-52f3-bb5b-9ccffee2a590', 'Ben Challum, near Tyndrum', 'https://www.walkhighlands.co.uk/argyll/ben-challum.shtml', 11.5, 910, 7.0, 'Ben Challum is not a distinguished peak when seen from the A82, as to this side it shows only sprawling grassy slopes. From the Glen Lochay side its fine peak is more prominent. The ascent is usually made from Kirkton Farm, with boggy lower slopes but a fine final ridge connecting the two summits.', 56.4168, -4.6669),
('edf0d879-2106-51ef-af43-a55055efdcb0', 'Flagstone Trail & the Battery, Castletown', 'https://www.walkhighlands.co.uk/sutherland/castletown.shtml', 3.75, 25, 2.0, 'Caithness flagstones were once a major industry in this area and can be seen as field boundaries, roofing slates, and house building material everywhere locally. This route combines three short walks - the Flagstone Trail which explores this heritage, a walk along the coast above the wavecut flagstone pavement, and a small sculpture trail through the community woodland.', 58.5975, -3.3864),
('ee38b231-5e80-55ee-aedc-6c4725419ebf', 'Torrylin cairn and beach, Kilmory', 'https://www.walkhighlands.co.uk/arran/kilmory.shtml', 2.4, 51, 1.0, 'This short circular walk a 5,000 year old neolithic burial cairn before continuing down to a fine and quiet beach on Arran''s southern coastline. The route then returns via a track to make a short circuit.', 55.4445, -5.2316),
('ee454e13-1be0-5ff3-8d06-8671708c72b5', 'Torosay Castle and jetty from Craignure', 'https://www.walkhighlands.co.uk/mull/torosay-castle.shtml', 6.0, 92, 2.5, 'This out-and-back walk heads through lovely woodland with great views to reach Torosay Castle (a private residence) and then visits an attractive bay overlooking Duart Castle.', 56.4707, -5.7066),
('ee5bd9c5-a604-5093-9168-406b595f495f', 'Kingsbarns and Cambo circuit, Kingsbarns', 'https://www.walkhighlands.co.uk/fife-stirling/kingsbarns.shtml', 5.25, 34, 2.0, 'This varied circular walk begins from the splendid sandy beach at Kingsbarns, briefly following the coast before heading inland beside the Cambo Burn through the Cambo estate and returning via woodland footpaths and a minor road over farmland.', 56.3031, -2.6449),
('ee7b1298-a316-58e7-a7eb-a1ca58ccccac', 'Kenmore to Aberfeldy by the River Tay', 'https://www.walkhighlands.co.uk/perthshire/kenmore-aberfeldy-tay.shtml', 13.6, 93, 4.0, 'This beautiful linear walk links Kenmore at the foot of Loch Tay, with the town of Aberfeldy, following the banks of the River Tay for most of the way. The route is waymarked as the first part of the River Tay Way.', 56.5842, -3.9969),
('eead7460-4a4c-51ed-a8bb-ceb498aaa7a4', 'Queensberry, from Mitchellslacks', 'https://www.walkhighlands.co.uk/galloway/queensberry.shtml', 11.25, 549, 5.0, 'Queensberry is the most southerly of the Lowther Hills, its position making it a prominent local landmark and an extensive viewpoint. The hill has mostly featureless, wet grassy slopes but the ascent from Mitchellslacks makes best use of ATV tracks. An alternative rougher return is given over the distinctive peak of Wee Queensberry.', 55.2477, -3.63041),
('eeb1e179-7924-59d6-819a-3e4a31c90355', 'Aspen Path, Cashel Forest', 'https://www.walkhighlands.co.uk/lochlomond/cashell.shtml', 4.2, 290, 2.5, 'Cashel estate is owned by the Royal Scottish Forestry Society who are restoring the are to more natural forest. They have waymarked 5 different walks of various length; the route here follows the  Aspen Path which is waymarked in red and offers great views of Loch Lomond.', 56.112, -4.5761),
('ef1f0c89-1468-59d7-8bee-cdccecface93', 'The Tors of Ben Rinnes', 'https://www.walkhighlands.co.uk/moray/tors-ben-rinnes.shtml', 11.5, 631, 6.0, 'This longer alternative to the usual Ben Rinnes ascent is tougher going, with more height to climb and some boggy, heathery terrain. The advantage is that it visits some fine granite tors that are missed by the standard route.', 57.4415, -3.236),
('ef34e142-cff6-5033-abfe-8933d725ad55', 'Gullane Bay & Hanging Rocks Caves', 'https://www.walkhighlands.co.uk/lothian/gullane-bay.shtml', 9.75, 82, 3.5, 'Gullane Bay is one of East Lothian''s magnificent sandy beaches; this enjoyable walk crosses the bay and continues round the headland to more secluded sandy beaches. The objective is a couple of caves at Hanging Rocks, which were once inhabited.', 56.0382, -2.8414),
('ef468a94-9ca1-5077-a50d-171bae136724', 'Allermuir Hill and Swanston', 'https://www.walkhighlands.co.uk/lothian/allermuir-hill.shtml', 6.0, 385, 3.5, 'Allermuir Hill is the nearest of the major Pentlands summit to Edinburgh and offers stunning views both over the city and into the heart of the range. The route ascends by the ski-slopes of the Midlothian Snowsports centre and returns via the picturesque thatched village of Swanston.', 55.89, -3.2012),
('ef61a0fe-cff7-5fc2-9a30-79e8e9c01a6b', 'Sgùrr Dearg and the In Pinn', 'https://www.walkhighlands.co.uk/skye/innpinn.shtml', 8.0, 1065, 8.0, 'The summit of Sgùrr Dearg is truly fantastic viewpoint, but is better known as of the most dramatic spots on the Cuillin ridge, being overtopped by the improbable tower of the Inaccessible Pinnacle. This circuit visits the base of the pinnacle but does not include the ascent, which is a rock-climb. Even omitting the pinnacle, this is an extremely rough walk with a great deal of rocky terrain, some scrambling and very tricky route-finding.', 57.212, -6.2884),
('ef79e95a-558b-534c-981f-fa3d43768d19', 'Beinn Bhuidhe, via Glen Fyne', 'https://www.walkhighlands.co.uk/argyll/beinn-bhuidhe.shtml', 21.5, 955, 8.0, 'Beinn Bhuidhe is a Munro isolated from any others, and the long walk in means it is much less visited than the nearby Arrochar Alps, despite it having rough and rocky slopes in places. The approach described here is the traditional one following a private road up the glen (can be cycled) and then a rugged ascent; it is possible instead to make use of an ugly new hydro track from near where the route crosses the river until around 550m, where the track crosses the route described.', 56.273, -4.9191),
('ef804575-e5c5-5029-b366-a2bda5d60ef4', 'Tollie to Slattadale on Loch Maree', 'https://www.walkhighlands.co.uk/torridon/lochmaree.shtml', 8.0, 275, 3.0, 'This fine linear walk follows a broad hill path over a low moorland pass, and gives great views over Loch Maree''s islands to the mountains beyond. The terrain is mostly open moors and is rough in places, before a final section which is very boggy. The time and distance given is for the one-way walk.', 57.7493, -5.59809),
('ef8b23f3-be4f-532c-bf39-1f18cbf84329', 'Lunan Bay', 'https://www.walkhighlands.co.uk/angus/lunan-bay.shtml', 11.5, 69, 3.0, 'Lunan Bay is probably the finest beach in Angus - a magnificent sweep of sand, with a cave and arch at its northern end, and even a ruined castle. The beach is divided in two by the Lunan Water flowing out over the sands - dividing this walk into two halves, with a chance to visit the cafe part way through.', 56.6497, -2.5083),
('efce3c38-fe37-5b69-8fca-b969d160cdda', 'Carsaig Arches', 'https://www.walkhighlands.co.uk/mull/carsaig-arches.shtml', 13.25, 84, 6.0, 'This fantastic coastal walk to the impressive sea arches at Carsaig is a tough route over very rocky ground and with some narrow sections of landslip-prone path most of which can be avoided by following the rocky shore. Extreme care must be taken if visiting the second arch.', 56.3208, -5.972),
('f01ed545-df05-5532-8920-c8e31e411d7e', 'Dùn da Ghaoithe, near Craignure', 'https://www.walkhighlands.co.uk/mull/dun-da-ghaoithe.shtml', 15.0, 843, 5.0, 'Dùn da Ghaoithe is the second highest hill on Mull and the only Corbett. It guards the approach to Craignure on the ferry from Oban, and offers perhaps the finest views on the island.', 56.451, -5.6941),
('f03e8329-0440-5759-a544-cc28a18ab099', 'Sandness Hill and Deepdale cliffs, Netherdale', 'https://www.walkhighlands.co.uk/shetland/sandness-hill.shtml', 10.75, 442, 5.0, 'Sandness Hill is the highest summit on Shetland''s westside, and offers superb views over the sea and surrounding islands. It is the coastal cliffs, however, that are its greatest attraction, as seen on the approach during this superb circuit.', 60.2561, -1.6749),
('f07bc003-998a-5c34-b063-79d2e10e6e05', 'Wideford and Inganess, near Kirkwall, Mainland', 'https://www.walkhighlands.co.uk/orkney/inganess-wideford.shtml', 5.5, 78, 2.5, 'A circular walk from sandy Inganess Bay following the course of the Burn of Wideford; the walk is within easy reach of Kirkwall.', 58.9623, -2.9138),
('f08b5bef-941a-5e7e-a4ef-802742205da4', 'Logierait Woods, near Ballinluig', 'https://www.walkhighlands.co.uk/perthshire/logierait-woods.shtml', 4.5, 129, 1.5, 'This route combines the two waymarked walking trails in Logierait Woods, between the Tay and Tummel. It visits an attractive old curling pond and the return gives views over the Tay.', 56.6545, -3.6808),
('f09c446c-e59b-546c-9ae0-bce362becdf9', 'Beinn an Lochain', 'https://www.walkhighlands.co.uk/lochlomond/beinn-an-lochain.shtml', 5.5, 720, 5.0, 'Beinn an Lochain was classified as a Munro on Sir Hugh''s original list. More recent surveys put it well below 3000 feet but it is very steep and fine mountain that admits no inferiority to the surrounding higher peaks. It gives a short but strenuous hillwalk.', 56.2391, -4.8512),
('f0d6021b-e764-5fb1-b52b-608406b2107f', 'Across Assynt: Elphin to Lochinver', 'https://www.walkhighlands.co.uk/ullapool/across-assynt.shtml', 19.0, 298, 7.0, 'This superb linear cross-country walk heads right through the wild heart of Assynt, passing between its remarkable mountains. The walk as described assumes transport will be arranged but there is also an infrequent bus service.', 58.0634, -4.9956),
('f0eb07a0-2712-5c0e-b3bf-09ecb15c5a6d', 'The Spar Cave, near Elgol', 'https://www.walkhighlands.co.uk/skye/sparcave.shtml', 1.3, 33, 2.0, 'A visit to the Spar Cave requires some forward planning and great care, and should not be underestimated. It is worth the effort, however, as it gives a true adventure, and is one of the great wonders of Scotland.', 57.1423, -6.0729),
('f0ed41ba-1ee4-5d12-8312-dd433071555e', 'Shalloch on Minnoch via the north ridge', 'https://www.walkhighlands.co.uk/glasgow/shalloch-on-minnoch.shtml', 9.5, 425, 4.0, 'Shalloch on Minnoch is the most northerly major summit on the ridge that runs northwards from The Merrick - known as the Range of the Awful Hand. The route described here is rather boggy and featureless but provides the fastest approach; routes from the southwest give tougher going. The walk can be extended to take in Tarfessock and even Kirriereoch Hill before returning the same way back over the Shalloch - or, if transport allows, it could be the start of a complete traverse of the range including the Merrick.', 55.2212, -4.5258),
('f0fbd26b-cf3c-59dd-be70-75e60f2ab682', 'Loch Ordie and Deuchary Hill, Dunkeld', 'https://www.walkhighlands.co.uk/perthshire/loch-ordie.shtml', 23.5, 640, 7.0, 'A long but easy-going walk into the quiet moorland north of Dunkeld, passing a number of picturesque lochs and climbing the superb viewpoint of Deuchary Hill before returning through mature woods.', 56.5752, -3.59148),
('f13d12a1-a36b-5250-86f4-7f1d35e367de', 'The Tappie Tower, Kirkhill Forest', 'https://www.walkhighlands.co.uk/aberdeenshire/kirkhill-woods.shtml', 6.75, 154, 2.0, 'This walk explores the forestry just off the A96 and west of the airport. Despite its location near to these transport hubs, the walk itself follows quiet tracks with a climb up to the open top of Tyrebagger Hill, crowned with a folly known locally as the Tappie Tower.', 57.1951, -2.244),
('f17865c9-b887-5af2-af01-b7c95e70a980', 'Beinn Dubh - Glen Striddle horseshoe, Luss', 'https://www.walkhighlands.co.uk/lochlomond/beinn-dubh.shtml', 11.5, 725, 5.0, 'The circuit of the hills above Glen Striddle makes an excellent short hillwalk. The ascent up the grassy ridge rising from Luss is a delight and the views over Loch Lomond and towards the Arrochar Alps are superb.', 56.1024, -4.6397),
('f181d321-9251-572a-87f4-69f8ae4ae79f', 'Crinan Canal: Crinan to Ardrishaig', 'https://www.walkhighlands.co.uk/argyll/crinan-canal.shtml', 14.0, 40, 4.0, 'A one way walk along the entire length of the Crinan Canal linking the Atlantic with Loch Fyne at Ardrishaig. Overlooking the sea for the first part, and then passing the pretty locks at Cairnbaan, this almost level walk is good for bird watching. A bus links the start and finish.', 56.0905, -5.5571),
('f1b7f817-8fbc-5f4b-93fb-c50f097b9f17', 'Scourie Headland', 'https://www.walkhighlands.co.uk/sutherland/scourie-headland.shtml', 3.0, 65, 1.0, 'This short but rough coastal walk runs out onto the peninsula from Scourie beach with its bird-watchers hide. The sea views, particularly from the cairns near the point, are superb.', 58.3508, -5.1615),
('f1fbdb2d-cc50-5b0d-bf72-6e7df6f0fd77', 'Lochan Fada and Gleann Bianasdail circuit, Kinlochewe', 'https://www.walkhighlands.co.uk/torridon/lochan-fada.shtml', 22.5, 590, 8.0, 'This superb circular day walk heads out from Incheril via the Heights of Kinlochewe to visit remote Lochan Fada in the Fisherfield Forest. The rougher return route involves a river crossing and a final descent down beautiful Gleann Bianasdail to return via Loch Maree - best kept for dry weather.', 57.6086, -5.2867),
('f2993b1f-d1b3-5085-89f4-a9602af40dba', 'Glen Brown circuit, near Tomintoul', 'https://www.walkhighlands.co.uk/cairngorms/glen-brown.shtml', 7.0, 320, 3.0, 'A very varied circuit at mid-height around the lowly hill of Tom Beag. Fine views of Glen Avon, and later, Glen Brown.', 57.2707, -3.439),
('f2be394a-5c9a-525c-b137-31e07aa12b08', 'The Maze beach (Tràigh Thòrasdail)', 'https://www.walkhighlands.co.uk/islands/the-maze.shtml', 3.5, 35, 1.0, 'This short walk crosses two beaches, including the Maze (Tràigh Thòrasdail) which is perhaps the finest on Tiree. The route leads to the site of an iron age fort before returning the same way.', 56.4899, -6.97392),
('f2c5d85c-a0ab-54d2-ab2c-840c61b76196', 'Central Circular link walk', 'https://www.walkhighlands.co.uk/islands/central-circuit.shtml', 20.0, 127, 5.5, 'Primarily a road walk with only a few kilometres of sandy track, this circuit is intended more as a means to link together some of Coll''s shorter walks - or to reach them from Arinagour - rather than as a walk in itself. The roads, however, are very quiet and give pleasant walking throughout.', 56.6226, -6.5255),
('f2de7b9a-1b7b-5625-b270-66ee2da7b889', 'Divie Gorge circuit, from Logie Steading', 'https://www.walkhighlands.co.uk/moray/divie-gorge.shtml', 7.25, 182, 2.0, 'Logie Steading is a well-known spot above the River Findhorn, but this superb circuit explores the much less visited course of the River Divie, where if flows through a lovely wooded gorge. There is plenty of interest with waterfalls and the ruins of a former castle - as well as the cafe at Logie Steading for after the walk.', 57.5338, -3.6609),
('f2f0ceff-365d-5dd9-b3b4-66df3f33bab8', 'Beecraigs and Cockleroy, near Linlithgow', 'https://www.walkhighlands.co.uk/lothian/beecraigs-cockleroy.shtml', 6.75, 131, 2.5, 'This straightforward walk explores the largest of West Lothian’s country parks, with a lake and woodland paths. It includes an ascent of Cockleroy, which gives stunning views across the Central Belt.', 55.9549, -3.5947),
('f324033d-bcba-53d1-9044-29d2172d6e30', 'Allt na Criche, near Fort Augustus', 'https://www.walkhighlands.co.uk/lochness/Alltnacriche.shtml', 2.5, 117, 1.0, 'This short waymarked woodland walk climbs up through the trees, passing a waterfall, to reach a bench with good views over Loch Ness. The walk can be extended along the Great Glen Way.', 57.1597, -4.6631),
('f3490afa-341a-50fd-832c-7ab5a34f352d', 'Mona Gowan, near Strathdon', 'https://www.walkhighlands.co.uk/cairngorms/mona-gowan.shtml', 11.5, 421, 4.0, 'Mona Gowan is a little known hill, lying west along an open moorland ridge from the better known Corbett, Morven. The ascent given here from the north makes a very straightforward hillwalk, making use of a landrover track. Alternative descent routes are suggested which include rougher, pathless sections.', 57.1786, -3.1034),
('f374b0c8-a040-58b6-84c0-eb0e3edb15a0', 'Ardcastle Point, Loch Fyne', 'https://www.walkhighlands.co.uk/argyll/ardcastle.shtml', 7.5, 112, 3.0, 'This fine forestry walk explores a section of the coastline of Loch Fyne with excellent views. Watch out for deer, perhaps even a pine marten, or seals and otters down by the shore.', 56.076, -5.3081),
('f3e2b5ca-8f1e-53d3-8c2c-3415141eefc6', 'Gulvain, near Kinlocheil', 'https://www.walkhighlands.co.uk/fortwilliam/gulvain.shtml', 21.0, 1228, 9.0, 'Gulvain (more correctly known as Gaor Bheinn) is the highest mountain in this area but is little known and remains hidden from the roads. A long approach walk (or mountain bike ride) and sustained ascent is repaid with great views from the fine ridge linking the summits.', 56.8597, -5.349),
('f3fdc2be-dbed-5d6c-8561-250c2200723b', 'Annan Shore walk, Annan', 'https://www.walkhighlands.co.uk/galloway/annan.shtml', 5.5, 23, 1.5, 'From the centre of Annan this walk heads to the Solway Firth to explore the Merse, an expanse of tidal salt marsh with great opportunities for birdwatching.', 54.9882, -3.2647),
('f43bdd12-868b-56fa-9bb7-2eea27b38d65', 'Fisherfield 6, from Shenavall', 'https://www.walkhighlands.co.uk/ullapool/fisherfield-6.shtml', 29.0, 2254, 18.0, 'The Fisherfield Forest - also known as the Great Wilderness - contains the remotest Munros in all Scotland. The effort required is fully repaid, however, as this is a spectacular region of dramatic peaks and ridges - the views from the summits are often claimed to be the finest in Scotland. The route is an epic round of all five Munros and one Corbett, starting and finishing at Shenavall bothy or a nearby wild camp.', 57.7768, -5.2545),
('f4462ecb-3ed0-5638-877e-89d4680f2b56', 'Watson Bird Walk, St John''s Town of Dalry', 'https://www.walkhighlands.co.uk/galloway/watson-dalry.shtml', 5.0, 115, 2.0, 'This varied walk was created to celebrate the late Donald Watson, a renowned bird artist who lived in Dalry; it was one of his favourite routes. The first half is along the flood embankment of the Water of Ken, rich in wildflowers. The second half climbs over Mulloch Hill with superb views over the Glenkens.', 55.1062, -4.16371),
('f4879845-cddd-59a3-8b58-fcb44726e3ad', 'Loch Lochy and the Canal, from Gairlochy', 'https://www.walkhighlands.co.uk/fortwilliam/gairlochy.shtml', 6.5, 72, 2.0, 'This easy and almost level walk using with stunning views up the length of Loch Lochy and across the Caledonian Canal and River Lochy to Ben Nevis. Moy Bridge is often left open - in which case you could retrace steps along the towpath.', 56.9131, -4.99625),
('f494d215-748c-5616-8148-d9f410ca730a', 'The Hidden Side of the Falls of Clyde, near Lanark', 'https://www.walkhighlands.co.uk/glasgow/clyde-hidden.shtml', 4.5, 155, 1.5, 'The walk that visits theFalls of Clydefrom New Lanark is a deserved classic - but this much quieter trail from a small unsigned parking area on a private estate visits some equally spectacular viewpoints on the far side of the river.', 55.6536, -3.785),
('f4bc95ca-d3c9-5fd6-a302-77b23aa96a86', 'Glenborrodale RSPB reserve', 'https://www.walkhighlands.co.uk/fortwilliam/glenborrodale.shtml', 2.75, 126, 1.0, 'The Glenborrodale RPSB reserve includes some of the remnant oakwoods on the fringes of Loch Sunart. This route climbs up through the woods - with a chance to see redstarts, spotted flycatchers and many other birds.', 56.6776, -5.9177),
('f4dee703-d151-5fba-a184-2fa92d41d728', 'St Combs to Rattray Head', 'https://www.walkhighlands.co.uk/aberdeenshire/rattray-head.shtml', 9.5, 46, 4.0, 'Extending south from St Combs is a vast system of dunes and a huge sandy beach, stretching all the way to Peterhead. The southern stretch is backed by a major gas terminal, but as far as Rattray Head the hinterland is the Strathbeg Nature Reserve; it makes a great one-way walk with a real feeling of remoteness.', 57.6567, -1.90746),
('f4f84f1e-ba89-5e4d-93e8-70383764ded3', 'Water of Leith: Slateford to Leith', 'https://www.walkhighlands.co.uk/lothian/water-of-leith-2.shtml', 11.5, 10, 4.0, 'The second half of the Water of Leith makes a cross-section through the city of Edinburgh and is very varied. There are some industrial interludes but the route has great views of Murrayfield Stadium and is very picturesque where it runs through Dean Village and Stockbridge.', 55.9234, -3.248),
('f52575d4-dcba-57f7-89f6-748309bacf89', 'Bearreraig Bay', 'https://www.walkhighlands.co.uk/skye/beareraigbay.shtml', 3.25, 153, 2.0, 'Bearreraig Bay is a beautiful stony bay famous for its fossils - a short walk with a very steep path. This is a quiet and secluded place when the nearby Old Man of Storr is packed with visitors.', 57.4935, -6.1536),
('f5f60451-7314-52bd-8be1-58edf6e56500', 'Duns Law, Castle and Hen Poo, Duns', 'https://www.walkhighlands.co.uk/borders/duns-law.shtml', 7.0, 129, 2.0, 'This straightforward walk leads through the grounds of Duns Castle and includes the relatively easy climb to the top of Duns Law as well as a peaceful woodland stroll. There are views over the town of Duns and to the Cheviots, and a chance to feed the ducks and other wild fowl in the Hen Poo, a former curling pond. Duns hosts stages of the Jim Clark Rally and the walk passes the door of the Jim Clark room which contains memorabilia of the World champion racing driver who won 25 Grand Prix.', 55.7806, -2.34638),
('f6218f20-e488-5c98-9773-81afab07f253', 'Dean Village and the Galleries of Modern Art', 'https://www.walkhighlands.co.uk/lothian/dean-village.shtml', 4.5, 58, 1.5, 'This circular walk heads from Stockbridge past some magnificent Georgian architecture to reach the Scottish National Galleries of Modern Art. It returns along the Water of Leith, passing through beautiful Dean Village, one of the most magical corners of Edinburgh with a fascinating range of buildings set in the deep gorge of the river.', 55.958, -3.20859),
('f63ca1d3-4db5-5c16-bd83-8c02213e93eb', 'Braigh nan Uamhachan, near Glenfinnan', 'https://www.walkhighlands.co.uk/fortwilliam/braigh-nan-uamhachan.shtml', 18.75, 1038, 8.0, 'Braigh nan Uamhachan may lack the height and drama of its neighbouring Corbett, Streap, but after a demanding initial climb it rewards with fine views of the mountains all around.', 56.864, -5.3976),
('f6613e49-1ead-5525-8c88-61e890e6eac7', 'Craigower circuit, Pitlochry', 'https://www.walkhighlands.co.uk/perthshire/craigower.shtml', 5.2, 240, 2.0, 'If climbing Ben Vrackie seems a little too daunting, little Craigower provides the perfect short hill ascent near Pitlochry. Owned by the National Trust of Scotland, the wooded summit offers great views both down the strath and up Loch Tummel.', 56.7136, -3.73849),
('f66ff922-7386-5441-b147-8572588eed19', 'Sgòrr na Diollaid, Glen Cannich', 'https://www.walkhighlands.co.uk/lochness/sgorr-na-diollaid.shtml', 7.0, 654, 5.0, 'The pathless, rough slopes of Sgòrr na Diollaid are made memorable by being crowned with a wonderful rocky summit - a great viewpoint. This Corbett makes for one of the shorter days'' hillwalking in the Cannich area.', 57.3589, -4.85151),
('f69e63a0-de2f-5388-a54b-ee0434e82a0c', 'Pressmennan Wood, near Stenton', 'https://www.walkhighlands.co.uk/lothian/pressmennan-wood.shtml', 4.5, 98, 1.5, 'Pressmennan Wood is a mixed woodland owned by the Woodland Trust. This short walk runs through the trees close to the shore of Pressmennan Lake, enlivened by the wood carvings of the homes of Glingbobs and Tooflits - a delight for families.', 55.9444, -2.6094),
('f6b46ec4-7cb3-52d2-947d-841bcd6e1c78', 'Sgùrr nan Clach Geala, near Braemore', 'https://www.walkhighlands.co.uk/ullapool/sgurrnanclachgeala.shtml', 18.0, 1153, 9.0, 'Sgùrr nan Clach Geala is the finest of the Fannichs, with its impressive eastern corrie. In combination with the neighbouring Munros of Meall a'' Chrasgaidh and Sgùrr nan Each it gives an excellent ridgewalk.', 57.7373, -5.09),
('f6ba1588-ea20-595b-9b2a-255fc30a0cf5', 'Kinnoull Hill and Tower, Perth', 'https://www.walkhighlands.co.uk/perthshire/kinnoull-tower.shtml', 6.5, 290, 3.0, 'Kinnoull Hill has fine woodlands and a dramatic clifftop escarpment above the Tay. It makes a grand setting for a cylindrical tower built as a folly. The whole walk makes an excellent circuit from Perth city centre.', 56.3917, -3.4268),
('f6c62790-50ee-5cc2-874a-1c6080555a58', 'North Queensferry coastal circuit', 'https://www.walkhighlands.co.uk/fife-stirling/north-queensferry.shtml', 5.25, 101, 2.0, 'From directly under the Forth Rail Bridge this route follows a lovely section of the Fife Coastal path until it heads inland to return on a road. An interesting mix of coast, wildlife and industrial landscape.', 56.0079, -3.3926),
('f6f9175d-c772-5b99-8878-f2ddd5478c0d', 'Sgùrr a'' Chaorachain, Bealach na Ba', 'https://www.walkhighlands.co.uk/torridon/Sgurrachaorachain.shtml', 7.0, 375, 2.5, 'A short hillwalk taking advantage of a start at over 2000 feet. Sgùrr a Chaorachain is a Corbett summit, and though easy to reach has very dramatic mountain views.', 57.4188, -5.70807),
('f704e50a-3ceb-5de4-b7b8-6d2d4f3d124f', 'The Distilleries coast walk, from Port Ellen', 'https://www.walkhighlands.co.uk/islay-jura/three-distilleries.shtml', 6.25, 74, 24.0, 'For those who love peated Islay whiskies, there couldn''t be a walk more tempting than one linking the famous distilleries of Laphraoig, Lagavulin and Ardbeg and Islay''s newest distillery, Port-n-truan. The walk takes the form of a metalled cycle path from Port Ellen, running close by but off the road for almost all the distance. All of the distilleries offer tours - best to book ahead; Ardbeg has a fine cafe at the end. The walk is described as a one-way linear walk - there is a bus service that can be used to return from Ardbeg (or the other distilleries).', 55.6294, -6.184),
('f7f1baa9-83e0-5bf8-a75b-b290a6ad1226', 'Sgùrr na Cìche: 3 Munros from Loch Arkaig', 'https://www.walkhighlands.co.uk/fortwilliam/sgurrnaciche.shtml', 26.0, 1523, 12.0, 'This epic mountain walk takes in three remote and exceptionally rugged Munros. The arduous effort required is rewarded with magnificent rocky mountainscapes throughout. Sgùrr na Cìche itself is one of the most shapely summits in Scotland and is a classic viewpoint.', 56.9719, -5.3123),
('f80e6ea2-d616-5eb7-9e31-70da76e2b0dc', 'Diabaig to Craig', 'https://www.walkhighlands.co.uk/torridon/Diabaigcraig.shtml', 8.0, 300, 3.5, 'This is the first part of the wild walk along the coast from Diabaig to Red Point (at the end of a minor road from Gairloch). Times are given for the return walk to Craig from Diabaig.', 57.581, -5.69813),
('f85f3b74-dd8f-5cbb-9690-3614b6c286be', 'The Livet circuit, near Tomnavoulin', 'https://www.walkhighlands.co.uk/cairngorms/livet.shtml', 9.5, 150, 3.0, 'A fairly level circuit that nonetheless takes in some very bleak and wild moorlands around the upper reaches of the river Livet. The route has been waymarked by Glenlivet estate. Look out for grouse, curlews and lapwings.', 57.3079, -3.2696),
('f8612ae8-9334-50ec-877e-e6c717157dee', 'Great Bernera Trail', 'https://www.walkhighlands.co.uk/outer-hebrides/great-bernera.shtml', 11.25, 249, 4.0, 'Great Bernera is the largest of many islands in Loch Roag off the shores of Lewis, connected to its larger neighbour by a road bridge since 1953. An exploration of the island on foot makes for a grand half day; the route follows faint and sometimes wet paths up the west side of the island to the magnificent beach at Bostadh before returning along the quiet minor road.', 58.2278, -6.8415),
('f86a77a1-092a-5b1b-94c7-ab09a4f5531c', 'Glencoe Lochan trails', 'https://www.walkhighlands.co.uk/fortwilliam/glencoelochan.shtml', 2.5, 100, 1.5, 'A gem of a walk following waymarked trails through ornamental woodland at the foot of Glen Coe.The picturesque and serene lochan and its wooded shores contrasts with the wild and dramatic mountains of the glen which are seen across it.', 56.6878, -5.09663),
('f8813c02-fc18-53ff-ad10-4a7f797c59bd', 'Aoineadh Mòr and the Fossil Leaves, Ardtun', 'https://www.walkhighlands.co.uk/mull/ardtun.shtml', 3.0, 65, 1.5, 'This short but rough and pathless walk visits some attractive wild coastline with views across to the Ardmeanach Peninsula. The objective is a visit to a gully of geological interest; narrow bands of fossilised leaf mould have been found in the side walls.', 56.3332, -6.2403),
('f886a0e5-6321-5202-bcd1-3d56ca8201cd', 'Clais Fhearnaig circuit', 'https://www.walkhighlands.co.uk/cairngorms/clais-fhearnaig.shtml', 16.25, 321, 4.5, 'This circular walk starts by visiting the impressive Linn of Quoich, then heads up the hidden Glen Quoich before crossing the Clais Fhearnaig pass to descend into Glen Lui and the walk down the Glen and back along the road to the starting point.', 57.0019, -3.4549),
('f8e30f7a-0e22-541f-9e0d-b7a518b7cdcc', 'Dunbar cliff top trail, Dunbar', 'https://www.walkhighlands.co.uk/lothian/dunbar-clifftop.shtml', 5.75, 43, 1.5, 'This circuit from Dunbar is in two parts - the first explores the red sandstone cliffs and golf courses and the second the historic high street and and harbours. Dunbar was the childhood home of the father of the conservation movement - John Muir - and his birthplace is now a museum.', 56.0044, -2.5169),
('f9021f11-ed31-5c61-b48b-a87be9d85f2e', 'Cook''s Cairn and Corryhabbie Hill from Allanreid', 'https://www.walkhighlands.co.uk/cairngorms/cooks-cairn.shtml', 25.75, 794, 8.0, 'An enjoyable exploration of the rolling hills and bleak moorland around the head of Glen Livet. The route takes in the Corbett, Corryhabbie Hill, as well as the neighbouring Fiona, Cook''s Cairn.', 57.3079, -3.2694),
('f911154e-ef88-5445-916d-37d09a6d66e9', 'Bunzeach Trail, Bellabeg, Strathdon', 'https://www.walkhighlands.co.uk/cairngorms/bunzeach.shtml', 6.5, 177, 1.5, 'Although a forest walk this circular route has plenty of open views of lovely Strathdon.', 57.203, -3.0727),
('f9623980-5b07-5448-9d33-f90ad40e04f6', 'Ardnave Point, Ardnave', 'https://www.walkhighlands.co.uk/islay-jura/ardnave-point.shtml', 6.0, 12, 2.5, 'A low level walk around the peninsula of Ardnave Point with good views to Nave Island andColonsay. The walk gives a chance to see choughs and seals.', 55.8721, -6.3396),
('f975520a-0d2d-5af9-8891-4838d697217f', 'The Hermitage and Braan Walk, Dunkeld', 'https://www.walkhighlands.co.uk/perthshire/hermitage.shtml', 7.0, 140, 2.0, 'This varied walk is a Perthshire classic. It begins through the beautiful wooded glen of the Hermitage, complete with picturesque follies and attractive waterfalls. The route then becomes less busy as it continues up the glen, visiting the dramatic Rumbling Bridge before a return through more open countryside with attractive views. The Hermitage is owned by the National Trust for Scotland.', 56.5616, -3.607),
('f9a54bd4-aab3-522e-b2de-64421968c970', 'Càrn Dàimh, Glenconglas', 'https://www.walkhighlands.co.uk/cairngorms/carn-daimh.shtml', 11.25, 400, 3.5, 'The summit of Càrn Dàimh, though less than 600m, offers fine views over the rolling Glenlivet hill country between Ben Rinnes and the Cairngorms. This waymarked circuit takes in farmland, forestry plantations and open heather moorland.', 57.2846, -3.3759),
('f9ab4f6e-b589-5a66-80e9-4a8ff25fb9e1', 'Dùn Skeig, Clachan', 'https://www.walkhighlands.co.uk/argyll/dun-skeig.shtml', 6.0, 153, 2.0, 'This walk both encircles and climbs Dùn Skeig, the prominent rocky hill that guards the entrance to West Loch Tarbert. The Dùn is crowned by iron-age remains and is also a superb viewpoint. The walk passes through areas grazed by livestock and has a couple of extremely boggy patches.', 55.7462, -5.5629),
('f9debf6d-f295-5075-8991-563853dc4eb9', 'Lossiemouth East Beach and the River Lossie', 'https://www.walkhighlands.co.uk/moray/lossiemouth.shtml', 6.25, 25, 2.0, 'This excellent circular walk crosses the fine new footbridge over the mouth of the Lossie before continuing along its tidal banks on the inland side of the dunes. It then heads into the woods before returning along Lossiemouth''s beautiful East Beach.', 57.7169, -3.2832),
('fa48965e-4f69-5dba-b76f-4afc57dadecf', 'West Coast Walk Stage 2: Bay of Skaill to Birsay', 'https://www.walkhighlands.co.uk/orkney/bay-of-skaill-birsay.shtml', 12.25, 326, 4.5, 'The west coast of Mainland Orkney has some spectacular cliff scenery, and has stiles to aid walking all the way from Stromness in the south to the Brough of Birsay in the north. This is the second part of the west coast walk, starting from the Bay of Skaill. Note that this is a linear walk requiring return transport.', 59.0535, -3.3336),
('fa511789-f1dc-56c3-bb26-544edb7339fb', 'Sgùrr na Strì', 'https://www.walkhighlands.co.uk/skye/sgurrnastri.shtml', 23.5, 645, 8.0, 'Diminutive Sgùrr Na Strì may be reach 494 metres in height, but it''s proof that - when it comes to mountains - size doesn''t matter. Reaching it requires a long and quite rugged walk, but the rewards are immense. Many walkers reckon that the view from the summit - over Loch Coruisk, the Cuillin and the sea - is the finest in all Britain.', 57.2905, -6.1714),
('facd3fa7-5351-558b-865e-d9f4e3e0c89b', 'Caisteal Bharraich, Tongue', 'https://www.walkhighlands.co.uk/sutherland/caisteal-bharraich.shtml', 2.75, 111, 1.0, 'Caisteal Bharraich (or Castle Varrich) is a prominent ruined castle in a superb prominent position overlooking the Kyle of Tongue. It gives a very pleasant short walk from Tongue village.', 58.4757, -4.4173),
('fb235585-c105-53cb-9f6a-69230322768b', 'Tomtain, near Kilsyth', 'https://www.walkhighlands.co.uk/glasgow/tomtain.shtml', 3.5, 150, 1.0, 'Tomtain is the most prominent of the Kilsyth Hills - the easterly extension of the Campsies. The summit offers superb views out of all proportion to the effort involved in climbing it.', 56.0066, -4.0315),
('fb2fa71d-e55c-5a5f-8925-6900b82c940a', 'Ruadh-stac Beag', 'https://www.walkhighlands.co.uk/torridon/ruadh-stac-beag.shtml', 15.5, 931, 7.5, 'The great domed Corbett of Ruadh-stac Beag is separated from the main Beinn Eighe ridge; it has considerable defences on most sides and access is usually via the screes of its southern flank. It makes a fine walk through stunning scenery - and could be combined with the ascent ofMeall a'' Ghiubhais.', 57.6132, -5.3165),
('fb692e10-ae60-5e17-bfe4-04dbc014fa74', 'Caerlaverock Castle and Nature Reserve', 'https://www.walkhighlands.co.uk/galloway/caerlaverock-castle.shtml', 3.0, 18, 1.0, 'Head along the edge of the Caerlaverock National Nature reserve mudflats, looking out for wintering geese, en route to one of Scotland''s most beautiful and romantic ruined castles.', 54.9721, -3.5343),
('fb80d8b2-ff1e-5da5-a5bf-ac2f3589afed', 'Diabaig Coastal Circuit', 'https://www.walkhighlands.co.uk/torridon/Diabaig.shtml', 12.0, 715, 5.0, 'A challenging coastal walk through spectacularly rugged and rocky scenery. The return route involves some road walking but the views are ample reward.', 57.5755, -5.68516),
('fb80ffa2-007f-5143-b7a3-904ffc5e9a89', 'Geal Charn, from Dorback Lodge near Nethy Bridge', 'https://www.walkhighlands.co.uk/cairngorms/geal-charn-dorback.shtml', 13.25, 524, 4.0, 'Like most hills which share the name, Geal Chàrn is an undistinguished and rounded hill with heathery slopes. Although pathless it can be climbed in a short half-day, and can usually be relied upon to provide solitude.', 57.2327, -3.5298),
('fb8a2661-6aff-50b0-a6f3-ad64206ce08b', 'Maoile Lunndaidh', 'https://www.walkhighlands.co.uk/torridon/maoilelunndaidh.shtml', 26.0, 1005, 11.0, 'Maoile Lunndaidh is sometimes referred to as Creag Toll a'' Choin - more properly the name of a creag below what recent surveys have shown to be its highest point. It''s a shy Munro hidden away from most viewpoints. Its initially lumpen appearance is livened up by some fine corries, and the ascent gives a long and tiring day.', 57.4914, -5.2722),
('fb973966-5760-5c41-b738-5bd237a8bda9', 'Fitful Head circuit, from Quendale', 'https://www.walkhighlands.co.uk/shetland/fitful-head.shtml', 9.0, 312, 4.5, 'Fitful Head is a high moorland towards the southern end of Mainland, fringed by dramatic coastal cliffs on the west side. It is the breeding ground for huge numbers of Bonxies and offers superb views on a good day.', 59.9031, -1.3374),
('fbb2d823-72e7-5801-af19-2d233e9a3d83', 'Sacquoy Head, Rousay', 'https://www.walkhighlands.co.uk/orkney/sacquoy-head.shtml', 6.75, 111, 2.5, 'A great coastal walk including Sacquoy Head, deep coastal inlets and natural arches. Good for spotting seals and arctic skuas.', 59.1834, -3.0498),
('fbe4a5dd-ade1-5ba5-90d0-9acb68a9568c', 'Elrick Hill circuit, from Tyrebagger', 'https://www.walkhighlands.co.uk/aberdeenshire/elrick-hill.shtml', 4.25, 122, 1.5, 'This excellent and varied short walk combines a forest trail, with a visit to the more natural and open landscapes of Elrick Hill.', 57.191, -2.2472),
('fc0d5893-10aa-556b-a28a-e65c68372cd2', 'Craigluscar Hill, near Dunfermline', 'https://www.walkhighlands.co.uk/fife-stirling/craigluscar.shtml', 3.5, 116, 1.5, 'This rather neglected hill is the site of an iron age fort. It offers commanding views and a delightful short walk with plenty of nature to discover in its regenerating woodlands.', 56.0999, -3.51278),
('fc26ee03-cc9c-5cf1-bc87-291222e8328b', 'Beinn na Caillich and the Broadford Red Hills', 'https://www.walkhighlands.co.uk/skye/beinnnacailleach.shtml', 8.5, 985, 6.0, 'Beinn na Caillich rises impressively above Broadford, it''s forbidding steep slopes of rock and scree deterring it from becoming a more popular ascent. That first steep pull is rewarded with some fine ridge walking and truly stunning 360 degree views.', 57.2336, -5.9467)
INSERT INTO hikes.walks (uuid, name, url, distance_km, ascent_m, duration_h, summary, latitude, longitude) VALUES
('fc34a83e-1a8f-54db-a2fc-4f8f69559c90', 'Dryburgh Abbey and the Tweed, St Boswells', 'https://www.walkhighlands.co.uk/borders/dryburgh-abbey.shtml', 7.75, 115, 2.0, 'A varied circuit following the River Tweed from St Boswells and visiting the Temple of the Muses before climbing to a huge statue of William Wallace and returning on a road with the option of visiting Dryburgh Abbey.', 55.5707, -2.64534),
('fcc48c06-2d7b-5f6c-9b0c-7cb5673ce781', 'Skelbo Forest, near Dornoch', 'https://www.walkhighlands.co.uk/sutherland/skelbo.shtml', 2.5, 56, 1.0, 'Skelbo is a commercial forest plantation; this waymarked walk around it runs along the edge in places to give more open views towards Ben Bhraggie. The trail has several crude wooden sculptures and tableaux to add to the appeal for children.', 57.9201, -4.0617),
('fcc602d1-3013-5650-bf07-b7a9c4ea17ad', 'Ben Tee, Kilfinnan', 'https://www.walkhighlands.co.uk/fortwilliam/bentee.shtml', 10.0, 911, 6.0, 'Ben Tee is a prominent Corbett, visible from many points along the Great Glen and Glen Garry, and makes a fine, wide ranging viewpoint.', 57.0214, -4.83904),
('fcce8f5c-fd9e-5344-87a5-327e2d9a9c37', 'Cam Chreag, Innerwick, Glen Lyon', 'https://www.walkhighlands.co.uk/perthshire/cam-chreag.shtml', 12.75, 640, 4.5, 'Cam Chreag is a Corbett on the north side of Glen Lyon, with a steep-flanked summit ridge defended by a few small crags. Its ascent makes for a short hillwalk from Innerwick; keen baggers can combine it with neighbouring Beinn Dearg.', 56.5982, -4.30392),
('fce8e963-2663-5b7e-b83b-2a0d5b2894f8', 'Beinn a'' Chlachair, Geal Chàrn & Creag Pitridh', 'https://www.walkhighlands.co.uk/fortwilliam/beinn-a-chlachair.shtml', 26.0, 1275, 10.0, 'These three Munros are quite isolated in the wilds south of Loch Laggan. Beinn a''Chlachair is  a massive whale-like ridge with steep sides, Geal Chàrn a sprawling mass and Creag Pitridh a pointed summit on its northern slopes.', 56.9122, -4.57556),
('fcf941b7-ad9d-58d3-ac41-57ee7d41357c', 'Abernethy Forest and Lyngarrie circuit', 'https://www.walkhighlands.co.uk/cairngorms/abernethy-forest.shtml', 11.25, 106, 3.5, 'This walk visits part of Abernethy Forest, the largest area of natural pine forest in the UK, directly descended from the ancient Caledonian forest. Follow a riverside path before a long section on a quiet tarmac road which does give fabulous views to the Cairngorm mountains. Old paths lead across the strath to the isolated house at Lyngarrie before the route leads back through the magnificent pinewoods.', 57.2534, -3.64),
('fda5dac9-b843-57a2-9481-34966f9d7f0f', 'Clunie walk, Pitlochry', 'https://www.walkhighlands.co.uk/perthshire/clunie-walk.shtml', 11.75, 450, 3.5, 'The Clunie Walk provides an escape from the hubbub of Pitlochry by climbing up into the forested hills on the opposite side of the River Tummel. It gives superb views over both the town and the hills beyond.', 56.7014, -3.734),
('fdd2a218-24f8-51c0-813e-d07c5fffd275', 'Holborn Head, Scrabster', 'https://www.walkhighlands.co.uk/sutherland/holborn-head.shtml', 7.5, 134, 2.0, 'This fine circuit takes in some of the very best of the Caithness coastline, with magnificent cliffs, a giant stack, blow holes and geos There are great views over Thurso and across to Hoy, with the Orkney ferry often seen crossing the turbulent waters of the Pentland Firth.', 58.6116, -3.5511),
('fe0f86e6-914a-51b8-904d-e8a74b63c1e3', 'Camusdarach Beach', 'https://www.walkhighlands.co.uk/fortwilliam/camusdarach-beach.shtml', 3.75, 12, 1.0, 'Beautiful Camusdarach Beach was made famous by its starring role in the cult film Local Hero. This short walk heads out to explore the celebrated sands and continues along the coastline.', 56.9575, -5.8426),
('fe35e0fb-fbaf-53ff-8423-b4aef8e12414', 'Ullapool hill and the Braes, Ullapool', 'https://www.walkhighlands.co.uk/ullapool/ullapoolhill.shtml', 7.5, 258, 2.5, 'This short but steep ascent reveals superb views over Loch Broom and Ullapool. The highest point is the outcrop of Meall Mòr with views inland of Loch Achall and surrounding countryside. The walk is particularly beautiful in the autumn when the heather is a purple blaze.', 57.8975, -5.1644),
('fe4f8ef3-1381-5fea-b9c6-8f8262a7c6d7', 'Correen Hills circuit, near Alford', 'https://www.walkhighlands.co.uk/aberdeenshire/correen-hills.shtml', 15.0, 365, 4.5, 'The Correen Hills are an area of rolling, open heather moorland, rising to 518m at the gentle dome of Lord Arthur''s Hill. They give a very pleasant circular walk from near the tiny hamlet of Tullynessle.', 57.269, -2.7505),
('fe8132e9-3d74-583a-9a48-3878a530c3a2', 'Cnoc a''Mhadaidh Ruaidh, Kyleakin', 'https://www.walkhighlands.co.uk/skye/cnoc-a-mhadaidh-ruaidh.shtml', 3.0, 89, 1.0, 'This short walk follows the Anavig Trail climbs through mixed woodland above the edge of Kyleakin. There are superb views over the Skye Bridge, Kyleakin, the Cuillin and distant Trotternish, more than making up for the massive nearby quarry works that mar the coast below.', 57.2717, -5.7446),
('fec8e356-6ab2-5034-9508-b96b401f0d0a', 'Beinn Mhòr and Hecla, South Uist', 'https://www.walkhighlands.co.uk/outer-hebrides/beinn-mhor-uist.shtml', 18.75, 1205, 10.0, 'A rough, tough but magnificent hillwalk requiring good navigation. Beinn Mhòr has a spectacular summit ridge and the other two peaks also have great character as well as superlative views. The route can easily be shortened to include just Beinn Mhòr before returning the same way.', 57.2873, -7.3666),
('ff08907e-45a6-5d8c-8da8-9de2c0bb1f71', 'Portavadie and Low Stillaig', 'https://www.walkhighlands.co.uk/argyll/portavadie.shtml', 5.0, 95, 2.0, 'This coastal circuit has fine views across the water to Kintyre and south to Arran. Passing bronze age standing stones and visiting the pretty bay at Port Leathan this makes a very pleasant short walk.', 55.8711, -5.3054),
('ff536906-4161-58c5-9b68-56578730263e', 'Stob a'' Choin, from Inverlochlarig', 'https://www.walkhighlands.co.uk/lochlomond/stob-a-choin.shtml', 10.5, 790, 7.0, 'Stob a'' Choin may not reach the Munro status of its near neighbours, but it must rank amongst the steepest and most rugged peaks in this part of the Highlands. The ascent is very demanding although short in distance. The delightful summit is a very fine viewpoint. The terrain would be slightly easier if the descent route given here is used for both ascent and descent - although this involves more ups and downs.', 56.3329, -4.5156),
('ff7ae20b-a8fa-59f1-af9a-0ebde47bf921', 'The Snap & Loch of Funzie circuit, Fetlar', 'https://www.walkhighlands.co.uk/shetland/funzie-the-snap.shtml', 8.25, 266, 3.5, 'Explore the Loch of Funzie RSPB reserve - famed for its red-necked phalaropes - before walking the clifftops around Funzie Ness to pass an impressive sea arch on a wild stretch of coastline.', 60.588, -0.8102),
('ffb2eb51-bc52-5c4f-ba34-d68d422cf7fb', 'Gigha south coast circular', 'https://www.walkhighlands.co.uk/argyll/gigha-south-end.shtml', 10.25, 120, 3.5, 'This exploration of Gigha''s southwestern coastline is a wilder challenge - unmarked, pathless in places and with plenty of rough, tough going underfoot - but the scenery out of this world. As well as stunning coastline it also visits the standing stones of Bodach and Cailleach, the windfarm, the beach at Grob Bay, the spouting cave and south pier, before returning along the road past Achamore Gardens.', 55.6779, -5.7331),
('ffead029-e37c-51f5-a01c-039e15536bd2', 'Coral Beaches, Claigan near Dunvegan', 'https://www.walkhighlands.co.uk/skye/coralbeaches.shtml', 4.0, 90, 2.0, 'This popular short walk to the spectacular Coral Beaches, one of the most beautiful coastal locations on Skye. The walk heads across crofting land with livestock so be sure to keep any dogs under tight control.', 57.4889, -6.6213),
('fffd7d02-9956-5983-9c9c-4a5fe50ea1f5', 'Little Wyvis, near Garve', 'https://www.walkhighlands.co.uk/lochness/little-wyvis.shtml', 10.0, 653, 4.0, 'Little Wyvis is very much in the shadow of its bigger neighbour. The ascent from Silverbridge follows landrover tracks for the ascent, making it one of the easier of the Corbetts; views are extensive.', 57.6368, -4.6782),
('ffff6e1f-9343-58b6-8a03-b6896ce2d097', 'The Hill of Beath, near Cowdenbeath', 'https://www.walkhighlands.co.uk/fife-stirling/hill-of-beath.shtml', 2.0, 73, 0.75, 'The Hill of Beath is the name of a village on the fringes of Cowdenbeath - built on the flanks of the hill of the same name. Although the summit is a lowly 240m and the walk to it extremely short, it''s a very fine viewpoint for this part of Fife.', 56.0972, -3.37422)
